INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97776, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有组织的武装反抗行动；多指大批人群的骚乱。", "primary_collocate": null, "pronunciation": "bào dòng", "ipa": "pɑʊ˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "一八五一年，农民发动了一场暴动。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们计划在春天发动暴动，推翻坏官员。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队很快就压下了这场武装暴动。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次暴动失败后，领导人逃到了国外。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，那场暴动持续了三个月。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们秘密开会，准备组织一次暴动。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民不满税太重，决定用暴动来反抗。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，这场暴动让国王很害怕。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府派兵去镇压暴动，死了很多人。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了那次暴动的原因和结果。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场暴动", "label": "量词（场）"}, {"form": "一次暴动", "label": "量词（次）"}, {"form": "武装暴动", "label": "复合"}], "register": "书面语", "sense_fingerprint": "有组织地发动的武装反抗，多见于历史和政治语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暴动", "is_correct": true, "explanation": "“暴动”指有组织的武装反抗，与“农民发动”相合，符合历史语境。"}, {"text": "舞会", "is_correct": false, "explanation": "语义：“舞会”是娱乐聚会，农民不能发动一场舞会，句子不通。"}, {"text": "宴会", "is_correct": false, "explanation": "语义：“宴会”是聚餐活动，与“发动”搭配后意思荒谬。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“发动”一般接“战争、进攻、攻势”，不说“发动一场比赛”。"}], "explanations": {"暴动": "“暴动”指有组织的武装反抗，与“农民发动”相合，符合历史语境。", "舞会": "语义：“舞会”是娱乐聚会，农民不能发动一场舞会，句子不通。", "宴会": "语义：“宴会”是聚餐活动，与“发动”搭配后意思荒谬。", "比赛": "搭配：“发动”一般接“战争、进攻、攻势”，不说“发动一场比赛”。"}, "sentence_index": 0, "correct_answer": "暴动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在田里暴动，认真地插秧。", "explanation": "这里应该用〈干活〉。“暴动”指武装反抗或大批人群的骚乱，和在田里认真干活的平和场面不符，应说“干活”。"}, {"text": "学生们在广场上和平暴动，手里举着标语。", "explanation": "这里应该用〈示威〉。“暴动”指有组织的武装反抗或大规模骚乱，和平地举标语属于示威，句中“和平”与之冲突。"}, {"text": "几百名居民在广场上暴动，一起庆祝节日。", "explanation": "这里应该用〈欢聚〉。“暴动”指武装反抗或大批人群的骚乱，不表示欢聚，应说“欢聚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴动", "is_correct": true, "explanation": "“用暴动来反抗”指用武装起事对抗，与“税太重”的反抗语境一致。"}, {"text": "点心", "is_correct": false, "explanation": "语义：“点心”是食物，不能用来反抗，句子不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是遮雨的用具，不是反抗的手段，这里说不通。"}, {"text": "奇迹", "is_correct": false, "explanation": "搭配：“奇迹”不能作为“用……来反抗”的手段，这里搭配不当。"}], "explanations": {"暴动": "“用暴动来反抗”指用武装起事对抗，与“税太重”的反抗语境一致。", "点心": "语义：“点心”是食物，不能用来反抗，句子不通。", "雨伞": "语义：“雨伞”是遮雨的用具，不是反抗的手段，这里说不通。", "奇迹": "搭配：“奇迹”不能作为“用……来反抗”的手段，这里搭配不当。"}, "sentence_index": 6, "correct_answer": "暴动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国代表在会上暴动，达成了协议。", "explanation": "这里应该用〈谈判〉。“暴动”指武装反抗或乱闹，不是和平的协商，与“达成协议”矛盾。"}, {"text": "学生们排队暴动，唱着歌。", "explanation": "这里应该用〈游行〉。“暴动”指武装反抗或打砸的乱局，排队唱歌是和平的游行。"}, {"text": "市长在广场上暴动，市民们认真听。", "explanation": "这里应该用〈演讲〉。“暴动”不能用来指市长讲话，“市民们认真听”的语境与暴动不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一九一一年，士兵们发动了一个暴动。", "corrected_sentence": "一九一一年，士兵们发动了一场暴动。", "error_description": "量词错误：“暴动”计数应用“场”或“次”，不说“一个暴动”，应改为“一场暴动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "县城的农民不满捐税太重，决定用一个暴动来反抗。", "corrected_sentence": "县城的农民不满捐税太重，决定用暴动来反抗。", "error_description": "量词错误：“暴动”前不能用量词“个”，计数应用“场”或“次”。应说“用暴动来反抗”（不加数量），或“用一场暴动来反抗”，不能说“用一个暴动来反抗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97779, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确：“保护”与“欺负”构成反义，指护卫弱小，与欺压相对。"}, {"text": "参观", "is_correct": false, "explanation": "无关：“参观”指实地察看，与“欺负”没有反义关系。"}, {"text": "学习", "is_correct": false, "explanation": "无关：“学习”指获取知识，与“欺负”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清理，与“欺负”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确：“保护”与“欺负”构成反义，指护卫弱小，与欺压相对。", "参观": "无关：“参观”指实地察看，与“欺负”没有反义关系。", "学习": "无关：“学习”指获取知识，与“欺负”没有反义关系。", "打扫": "无关：“打扫”指清理，与“欺负”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
