INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仗着自己大，欺压比自己小的人。", "primary_collocate": null, "pronunciation": "qī fu", "ipa": "tɕʰi˥ fu", "syllable_count": 2, "sentences": [{"text": "哥哥比弟弟大，常常欺负弟弟。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大孩子不应该欺负小孩子。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仗着个子高，总是欺负同桌。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你比他大，不要欺负他。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个大男孩欺负过我的妹妹。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐欺负了弟弟，妈妈很生气。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高年级的学生有时会欺负低年级的学生。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟哭着说：“哥哥又欺负我了！”", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不能因为自己大就欺负别人。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候个子小，同学常常欺负我。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欺负了", "label": "体标（了）"}, {"form": "欺负过", "label": "体标（过）"}, {"form": "欺負", "label": "繁体"}], "register": "口语", "sense_fingerprint": "仗着年纪或个子大，欺压比自己小的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欺负", "is_correct": true, "explanation": "正确：“欺负”指仗着年纪大压迫弟弟，符合句意。"}, {"text": "娶", "is_correct": false, "explanation": "语义：“娶”只用于男子娶妻，不能用于兄弟之间。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指推倒政权、结论等，不表示兄弟间的欺压。"}, {"text": "追求", "is_correct": false, "explanation": "搭配：“追求”多指理想、爱情，不用于兄弟之间的日常关系。"}], "explanations": {"欺负": "正确：“欺负”指仗着年纪大压迫弟弟，符合句意。", "娶": "语义：“娶”只用于男子娶妻，不能用于兄弟之间。", "推翻": "语义：“推翻”指推倒政权、结论等，不表示兄弟间的欺压。", "追求": "搭配：“追求”多指理想、爱情，不用于兄弟之间的日常关系。"}, "sentence_index": 0, "correct_answer": "欺负"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用甜言蜜语欺负了我的感情。", "explanation": "这里应该用〈欺骗〉。欺负指仗势压迫比自己弱的人，欺骗指用假话使人上当，不能用于感情。"}, {"text": "他仗着自己大，常常欺负比他大的哥哥。", "explanation": "这里把〈欺负〉当成了一般的“与人闹别扭、顶撞”，但欺负特指仗着自己强大欺压比自己小的人；句中对象比他大，仗势压迫之说不通。"}, {"text": "他一生气就欺负那张桌子。", "explanation": "这里把〈欺负〉当成了“拿东西撒气”的意思；欺负的对象必须是比自己弱小的人，不能用于桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欺负", "is_correct": true, "explanation": "正确：“欺负”指仗着个子大压迫弱小，符合“高年级学生欺负低年级学生”的句意。"}, {"text": "降级", "is_correct": false, "explanation": "语义：“降级”用于职务或等级，不能用于学生。"}, {"text": "攻克", "is_correct": false, "explanation": "搭配：“攻克”多搭配难关、堡垒，不搭配人。"}, {"text": "判决", "is_correct": false, "explanation": "语义：“判决”用于法律裁定，不能用于学生。"}], "explanations": {"欺负": "正确：“欺负”指仗着个子大压迫弱小，符合“高年级学生欺负低年级学生”的句意。", "降级": "语义：“降级”用于职务或等级，不能用于学生。", "攻克": "搭配：“攻克”多搭配难关、堡垒，不搭配人。", "判决": "语义：“判决”用于法律裁定，不能用于学生。"}, "sentence_index": 6, "correct_answer": "欺负"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们欺负他的书包，把里面的书都扔在了地上。", "explanation": "这里把〈欺负〉当成了“乱扔、摆弄”的意思；欺负是仗势压迫比自己弱小的人，不能用于书包。"}, {"text": "他比同学都强壮，却常常欺负比他强壮的同学。", "explanation": "这里把〈欺负〉当成了“与人较量、争强斗胜”的意思；欺负是仗着强势压迫弱小，比他强壮的同学不可能被这样欺压，句意变成了争强斗胜。"}, {"text": "他常常欺负那个玩具，把它摔坏了。", "explanation": "这里把〈欺负〉当成了“摔打、折腾”的意思；欺负是仗势压迫人的行为，不能用于玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个大孩子昨天欺负着我的弟弟。", "corrected_sentence": "那个大孩子昨天欺负了我的弟弟。", "error_description": "错误形式：“欺负着”；正确形式：“欺负了”。“昨天”表示动作已经完成，应该用“了”；“着”表示持续的状态，这里不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，不要对欺负同学。", "corrected_sentence": "老师说，不要欺负同学。", "error_description": "错误形式：“不要对欺负同学”；正确形式：“不要欺负同学”。“欺负”是动词，前面不能加介词“对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97780, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "尊重", "is_correct": true, "explanation": "正确：“尊重”与“欺负”构成反义，指敬重他人，与欺压、侮辱相对。"}, {"text": "浏览", "is_correct": false, "explanation": "无关：“浏览”指粗略地看，与“欺负”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指使器物恢复正常，与“欺负”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指移动物品，与“欺负”没有反义关系。"}], "correct_answer": "尊重", "explanations": {"尊重": "正确：“尊重”与“欺负”构成反义，指敬重他人，与欺压、侮辱相对。", "浏览": "无关：“浏览”指粗略地看，与“欺负”没有反义关系。", "修理": "无关：“修理”指使器物恢复正常，与“欺负”没有反义关系。", "搬运": "无关：“搬运”指移动物品，与“欺负”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97780, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "尊重", "is_correct": true, "explanation": "正确：“尊重”与“欺负”构成反义，指敬重他人，与欺压、侮辱相对。"}, {"text": "订购", "is_correct": false, "explanation": "无关：“订购”指预先订立购买，与“欺负”没有反义关系。"}, {"text": "栽种", "is_correct": false, "explanation": "无关：“栽种”指种植，与“欺负”没有反义关系。"}, {"text": "调整", "is_correct": false, "explanation": "无关：“调整”指改变以适应需要，与“欺负”没有反义关系。"}], "correct_answer": "尊重", "explanations": {"尊重": "正确：“尊重”与“欺负”构成反义，指敬重他人，与欺压、侮辱相对。", "订购": "无关：“订购”指预先订立购买，与“欺负”没有反义关系。", "栽种": "无关：“栽种”指种植，与“欺负”没有反义关系。", "调整": "无关：“调整”指改变以适应需要，与“欺负”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用无理的手段压迫、侮辱别人。", "primary_collocate": null, "pronunciation": "qī fu", "ipa": "tɕʰi˥ fu", "syllable_count": 2, "sentences": [{"text": "老板用难听的话欺负新来的员工。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们欺负老实人，说话很不客气。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店欺负外地游客，价钱高得没道理。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能因为他穷就欺负他。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在网上欺负她，说了很多难听的话。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他欺负过很多人，现在很后悔。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别以为我好说话，你不能欺负我。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们几个人欺负他一个，真不公平。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同事常常欺负新人，让他做所有的事。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不怕那些欺负她的人。", "target_word": "欺负", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欺负了", "label": "体标（了）"}, {"form": "欺负过", "label": "体标（过）"}, {"form": "欺負", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用无理的手段压迫、侮辱别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欺负", "is_correct": true, "explanation": "正确：“欺负”指用无理手段压迫员工，与“难听的话”相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”与句中“难听的话”矛盾。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”多用温和的话，不与“难听的话”搭配。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”与句中“难听的话”矛盾。"}], "explanations": {"欺负": "正确：“欺负”指用无理手段压迫员工，与“难听的话”相符。", "夸奖": "语义：“夸奖”与句中“难听的话”矛盾。", "安慰": "搭配：“安慰”多用温和的话，不与“难听的话”搭配。", "感谢": "语义：“感谢”与句中“难听的话”矛盾。"}, "sentence_index": 0, "correct_answer": "欺负"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用谎话欺负了我的信任。", "explanation": "这里应该用〈欺骗〉。欺负针对的是人且是仗势压迫，“信任”不能被欺负，应说欺骗。"}, {"text": "他仗着父亲是校长，常常欺负学校的操场。", "explanation": "这里把〈欺负〉当成了“霸占、独占”的意思；欺负是无理压迫人的行为，不能用来指占用场地。"}, {"text": "他欺负了这个问题，很快就解决了。", "explanation": "这里把〈欺负〉当成了“对付、解决”的意思；欺负是无理压迫人的行为，不能用来指解决问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欺负", "is_correct": true, "explanation": "正确：“欺负”指无理压迫别人，与“你不能……我”的语境相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能用于人。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指想念，与句中要求的压迫性行为不符。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”指量取尺寸，不能用于对人的态度和行为。"}], "explanations": {"欺负": "正确：“欺负”指无理压迫别人，与“你不能……我”的语境相符。", "驾驶": "搭配：“驾驶”的对象是车辆，不能用于人。", "怀念": "语义：“怀念”指想念，与句中要求的压迫性行为不符。", "测量": "语义：“测量”指量取尺寸，不能用于对人的态度和行为。"}, "sentence_index": 6, "correct_answer": "欺负"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这份报告欺负得很彻底，每一页都改了。", "explanation": "这里把〈欺负〉当成了“认真修改、整治”的意思；欺负是无理压迫人的行为，不能用来指修改报告。"}, {"text": "他把这个月的工资欺负了一半，留给自己的很少。", "explanation": "这里把〈欺负〉当成了“挪用、花掉”的意思；欺负是无理压迫人的行为，不能用来指花钱。"}, {"text": "我的朋友很善良，常常欺负别人的困难。", "explanation": "这里把〈欺负〉当成了“克服、对付”的意思；欺负是无理压迫人的行为，困难不是人，不能用来指克服困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她以前欺负了过同学，现在很后悔。", "corrected_sentence": "她以前欺负过同学，现在很后悔。", "error_description": "错误形式：“欺负了过”；正确形式：“欺负过”。“了”与“过”不能同时用在同一个动词后；表示曾经有过的经历只用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不欺负过我。", "corrected_sentence": "他从来没欺负过我。", "error_description": "错误形式：“从来不……过”；正确形式：“从来没……过”。表示过去未曾经历某事，应用“没”而不用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
