INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97785, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97785, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对的路，不会走错的路。", "primary_collocate": null, "pronunciation": "zhèng lù", "ipa": "ʈʂɤŋ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "山里路很多，这条才是正路。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们走错了，快回到正路上。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，去火车站的正路是哪条？", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上这条是正路，别走小路。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，我们在山里找不到正路。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认得正路，大家跟着他走。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面有两条路，哪条是正路？", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小路不是正路，会走到河边。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪以后，我看不清正路了。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷带着我们找回了正路。", "target_word": "正路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "不会走错的那条路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流是水流，不是路，与“山里路很多”的语境不符。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：量词“条”不能修饰房间。"}, {"text": "正路", "is_correct": true, "explanation": "正路：对的路，不会走错的路，与“山里路很多，这条才是”的语境一致。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥不是路，“这条才是”的所指与“山里路很多”不符。"}], "explanations": {"河流": "语义：河流是水流，不是路，与“山里路很多”的语境不符。", "房间": "搭配：量词“条”不能修饰房间。", "正路": "正路：对的路，不会走错的路，与“山里路很多，这条才是”的语境一致。", "桥": "语义：桥不是路，“这条才是”的所指与“山里路很多”不符。"}, "sentence_index": 0, "correct_answer": "正路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条正路很深，我们游不过去。", "explanation": "这里应该用〈河〉。“正路”是道路，不能用来形容水的深浅。"}, {"text": "这片正路很深，我们不能下水。", "explanation": "这里应该用〈湖〉。“正路”是道路，不能用来形容湖水的深浅。"}, {"text": "这颗正路很亮，闪闪发光。", "explanation": "这里应该用〈星星〉。“正路”是道路，不能形容星光的亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是路，“哪条”问的是路，与语境不符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“条”不能修饰桌子，应说“张”。"}, {"text": "正路", "is_correct": true, "explanation": "正路：对的路，不会走错的路，与“前面有两条路，哪条是”的语境一致。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以“哪条”选择的路，与“前面有两条路”的语境不符。"}], "explanations": {"歌曲": "语义：歌曲不是路，“哪条”问的是路，与语境不符。", "桌子": "搭配：量词“条”不能修饰桌子，应说“张”。", "正路": "正路：对的路，不会走错的路，与“前面有两条路，哪条是”的语境一致。", "天空": "语义：天空不是可以“哪条”选择的路，与“前面有两条路”的语境不符。"}, "sentence_index": 6, "correct_answer": "正路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只正路飞得很高，像一片云。", "explanation": "这里应该用〈鸟〉。“正路”是道路，不能指飞行的动物。"}, {"text": "这面正路很干净，能照出人影。", "explanation": "这里应该用〈镜子〉。“正路”是道路，不能照出人影，镜子才有这种用途。"}, {"text": "这枚正路很美，在阳光下闪闪发光。", "explanation": "这里应该用〈宝石〉。“正路”是道路，不能在阳光下闪闪发光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们迷路了，得赶紧找到一座正路。", "corrected_sentence": "我们迷路了，得赶紧找到一条正路。", "error_description": "量词“座”用于山、桥等大型物体，不能修饰道路。道路的量词是“条”，应为“一条正路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于回找了正路。", "corrected_sentence": "我们终于找回了正路。", "error_description": "“回找”颠倒了“找回”的词序，“找回”是动补结构，表示找到后重新拿回，应为“找回了正路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97786, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪路", "is_correct": true, "explanation": "邪路：不正当的道路，与“正路”构成反义。"}, {"text": "天空", "is_correct": false, "explanation": "天空：指天空，与做人做事的正道没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流：指水流，与“正路”不构成反义。"}, {"text": "房屋", "is_correct": false, "explanation": "房屋：指建筑物，与“正路”没有反义关系。"}], "correct_answer": "邪路", "explanations": {"邪路": "邪路：不正当的道路，与“正路”构成反义。", "天空": "天空：指天空，与做人做事的正道没有反义关系。", "河流": "河流：指水流，与“正路”不构成反义。", "房屋": "房屋：指建筑物，与“正路”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97786, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪路", "is_correct": true, "explanation": "邪路：不正当的道路，与“走正路”构成反义。"}, {"text": "旅途", "is_correct": false, "explanation": "旅途：指旅行的路程，与“正路”没有反义关系。"}, {"text": "商店", "is_correct": false, "explanation": "商店：指售货的场所，与“正路”不构成反义。"}, {"text": "公园", "is_correct": false, "explanation": "公园：指供人游玩的场所，与“正路”没有反义关系。"}], "correct_answer": "邪路", "explanations": {"邪路": "邪路：不正当的道路，与“走正路”构成反义。", "旅途": "旅途：指旅行的路程，与“正路”没有反义关系。", "商店": "商店：指售货的场所，与“正路”不构成反义。", "公园": "公园：指供人游玩的场所，与“正路”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "正道；正确的道路。", "primary_collocate": null, "pronunciation": "zhèng lù", "ipa": "ʈʂɤŋ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "他后来走上了正路。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人应该走正路。", "target_word": "正路", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师希望学生都走正路。", "target_word": "正路", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他做错过事，现在回到了正路。", "target_word": "正路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要走正路，不能骗人。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一直教我走正路。", "target_word": "正路", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友帮助他重新走上正路。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前不听话，现在走正路了。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走正路也许辛苦，但是心里踏实。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她相信，走正路才会有好生活。", "target_word": "正路", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "做人做事的正道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道理", "is_correct": false, "explanation": "语义：道理指事理，不是人可以走上的道路。"}, {"text": "正路", "is_correct": true, "explanation": "正路：做人做事的正道，与“他后来走上了”搭配。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“走上”接道路或台阶，不接房间，应说“走进房间”。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“走上”不能与饭菜搭配，饭菜不是人要走上的路。"}], "explanations": {"道理": "语义：道理指事理，不是人可以走上的道路。", "正路": "正路：做人做事的正道，与“他后来走上了”搭配。", "房间": "搭配：“走上”接道路或台阶，不接房间，应说“走进房间”。", "饭菜": "搭配：“走上”不能与饭菜搭配，饭菜不是人要走上的路。"}, "sentence_index": 0, "correct_answer": "正路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的为人很有正路。", "explanation": "这里应该用〈道德〉。“正路”指做人做事的正道，形容品行要说“有道德”，“有正路”不通。"}, {"text": "这次考试我考了正路。", "explanation": "这里应该用〈好成绩〉。“正路”指做人做事的正道，不能用来说考试的成绩。"}, {"text": "这个专业有很好的正路。", "explanation": "这里应该用〈出路〉。“出路”指发展前途，“正路”指做人做事的正道，不能用来说专业的前景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：“走上”的对象是道路，天空不是可以走上的路。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：情绪不是道路，不能“走上”。"}, {"text": "正路", "is_correct": true, "explanation": "正路：做人做事的正道，与“重新走上”搭配。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“重新走上”接的是道路或阶段，不接考试。"}], "explanations": {"天空": "语义：“走上”的对象是道路，天空不是可以走上的路。", "情绪": "语义：情绪不是道路，不能“走上”。", "正路": "正路：做人做事的正道，与“重新走上”搭配。", "考试": "搭配：“重新走上”接的是道路或阶段，不接考试。"}, "sentence_index": 6, "correct_answer": "正路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对工作的正路很认真。", "explanation": "这里应该用〈态度〉。“正路”指做人做事的正道，不能用来形容对工作的态度。"}, {"text": "他的身材很正路。", "explanation": "这里应该用〈魁梧〉。“正路”是名词，指做人做事的正道，不能用来形容身材。"}, {"text": "他讲的正路很正确。", "explanation": "这里应该用〈道理〉。“正路”指做人做事的正道，不能用来说话语的对错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈希望我早日走上着正路。", "corrected_sentence": "妈妈希望我早日走上正路。", "error_description": "“走上着正路”误加了表示持续的“着”。这里表示动作的方向，应直接说“走上正路”，应删去“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下决心做正路，再也不做坏事了。", "corrected_sentence": "他下决心走正路，再也不做坏事了。", "error_description": "搭配错误：“正路”要和动词“走”搭配，不能说“做正路”。错误在“做”，正确说法是“走正路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
