INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "走路去打仗的兵。", "primary_collocate": null, "pronunciation": "bù bīng", "ipa": "pu˥˩ piŋ˥", "syllable_count": 2, "sentences": [{"text": "步兵走路去打仗，不骑马。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支步兵队走了一天的路。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的战争里有很多步兵。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名步兵，每天都要走很远。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步兵走得很累，晚上就在山下休息。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑兵跑得快，步兵跑得慢。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面走过来一队步兵。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时当过步兵。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步兵背着东西，走了很长的路。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当步兵，不想当骑兵。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名步兵", "label": "量词"}, {"form": "一队步兵", "label": "量词"}, {"form": "步兵团", "label": "复合词"}], "register": "中性", "sense_fingerprint": "走路去打仗的兵，与骑兵相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "步兵", "is_correct": true, "explanation": "步兵：走路去打仗的兵，与“走路去打仗，不骑马”的描述相符。"}, {"text": "骑兵", "is_correct": false, "explanation": "语义：骑兵是骑马作战的兵，与“不骑马”的描述矛盾。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机是开车的人，不去打仗，句子说不通。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁负责照料花草，不去打仗，句子说不通。"}], "explanations": {"步兵": "步兵：走路去打仗的兵，与“走路去打仗，不骑马”的描述相符。", "骑兵": "语义：骑兵是骑马作战的兵，与“不骑马”的描述矛盾。", "司机": "语义：司机是开车的人，不去打仗，句子说不通。", "园丁": "语义：园丁负责照料花草，不去打仗，句子说不通。"}, "sentence_index": 0, "correct_answer": "步兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的足球队里有一名步兵，每场都进球。", "explanation": "这里应该用〈前锋〉。步兵是徒步作战的士兵，足球队员不能叫步兵，应说“前锋”。"}, {"text": "草原上的步兵骑着马来回巡逻。", "explanation": "这里应该用〈骑兵〉。步兵是徒步作战的，骑马巡逻与此矛盾，应说骑兵。"}, {"text": "消防站的步兵每天都在训练救火。", "explanation": "这里应该用〈战士〉。步兵是陆军兵种，消防员不是步兵，应说“消防站的战士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "步兵", "is_correct": true, "explanation": "步兵：徒步作战的士兵，与“前面走过来一队”的语境相符。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：“走过来”指人或动物行走，火车不能走，一队火车也不说。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会走，“走过来一队石头”说不通。"}, {"text": "轮船", "is_correct": false, "explanation": "搭配：“走过来”不用于轮船，轮船只能说“开过来”。"}], "explanations": {"步兵": "步兵：徒步作战的士兵，与“前面走过来一队”的语境相符。", "火车": "搭配：“走过来”指人或动物行走，火车不能走，一队火车也不说。", "石头": "语义：石头不会走，“走过来一队石头”说不通。", "轮船": "搭配：“走过来”不用于轮船，轮船只能说“开过来”。"}, "sentence_index": 6, "correct_answer": "步兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校食堂里的步兵每天给我们做饭。", "explanation": "这里应该用〈厨师〉。步兵是徒步作战的士兵，在学校食堂做饭的人应说厨师。"}, {"text": "图书馆里的步兵正在安静地看书。", "explanation": "这里应该用〈读者〉。步兵是士兵，在图书馆看书的人应说读者。"}, {"text": "医院的步兵每天给病人看病。", "explanation": "这里应该用〈医生〉。步兵是徒步作战的士兵，给病人看病的人应说医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥大学毕业后去当了一匹步兵。", "corrected_sentence": "我表哥大学毕业后去当了一名步兵。", "error_description": "“步兵”指人，量词错用了“匹”（“匹”用于马等牲畜）。应改为“名”，即“一名步兵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "营地门口来了三名步兵们。", "corrected_sentence": "营地门口来了三名步兵。", "error_description": "“三名”这类数量词后面不能再加“们”，“们”与数量词重复。应去掉“们”，即“三名步兵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
