INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "徒步作战的士兵。", "primary_collocate": null, "pronunciation": "bù bīng", "ipa": "pu˥˩ piŋ˥", "syllable_count": 2, "sentences": [{"text": "步兵在山里和敌人打了一仗。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步兵拿着枪，慢慢向前走。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战场上，步兵跟着坦克一起前进。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有十万步兵。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步兵是陆军里人数最多的兵种。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步兵守住了桥，敌人过不来。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在战争中是一名勇敢的步兵。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "步兵要学会用枪，也要学会跑步。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的步兵从左边来了。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人曾经是步兵。", "target_word": "步兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名步兵", "label": "量词"}, {"form": "一队步兵", "label": "量词"}, {"form": "步兵团", "label": "复合词"}], "register": "中性", "sense_fingerprint": "徒步作战的士兵，陆军的一个兵种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "步兵", "is_correct": true, "explanation": "步兵：徒步作战的士兵，与“在山里和敌人打了一仗”的语境相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来旅游的人，不会去和敌人打仗。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁负责照料花草，不去和敌人打仗，句子说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不去和敌人打仗，句子说不通。"}], "explanations": {"步兵": "步兵：徒步作战的士兵，与“在山里和敌人打了一仗”的语境相符。", "游客": "语义：游客是来旅游的人，不会去和敌人打仗。", "园丁": "语义：园丁负责照料花草，不去和敌人打仗，句子说不通。", "厨师": "语义：厨师负责做饭，不去和敌人打仗，句子说不通。"}, "sentence_index": 0, "correct_answer": "步兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟在篮球队里当步兵，每场都得分。", "explanation": "这里应该用〈球员〉。步兵是徒步作战的士兵，篮球队员不能叫步兵，应说“球员”。"}, {"text": "草原上的步兵骑着马来回巡逻。", "explanation": "这里应该用〈骑兵〉。步兵是徒步作战的，不骑马，骑马巡逻的是骑兵。"}, {"text": "消防站的步兵冲进了火场。", "explanation": "这里应该用〈战士〉。步兵是陆军兵种，消防员不是步兵，应说“消防战士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "步兵", "is_correct": true, "explanation": "步兵：徒步作战的士兵，与“在战争中是一名勇敢的”的语境相符。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁负责照料花草，与战争无关，句子说不通。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师的工作是理发，不参与战争，句子说不通。"}, {"text": "会计", "is_correct": false, "explanation": "语义：会计负责记账，不参与战斗，句子说不通。"}], "explanations": {"步兵": "步兵：徒步作战的士兵，与“在战争中是一名勇敢的”的语境相符。", "园丁": "语义：园丁负责照料花草，与战争无关，句子说不通。", "理发师": "语义：理发师的工作是理发，不参与战争，句子说不通。", "会计": "语义：会计负责记账，不参与战斗，句子说不通。"}, "sentence_index": 6, "correct_answer": "步兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的步兵每天在操场上踢足球。", "explanation": "这里应该用〈学生〉。步兵是徒步作战的士兵，在操场踢球的人应说学生。"}, {"text": "医院的步兵每天给病人看病。", "explanation": "这里应该用〈医生〉。步兵是士兵，给病人看病的人应说医生。"}, {"text": "这家饭店的步兵每天都在厨房里做菜。", "explanation": "这里应该用〈厨师〉。步兵是士兵，在厨房做菜的人应说厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌人派来了一只步兵。", "corrected_sentence": "敌人派来了一队步兵。", "error_description": "“步兵”指人，量词错用了“只”（“只”用于动物）。应改为“队”，即“一队步兵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他带着三名勇敢的步兵们守住了桥。", "corrected_sentence": "他带着三名勇敢的步兵守住了桥。", "error_description": "“三名”这类数量词后面不能再加“们”，“们”与数量词重复。应去掉“们”，即“三名勇敢的步兵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
