INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一天天，一年年过去的时间。", "primary_collocate": null, "pronunciation": "suì yuè", "ipa": "swei˥˩ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "岁月一天天过去，爷爷的头发白了。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间像流水，岁月不会等人。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岁月悄悄地走了，孩子长大了。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脸上留下了岁月的痕迹。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岁月过得真快，转眼十年了。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都在岁月里慢慢变老。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岁月不饶人，爸爸跑不动了。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老照片让我想起过去的岁月。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水流走了，岁月也流走了。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岁月一年年过去，这棵树越长越高。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "歲月", "label": "繁体"}], "register": "书面", "sense_fingerprint": "指一天天、一年年不停流逝的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岁月", "is_correct": true, "explanation": "正确：“岁月”指一天天、一年年过去的时间，可以作主语，与“一天天过去”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是流逝的时间，不会“一天天过去”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开锁的工具，不指时间，“钥匙一天天过去”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是报酬，不是时间，这里说不通。"}], "explanations": {"岁月": "正确：“岁月”指一天天、一年年过去的时间，可以作主语，与“一天天过去”搭配。", "天气": "语义：“天气”不是流逝的时间，不会“一天天过去”。", "钥匙": "语义：“钥匙”是开锁的工具，不指时间，“钥匙一天天过去”说不通。", "工资": "语义：“工资”是报酬，不是时间，这里说不通。"}, "sentence_index": 0, "correct_answer": "岁月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约定的岁月是下午三点。", "explanation": "这里应该用〈时间〉。“岁月”指一天天、一年年流逝的漫长时光，不指约定好的某个时刻。"}, {"text": "他的岁月比我大两岁。", "explanation": "这里应该用〈年龄〉。说人比别人大几岁用“年龄”，“岁月”不表示人的年纪。"}, {"text": "他的岁月有一米八。", "explanation": "这里应该用〈身高〉。“岁月”指流逝的时间，不能表示人有多高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岁月", "is_correct": true, "explanation": "正确：“岁月不饶人”是常用说法，“岁月”指流逝的时间，催人变老。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会“饶人”，“不饶人”只用于时间或年纪。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不会催人变老，句中指的是时光对人的催促。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“不饶人”不搭配“课本”，只说时间、年纪这类事物。"}], "explanations": {"岁月": "正确：“岁月不饶人”是常用说法，“岁月”指流逝的时间，催人变老。", "手机": "语义：手机不会“饶人”，“不饶人”只用于时间或年纪。", "价格": "语义：价格不会催人变老，句中指的是时光对人的催促。", "课本": "搭配：“不饶人”不搭配“课本”，只说时间、年纪这类事物。"}, "sentence_index": 6, "correct_answer": "岁月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约好去岁月的超市买菜。", "explanation": "岁月是抽象的时间，不是可以前往或购物的地方，“岁月的超市”说不通。"}, {"text": "妈妈在厨房里炒岁月。", "explanation": "岁月不是具体的食材，“炒”只能用于能下锅的东西。"}, {"text": "他在超市买了岁月。", "explanation": "岁月是抽象的时间，不是商品，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们经历了一个岁月，才有今天的生活。", "corrected_sentence": "我们经历了一段岁月，才有今天的生活。", "error_description": "量词错误：指一段时间时，“岁月”的常用量词是“段”，“一个岁月”不自然。正确说法是“经历了一段岁月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "岁月们过得很快。", "corrected_sentence": "岁月过得很快。", "error_description": "词缀错误：“们”一般只加在指人的名词后面，不能加在“岁月”后。正确说法是“岁月过得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
