INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97794, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年月；泛指时间。", "primary_collocate": null, "pronunciation": "suì yuè", "ipa": "swei˥˩ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "那是一段艰苦的岁月。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在战争的岁月里，人们过得很苦。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在农村度过了难忘的岁月。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些年轻的岁月，我永远忘不了。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在大学里有一段快乐的岁月。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常讲她小时候的岁月。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个贫穷的岁月，大家都很节约。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把最好的岁月给了学校。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那段岁月里，我们住在小房子里。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休后，他在乡下度过了安静的岁月。", "target_word": "岁月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "歲月", "label": "繁体"}], "register": "书面", "sense_fingerprint": "泛指某一段年月、时期或时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岁月", "is_correct": true, "explanation": "正确：“一段艰苦的岁月”指一段困难的时期，“一段”与“岁月”搭配。"}, {"text": "岁数", "is_correct": false, "explanation": "语义：“岁数”指年纪，不指一段时期，“一段艰苦的岁数”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形，不能说“一段艰苦的身材”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是时期，不能用“艰苦”修饰。"}], "explanations": {"岁月": "正确：“一段艰苦的岁月”指一段困难的时期，“一段”与“岁月”搭配。", "岁数": "语义：“岁数”指年纪，不指一段时期，“一段艰苦的岁数”说不通。", "身材": "体貌：“身材”指体形，不能说“一段艰苦的身材”。", "手机": "语义：手机不是时期，不能用“艰苦”修饰。"}, "sentence_index": 0, "correct_answer": "岁月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约定的岁月是晚上八点。", "explanation": "这里应该用〈时间〉。“岁月”指一段时期，不指某个具体时刻，约定的是时刻。"}, {"text": "这份合同的岁月是三月五号。", "explanation": "这里应该用〈日期〉。“岁月”泛指较长的时间，不指某一天，说具体哪一天要用“日期”。"}, {"text": "她的岁月和我一样大。", "explanation": "这里应该用〈年龄〉。说人的年纪要用“年龄”或“岁数”，“岁月”不表示年纪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岁月", "is_correct": true, "explanation": "正确：“贫穷的岁月”指一段贫穷的时期，符合句中的时间背景。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“贫穷”修饰人或地区，不说“贫穷的工资”，应说“低工资”。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是身体部位，不能用“贫穷”修饰，也不指时期。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是时期，“在那个贫穷的空气”说不通。"}], "explanations": {"岁月": "正确：“贫穷的岁月”指一段贫穷的时期，符合句中的时间背景。", "工资": "搭配：“贫穷”修饰人或地区，不说“贫穷的工资”，应说“低工资”。", "眼睛": "体貌：“眼睛”是身体部位，不能用“贫穷”修饰，也不指时期。", "空气": "语义：空气不是时期，“在那个贫穷的空气”说不通。"}, "sentence_index": 6, "correct_answer": "岁月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把岁月搬进了新房子。", "explanation": "岁月是一段时期，不是物品，不能搬运，这里用法不对。"}, {"text": "她把岁月寄给了朋友。", "explanation": "岁月是抽象的时期，不是包裹，不能寄送。"}, {"text": "他在工厂里生产岁月。", "explanation": "岁月不是产品，不能生产，“生产”只用于具体的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她年轻时过了一个岁月。", "corrected_sentence": "她年轻时过了一段岁月。", "error_description": "量词错误：指一段时期时，“岁月”的常用量词是“段”，“一个岁月”不自然。正确说法是“过了一段岁月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在那段岁月的，他学会了很多东西。", "corrected_sentence": "在那段岁月，他学会了很多东西。", "error_description": "助词错误：“在那段岁月”作时间状语，后面不能加“的”。正确说法是“在那段岁月，他学会了很多东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
