INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由政治主张相同的人组成的团体。", "primary_collocate": null, "pronunciation": "dǎng pài", "ipa": "tɑŋ˨˩ pʰaɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这个党派的政治主张很清楚。", "target_word": "党派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有三个主要党派。", "target_word": "党派", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "各党派都派代表参加了会议。", "target_word": "党派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些党派在选举中互相竞争。", "target_word": "党派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个党派主张减少税收。", "target_word": "党派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新成立的党派得到了很多人支持。", "target_word": "党派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个党派对这个问题看法不同。", "target_word": "党派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个党派的领导人发表了讲话。", "target_word": "党派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个党派决定一起合作。", "target_word": "党派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "党派之间有时会发生争论。", "target_word": "党派", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个党派", "label": "量词"}, {"form": "民主党派", "label": "复合"}, {"form": "无党派", "label": "复合"}, {"form": "黨派", "label": "繁体"}], "register": "书面", "sense_fingerprint": "政治主张相同的人组成的正式团体，如参加选举的政党", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党派", "is_correct": true, "explanation": "正确：党派是持有政治主张的团体，与「这个」搭配，主张可以「很清楚」。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是场所，没有政治主张。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「政治主张」需要人或团体作主语，不能说「天气的政治主张」。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外形特征，不能持有政治主张。"}], "explanations": {"党派": "正确：党派是持有政治主张的团体，与「这个」搭配，主张可以「很清楚」。", "食堂": "语义：食堂是场所，没有政治主张。", "天气": "搭配：「政治主张」需要人或团体作主语，不能说「天气的政治主张」。", "身材": "体貌：身材是外形特征，不能持有政治主张。"}, "sentence_index": 0, "correct_answer": "党派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个政府的教育党派负责管理学校。", "explanation": "这里应该用〈机构〉。党派指由政治主张相同的人组成的团体，政府的教育机构不叫党派。"}, {"text": "学校的摄影党派每周活动一次。", "explanation": "这里应该用〈社团〉。党派指由政治主张相同的人组成的团体，摄影兴趣小组不叫党派。"}, {"text": "我们的生日党派很热闹。", "explanation": "这里应该用〈派对〉。党派是政治团体，生日聚会应说派对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党派", "is_correct": true, "explanation": "正确：党派是团体，各个党派可以对问题有不同看法，与「各个」搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮没有看法，不能「对这个问题看法不同」。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不持有看法，不能「对这个问题看法不同」。"}, {"text": "水", "is_correct": false, "explanation": "搭配：「水」是不可数名词，不能用「各个」修饰。"}], "explanations": {"党派": "正确：党派是团体，各个党派可以对问题有不同看法，与「各个」搭配。", "月亮": "语义：月亮没有看法，不能「对这个问题看法不同」。", "钥匙": "语义：钥匙不持有看法，不能「对这个问题看法不同」。", "水": "搭配：「水」是不可数名词，不能用「各个」修饰。"}, "sentence_index": 6, "correct_answer": "党派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是这个俱乐部的党派。", "explanation": "这里应该用〈成员〉。党派指团体本身，不指其中的个人。"}, {"text": "我们班的篮球党派每周训练三次。", "explanation": "这里应该用〈球队〉。党派指由政治主张相同的人组成的团体，篮球队不叫党派。"}, {"text": "这家党派生产了很多汽车。", "explanation": "这里应该用〈工厂〉。党派是政治团体，不是生产单位，不能说生产汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家有两所主要党派。", "corrected_sentence": "这个国家有两个主要党派。", "error_description": "量词错误：「所」用于学校、医院等机构，「党派」应用「个」计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各个党派们都希望减少税收。", "corrected_sentence": "各个党派都希望减少税收。", "error_description": "复数错误：「们」只加在指人的名词后，「党派」是团体名词，应去掉「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
