INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97809, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在上面的那一层。", "primary_collocate": null, "pronunciation": "shàng céng", "ipa": "ʂɑŋ˥˩ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "书放在书架的上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的房间在楼房的上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱的上层放着牛奶。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕的上层是白色的。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上层的床比下层的床好。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把箱子放到柜子的上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书架的上层太高，我拿不到。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水果放在盒子的上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条船的上层可以看海。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包店的上层是咖啡馆。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "上层：东西或房子中位置在上面的那一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是书架的一部分，书不能放在书架的冰箱里。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是房间，不属于书架的构成部分。"}, {"text": "上层", "is_correct": true, "explanation": "上层：指书架中位置在上面的那一层，与“书放在”搭配，符合句意。"}, {"text": "地面", "is_correct": false, "explanation": "搭配：“书架的地面”说法不通，地面不是书架的一部分。"}], "explanations": {"冰箱": "语义：“冰箱”不是书架的一部分，书不能放在书架的冰箱里。", "厨房": "语义：“厨房”是房间，不属于书架的构成部分。", "上层": "上层：指书架中位置在上面的那一层，与“书放在”搭配，符合句意。", "地面": "搭配：“书架的地面”说法不通，地面不是书架的一部分。"}, "sentence_index": 0, "correct_answer": "上层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的上层很有意思，值得读。", "explanation": "〈上层〉指有分层的东西的上面一层，文章没有这样的层次。这里想说“前面的部分”，应说〈开头〉。"}, {"text": "他的上层很痛，可能是昨天受凉了。", "explanation": "〈上层〉指物体分层中上面的一层，不用来指身体部位。这里应说〈上半身〉。"}, {"text": "这个杯子的上层很滑，我拿不住。", "explanation": "〈上层〉指有分层的东西的上面一层，杯子没有分层。指杯口应说〈杯口〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是书架的一部分，书架上不会有窗户。"}, {"text": "草地", "is_correct": false, "explanation": "语义：“草地”指地面上长草的地方，与书架的高度没有关系。"}, {"text": "杯子", "is_correct": false, "explanation": "搭配：“书架的杯子太高”说法不通，杯子高低不是书架的属性。"}, {"text": "上层", "is_correct": true, "explanation": "上层：指书架上面的一层，与“太高”“拿不到”的语境相符。"}], "explanations": {"窗户": "语义：“窗户”不是书架的一部分，书架上不会有窗户。", "草地": "语义：“草地”指地面上长草的地方，与书架的高度没有关系。", "杯子": "搭配：“书架的杯子太高”说法不通，杯子高低不是书架的属性。", "上层": "上层：指书架上面的一层，与“太高”“拿不到”的语境相符。"}, "sentence_index": 6, "correct_answer": "上层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个星期的上层很忙，我没有时间休息。", "explanation": "〈上层〉指分层东西的上面一层，不用来指时间。这里应说〈这个星期很忙〉。"}, {"text": "这次考试的上层很难，我没考好。", "explanation": "〈上层〉指分层东西的上面一层，考试没有层次。这里想说考试难，应说〈考试很难〉。"}, {"text": "他唱歌的上层很好听，大家都喜欢。", "explanation": "〈上层〉指有分层的东西上面的那一层，唱歌没有层次。这里想说声音好听，应说〈他唱歌很好听〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "衣服放在箱子的上层的。", "corrected_sentence": "衣服放在箱子的上层。", "error_description": "错误在句末多加了“的”：“箱子的上层”是完整的地点短语，句末不能加“的”，应说“放在箱子的上层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼的上层上很大。", "corrected_sentence": "这栋楼的上层很大。", "error_description": "“上层”本身已表示位置，后面不能再加“上”，应说“这栋楼的上层很大”，去掉多余的“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97810, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窗户", "is_correct": false, "explanation": "“窗户”是建筑部件，与“上层”的社会阶层义没有反义关系。"}, {"text": "下层", "is_correct": true, "explanation": "下层：指社会中地位低的阶层，与“上层”（社会上等阶层）相对，是这一义项的反义词。"}, {"text": "草地", "is_correct": false, "explanation": "“草地”指长草的地面，与社会阶层无关。"}, {"text": "墨水", "is_correct": false, "explanation": "“墨水”是书写用品，与“上层”没有反义关系。"}], "correct_answer": "下层", "explanations": {"窗户": "“窗户”是建筑部件，与“上层”的社会阶层义没有反义关系。", "下层": "下层：指社会中地位低的阶层，与“上层”（社会上等阶层）相对，是这一义项的反义词。", "草地": "“草地”指长草的地面，与社会阶层无关。", "墨水": "“墨水”是书写用品，与“上层”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97810, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "花园", "is_correct": false, "explanation": "“花园”是种植花草的地方，与“上层”没有反义关系。"}, {"text": "底层", "is_correct": true, "explanation": "底层：指社会中地位最低、没钱没权的阶层，与“上层”（社会上等阶层）相对，是这一义项的反义词。"}, {"text": "书包", "is_correct": false, "explanation": "“书包”是装书的用品，与“上层”没有反义关系。"}, {"text": "镜子", "is_correct": false, "explanation": "“镜子”是照人的用品，与“上层”没有反义关系。"}], "correct_answer": "底层", "explanations": {"花园": "“花园”是种植花草的地方，与“上层”没有反义关系。", "底层": "底层：指社会中地位最低、没钱没权的阶层，与“上层”（社会上等阶层）相对，是这一义项的反义词。", "书包": "“书包”是装书的用品，与“上层”没有反义关系。", "镜子": "“镜子”是照人的用品，与“上层”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会中地位高、有钱有权的阶层。", "primary_collocate": null, "pronunciation": "shàng céng", "ipa": "ʂɑŋ˥˩ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他家里的人都是社会的上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想进入上层，认识更多有钱人。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上层的人不一定比别人快乐。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的客人多是社会上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小生活在上层，没有吃过苦。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个圈子的成员大多来自上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个俱乐部只有上层的人才能加入。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上层的人和下层的人生活很不一样。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人努力工作，想成为社会的上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出身普通，却嫁进了上层。", "target_word": "上层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "上层：社会中地位高、有钱有权的阶层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然地理事物，不属于社会阶层。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是家居用品，“社会的地毯”不成立。"}, {"text": "上层", "is_correct": true, "explanation": "上层：指社会中地位高的阶层，与“社会的”搭配，符合句意。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“社会的树木”不是常见搭配，树木不指社会阶层。"}], "explanations": {"河流": "语义：“河流”是自然地理事物，不属于社会阶层。", "地毯": "语义：“地毯”是家居用品，“社会的地毯”不成立。", "上层": "上层：指社会中地位高的阶层，与“社会的”搭配，符合句意。", "树木": "搭配：“社会的树木”不是常见搭配，树木不指社会阶层。"}, "sentence_index": 0, "correct_answer": "上层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的头的上层很疼，可能是感冒了。", "explanation": "〈上层〉指物体分层中上面的一层，不用来指头部。指头顶应说〈头顶〉，这里应说〈头顶很疼〉。"}, {"text": "这个杯子的上层很滑，我拿不住。", "explanation": "〈上层〉指有分层的东西的上面一层，杯子没有分层。指杯口应说〈杯口〉。"}, {"text": "我们家的上层很有钱，经常出国。", "explanation": "〈上层〉指社会中地位高的阶层，不用于家庭成员。这里应该说〈父母〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：“花园”是种花草的地方，不指人，“花园的人”说不通。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：“镜子”是照人的用品，不能指一类人。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”指一顿饭，“早餐的人”说不通。"}, {"text": "上层", "is_correct": true, "explanation": "上层：指社会中地位高的阶层，“只有上层的人才能加入”与语境相符。"}], "explanations": {"花园": "语义：“花园”是种花草的地方，不指人，“花园的人”说不通。", "镜子": "语义：“镜子”是照人的用品，不能指一类人。", "早餐": "语义：“早餐”指一顿饭，“早餐的人”说不通。", "上层": "上层：指社会中地位高的阶层，“只有上层的人才能加入”与语境相符。"}, "sentence_index": 6, "correct_answer": "上层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的上层同学学习最好。", "explanation": "〈上层〉指社会中地位高的阶层，不用于班里的同学。这里应该说〈优等生〉。"}, {"text": "这家店的上层服务很好。", "explanation": "〈上层〉指社会阶层，不用于形容服务质量。这里应该说〈周到〉。"}, {"text": "这部电影的上层很好看，我想再看一遍。", "explanation": "〈上层〉指分层东西的上面一层或社会的上等阶层，不用来评价电影。这里应说〈这部电影很好看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的朋友大多是社会的上层们。", "corrected_sentence": "他的朋友大多是社会的上层。", "error_description": "“上层”本身表示一个阶层（集合），后面不能加“们”表示复数，应去掉“们”，说“社会的上层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他属于社会的很上层。", "corrected_sentence": "他属于社会的上层。", "error_description": "“上层”是名词，前面不能加“很”来修饰，应说“社会的上层”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
