INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97811, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从来没有做过某件事。", "primary_collocate": null, "pronunciation": "bù céng", "ipa": "pu˥˩ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我不曾去过北京。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不曾学过画画。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不曾坐过飞机。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从不曾吃过这种水果。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我不曾离开过爸爸妈妈。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不曾骑过马。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的比赛，我不曾参加过。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不曾养过小动物。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这之前，我不曾喝过茶。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不曾批评过他。", "target_word": "不曾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不曾……过", "label": "否定经历结构"}, {"form": "从不曾", "label": "强调否定"}], "register": "书面", "sense_fingerprint": "否定副词，表示说话人或某人从来没有亲身做过、经历过某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b59156-5839-4aea-8d08-252264446946') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不曾", "is_correct": true, "explanation": "“不曾”表示从未做过某事，与“去过北京”的经历意思相合。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“去过”表示的已完成经历不相合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将发生，与“去过北京”的已发生经历相冲突。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”表示时间短促，与“去过”表示的经历意思不符。"}], "explanations": {"不曾": "“不曾”表示从未做过某事，与“去过北京”的经历意思相合。", "正在": "体貌：“正在”表示动作进行中，与“去过”表示的已完成经历不相合。", "马上": "语义：“马上”表示即将发生，与“去过北京”的已发生经历相冲突。", "很快": "语义：“很快”表示时间短促，与“去过”表示的经历意思不符。"}, "sentence_index": 0, "correct_answer": "不曾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天不曾吃这种水果。", "explanation": "这里应该用〈不会〉。“不曾”只表示过去从未做过，不能用于“明天”。"}, {"text": "我每天不曾吃这种水果。", "explanation": "这里应该用〈从不〉。“不曾”只说过去从未有过的经历，描述习惯要说从不。"}, {"text": "请你不曾吃这种水果。", "explanation": "这里应该用〈别〉。“不曾”只陈述过去的事实，不能用来提出请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不曾", "is_correct": true, "explanation": "“不曾”表示从未参加过某类比赛，符合“这样的比赛”的语境。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“参加过”表示的已完成经历不相合。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上，与“参加过”表示的已有经历相冲突。"}, {"text": "打算", "is_correct": false, "explanation": "体貌：“打算”指将来要做的事，不能与表示已有经历的“参加过”连用。"}], "explanations": {"不曾": "“不曾”表示从未参加过某类比赛，符合“这样的比赛”的语境。", "正在": "体貌：“正在”表示动作进行中，与“参加过”表示的已完成经历不相合。", "立即": "语义：“立即”表示马上，与“参加过”表示的已有经历相冲突。", "打算": "体貌：“打算”指将来要做的事，不能与表示已有经历的“参加过”连用。"}, "sentence_index": 6, "correct_answer": "不曾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师明年不曾批评他。", "explanation": "这里应该用〈将〉。“不曾”只说过去从未做过，指明年的事要用将。"}, {"text": "老师下星期不曾批评他。", "explanation": "这里应该用〈要〉。“不曾”只说过去从未做过，指下星期的事要用要。"}, {"text": "老师过几天不曾批评他。", "explanation": "这里应该用〈会〉。“不曾”只说过去从未做过，将来的事要用会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从不曾坐船过。", "corrected_sentence": "他从不曾坐过船。", "error_description": "体标错误：“过”应紧跟动词“坐”之后，说“坐过船”，不能放在宾语“船”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她不曾养着宠物。", "corrected_sentence": "她不曾养过宠物。", "error_description": "体标错误：“不曾”表示从未有过的经历，应与“过”搭配，说“养过”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
