INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97813, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一辈传一辈，每一辈人叫一代。", "primary_collocate": null, "pronunciation": "shì dài", "ipa": "ʂʐ̩˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他们家世代住在这个小村子里。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门手艺在我家传了好几个世代。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王家世代都是农民。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的人世代种茶。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个世代的人想法不一样。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家世代做面包。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地世代属于我们家。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们世代生活在海边。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，三个世代的人住在一起。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树见过很多个世代的人。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一辈接一辈，每一辈人是一个世代；常作状语，表示家族长期如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世代", "is_correct": true, "explanation": "目标词“世代”（shì dài），指一代一代传下来的每一辈人。"}, {"text": "时代", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“时代”，指一个历史时期。"}, {"text": "事态", "is_correct": false, "explanation": "dài 与 tài 声母不同（d/t），意思是“事态”，指事情的发展状况。"}, {"text": "适当", "is_correct": false, "explanation": "dàng 与 dài 韵母不同（-ang/-ai），意思是“适当”，指合适、恰当。"}], "explanations": {"世代": "目标词“世代”（shì dài），指一代一代传下来的每一辈人。", "时代": "shí（第二声）与 shì（第四声）声调不同，意思是“时代”，指一个历史时期。", "事态": "dài 与 tài 声母不同（d/t），意思是“事态”，指事情的发展状况。", "适当": "dàng 与 dài 韵母不同（-ang/-ai），意思是“适当”，指合适、恰当。"}, "sentence_index": null, "correct_answer": "世代"}, "level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "正确：“他们家世代住在这个小村子里”表示一代代都住在这里。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市很大，不能住在这个小村子里，这里说不通。"}, {"text": "国家", "is_correct": false, "explanation": "语义：国家不能住在村子里，这个说法荒谬。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“住”的主语须是人或动物，“年代”是时间，不能作“住”的主语。"}], "explanations": {"世代": "正确：“他们家世代住在这个小村子里”表示一代代都住在这里。", "城市": "语义：城市很大，不能住在这个小村子里，这里说不通。", "国家": "语义：国家不能住在村子里，这个说法荒谬。", "年代": "搭配：“住”的主语须是人或动物，“年代”是时间，不能作“住”的主语。"}, "sentence_index": 0, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子在一九八五年世代通了电。", "explanation": "这里应去掉“世代”，改用“才”。“世代”指一代代的人，不能用来表示某一年发生的一次性事件。"}, {"text": "他世代在这家公司工作了三十年。", "explanation": "这里应去掉“世代”。“世代”指一代代的人，不能用来描述某一个人的工作经历。"}, {"text": "这家店世代开了三年。", "explanation": "这里应去掉“世代”，只说“开了三年”。“世代”按代计算，不能直接与具体年数搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "正确：“这块地世代属于我们家”表示这块地代代都是我家的。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节不能属于某户人家，这里说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能修饰“属于我们家”，这里说不通。"}, {"text": "时光", "is_correct": false, "explanation": "语义：“时光”不能表示“一代一代地”，放在这里句意不通。"}], "explanations": {"世代": "正确：“这块地世代属于我们家”表示这块地代代都是我家的。", "季节": "语义：季节不能属于某户人家，这里说不通。", "桌子": "语义：桌子是物品，不能修饰“属于我们家”，这里说不通。", "时光": "语义：“时光”不能表示“一代一代地”，放在这里句意不通。"}, "sentence_index": 6, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子的世代增加了很多。", "explanation": "这里应该用“人口”。“世代”指一代代的人，不能说人数增加，要说“人口增加”。"}, {"text": "我每天给世代浇水。", "explanation": "这里“浇水”的对象应是植物，“世代”不能被浇水，应说“给花浇水”。"}, {"text": "老师的世代很严格。", "explanation": "这里应该用“作风”。“世代”指一代代的人，不能用来描述某个人的作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个山谷里住着三只世代的人。", "corrected_sentence": "这个山谷里住着三个世代的人。", "error_description": "量词错误：“世代”应用量词“个”，“只”用于动物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片果园传了三座世代。", "corrected_sentence": "这片果园传了三个世代。", "error_description": "量词错误：“世代”应用量词“个”，“座”用于建筑、山等，不能用来数“世代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
