INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世系的辈分；一个时期一代又一代。", "primary_collocate": null, "pronunciation": "shì dài", "ipa": "ʂʐ̩˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个故事世代相传，大家都知道。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座老房子世代相传，没有卖过。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的人世代靠打鱼生活。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世代相传的好习惯不能忘。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人世代都爱读书。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片山林世代有人保护。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家世代当老师。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的老照片世代保存着。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种歌世代流传，现在还有人唱。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要让好传统世代传下去。", "target_word": "世代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一代又一代地延续，多说传承、流传、延续的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世代", "is_correct": true, "explanation": "目标词“世代”（shì dài），指一代又一代地延续。"}, {"text": "时代", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“时代”，指一个历史时期。"}, {"text": "事态", "is_correct": false, "explanation": "dài 与 tài 声母不同（d/t），意思是“事态”，指事情的发展状况。"}, {"text": "四代", "is_correct": false, "explanation": "sì（第四声）与 shì（第四声）声母不同（s/sh），意思是“四代”。"}], "explanations": {"世代": "目标词“世代”（shì dài），指一代又一代地延续。", "时代": "shí（第二声）与 shì（第四声）声调不同，意思是“时代”，指一个历史时期。", "事态": "dài 与 tài 声母不同（d/t），意思是“事态”，指事情的发展状况。", "四代": "sì（第四声）与 shì（第四声）声母不同（s/sh），意思是“四代”。"}, "sentence_index": null, "correct_answer": "世代"}, "level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "正确：“这个故事世代相传”表示一代代流传下来。"}, {"text": "时期", "is_correct": false, "explanation": "语义：“时期”是时间段，不能“相传”。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节是时段，不能“相传”，这里说不通。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：“辈分”是亲属的排行，不能作为故事被相传。"}], "explanations": {"世代": "正确：“这个故事世代相传”表示一代代流传下来。", "时期": "语义：“时期”是时间段，不能“相传”。", "季节": "语义：季节是时段，不能“相传”，这里说不通。", "辈分": "语义：“辈分”是亲属的排行，不能作为故事被相传。"}, "sentence_index": 0, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天世代相传了这个故事。", "explanation": "这里应该用“讲”。“世代相传”指一代代延续，不能用于一次性的动作。"}, {"text": "我的新手机是世代相传的。", "explanation": "这里应该用“买的”。“世代相传”只用于代代留下的东西，不能用于刚买的新东西。"}, {"text": "我一个人世代相传了这首歌。", "explanation": "这里应去掉“世代相传”，改用“唱”。“世代相传”指一代代延续，不能用来描述一个人的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "正确：“他家世代当老师”表示家里代代都是老师。"}, {"text": "班级", "is_correct": false, "explanation": "语义：班级是集体，不能“当老师”，这里说不通。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是机构，不能“当老师”，这里说不通。"}, {"text": "工资", "is_correct": false, "explanation": "配价：“当”需要人作主语，“工资”不能当老师。"}], "explanations": {"世代": "正确：“他家世代当老师”表示家里代代都是老师。", "班级": "语义：班级是集体，不能“当老师”，这里说不通。", "学校": "语义：学校是机构，不能“当老师”，这里说不通。", "工资": "配价：“当”需要人作主语，“工资”不能当老师。"}, "sentence_index": 6, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要让这次考试世代传下去。", "explanation": "这里“传下去”的对象应是传统、习惯等，“考试”是一次性事件，不能世代传下去。"}, {"text": "我们要让这个月世代传下去。", "explanation": "这里“传下去”的对象应是传统、习惯等，“这个月”是时间，不能世代传下去。"}, {"text": "我们要让三天的假期世代传下去。", "explanation": "这里“世代”的对象应是传统、习惯等，“假期”是短期的时间段，不能世代传下去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
