INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97815, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数字，比四十多十个。", "primary_collocate": null, "pronunciation": "wǔ shí", "ipa": "u˨˩˦ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这个数字是五十。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "四十加十等于五十。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "五十是一个两位数。", "target_word": "五十", "complexity_tier": "T3", "furigana": "wǔ shí shì yí gè liǎng wèi shù。", "sentence_source": "generated"}, {"text": "五十比四十多十。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请从一数到五十。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "五十的个位是零。", "target_word": "五十", "complexity_tier": "T3", "furigana": "wǔ shí de gè wèi shì líng。", "sentence_source": "generated"}, {"text": "五十是偶数。", "target_word": "五十", "complexity_tier": "T3", "furigana": "wǔ shí shì ǒu shù。", "sentence_source": "generated"}, {"text": "他在纸上写了五十。", "target_word": "五十", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "五十的后面是五十一。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "九十减四十是五十。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作为数字的五十，比四十大十", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97815, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "五十", "is_correct": true, "explanation": "正确答案。五十（wǔ shí）是数字五十，比四十大十。"}, {"text": "武士", "is_correct": false, "explanation": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是武士。"}, {"text": "舞狮", "is_correct": false, "explanation": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是舞狮表演。"}, {"text": "务实", "is_correct": false, "explanation": "wù shí 与 wǔ shí 只有第一个音节声调不同（第四声），意思是务实。"}, {"text": "无事", "is_correct": false, "explanation": "wú shì 与 wǔ shí 两个音节的声调都不同，意思是没有事情。"}], "explanations": {"五十": "正确答案。五十（wǔ shí）是数字五十，比四十大十。", "武士": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是武士。", "舞狮": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是舞狮表演。", "务实": "wù shí 与 wǔ shí 只有第一个音节声调不同（第四声），意思是务实。", "无事": "wú shì 与 wǔ shí 两个音节的声调都不同，意思是没有事情。"}, "sentence_index": null, "correct_answer": "五十"}, "level_3": {"options": [{"text": "五十", "is_correct": true, "explanation": "数字五十正是该句中的值，句子成立。"}, {"text": "星期五", "is_correct": false, "explanation": "语义：“星期五”是日子，不是数目，“这个数字是星期五”不成立。"}, {"text": "五楼", "is_correct": false, "explanation": "语义：“五楼”指楼层，不能作为数字的值。"}, {"text": "五岁", "is_correct": false, "explanation": "搭配：“岁”只用于人或动物的年龄，不能说数字是“五岁”。"}], "explanations": {"五十": "数字五十正是该句中的值，句子成立。", "星期五": "语义：“星期五”是日子，不是数目，“这个数字是星期五”不成立。", "五楼": "语义：“五楼”指楼层，不能作为数字的值。", "五岁": "搭配：“岁”只用于人或动物的年龄，不能说数字是“五岁”。"}, "sentence_index": 0, "correct_answer": "五十"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今年五十岁，还在上小学一年级。", "explanation": "这里应该用〈六〉。小学一年级学生通常六七岁，“五十”指五十岁，与语境不符。"}, {"text": "我今年十五岁，妈妈比我大二十五岁，所以妈妈今年五十岁。", "explanation": "这里应该用〈四十〉。十五加二十五等于四十，妈妈应是四十岁，“五十”与前面的年龄不符。"}, {"text": "这台电脑原价五十块，打五折后只要二百五十块。", "explanation": "这里应该用〈五百〉。原价五百块打五折是二百五十块，“五十”与后面的价格不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97815, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "五十", "is_correct": true, "explanation": "正确答案。五十（wǔ shí）是数字五十。"}, {"text": "武师", "is_correct": false, "explanation": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是武术教练。"}, {"text": "巫师", "is_correct": false, "explanation": "wū shī 与 wǔ shí 两个音节的声调都不同，意思是巫师。"}, {"text": "午市", "is_correct": false, "explanation": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是午餐时段的营业。"}], "explanations": {"五十": "正确答案。五十（wǔ shí）是数字五十。", "武师": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是武术教练。", "巫师": "wū shī 与 wǔ shí 两个音节的声调都不同，意思是巫师。", "午市": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是午餐时段的营业。"}, "sentence_index": null, "correct_answer": "五十"}, "level_3": {"options": [{"text": "五十", "is_correct": true, "explanation": "五十是偶数，符合句子的意思。"}, {"text": "奇数", "is_correct": false, "explanation": "语义：“奇数”与句中的“偶数”互相矛盾，“奇数是偶数”不成立。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：“星期三”是日期，不是数，不能说是偶数。"}, {"text": "五块", "is_correct": false, "explanation": "搭配：“块”是货币量词，“五块”指钱的数额，不能作为数字的值。"}], "explanations": {"五十": "五十是偶数，符合句子的意思。", "奇数": "语义：“奇数”与句中的“偶数”互相矛盾，“奇数是偶数”不成立。", "星期三": "语义：“星期三”是日期，不是数，不能说是偶数。", "五块": "搭配：“块”是货币量词，“五块”指钱的数额，不能作为数字的值。"}, "sentence_index": 6, "correct_answer": "五十"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今年五十岁，比哥哥大三岁，哥哥今年二十岁。", "explanation": "这里应该用〈二十三〉。哥哥二十岁，我比他大三岁，应是二十三岁，“五十”与此不符。"}, {"text": "这支笔只要五十块钱，我买了两支，一共花了十块钱。", "explanation": "这里应该用〈五〉。两支共十块，每支应是五块，“五十”与“一共花了十块”矛盾。"}, {"text": "我刚刚大学毕业，今年才五十岁。", "explanation": "这里应该用〈二十二〉。“刚刚大学毕业”说明年龄很轻，应是二十二岁左右，“五十”与语境不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸今年五十岁多了。", "corrected_sentence": "我爸爸今年五十多岁了。", "error_description": "错误：“五十岁多”；正确：“五十多岁”。表示“比五十多一些”时，“多”要紧跟在“五十”后面，放在“岁”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
