INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数目，四十加十。", "primary_collocate": null, "pronunciation": "wǔ shí", "ipa": "u˨˩˦ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "教室里有五十个学生。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服卖五十块。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我走了五十分钟。", "target_word": "五十", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家离学校有五十米。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸给了我五十块钱。", "target_word": "五十", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一共买了五十张票。", "target_word": "五十", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店今天卖出了五十本书。", "target_word": "五十", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上有五十个苹果。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路有五十公里长。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司有五十个工人。", "target_word": "五十", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示数量的五十，即四十加十", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generat