INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "五十", "is_correct": true, "explanation": "正确答案。五十（wǔ shí）表示数目，即四十加十。"}, {"text": "武师", "is_correct": false, "explanation": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是武术教练。"}, {"text": "务实", "is_correct": false, "explanation": "wù shí 与 wǔ shí 只有第一个音节声调不同（第四声），意思是务实。"}, {"text": "无事", "is_correct": false, "explanation": "wú shì 与 wǔ shí 两个音节的声调都不同，意思是没有事情。"}, {"text": "巫师", "is_correct": false, "explanation": "wū shī 与 wǔ shí 两个音节的声调都不同，意思是巫师。"}], "explanations": {"五十": "正确答案。五十（wǔ shí）表示数目，即四十加十。", "武师": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是武术教练。", "务实": "wù shí 与 wǔ shí 只有第一个音节声调不同（第四声），意思是务实。", "无事": "wú shì 与 wǔ shí 两个音节的声调都不同，意思是没有事情。", "巫师": "wū shī 与 wǔ shí 两个音节的声调都不同，意思是巫师。"}, "sentence_index": null, "correct_answer": "五十"}, "level_3": {"options": [{"text": "五十", "is_correct": true, "explanation": "“五十”表示人数，与“学生”和“个”搭配，句子成立。"}, {"text": "五万", "is_correct": false, "explanation": "语义：一间教室容不下五万个学生，“教室里有五万个学生”不合常理。"}, {"text": "一亿", "is_correct": false, "explanation": "语义：“一亿”远超教室的容量，与“教室里”的场景矛盾。"}, {"text": "半", "is_correct": false, "explanation": "搭配：“半”不能修饰成群的人，“半个学生”不能表示教室里的人数。"}], "explanations": {"五十": "“五十”表示人数，与“学生”和“个”搭配，句子成立。", "五万": "语义：一间教室容不下五万个学生，“教室里有五万个学生”不合常理。", "一亿": "语义：“一亿”远超教室的容量，与“教室里”的场景矛盾。", "半": "搭配：“半”不能修饰成群的人，“半个学生”不能表示教室里的人数。"}, "sentence_index": 0, "correct_answer": "五十"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段路很短，我走了五十分钟就到了。", "explanation": "这里应该用〈十五〉。“很短”说明只需十五分钟左右，“五十”指五十分钟，与语境不符。"}, {"text": "这种橡皮只要五十块钱，我买了两块，一共花了十块钱。", "explanation": "这里应该用〈五〉。两块共十块，每块应是五块，“五十”与“一共花了十块”矛盾。"}, {"text": "我们班有五十个学生，正好坐满四十把椅子。", "explanation": "这里应该用〈四十〉。“正好坐满”说明学生与椅子数相同，应是四十人，“五十”与“四十把椅子”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97816, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "五十", "is_correct": true, "explanation": "正确答案。五十（wǔ shí）表示数目，即四十加十。"}, {"text": "武士", "is_correct": false, "explanation": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是武士。"}, {"text": "舞狮", "is_correct": false, "explanation": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是舞狮表演。"}, {"text": "午市", "is_correct": false, "explanation": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是午餐时段的营业。"}], "explanations": {"五十": "正确答案。五十（wǔ shí）表示数目，即四十加十。", "武士": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是武士。", "舞狮": "wǔ shī 与 wǔ shí 只有第二个音节声调不同（第一声），意思是舞狮表演。", "午市": "wǔ shì 与 wǔ shí 只有第二个音节声调不同（第四声），意思是午餐时段的营业。"}, "sentence_index": null, "correct_answer": "五十"}, "level_3": {"options": [{"text": "五十", "is_correct": true, "explanation": "“五十”表示数量，与“本”和“书”搭配，句子成立。"}, {"text": "书包", "is_correct": false, "explanation": "语法：“书包”是名词，不能放在“本书”前面表示数量，“卖出了书包本书”不成立。"}, {"text": "三分之一", "is_correct": false, "explanation": "搭配：“书”以整本计，不能说卖出了“三分之一本书”。"}, {"text": "一千亿", "is_correct": false, "explanation": "语义：一家书店一天不可能卖出一千亿本书，与句子的常识矛盾。"}], "explanations": {"五十": "“五十”表示数量，与“本”和“书”搭配，句子成立。", "书包": "语法：“书包”是名词，不能放在“本书”前面表示数量，“卖出了书包本书”不成立。", "三分之一": "搭配：“书”以整本计，不能说卖出了“三分之一本书”。", "一千亿": "语义：一家书店一天不可能卖出一千亿本书，与句子的常识矛盾。"}, "sentence_index": 6, "correct_answer": "五十"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个箱子各重二十公斤，一共是五十公斤。", "explanation": "这里应该用〈四十〉。二十加二十等于四十，“五十”与前面的重量不符。"}, {"text": "班里有三十个人，还有三十个人没来，所以全班有五十人。", "explanation": "这里应该用〈六十〉。三十加三十等于六十，“五十”与前面的人数不符。"}, {"text": "我刚刚大学毕业，今年才五十岁。", "explanation": "这里应该用〈二十二〉。“刚刚大学毕业”说明年龄很轻，应是二十二岁左右，“五十”与语境不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来参加的有五十条人左右。", "corrected_sentence": "来参加的有五十人左右。", "error_description": "错误：“五十条人”；正确：“五十人”。“条”用于细长的东西，不能用来计算人，人数直接说“五十人”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书店今天卖出了五十本多书。", "corrected_sentence": "书店今天卖出了五十多本书。", "error_description": "错误：“五十本多书”；正确：“五十多本书”。表示“超过五十”时，“多”要紧跟在“五十”后面，放在量词“本”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
