INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97823, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻碍", "is_correct": true, "explanation": "反义：“阻碍”是阻挡使不顺利，与“使做起来方便”相反。"}, {"text": "完成", "is_correct": false, "explanation": "完成是做成某事，与“使做起来方便”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究是深入探讨，与“使做起来方便”没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集是聚集材料，与“使做起来方便”没有反义关系。"}], "correct_answer": "阻碍", "explanations": {"阻碍": "反义：“阻碍”是阻挡使不顺利，与“使做起来方便”相反。", "完成": "完成是做成某事，与“使做起来方便”没有反义关系。", "研究": "研究是深入探讨，与“使做起来方便”没有反义关系。", "收集": "收集是聚集材料，与“使做起来方便”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97823, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使做起来方便。", "primary_collocate": null, "pronunciation": "biàn yú", "ipa": "pjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这种小书包便于携带。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子放在门口，便于大家拿东西。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把名字写在书上，便于找到自己的书。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里有地图，便于我们找路。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里放一个大钟，便于看时间。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样分开放，便于以后找东西。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每人一个号，便于记名字。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店开在车站旁边，便于坐车的人买水。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上写着电话，便于客人联系。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个本子很薄，便于放进口袋里。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "便於", "label": "繁体"}], "register": "通用", "sense_fingerprint": "动词，后面接动作，表示这样安排或设计使做某事更方便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便于", "is_correct": true, "explanation": "便于：表示使携带方便，与“小书包”的用途相符。"}, {"text": "妨碍", "is_correct": false, "explanation": "语义：“妨碍”是阻碍，与“小书包便于携带”的意思相反。"}, {"text": "善于", "is_correct": false, "explanation": "搭配：“善于”要求人作主语，不能说“书包善于携带”。"}, {"text": "防止", "is_correct": false, "explanation": "语义：“防止”是预先阻止，说书包防止携带与常识相悖。"}], "explanations": {"便于": "便于：表示使携带方便，与“小书包”的用途相符。", "妨碍": "语义：“妨碍”是阻碍，与“小书包便于携带”的意思相反。", "善于": "搭配：“善于”要求人作主语，不能说“书包善于携带”。", "防止": "语义：“防止”是预先阻止，说书包防止携带与常识相悖。"}, "sentence_index": 0, "correct_answer": "便于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试很难，便于大家顺利通过。", "explanation": "这里应该用〈妨碍〉。便于表示使做起来方便，与“很难”矛盾；使事情变得困难要用妨碍。"}, {"text": "这台机器太复杂，便于大家操作。", "explanation": "这里应该用〈不便于〉。便于表示使做起来方便，与“太复杂”矛盾；使操作变难要用不便于。"}, {"text": "这里的交通很拥挤，便于大家出行。", "explanation": "这里应该用〈阻碍〉。便于表示使做起来方便，与“很拥挤”矛盾；使大家出行变难要用阻碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便于", "is_correct": true, "explanation": "便于：表示使记名字方便，与“给每人一个号”的目的相符。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止记名字”与“给号”的目的相反，句意不通。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止记名字”与“给号”是为了帮助记忆的意图相悖。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”多接请求、邀请等，不说“拒绝记名字”。"}], "explanations": {"便于": "便于：表示使记名字方便，与“给每人一个号”的目的相符。", "禁止": "语义：“禁止记名字”与“给号”的目的相反，句意不通。", "阻止": "语义：“阻止记名字”与“给号”是为了帮助记忆的意图相悖。", "拒绝": "搭配：“拒绝”多接请求、邀请等，不说“拒绝记名字”。"}, "sentence_index": 6, "correct_answer": "便于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很危险，便于大家通行。", "explanation": "这里应该用〈禁止〉。便于表示使做起来方便，与“很危险”矛盾；不让人通行要用禁止。"}, {"text": "这场比赛非常紧张，便于选手放松。", "explanation": "这里应该用〈不利于〉。便于表示使做起来方便，与“非常紧张”矛盾；使选手难以放松要用不利于。"}, {"text": "这个操作比那个更繁琐，便于大家学习。", "explanation": "这里应该用〈妨碍〉。便于表示使做起来方便，与“更繁琐”矛盾；使大家学习变难要用妨碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盒子很小，便于了装东西。", "corrected_sentence": "这个盒子很小，便于装东西。", "error_description": "错误：“了”插在“便于”和后面的动词之间。“便于”后应直接接动词“装”，不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
