INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有利于做某事；容易。", "primary_collocate": null, "pronunciation": "biàn yú", "ipa": "pjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这种字很简单，便于小孩子学习。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河边有路，便于大家散步。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用图片来讲故事，便于孩子记住。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些词放在一起，便于比较。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在地铁站附近，便于上班的人来去。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔记写清楚，便于考试前复习。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机付钱，便于出门买东西。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户很大，便于看外面的风景。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家具都有轮子，便于搬动。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把窗户打开，便于通风。", "target_word": "便于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "便於", "label": "繁体"}], "register": "通用", "sense_fingerprint": "动词，后面接动作，表示条件有利，做某事比较容易", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便于", "is_correct": true, "explanation": "便于：表示做某事容易，与“这种字很简单”和“小孩子学习”相符。"}, {"text": "妨碍", "is_correct": false, "explanation": "语义：“妨碍”是阻碍，与“字很简单”的前提矛盾。"}, {"text": "阻挠", "is_correct": false, "explanation": "语义：“阻挠”是故意使人不能顺利进行，与“很简单”的前提矛盾。"}, {"text": "忙于", "is_correct": false, "explanation": "搭配：“忙于”要求人作主语，不能说“字忙于小孩子学习”。"}], "explanations": {"便于": "便于：表示做某事容易，与“这种字很简单”和“小孩子学习”相符。", "妨碍": "语义：“妨碍”是阻碍，与“字很简单”的前提矛盾。", "阻挠": "语义：“阻挠”是故意使人不能顺利进行，与“很简单”的前提矛盾。", "忙于": "搭配：“忙于”要求人作主语，不能说“字忙于小孩子学习”。"}, "sentence_index": 0, "correct_answer": "便于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题很难，便于大家做出来。", "explanation": "这里应该用〈妨碍〉。便于表示使做起来容易，与“很难”矛盾；使大家难以做出来要用妨碍。"}, {"text": "这个方案很复杂，便于大家理解。", "explanation": "这里应该用〈不便于〉。便于表示使做起来容易，与“很复杂”矛盾；使理解变难要用不便于。"}, {"text": "这间屋子很吵，便于大家休息。", "explanation": "这里应该用〈阻碍〉。便于表示使做起来容易，与“很吵”矛盾；使大家休息变难要用阻碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便于", "is_correct": true, "explanation": "便于：表示出门买东西方便，与“用手机付钱”的好处相符。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍出门买东西”与“用手机付钱”的好处相反。"}, {"text": "阻挡", "is_correct": false, "explanation": "语义：“阻挡”是挡住，与“用手机付钱”的好处矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”多接请求、邀请等，不说“拒绝出门买东西”。"}], "explanations": {"便于": "便于：表示出门买东西方便，与“用手机付钱”的好处相符。", "阻碍": "语义：“阻碍出门买东西”与“用手机付钱”的好处相反。", "阻挡": "语义：“阻挡”是挡住，与“用手机付钱”的好处矛盾。", "拒绝": "搭配：“拒绝”多接请求、邀请等，不说“拒绝出门买东西”。"}, "sentence_index": 6, "correct_answer": "便于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只箱子很重，人根本抬不起来，便于搬动。", "explanation": "这里应该用〈无法〉。便于表示使做起来方便，与“根本抬不起来”矛盾；搬不动要用无法。"}, {"text": "这份工作压力很大，便于员工休息。", "explanation": "这里应该用〈不利于〉。便于表示使做起来方便，与“压力很大”矛盾；使员工难以休息要用不利于。"}, {"text": "这个流程比那个更繁琐，便于大家学会。", "explanation": "这里应该用〈妨碍〉。便于表示做某事容易，与“更繁琐”矛盾；使大家学会变难要用妨碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
