INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97827, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情藏在心里，不让别人知道。", "primary_collocate": null, "pronunciation": "bǎo mì", "ipa": "pɑu˨˩˦ mi˥˩", "syllable_count": 2, "sentences": [{"text": "这件事你要替我保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她答应过我，会一直保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生日礼物，现在要保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先别问，这是个秘密，我得保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友的难处一直保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟说他有个计划，但是要保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事关系到他的名誉，我们应当为他保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对家人保密了很久。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，我肯定保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想给妻子一个惊喜，所以对她保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保密了", "label": "体标（了）"}, {"form": "对……保密", "label": "常见结构"}], "register": "口语", "sense_fingerprint": "个人之间答应或打算把某件事藏在心里、不对别人说（朋友、家人之间）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b59156-5839-4aea-8d08-252264446946') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保密", "is_correct": true, "explanation": "“保密”表示把事情藏在心里，符合“替我”守住事情的请求。"}, {"text": "泄露", "is_correct": false, "explanation": "语义：“泄露”指秘密外传，与“替我”守住秘密的请求正好相反。"}, {"text": "散布", "is_correct": false, "explanation": "语义：“散布”多指传播消息，与替朋友守住这件事的意思相反。"}, {"text": "拍照", "is_correct": false, "explanation": "搭配：“拍照”不能搭配“这件事”作宾语。"}], "explanations": {"保密": "“保密”表示把事情藏在心里，符合“替我”守住事情的请求。", "泄露": "语义：“泄露”指秘密外传，与“替我”守住秘密的请求正好相反。", "散布": "语义：“散布”多指传播消息，与替朋友守住这件事的意思相反。", "拍照": "搭配：“拍照”不能搭配“这件事”作宾语。"}, "sentence_index": 0, "correct_answer": "保密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈保密了晚饭。", "explanation": "这里应该用〈准备〉。保密指守住秘密，不能用于晚饭；做晚饭要用准备。"}, {"text": "他保密了水管。", "explanation": "这里应该用〈修理〉。保密指守住秘密，不能用于水管；修水管要用修理。"}, {"text": "她每天保密生病的爷爷。", "explanation": "这里应该用〈照顾〉。保密针对的是秘密，不能以人作对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保密", "is_correct": true, "explanation": "“保密”表示不让别人知道，符合“我们应当为他”守住名誉相关事情的语境。"}, {"text": "张扬", "is_correct": false, "explanation": "语义：“张扬”指炫耀、外露，与“关系到他的名誉”需要保护的意思相反。"}, {"text": "造谣", "is_correct": false, "explanation": "语义：“造谣”是捏造谣言，与维护他的名誉的意思正好相反。"}, {"text": "说出", "is_correct": false, "explanation": "配价：“说出”需要带所说的内容作宾语，句末缺少宾语。"}], "explanations": {"保密": "“保密”表示不让别人知道，符合“我们应当为他”守住名誉相关事情的语境。", "张扬": "语义：“张扬”指炫耀、外露，与“关系到他的名誉”需要保护的意思相反。", "造谣": "语义：“造谣”是捏造谣言，与维护他的名誉的意思正好相反。", "说出": "配价：“说出”需要带所说的内容作宾语，句末缺少宾语。"}, "sentence_index": 6, "correct_answer": "保密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫决定保密了。", "explanation": "这里应该用〈躲〉。保密指人守住秘密，猫的动作应说躲起来。"}, {"text": "我们保密了这座桥。", "explanation": "这里应该用〈修建〉。保密指守住秘密，不能以桥为对象；建桥要用修建。"}, {"text": "他每天保密一份报纸。", "explanation": "这里应该用〈订阅〉。保密指守住消息秘密，报纸要说订阅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直我们保密。", "corrected_sentence": "她一直对我们保密。", "error_description": "介词错误：“保密”的对象（被瞒的人）须用介词“对”引出，应说“对我们保密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对朋友的难处保密很好。", "corrected_sentence": "他对朋友的难处保密得很好。", "error_description": "补语错误：程度补语前必须有“得”，应说“保密得很好”，不能说“保密很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
