INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97828, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "严守秘密，不让他人知晓。", "primary_collocate": null, "pronunciation": "bǎo mì", "ipa": "pɑu˨˩˦ mi˥˩", "syllable_count": 2, "sentences": [{"text": "公司要求所有员工对新产品保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同的内容必须保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生有责任为病人保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察答应替证人保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的题目，老师一直保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对这次会议的结果严格保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你对客户的资料保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员签了字，保证保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个配方，工厂已经保密了很多年。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者说会为消息来源保密。", "target_word": "保密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保密了", "label": "体标（了）"}, {"form": "对……保密", "label": "常见结构"}], "register": "书面", "sense_fingerprint": "出于职责或规定，严格守住秘密、不对外公开（公司、医生、警方等场合）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b59156-5839-4aea-8d08-252264446946') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保密", "is_correct": true, "explanation": "“保密”表示严守秘密，符合“公司要求员工”对新产品的管理语境。"}, {"text": "公开", "is_correct": false, "explanation": "语义：“公开”是让人知道，与“要求员工”守密的意思相反。"}, {"text": "泄露", "is_correct": false, "explanation": "语义：“泄露”指秘密外传，与公司要求的守密正好相反，不会要求员工这样做。"}, {"text": "宣布", "is_correct": false, "explanation": "语义：“宣布”是公开发布消息，与要求员工守密的意思相反。"}], "explanations": {"保密": "“保密”表示严守秘密，符合“公司要求员工”对新产品的管理语境。", "公开": "语义：“公开”是让人知道，与“要求员工”守密的意思相反。", "泄露": "语义：“泄露”指秘密外传，与公司要求的守密正好相反，不会要求员工这样做。", "宣布": "语义：“宣布”是公开发布消息，与要求员工守密的意思相反。"}, "sentence_index": 0, "correct_answer": "保密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察答应保密证人的安全。", "explanation": "这里应该用〈保护〉。保密只针对秘密和消息，不能用于“安全”。"}, {"text": "政府保密公民的权利。", "explanation": "这里应该用〈保障〉。保密只针对秘密和信息，不能用于“权利”。"}, {"text": "士兵们保密了边疆。", "explanation": "这里应该用〈保卫〉。保密指守住秘密，不能用于边疆；守卫国土要用保卫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保密", "is_correct": true, "explanation": "“保密”表示不对外透露，符合“请你对客户的资料”的语境。"}, {"text": "外传", "is_correct": false, "explanation": "语义：“外传”指资料流向外界，与“请你”要求的守密意思相反。"}, {"text": "张贴", "is_correct": false, "explanation": "搭配：“张贴”多用于告示、海报，不能用于客户资料。"}, {"text": "告诉", "is_correct": false, "explanation": "配价：“告诉”的对象应是人，不能以“资料”作对象。"}], "explanations": {"保密": "“保密”表示不对外透露，符合“请你对客户的资料”的语境。", "外传": "语义：“外传”指资料流向外界，与“请你”要求的守密意思相反。", "张贴": "搭配：“张贴”多用于告示、海报，不能用于客户资料。", "告诉": "配价：“告诉”的对象应是人，不能以“资料”作对象。"}, "sentence_index": 6, "correct_answer": "保密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府保密了全体居民。", "explanation": "这里应该用〈服务〉。保密指守住秘密，不能以居民为对象；为居民办事要用服务。"}, {"text": "他把钥匙保密了一整天。", "explanation": "这里应该用〈藏〉。保密指守住信息秘密，钥匙是具体物品，应说藏起来。"}, {"text": "这座山保密了很多年。", "explanation": "这里应该用〈存在〉。保密的主语须是人或机构，描写山时应说存在或屹立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经这份报告保密了。", "corrected_sentence": "我们已经对这份报告保密了。", "error_description": "结构错误：宾语“这份报告”直接置于“已经”之后、动词“保密”之前，结构不成立；改用介词“对”引出即可，应说“我们已经对这份报告保密了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把这个消息保密很好。", "corrected_sentence": "他们把这个消息保密得很好。", "error_description": "补语错误：程度补语前必须有“得”，应说“保密得很好”，不能说“保密很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
