INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97831, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用一件事，做出很多话题或大的事来。", "primary_collocate": null, "pronunciation": "zuò wén zhāng", "ipa": "tsuɔ˥˩ wən˧˥ ʈʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "这家店想在包装上做文章，吸引年轻人。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家常在节日里做文章，推出各种活动。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区在夜景上做文章，晚上也有很多游客。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇就在一碗面上做文章，办了美食节。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子在茶叶上做文章，日子越过越好。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想在课间活动上做文章，让学生多运动。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影公司拿这个小故事做文章，拍了三部电影。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店在菜名上做文章，客人一看就想点。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张老板在门口的招牌上做文章，生意好多了。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行社拿雪景做文章，冬天也有很多客人。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大做文章", "label": "复合"}, {"form": "做过文章", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "围绕某一点想办法，做出许多内容或名堂（中性，常说“在……上做文章”）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做文章", "is_correct": true, "explanation": "“做文章”指在包装上想办法、做出新花样，与“吸引年轻人”的目的相符。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”指把东西切开，在包装上切割无法吸引年轻人，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人的休息动作，店家不能在包装上睡觉。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是流泪的动作，店家不可能靠哭在包装上做出花样，句子不通。"}], "explanations": {"做文章": "“做文章”指在包装上想办法、做出新花样，与“吸引年轻人”的目的相符。", "切割": "语义：“切割”指把东西切开，在包装上切割无法吸引年轻人，句子不通。", "睡觉": "语义：“睡觉”是人的休息动作，店家不能在包装上睡觉。", "哭": "语义：“哭”是流泪的动作，店家不可能靠哭在包装上做出花样，句子不通。"}, "sentence_index": 0, "correct_answer": "做文章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们用钢材做文章，把货都搬上了车。", "explanation": "这里应该用〈搬运〉。“做文章”指利用某件事做出话题或大的事来，与搬运货物无关，搬货应说“搬运”。"}, {"text": "农民每天弯着腰在地里做文章，把杂草都拔干净了。", "explanation": "这里应该用〈除草〉。“做文章”指围绕某一点想办法、做出名堂，不指拔草这种体力劳动，把杂草拔干净应说“除草”。"}, {"text": "妈妈用面粉做文章，把地板都拖干净了。", "explanation": "这里应该用〈拖地〉。“做文章”指利用某件事做出话题或大的事来，与打扫清洁无关，把地板拖干净应说“拖地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做文章", "is_correct": true, "explanation": "“做文章”指围绕小故事想办法，做出多部作品，符合“拍了三部电影”的语境。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”指把东西咽下去，不能用来对待一个小故事，句子不通。"}, {"text": "煮熟", "is_correct": false, "explanation": "语义：“煮熟”指用水加热到能吃，用在故事上说不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”多搭配杯子、玻璃等器物，不搭配“故事”。"}], "explanations": {"做文章": "“做文章”指围绕小故事想办法，做出多部作品，符合“拍了三部电影”的语境。", "吃掉": "语义：“吃掉”指把东西咽下去，不能用来对待一个小故事，句子不通。", "煮熟": "语义：“煮熟”指用水加热到能吃，用在故事上说不通。", "打碎": "搭配：“打碎”多搭配杯子、玻璃等器物，不搭配“故事”。"}, "sentence_index": 6, "correct_answer": "做文章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在石头上做文章，把石头都扔进了河里。", "explanation": "这里应该用〈扔〉。“做文章”指利用某件事做出话题或大的事来，与丢弃东西无关，把石头扔进河里应说“扔”。"}, {"text": "假期我们去海边做文章，玩得很开心。", "explanation": "这里应该用〈旅行〉。“做文章”不指出门游览，外出游玩要说“旅行”。"}, {"text": "农民每天在田里做文章，很辛苦。", "explanation": "这里应该用〈种菜〉。“做文章”不指种植，在田里种菜要说“种菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店想封面上做文章，吸引更多读者。", "corrected_sentence": "这家书店想在封面上做文章，吸引更多读者。", "error_description": "漏掉了介词“在”。“在……上做文章”是固定格式，“封面上”前必须加“在”，应改为“在封面上做文章”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅在老店的故事做文章，推出了一套新菜单。", "corrected_sentence": "这家餐厅在老店的故事上做文章，推出了一套新菜单。", "error_description": "漏掉了方位词“上”。“在……上做文章”是固定格式，“故事”后必须加“上”，应改为“在老店的故事上做文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
