INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97832, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻抓住某一点大做文章。", "primary_collocate": null, "pronunciation": "zuò wén zhāng", "ipa": "tsuɔ˥˩ wən˧˥ ʈʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "他抓住我一句话大做文章。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别拿这点小事做文章，大家都累了。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想在他的小错误上做文章。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者拿他的一句玩笑话大做文章。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手总想在我的年龄上做文章。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们抓住这个小问题做文章，不让我们通过。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是说错了一个字，你为什么拿它做文章？", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一迟到，同事就在这件事上做文章。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有人拿他的照片做文章，说了很多难听的话。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司出了点小问题，对手就大做文章。", "target_word": "做文章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大做文章", "label": "复合"}, {"form": "做过文章", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "抓住别人的某句话或某个小错，借题发挥、小题大做（多含贬义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做文章", "is_correct": true, "explanation": "“做文章”指抓住别人的一句话借题发挥，与“抓住我一句话”相呼应。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与抓住别人的话借题发挥无关，句子不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”是日常用餐，和“抓住我一句话”无关，说不通。"}, {"text": "逃走", "is_correct": false, "explanation": "配价：“逃走”是不及物动词，不能表示对一句话借题发挥的动作。"}], "explanations": {"做文章": "“做文章”指抓住别人的一句话借题发挥，与“抓住我一句话”相呼应。", "唱歌": "语义：“唱歌”与抓住别人的话借题发挥无关，句子不通。", "吃饭": "语义：“吃饭”是日常用餐，和“抓住我一句话”无关，说不通。", "逃走": "配价：“逃走”是不及物动词，不能表示对一句话借题发挥的动作。"}, "sentence_index": 0, "correct_answer": "做文章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "建筑队在木材上大做文章，盖起了一座房子。", "explanation": "这里应该用〈建造〉。“大做文章”指小题大做、借题发挥，含贬义，不指建造房屋，盖房子要说“建造”。"}, {"text": "这个学生在作业本上大做文章，把字都写得很工整。", "explanation": "这里应该用〈认真写〉。“大做文章”指小题大做、借题发挥，含贬义，不指认真书写，把字写工整要说“认真写”。"}, {"text": "司机每天在公路上大做文章，开了很远的路。", "explanation": "这里应该用〈开车〉。“大做文章”指小题大做、借题发挥，含贬义，不指驾驶，开车要说“开车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做文章", "is_correct": true, "explanation": "“做文章”指借一个小错误借题发挥，符合“拿它”的语境。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是清洁身体的动作，拿一个字来洗澡说不通。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使东西着火，拿一个字点燃说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“它”作宾语，这里说不通。"}], "explanations": {"做文章": "“做文章”指借一个小错误借题发挥，符合“拿它”的语境。", "洗澡": "语义：“洗澡”是清洁身体的动作，拿一个字来洗澡说不通。", "点燃": "语义：“点燃”指使东西着火，拿一个字点燃说不通。", "睡觉": "配价：“睡觉”是不及物动词，不能带“它”作宾语，这里说不通。"}, "sentence_index": 6, "correct_answer": "做文章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "裁缝在布料上大做文章，缝出了一件衣服。", "explanation": "这里应该用〈缝制〉。“大做文章”指小题大做、借题发挥，含贬义，不指缝制衣服，缝衣服要说“缝制”。"}, {"text": "周末我们去山里做文章，玩得很开心。", "explanation": "这里应该用〈旅行〉。“做文章”不指出门游览，去山里玩要说“旅行”。"}, {"text": "村民每天在地里做文章，很辛苦。", "explanation": "这里应该用〈种菜〉。“做文章”不指种植，在地里种菜要说“种菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别人总想她的小事上做文章，弄得她很烦。", "corrected_sentence": "别人总想在她的小事上做文章，弄得她很烦。", "error_description": "漏掉了介词“在”。“在……上做文章”的“在”不能省，“她的小事上”前必须加“在”，应为“在她的小事上做文章”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对手把他的一句话做文章，弄得大家都很紧张。", "corrected_sentence": "对手拿他的一句话做文章，弄得大家都很紧张。", "error_description": "介词用错：“做文章”的对象要用“拿……做文章”或“在……上做文章”，不能说“把……做文章”，应改为“拿他的一句话做文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97835, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放电", "is_correct": true, "explanation": "放电指释放电能，与充电相对，是这个义项的反义词。"}, {"text": "打开", "is_correct": false, "explanation": "打开是把封闭的东西开启，与给电器装电没有反义关系。"}, {"text": "擦干", "is_correct": false, "explanation": "擦干是把水分擦去，与充电不构成反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是转移物体的位置，与充电不构成反义关系。"}], "correct_answer": "放电", "explanations": {"放电": "放电指释放电能，与充电相对，是这个义项的反义词。", "打开": "打开是把封闭的东西开启，与给电器装电没有反义关系。", "擦干": "擦干是把水分擦去，与充电不构成反义关系。", "搬运": "搬运是转移物体的位置，与充电不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97835, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放电", "is_correct": true, "explanation": "放电指释放电能，与充电相对，是这个义项的反义词。"}, {"text": "拆开", "is_correct": false, "explanation": "拆开是把组合的东西分开，与给电器装电没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗是用水除去污物，与充电不构成反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理是使损坏的东西恢复正常，与充电不构成反义关系。"}], "correct_answer": "放电", "explanations": {"放电": "放电指释放电能，与充电相对，是这个义项的反义词。", "拆开": "拆开是把组合的东西分开，与给电器装电没有反义关系。", "清洗": "清洗是用水除去污物，与充电不构成反义关系。", "修理": "修理是使损坏的东西恢复正常，与充电不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "装满；也指把电充进去。", "primary_collocate": null, "pronunciation": "chōng", "ipa": "ʈʂʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "手机没电了，快充一下。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机充了两个小时。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电池能充很多次。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快把你的手表充上。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机充好了，你拿走吧。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车充一次能跑很远。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，我把手机充着。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耳机没电了，你先充一下。", "target_word": "充", "complexity_tier": "T3", "furigana": "ěr jī méi diàn le, nǐ xiān chōng yí xià", "sentence_source": "generated"}, {"text": "他的耳机还没充，先别用。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车一晚上就能充好。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "充了", "label": "体标"}, {"form": "充着", "label": "体标"}, {"form": "充过", "label": "体标"}, {"form": "充电", "label": "复合"}], "register": "口语", "sense_fingerprint": "给手机、电池、轮胎等装进电或气，使它满起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97835, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "充", "is_correct": true, "explanation": "充（chōng）是本词，意思是装满，也指把电充进去。"}, {"text": "虫", "is_correct": false, "explanation": "chóng（第二声）与 chōng（第一声）声调不同，意思是虫子。"}, {"text": "宠", "is_correct": false, "explanation": "chǒng（第三声）与 chōng（第一声）声调不同，意思是宠爱。"}, {"text": "中", "is_correct": false, "explanation": "zhōng 与 chōng 声母不同（zh 与 ch），意思是中间。"}, {"text": "葱", "is_correct": false, "explanation": "cōng 与 chōng 声母不同（c 与 ch），意思是葱。"}, {"text": "称", "is_correct": false, "explanation": "chēng 与 chōng 韵母不同（eng 与 ong），意思是称重。"}], "explanations": {"充": "充（chōng）是本词，意思是装满，也指把电充进去。", "虫": "chóng（第二声）与 chōng（第一声）声调不同，意思是虫子。", "宠": "chǒng（第三声）与 chōng（第一声）声调不同，意思是宠爱。", "中": "zhōng 与 chōng 声母不同（zh 与 ch），意思是中间。", "葱": "cōng 与 chōng 声母不同（c 与 ch），意思是葱。", "称": "chēng 与 chōng 韵母不同（eng 与 ong），意思是称重。"}, "sentence_index": null, "correct_answer": "充"}, "level_3": {"options": [{"text": "充", "is_correct": true, "explanation": "充是给手机补电，正好能填入“快___一下”的空。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去污渍，与“没电了”的情况不相关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗多用于衣物或身体，不能用来给手机补电。"}, {"text": "拆", "is_correct": false, "explanation": "语义：拆是拆开，与“没电了，快……一下”的意思不符。"}], "explanations": {"充": "充是给手机补电，正好能填入“快___一下”的空。", "擦": "语义：擦是抹去污渍，与“没电了”的情况不相关。", "洗": "搭配：洗多用于衣物或身体，不能用来给手机补电。", "拆": "语义：拆是拆开，与“没电了，快……一下”的意思不符。"}, "sentence_index": 0, "correct_answer": "充"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车充了一箱油。", "explanation": "这里应该用〈加〉。充用于给手机、电池等装电，给车加油要用〈加〉。"}, {"text": "我给自己充了一杯茶。", "explanation": "这里应该用〈冲〉。冲茶要用〈冲〉，充表示装电或装满，不能用于泡茶。"}, {"text": "我每天给花充水。", "explanation": "这里应该用〈浇〉。给花浇水要用〈浇〉，充表示给电器或容器装满电或气，不能用于浇花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97835, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "充", "is_correct": true, "explanation": "充（chōng）是本词，意思是装满，也指把电充进去。"}, {"text": "重", "is_correct": false, "explanation": "chóng（第二声）与 chōng（第一声）声调不同，意思是重复、再次。"}, {"text": "聪", "is_correct": false, "explanation": "cōng 与 chōng 声母不同（c 与 ch），意思是聪明。"}, {"text": "宠", "is_correct": false, "explanation": "chǒng（第三声）与 chōng（第一声）声调不同，意思是宠爱。"}, {"text": "钟", "is_correct": false, "explanation": "zhōng 与 chōng 声母不同（zh 与 ch），意思是钟表。"}, {"text": "撑", "is_correct": false, "explanation": "chēng 与 chōng 韵母不同（eng 与 ong），意思是撑开。"}], "explanations": {"充": "充（chōng）是本词，意思是装满，也指把电充进去。", "重": "chóng（第二声）与 chōng（第一声）声调不同，意思是重复、再次。", "聪": "cōng 与 chōng 声母不同（c 与 ch），意思是聪明。", "宠": "chǒng（第三声）与 chōng（第一声）声调不同，意思是宠爱。", "钟": "zhōng 与 chōng 声母不同（zh 与 ch），意思是钟表。", "撑": "chēng 与 chōng 韵母不同（eng 与 ong），意思是撑开。"}, "sentence_index": null, "correct_answer": "充"}, "level_3": {"options": [{"text": "充", "is_correct": true, "explanation": "充是给手机补电，正好能填入“把手机___着”的空。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：砸多指打碎，把手机砸着不是正常说法。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，与睡觉前给手机补电的情境不符。"}, {"text": "晒", "is_correct": false, "explanation": "语义：晒是放在阳光下，与“睡觉前”的情境相冲突。"}], "explanations": {"充": "充是给手机补电，正好能填入“把手机___着”的空。", "砸": "搭配：砸多指打碎，把手机砸着不是正常说法。", "修": "语义：修是修理，与睡觉前给手机补电的情境不符。", "晒": "语义：晒是放在阳光下，与“睡觉前”的情境相冲突。"}, "sentence_index": 6, "correct_answer": "充"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我充了一张合影。", "explanation": "这里应该用〈拍〉。拍照、合影要用〈拍〉，充只表示装满或给电器充电，不能用于拍照。"}, {"text": "他在厨房里充了一盘菜。", "explanation": "这里应该用〈炒〉。做菜要用〈炒〉，充不能表示烹饪。"}, {"text": "妈妈在烤箱里充了一个蛋糕。", "explanation": "这里应该用〈烤〉。烤蛋糕要用〈烤〉，充不能表示烘烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天充着一次手表。", "corrected_sentence": "我昨天充了一次手表。", "error_description": "错误：体标用错。「充」后带动量补语「一次」，表示完成的动作，要用「了」，不能用表示持续的「着」，应说「充了一次」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平板没电了，我帮你充得一下。", "corrected_sentence": "平板没电了，我帮你充一下。", "error_description": "错误：「充」后多出了助词「得」。「充一下」是动词加动量补语，中间不能插入「得」，应说「充一下」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
