INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给卡、账户等补上钱，使余额增加。", "primary_collocate": null, "pronunciation": "chōng", "ipa": "ʈʂʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "我去给饭卡充点钱。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在游戏里充了很多钱。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话费不够了，我充了五十元。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交卡里没钱了，得充一下。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给手机号充了一百块话费。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张新卡得先充钱，再用。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我的卡充了二百块。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店的会员卡能充钱吗？", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的账号还要再充吗？", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把游戏账号充好了。", "target_word": "充", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "充了", "label": "体标"}, {"form": "充着", "label": "体标"}, {"form": "充过", "label": "体标"}, {"form": "充值", "label": "复合"}], "register": "口语", "sense_fingerprint": "给卡、账户补上钱，使余额增加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97836, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "充", "is_correct": true, "explanation": "充（chōng）是本词，意思是给卡或账户补上钱。"}, {"text": "重", "is_correct": false, "explanation": "chóng（第二声）与 chōng（第一声）声调不同，意思是重复。"}, {"text": "葱", "is_correct": false, "explanation": "cōng 与 chōng 声母不同（c 与 ch），意思是葱。"}, {"text": "撑", "is_correct": false, "explanation": "chēng 与 chōng 韵母不同（eng 与 ong），意思是撑开。"}, {"text": "忠", "is_correct": false, "explanation": "zhōng 与 chōng 声母不同（zh 与 ch），意思是忠诚。"}], "explanations": {"充": "充（chōng）是本词，意思是给卡或账户补上钱。", "重": "chóng（第二声）与 chōng（第一声）声调不同，意思是重复。", "葱": "cōng 与 chōng 声母不同（c 与 ch），意思是葱。", "撑": "chēng 与 chōng 韵母不同（eng 与 ong），意思是撑开。", "忠": "zhōng 与 chōng 声母不同（zh 与 ch），意思是忠诚。"}, "sentence_index": null, "correct_answer": "充"}, "level_3": {"options": [{"text": "充", "is_correct": true, "explanation": "充是给饭卡补钱，正好能填入“给饭卡___点钱”的空。"}, {"text": "查", "is_correct": false, "explanation": "语义：查是检查，与给饭卡补钱的意思不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：擦用于抹去污渍，不能说擦钱。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，与“给饭卡补钱”的意思相反。"}], "explanations": {"充": "充是给饭卡补钱，正好能填入“给饭卡___点钱”的空。", "查": "语义：查是检查，与给饭卡补钱的意思不符。", "擦": "搭配：擦用于抹去污渍，不能说擦钱。", "扔": "语义：扔是丢弃，与“给饭卡补钱”的意思相反。"}, "sentence_index": 0, "correct_answer": "充"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去商店充了一瓶水。", "explanation": "这里应该用〈买〉。在商店买东西要用〈买〉，充只用于给卡或账户补钱。"}, {"text": "我去银行把人民币充了美元。", "explanation": "这里应该用〈换〉。兑换货币要用〈换〉，充只用于给卡或账户补钱，不能表示兑换。"}, {"text": "我充了房租。", "explanation": "这里应该用〈付〉。支付房租要用〈付〉，充不能用于一次性支付房租。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97836, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "充", "is_correct": true, "explanation": "充（chōng）是本词，意思是给卡或账户补上钱。"}, {"text": "虫", "is_correct": false, "explanation": "chóng（第二声）与 chōng（第一声）声调不同，意思是虫子。"}, {"text": "聪", "is_correct": false, "explanation": "cōng 与 chōng 声母不同（c 与 ch），意思是聪明。"}, {"text": "宠", "is_correct": false, "explanation": "chǒng（第三声）与 chōng（第一声）声调不同，意思是宠爱。"}, {"text": "钟", "is_correct": false, "explanation": "zhōng 与 chōng 声母不同（zh 与 ch），意思是钟表。"}, {"text": "称", "is_correct": false, "explanation": "chēng 与 chōng 韵母不同（eng 与 ong），意思是称重。"}], "explanations": {"充": "充（chōng）是本词，意思是给卡或账户补上钱。", "虫": "chóng（第二声）与 chōng（第一声）声调不同，意思是虫子。", "聪": "cōng 与 chōng 声母不同（c 与 ch），意思是聪明。", "宠": "chǒng（第三声）与 chōng（第一声）声调不同，意思是宠爱。", "钟": "zhōng 与 chōng 声母不同（zh 与 ch），意思是钟表。", "称": "chēng 与 chōng 韵母不同（eng 与 ong），意思是称重。"}, "sentence_index": null, "correct_answer": "充"}, "level_3": {"options": [{"text": "充", "is_correct": true, "explanation": "充是给妈妈给的卡补钱，正好能填入“卡___了二百块”的空。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗用于衣物或身体，不能说洗二百块给卡。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，与给卡补钱的意思不符。"}, {"text": "锁", "is_correct": false, "explanation": "搭配：锁是关闭，不能说锁了二百块给卡。"}], "explanations": {"充": "充是给妈妈给的卡补钱，正好能填入“卡___了二百块”的空。", "洗": "搭配：洗用于衣物或身体，不能说洗二百块给卡。", "修": "语义：修是修理，与给卡补钱的意思不符。", "锁": "搭配：锁是关闭，不能说锁了二百块给卡。"}, "sentence_index": 6, "correct_answer": "充"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去超市充了一些货。", "explanation": "这里应该用〈补〉。补货、进货要用〈补〉，充表示给卡或账户补钱，不能用于货物。"}, {"text": "姐姐在锅里充了一碗面。", "explanation": "这里应该用〈煮〉。煮面要用〈煮〉，充不能表示烹煮。"}, {"text": "他在纸上充了一幅画。", "explanation": "这里应该用〈画〉。画画要用〈画〉，充不能表示作画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_typ