INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一样东西从头到尾的长度。", "primary_collocate": null, "pronunciation": "quán cháng", "ipa": "tɕʰɥɛn˧˥ tʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条河的全长有三百公里。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的全长是五百米。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的全长大约二十厘米。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你量一下这条绳子的全长。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条蛇的全长有两米多。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆火车的全长是两百米。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的全长一米二。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船的全长不到五米。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的全长是多少公里？", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道长城的全长吗？", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一样东西从头到尾的长度，如河、桥、鱼、绳子的全长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全长", "is_correct": true, "explanation": "全长：指从头到尾的长度，与“有三百公里”相符。"}, {"text": "名称", "is_correct": false, "explanation": "语义：“名称”是称呼，不表示长度，与“三百公里”不搭。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能说河的体重。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”用平方单位计量，不说“有三百公里”。"}], "explanations": {"全长": "全长：指从头到尾的长度，与“有三百公里”相符。", "名称": "语义：“名称”是称呼，不表示长度，与“三百公里”不搭。", "体重": "搭配：“体重”只用于人或动物，不能说河的体重。", "面积": "搭配：“面积”用平方单位计量，不说“有三百公里”。"}, "sentence_index": 0, "correct_answer": "全长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家离学校的全长有两公里。", "explanation": "这里应该用〈距离〉。全长指一样东西从头到尾的长度，不能用来说两地之间的远近。"}, {"text": "这块地的全长是两亩。", "explanation": "这里应该用〈面积〉。全长是长度，单位是米、公里；地的大小用面积，单位才是亩。"}, {"text": "他的全长有一米七。", "explanation": "这里应该用〈身高〉。全长用于物体，说人的高矮要用身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全长", "is_correct": true, "explanation": "全长：指从头到尾的长度，与“一米二”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不用米来计量，不说“颜色一米二”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”用元来计，不说“价格一米二”。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指存在的年限，与长度无关，句意不通。"}], "explanations": {"全长": "全长：指从头到尾的长度，与“一米二”相符。", "颜色": "搭配：“颜色”不用米来计量，不说“颜色一米二”。", "价格": "搭配：“价格”用元来计，不说“价格一米二”。", "寿命": "语义：“寿命”指存在的年限，与长度无关，句意不通。"}, "sentence_index": 6, "correct_answer": "全长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的全长有多宽？", "explanation": "这里应该用〈宽度〉。全长指从头到尾的长度，问河的横向距离要用宽度。"}, {"text": "这列火车的全长每小时六十公里。", "explanation": "这里应该用〈速度〉。全长表示静态的长度，不表示每小时行驶的快慢。"}, {"text": "这口井的全长是十平方米。", "explanation": "这里应该用〈面积〉。全长是长度，单位是米、公里；平方米是面积的单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根木棍的全长了是一米。", "corrected_sentence": "这根木棍的全长是一米。", "error_description": "错误：“全长”后面加了“了”。正确：“全长是一米”。全长是名词，表示长度，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路的全长是十五个公里。", "corrected_sentence": "这条路的全长是十五公里。", "error_description": "错误：“十五”与“公里”之间多了量词“个”。正确：“十五公里”，表示长度时数量词直接接单位，不加量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
