INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "整体的长度。", "primary_collocate": null, "pronunciation": "quán cháng", "ipa": "tɕʰɥɛn˧˥ tʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条路分三段，全长十公里。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鲸鱼的全长超过二十米。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁二号线全长四十公里。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架的全长是三米，放得下很多书。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条围巾全长一米八。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我量了这条小路的全长，有两公里。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的全长比这座楼还长。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大桥全长两公里，走过去要半小时。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河的全长除以三，就是每段的长度。", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条隧道的全长是多少米？", "target_word": "全长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整体的长度，与分段或局部的长度相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全长", "is_correct": true, "explanation": "全长：指整条路的长度，与“分三段”和“十公里”相符。"}, {"text": "宽度", "is_correct": false, "explanation": "语义：“宽度”是横向的距离，与整条路的长度不符，“十公里”作路宽也不合常理。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”要带“每小时”等单位，不能直接说“速度十公里”。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”用千克、吨计，不说“重量十公里”。"}], "explanations": {"全长": "全长：指整条路的长度，与“分三段”和“十公里”相符。", "宽度": "语义：“宽度”是横向的距离，与整条路的长度不符，“十公里”作路宽也不合常理。", "速度": "搭配：“速度”要带“每小时”等单位，不能直接说“速度十公里”。", "重量": "搭配：“重量”用千克、吨计，不说“重量十公里”。"}, "sentence_index": 0, "correct_answer": "全长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个水杯的全长是五百毫升，装得下很多水。", "explanation": "这里应该用〈容量〉。全长是长度，单位是米、公里；杯子能装多少水要用容量，单位是毫升。"}, {"text": "他的全长是二十岁。", "explanation": "这里应该用〈年龄〉。全长是长度，不用来说人的年龄。"}, {"text": "这袋米的全长是十斤。", "explanation": "这里应该用〈重量〉。全长是长度，单位是米、公里；米的轻重要用重量，单位是斤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全长", "is_correct": true, "explanation": "全长：指整体的长度，与飞机和楼的比较相符。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：“厚度”指上下的距离，不能说飞机的厚度比楼还长。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不用于飞机。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”用钱计量，不能用“长”来比较。"}], "explanations": {"全长": "全长：指整体的长度，与飞机和楼的比较相符。", "厚度": "语义：“厚度”指上下的距离，不能说飞机的厚度比楼还长。", "体重": "搭配：“体重”只用于人或动物，不用于飞机。", "价格": "搭配：“价格”用钱计量，不能用“长”来比较。"}, "sentence_index": 6, "correct_answer": "全长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条马路的全长有多宽？", "explanation": "这里应该用〈宽度〉。全长指整体的长度，问路的横向距离要用宽度。"}, {"text": "这列火车的全长每小时一百公里。", "explanation": "这里应该用〈速度〉。全长表示长度，不表示每小时行驶的快慢。"}, {"text": "这座山的全长很高。", "explanation": "这里应该用〈高度〉。全长指长度，形容山的高低要用高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河分两段，全长了六十公里。", "corrected_sentence": "这条河分两段，全长六十公里。", "error_description": "错误：“全长”后面加了“了”。正确：“全长六十公里”。全长是名词，直接接数量加单位表示长度，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条小路全长两个公里。", "corrected_sentence": "这条小路全长两公里。", "error_description": "错误：“两”与“公里”之间多了量词“个”。正确：“全长两公里”，表示长度时数量词直接接单位，不加量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97847, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增强", "is_correct": true, "explanation": "“增强”与“削弱”意思相反，指使力量、影响、热情等变强。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”与“削弱”没有反义关系，指仔细看以了解情况。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”与“削弱”没有反义关系，指使坏的东西恢复正常。"}, {"text": "安排", "is_correct": false, "explanation": "“安排”与“削弱”没有反义关系，指对事情作出布置。"}], "correct_answer": "增强", "explanations": {"增强": "“增强”与“削弱”意思相反，指使力量、影响、热情等变强。", "观察": "“观察”与“削弱”没有反义关系，指仔细看以了解情况。", "修理": "“修理”与“削弱”没有反义关系，指使坏的东西恢复正常。", "安排": "“安排”与“削弱”没有反义关系，指对事情作出布置。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
