INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97847, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让力量变小，变得没那么强。", "primary_collocate": null, "pronunciation": "xuē ruò", "ipa": "ɕɥe⁵⁵ ʐuo⁵¹", "syllable_count": 2, "sentences": [{"text": "睡眠不足会削弱人的记忆力。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水削弱了敌人进攻的力量。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想削弱大公司的影响力。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太累削弱了他的热情。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林能削弱风的力量。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息削弱了球迷的信心。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用新计划削弱对方的优势。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷了，也没削弱大家爬山的兴趣。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把经理的权力削弱了。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防护墙削弱着海浪的冲击。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "削弱了", "label": "体标"}, {"form": "削弱过", "label": "体标"}, {"form": "削弱着", "label": "体标"}], "register": "书面", "sense_fingerprint": "让力量、影响、热情等变得没那么强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "削弱", "is_correct": true, "explanation": "“削弱”指使记忆力变弱，与“睡眠不足”的后果一致。"}, {"text": "增添", "is_correct": false, "explanation": "搭配：“增添”多接乐趣、光彩之类的事物，不说“增添记忆力”。"}, {"text": "锻炼", "is_correct": false, "explanation": "语义：“锻炼”指通过练习使能力增强，与“睡眠不足”的结果矛盾。"}, {"text": "激发", "is_correct": false, "explanation": "语义：“激发”指使人振奋或产生某种反应，与“睡眠不足”的后果矛盾。"}], "explanations": {"削弱": "“削弱”指使记忆力变弱，与“睡眠不足”的后果一致。", "增添": "搭配：“增添”多接乐趣、光彩之类的事物，不说“增添记忆力”。", "锻炼": "语义：“锻炼”指通过练习使能力增强，与“睡眠不足”的结果矛盾。", "激发": "语义：“激发”指使人振奋或产生某种反应，与“睡眠不足”的后果矛盾。"}, "sentence_index": 0, "correct_answer": "削弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每年削弱了两成的产量。", "explanation": "这里应该用〈减少〉。削弱用于力量、热情等抽象的强弱，产量的下降要用减少。"}, {"text": "他削弱了那次会议。", "explanation": "这里应该用〈取消〉。削弱指使力量、热情变弱，不能用于会议。"}, {"text": "他把房间削弱了一半。", "explanation": "这里应该用〈缩小〉。削弱用于力量、影响，房间的大小要用缩小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "削弱", "is_correct": true, "explanation": "“削弱”指使对方的优势变弱，与“他们用新计划”的目的一致。"}, {"text": "巩固", "is_correct": false, "explanation": "语义：“巩固”指使更稳固，与“他们想削弱对方”的意图相反。"}, {"text": "扩展", "is_correct": false, "explanation": "语义：“扩展”指扩大范围，与“他们想削弱对方”的意图相反。"}, {"text": "点缀", "is_correct": false, "explanation": "搭配：“点缀”多用于装饰外观，不搭配“优势”。"}], "explanations": {"削弱": "“削弱”指使对方的优势变弱，与“他们用新计划”的目的一致。", "巩固": "语义：“巩固”指使更稳固，与“他们想削弱对方”的意图相反。", "扩展": "语义：“扩展”指扩大范围，与“他们想削弱对方”的意图相反。", "点缀": "搭配：“点缀”多用于装饰外观，不搭配“优势”。"}, "sentence_index": 6, "correct_answer": "削弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他削弱了比赛时间。", "explanation": "这里应该用〈缩短〉。削弱用于力量、影响，时间的长短要用缩短。"}, {"text": "公司削弱了店铺面积。", "explanation": "这里应该用〈缩小〉。削弱用于力量、影响，面积的大小要用缩小。"}, {"text": "他削弱了水果的数量。", "explanation": "这里应该用〈减少〉。削弱用于力量、热情等的变弱，数量的变少要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森林曾经削弱着风的力量。", "corrected_sentence": "森林曾经削弱过风的力量。", "error_description": "错误形式为“曾经削弱着”，正确形式为“曾经削弱过”。“曾经”表示过去的经历，要用“过”；“着”表示动作持续或正在进行，与“曾经”矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "堤坝把洪水的冲击削弱。", "corrected_sentence": "堤坝把洪水的冲击削弱了。", "error_description": "错误形式为“把洪水的冲击削弱”，正确形式为“把洪水的冲击削弱了”。“把”字句的动词后通常要带“了”“着”或补语，只说“把洪水的冲击削弱”句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97848, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增强", "is_correct": true, "explanation": "“增强”与“削弱”意思相反，指使力量、实力变强。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”与“削弱”没有反义关系，指使东西留存不坏。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”与“削弱”没有反义关系，指彼此交换意见。"}, {"text": "运输", "is_correct": false, "explanation": "“运输”与“削弱”没有反义关系，指把物品从一地运到另一地。"}], "correct_answer": "增强", "explanations": {"增强": "“增强”与“削弱”意思相反，指使力量、实力变强。", "保存": "“保存”与“削弱”没有反义关系，指使东西留存不坏。", "讨论": "“讨论”与“削弱”没有反义关系，指彼此交换意见。", "运输": "“运输”与“削弱”没有反义关系，指把物品从一地运到另一地。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
