INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97848, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使变弱；减小力量。", "primary_collocate": null, "pronunciation": "xuē ruò", "ipa": "ɕɥe⁵⁵ ʐuo⁵¹", "syllable_count": 2, "sentences": [{"text": "这场大雨削弱了火势。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间不锻炼会削弱身体的力量。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想削弱对手的实力。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药会削弱病人的免疫力。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖掉主力球员，削弱了球队的实力。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多的批评削弱了孩子的信心。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想把对手的优势削弱一点。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高山削弱了台风的力量。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败并没有削弱他的决心。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们曾经削弱过对方的力量。", "target_word": "削弱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "削弱了", "label": "体标"}, {"form": "削弱过", "label": "体标"}, {"form": "削弱着", "label": "体标"}], "register": "书面", "sense_fingerprint": "使力量、实力、信心等变弱变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "削弱", "is_correct": true, "explanation": "“削弱”指使火势变弱，与“大雨”的作用一致。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使开始燃烧，火已存在且大雨会浇灭它，与语境矛盾。"}, {"text": "增强", "is_correct": false, "explanation": "语义：“增强”指使变强，大雨使火势变强与常理相反，与语境矛盾。"}, {"text": "助长", "is_correct": false, "explanation": "语义：“助长”指促使坏的事物发展，大雨浇灭火势，与语境矛盾。"}], "explanations": {"削弱": "“削弱”指使火势变弱，与“大雨”的作用一致。", "点燃": "语义：“点燃”指使开始燃烧，火已存在且大雨会浇灭它，与语境矛盾。", "增强": "语义：“增强”指使变强，大雨使火势变强与常理相反，与语境矛盾。", "助长": "语义：“助长”指促使坏的事物发展，大雨浇灭火势，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "削弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他削弱了每天吃饭的次数。", "explanation": "这里应该用〈减少〉。削弱用于力量、实力、信心等，次数、数量要用减少。"}, {"text": "超市削弱了鸡蛋的价格。", "explanation": "这里应该用〈降低〉。削弱指使力量变弱，价格的涨跌要用降低。"}, {"text": "他把照片削弱了。", "explanation": "这里应该用〈缩小〉。削弱用于力量、影响，照片的大小要用缩小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "削弱", "is_correct": true, "explanation": "“削弱”指使对方的优势变弱，与“想把……一点”的意图一致。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”指使范围变大，与“想把对手的优势……一点”的意图相反。"}, {"text": "放大", "is_correct": false, "explanation": "语义：“放大”指使变大，与“想把对手的优势……一点”的意图相反。"}, {"text": "缩短", "is_correct": false, "explanation": "搭配：“缩短”多用于时间、距离，不搭配“优势”。"}], "explanations": {"削弱": "“削弱”指使对方的优势变弱，与“想把……一点”的意图一致。", "扩大": "语义：“扩大”指使范围变大，与“想把对手的优势……一点”的意图相反。", "放大": "语义：“放大”指使变大，与“想把对手的优势……一点”的意图相反。", "缩短": "搭配：“缩短”多用于时间、距离，不搭配“优势”。"}, "sentence_index": 6, "correct_answer": "削弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司削弱了员工的工资。", "explanation": "这里应该用〈降低〉。削弱用于力量、实力，工资的高低要用降低。"}, {"text": "他削弱了工期。", "explanation": "这里应该用〈缩短〉。削弱用于力量、实力，工期的长短要用缩短。"}, {"text": "他削弱了家里的东西。", "explanation": "这里应该用〈减少〉。削弱用于力量、实力，东西的多少要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大雨把火势削弱。", "corrected_sentence": "这场大雨把火势削弱了。", "error_description": "错误形式为“把火势削弱”，正确形式为“把火势削弱了”。“把”字句的动词后通常要带“了”“着”或补语，只说“把火势削弱”句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药把病人的免疫力削弱很厉害。", "corrected_sentence": "这种药把病人的免疫力削弱得很厉害。", "error_description": "错误形式缺少补语标记“得”，正确形式为“削弱得很厉害”。“很厉害”作补语时，前面要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
