INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "里面养着很多动物，让人看的公园。", "primary_collocate": null, "pronunciation": "dòng wù yuán", "ipa": "tʊŋ˥˩ u˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "周末我带孩子去动物园。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里有很多老虎和大象。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动物园离我家很近。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢动物园里的熊猫。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园的门票多少钱？", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在动物园看见了一只长颈鹿。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天去动物园看猴子。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的孩子们都很高兴。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园几点开门？", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，爸爸常常带我去动物园。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "养着很多动物、可以去玩去看的公园，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物园", "is_correct": true, "explanation": "正确：“去动物园”是带孩子出去玩的常见说法。"}, {"text": "苹果", "is_correct": false, "explanation": "配价：“去”后要接地点，“苹果”是水果，不能说“去苹果”。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“去”后要接地点，“老师”是人，应说“去老师家”。"}, {"text": "颜色", "is_correct": false, "explanation": "配价：“颜色”不是地点，不能说“带孩子去颜色”。"}], "explanations": {"动物园": "正确：“去动物园”是带孩子出去玩的常见说法。", "苹果": "配价：“去”后要接地点，“苹果”是水果，不能说“去苹果”。", "老师": "配价：“去”后要接地点，“老师”是人，应说“去老师家”。", "颜色": "配价：“颜色”不是地点，不能说“带孩子去颜色”。"}, "sentence_index": 0, "correct_answer": "动物园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每周都去动物园借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，动物园是让人观赏动物的地方，不能借书。"}, {"text": "我周末去动物园理发。", "explanation": "这里应该用〈理发店〉。动物园是让人观赏动物的地方，理发要去理发店。"}, {"text": "我们明天一早去动物园赶飞机。", "explanation": "这里应该用〈机场〉。动物园不是机场，赶飞机要去机场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动物园", "is_correct": true, "explanation": "正确：“去动物园看猴子”是常见的说法。"}, {"text": "水族馆", "is_correct": false, "explanation": "语义：水族馆展出的是水生动物，没有猴子。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”是看病的地方，去那里不是为了看猴子。"}, {"text": "游泳池", "is_correct": false, "explanation": "搭配：“游泳池”与“看猴子”搭配不当，去那里应该是游泳。"}], "explanations": {"动物园": "正确：“去动物园看猴子”是常见的说法。", "水族馆": "语义：水族馆展出的是水生动物，没有猴子。", "医院": "语义：“医院”是看病的地方，去那里不是为了看猴子。", "游泳池": "搭配：“游泳池”与“看猴子”搭配不当，去那里应该是游泳。"}, "sentence_index": 6, "correct_answer": "动物园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在动物园里修了一辆汽车。", "explanation": "这里应该用〈修车厂〉。动物园是让人观赏动物的地方，不能在里面修车。"}, {"text": "我们去动物园存了一万块钱。", "explanation": "这里应该用〈银行〉。动物园不是存钱的地方，存钱要去银行。"}, {"text": "我每天给动物园喂食。", "explanation": "这里“喂”的对象应是动物，不能说喂动物园，应说“给动物喂食”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个周末，我们一家人去一只动物园看大象。", "corrected_sentence": "上个周末，我们一家人去一座动物园看大象。", "error_description": "量词错误：动物园应用“座”，“只”用于动物，不能用来数动物园。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈上周带我动物园拍了很多照片。", "corrected_sentence": "妈妈上周带我在动物园拍了很多照片。", "error_description": "错误：“动物园”前面漏了介词“在”。正确：“在动物园拍了很多照片”。表示在某地做事，地点前要加“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
