INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "饲养和展出各种动物供人观赏的公园。", "primary_collocate": null, "pronunciation": "dòng wù yuán", "ipa": "tʊŋ˥˩ u˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这家动物园养着三只熊猫。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里新建了一座动物园。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园的工作人员每天喂动物。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座动物园有一百多年的历史。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园把老虎放在大院子里。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里不能给动物吃东西。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园的工作人员给我们介绍了狮子。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京动物园很大，一天看不完。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的动物吃得很好。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那个动物园新来了两只企鹅。", "target_word": "动物园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "饲养并展出各种动物供人观赏的机构，强调饲养和管理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物园", "is_correct": true, "explanation": "正确：“这家动物园养着三只熊猫”符合动物园饲养动物的特点。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店不会养熊猫，这里说不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院一般不饲养熊猫，与“养着三只熊猫”的语境不符。"}, {"text": "游乐场", "is_correct": false, "explanation": "搭配：“游乐场”一般不饲养动物，不与“养着三只熊猫”搭配。"}], "explanations": {"动物园": "正确：“这家动物园养着三只熊猫”符合动物园饲养动物的特点。", "饭店": "语义：饭店不会养熊猫，这里说不通。", "医院": "语义：医院一般不饲养熊猫，与“养着三只熊猫”的语境不符。", "游乐场": "搭配：“游乐场”一般不饲养动物，不与“养着三只熊猫”搭配。"}, "sentence_index": 0, "correct_answer": "动物园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座动物园每天给客户存钱。", "explanation": "这里应该用〈银行〉。动物园不办存款业务，给客户存钱要去银行。"}, {"text": "这座动物园每天接收很多病人。", "explanation": "这里应该用〈医院〉。动物园主要饲养和展出动物，接收病人要去医院。"}, {"text": "这座动物园每天生产很多汽车。", "explanation": "这里应该用〈工厂〉。动物园是饲养和展出动物的地方，生产汽车要用工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动物园", "is_correct": true, "explanation": "正确：“动物园的工作人员”指动物园的员工，且能介绍动物。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市卖的是商品，不会向人介绍狮子。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行办理金融业务，与介绍狮子无关。"}, {"text": "药店", "is_correct": false, "explanation": "搭配：药店的工作人员通常介绍药品，“介绍狮子”与药店不搭。"}], "explanations": {"动物园": "正确：“动物园的工作人员”指动物园的员工，且能介绍动物。", "超市": "语义：超市卖的是商品，不会向人介绍狮子。", "银行": "语义：银行办理金融业务，与介绍狮子无关。", "药店": "搭配：药店的工作人员通常介绍药品，“介绍狮子”与药店不搭。"}, "sentence_index": 6, "correct_answer": "动物园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个周末都去那个动物园还书。", "explanation": "这里应该用〈图书馆〉。还书要去图书馆，动物园是让人观赏动物的地方。"}, {"text": "我们每周六去那个动物园修自行车。", "explanation": "这里应该用〈修车铺〉。动物园不是修车的地方，修自行车要去修车铺。"}, {"text": "妈妈每周去那个动物园剪头发。", "explanation": "这里应该用〈理发店〉。动物园是让人观赏动物的地方，剪头发要去理发店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只动物园每天早上八点开门。", "corrected_sentence": "这座动物园每天早上八点开门。", "error_description": "量词错误：动物园应用“座”，“只”用于动物，不能用来数动物园。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我们想去一只新的动物园。", "corrected_sentence": "周末我们想去一座新的动物园。", "error_description": "量词错误：动物园应用“座”，“只”用于动物，不能用来数动物园。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
