INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人说话或写文章时，最开始的那样的话。", "primary_collocate": null, "pronunciation": "yuán wén", "ipa": "yɛn˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这句话我记不清原文了。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转告我的话，和老板的原文不一样。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写报告时，引用要保留他的原文。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把他说的原文告诉我吧。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的原文，你还记得吗？", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抄写时没有改动原文，一个字都没少。", "target_word": "原文", "complexity_tier": "T3", "furigana": "tā chāoxiě shí méiyǒu gǎidòng yuánwén, yí gè zì dōu méi shǎo", "sentence_source": "generated"}, {"text": "新闻里引用了市长的原文。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请照他的原文写下来，别改。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我，这是不是他的原文？", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只记得大意，忘了原文。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}], "register": "中性", "sense_fingerprint": "转述或引用时，别人最初说出或写下的那句话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原文", "is_correct": true, "explanation": "原文指别人说话时最初说出的那些话，正好能填入“记不清___了”的空。"}, {"text": "标题", "is_correct": false, "explanation": "语义：标题是文章或书的题目，“这句话”是一句话，没有标题。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：尺寸说物品的大小，不能说一句话有尺寸。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色指事物的色彩，不能用来指话语的内容。"}], "explanations": {"原文": "原文指别人说话时最初说出的那些话，正好能填入“记不清___了”的空。", "标题": "语义：标题是文章或书的题目，“这句话”是一句话，没有标题。", "尺寸": "搭配：尺寸说物品的大小，不能说一句话有尺寸。", "颜色": "搭配：颜色指事物的色彩，不能用来指话语的内容。"}, "sentence_index": 0, "correct_answer": "原文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这句话的原文是提醒大家小心。", "explanation": "这里应该用〈原意〉。原意指说话人想表达的本来意思，原文指说出或写下的原来文字，不能说原文是提醒大家小心这种意思。"}, {"text": "这幅画的原文在博物馆展出。", "explanation": "这里应该用〈原作〉。原作指画作、雕塑等艺术作品的原件，原文指别人说话或写文章时最开始的那样的话，不能用来指一幅画。"}, {"text": "这部电影的原文很好听。", "explanation": "这里应该用〈原声〉。原声指电影里原始的声音或配乐，原文指话语的原来文字，不能用来说电影的声音好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原文", "is_correct": true, "explanation": "原文指别人说的话的原来文字，正好能被“引用”。"}, {"text": "车牌", "is_correct": false, "explanation": "语义：车牌是车辆上的号码牌，不是可以引用的文字内容。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是可以引用的文字内容。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片是介绍身份的卡片，不属于可以引用的话语。"}], "explanations": {"原文": "原文指别人说的话的原来文字，正好能被“引用”。", "车牌": "语义：车牌是车辆上的号码牌，不是可以引用的文字内容。", "体重": "语义：体重是身体的重量，不是可以引用的文字内容。", "名片": "语义：名片是介绍身份的卡片，不属于可以引用的话语。"}, "sentence_index": 6, "correct_answer": "原文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作家的原文堆在书桌上。", "explanation": "这里应该用〈原稿〉。原稿指作者手写或打印的稿件，是实物；原文指话语的原来文字，不能说堆在书桌上。"}, {"text": "这道菜的原文很新鲜。", "explanation": "这里应该用〈原料〉。原料指做菜用的食材，原文指话语的原来文字，不能用来形容食材新鲜。"}, {"text": "这座老宅的原文在城东。", "explanation": "这里应该用〈原址〉。原址指建筑物原来所在的地点，原文指话语的原来文字，不能用来指地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经背下了这只原文。", "corrected_sentence": "我已经背下了这段原文。", "error_description": "错误：「原文」的量词用错。「只」多用于动物或成对物品中的一个，不用于数文字；原文应用「段」来数，应说「这段原文」，不能说「这只原文」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板那只原文我记不清了。", "corrected_sentence": "老板那段原文我记不清了。", "error_description": "错误：「原文」的量词用错。「只」用于动物等，不用于话语；一段话要用「段」来数，应说「那段原文」，不能说「那只原文」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
