INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "未经翻译或改动的原来文字。", "primary_collocate": null, "pronunciation": "yuán wén", "ipa": "yɛn˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这本书我想读中文原文。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译和原文有一点不一样。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他能看懂英文原文。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把原文和译文放在一起看。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗的原文很美。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对照原文检查了翻译。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先读原文。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的原文是法语。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看原文比看译文更有意思。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用日语读了小说的原文。", "target_word": "原文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}], "register": "中性", "sense_fingerprint": "翻译之前、未经改动的原来文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原文", "is_correct": true, "explanation": "原文指未经翻译的原来文字，正好能被“读中文”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“读”的对象是文字，不能说读歌曲。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“读”用于文字，照片要说看，不能说读照片。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是视听作品，不是可以阅读的文字，与“读中文”不搭。"}], "explanations": {"原文": "原文指未经翻译的原来文字，正好能被“读中文”。", "歌曲": "搭配：“读”的对象是文字，不能说读歌曲。", "照片": "搭配：“读”用于文字，照片要说看，不能说读照片。", "电影": "语义：电影是视听作品，不是可以阅读的文字，与“读中文”不搭。"}, "sentence_index": 0, "correct_answer": "原文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅名画的原文价值连城。", "explanation": "这里应该用〈原作〉。原作指名画等艺术作品的原件，才谈得上价值连城；原文指未经翻译的文字，不能用来说画的价值。"}, {"text": "作家的原文堆在书桌上。", "explanation": "这里应该用〈原稿〉。原稿指作者亲手写的稿件，可以堆在桌上；原文指未经翻译的文字，不能说堆在书桌上。"}, {"text": "这道菜的原文很新鲜。", "explanation": "这里应该用〈原料〉。原料指做菜用的食材，才会新鲜；原文指未经翻译的文字，不能用来形容食材新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原文", "is_correct": true, "explanation": "原文指未经翻译的原来文字，正好能被“读”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“读”的对象是文字，窗户不能被读。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车不是可以阅读的东西，与“读”不搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，要说看天气，不能说读天气。"}], "explanations": {"原文": "原文指未经翻译的原来文字，正好能被“读”。", "窗户": "搭配：“读”的对象是文字，窗户不能被读。", "汽车": "搭配：汽车不是可以阅读的东西，与“读”不搭配。", "天气": "语义：天气是自然现象，要说看天气，不能说读天气。"}, "sentence_index": 6, "correct_answer": "原文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座古城的原文在河边。", "explanation": "这里应该用〈原址〉。原址指建筑物原来所在的地点，原文指未经翻译的文字，不能用来指地点。"}, {"text": "这个小说人物的原文是他的朋友。", "explanation": "这里应该用〈原型〉。原型指小说人物的现实依据，即现实中的原形；原文指未经翻译的文字，不能说人物的原文是某个人。"}, {"text": "这张桌子是用原文做的。", "explanation": "这里应该用〈原木〉。原木指未加工的木材，原文指文字，不能用来说桌子是用什么做的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经读完了这只原文。", "corrected_sentence": "我已经读完了这篇原文。", "error_description": "错误：「原文」的量词用错。「只」多用于动物或成对物品中的一个，不用于数文字；「原文」这类文章应用「篇」来数，应说「这篇原文」，不能说「这只原文」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他读完了那位原文。", "corrected_sentence": "他读完了那篇原文。", "error_description": "错误：「原文」的量词用错。「位」只用于人，不用于文字；文章类的原文应用「篇」来数，应说「那篇原文」，不能说「那位原文」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
