INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "口里说的和心里想的意思相反的话。", "primary_collocate": null, "pronunciation": "fǎn huà", "ipa": "fan˨˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "她嘴上说没事，其实是反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说“随你便”，那是反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里不高兴，嘴上却说反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女朋友说不要，往往是反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别听她说，那都是反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想去，却说了句反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道这是反话，所以没生气。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子有时也会说反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说不累，我听出是反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说“你真行”，其实是反话。", "target_word": "反话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "句", "label": "量词"}], "register": "口语", "sense_fingerprint": "嘴上说的和心里真正想的正好相反的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喊话", "is_correct": false, "explanation": "fǎn（f）与 hǎn（h）声母不同，hǎnhuà 的意思是“大声对人说话”。"}, {"text": "感化", "is_correct": false, "explanation": "fǎn（f）与 gǎn（g）声母不同，gǎnhuà 的意思是“用道理或行动使人改变”。"}, {"text": "反话", "is_correct": true, "explanation": "正确答案。反话 fǎnhuà，指嘴上说的与心里真正想的相反的话。"}, {"text": "泛化", "is_correct": false, "explanation": "反（第三声）与泛（第四声）声调不同，fànhuà 的意思是“推广到一般情况”。"}, {"text": "发话", "is_correct": false, "explanation": "反（第三声）与发（第一声）声调不同，fāhuà 的意思是“发出话语或命令”。"}, {"text": "繁华", "is_correct": false, "explanation": "反话 fǎnhuà（三、四声）与繁华 fánhuá（二、二声）声调都不同，繁华的意思是“热闹繁荣”。"}], "explanations": {"喊话": "fǎn（f）与 hǎn（h）声母不同，hǎnhuà 的意思是“大声对人说话”。", "感化": "fǎn（f）与 gǎn（g）声母不同，gǎnhuà 的意思是“用道理或行动使人改变”。", "反话": "正确答案。反话 fǎnhuà，指嘴上说的与心里真正想的相反的话。", "泛化": "反（第三声）与泛（第四声）声调不同，fànhuà 的意思是“推广到一般情况”。", "发话": "反（第三声）与发（第一声）声调不同，fāhuà 的意思是“发出话语或命令”。", "繁华": "反话 fǎnhuà（三、四声）与繁华 fánhuá（二、二声）声调都不同，繁华的意思是“热闹繁荣”。"}, "sentence_index": null, "correct_answer": "反话"}, "level_3": {"options": [{"text": "反话", "is_correct": true, "explanation": "句意是“她嘴上说没事，实际想法相反”，只有“反话”符合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“其实是电话”与前句“嘴上说没事”无关，句意不通。"}, {"text": "神话", "is_correct": false, "explanation": "语义：“其实是神话”与“嘴上说没事”的语境不合，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“其实是”之后接的是话语内容的真实意思，不能接“声音”。"}], "explanations": {"反话": "句意是“她嘴上说没事，实际想法相反”，只有“反话”符合。", "电话": "语义：“其实是电话”与前句“嘴上说没事”无关，句意不通。", "神话": "语义：“其实是神话”与“嘴上说没事”的语境不合，句意不通。", "声音": "搭配：“其实是”之后接的是话语内容的真实意思，不能接“声音”。"}, "sentence_index": 0, "correct_answer": "反话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嘴上说不去，心里却真的很想去，这句反话是他的真心话。", "explanation": "反话指嘴上说的与心里想的相反的话，不指心里真实想的话。句中却把“反话”当作心里的真实想法，二者意思相反。"}, {"text": "他说的都是心里话，全是反话。", "explanation": "反话是嘴上说的和心里想的相反的话，心里话是真实想法，二者矛盾，不能说心里话“全是反话”。"}, {"text": "他总是说反话，从不拐弯抹角。", "explanation": "这里应该用〈大实话〉。反话是故意说与本意相反的话，不能说成直说本意的大实话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反话", "is_correct": true, "explanation": "“我知道这是……所以没生气”，说明这是不必认真的话，只有“反话”符合。"}, {"text": "噩耗", "is_correct": false, "explanation": "语义：“噩耗”令人难过，与“所以没生气”不合，句意不通。"}, {"text": "训令", "is_correct": false, "explanation": "语域：“训令”是正式公文用语，与日常口语语境不合。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”与“所以没生气”没有逻辑联系，句意不通。"}], "explanations": {"反话": "“我知道这是……所以没生气”，说明这是不必认真的话，只有“反话”符合。", "噩耗": "语义：“噩耗”令人难过，与“所以没生气”不合，句意不通。", "训令": "语域：“训令”是正式公文用语，与日常口语语境不合。", "账单": "语义：“账单”与“所以没生气”没有逻辑联系，句意不通。"}, "sentence_index": 6, "correct_answer": "反话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渴了，想喝一杯反话。", "explanation": "“反话”是说出来的话，不是饮料，不能“喝”。"}, {"text": "爸爸用反话种了一棵树。", "explanation": "搭配：“种树”是动作，“反话”是说的话，二者不能搭配。"}, {"text": "这次考试的反话很难，大家都没做完。", "explanation": "“反话”不指试题，它只指故意说与本意相反的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他嘴上说好，其实是一个反话。", "corrected_sentence": "他嘴上说好，其实是一句反话。", "error_description": "量词错误。“反话”用量词“句”，不用“个”。错误是“一个反话”，正确是“一句反话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹听出了哥哥地反话，笑了起来。", "corrected_sentence": "妹妹听出了哥哥的反话，笑了起来。", "error_description": "助词错误。「哥哥」修饰名词「反话」，应用结构助词「的」，不能用「地」。「地」用于修饰动词或形容词。错误是「哥哥地反话」，正确是「哥哥的反话」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97867, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97867, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话的方法，大家说的要一样。", "primary_collocate": null, "pronunciation": "kǒu jìng", "ipa": "kʰou˨˩˦ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "出发前，我们要先统一口径。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的口径不一样，老师不知道听谁的。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对记者的口径必须一致。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早就对好了口径，所以说的一样。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发言之前，大家先把口径定下来。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事，经理要我们对外统一口径。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现两个人的口径完全不同。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的口径不一样，客人就会觉得奇怪。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，我们先商量一下对外的口径。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，大家回答问题的口径要一致。", "target_word": "口径", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "统一口径", "label": "复合"}, {"form": "对口径", "label": "复合"}], "register": "中性", "sense_fingerprint": "对外说法要一致的统一说辞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34d10ddf-7e02-4d9e-8c6e-6ed723a2eab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口径", "is_correct": true, "explanation": "口径指对外统一的说法，与“统一”搭配，填入后语义通顺。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“统一”可以搭配“口径、标准、意见”，不能搭配“脸色”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能被“统一”，与句子所说的对外说法不合。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重属于人的身体特征，不是可以统一的表述，填入后不合语义。"}], "explanations": {"口径": "口径指对外统一的说法，与“统一”搭配，填入后语义通顺。", "脸色": "搭配：“统一”可以搭配“口径、标准、意见”，不能搭配“脸色”。", "天气": "语义：天气是自然现象，不能被“统一”，与句子所说的对外说法不合。", "体重": "体貌：体重属于人的身体特征，不是可以统一的表述，填入后不合语义。"}, "sentence_index": 0, "correct_answer": "口径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们商量出了一支口径。", "explanation": "这里应该用〈套〉。口径是抽象的说法，应说“一套口径”；〈支〉用于笔、枪、队伍等，不用于说法。"}, {"text": "他们定了一把口径，大家都照着说。", "explanation": "这里应该用〈套〉。〈把〉用于有柄的器具，不能用来计量统一的说法。"}, {"text": "我在商店买了一个新口径。", "explanation": "口径指大家统一的说法，不是能买的东西；这里应该用〈杯子〉等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口径", "is_correct": true, "explanation": "口径指说法的标准，填入后与“完全不同”形成通顺的对比，表示两人的说法不一致。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：不说“两个人的面积”，“面积”不能用来描述人。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学概念，不能用来比较两个人。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节不属于人，两个人的季节不能“完全不同”，与句意不合。"}], "explanations": {"口径": "口径指说法的标准，填入后与“完全不同”形成通顺的对比，表示两人的说法不一致。", "面积": "搭配：不说“两个人的面积”，“面积”不能用来描述人。", "电压": "语义：电压是电学概念，不能用来比较两个人。", "季节": "语义：季节不属于人，两个人的季节不能“完全不同”，与句意不合。"}, "sentence_index": 6, "correct_answer": "口径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的口径很多。", "explanation": "这里应该用〈说法〉。口径指事先统一好的对外说法，只能有一种，不能说“很多口径”。"}, {"text": "我把口径放进了书包里。", "explanation": "口径是抽象的说法，不能像物品一样放进书包；这里应该用〈资料〉。"}, {"text": "他把这件事的口径切成了三块。", "explanation": "口径指统一的说法，不能切成块；这里应该用〈说明〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上台以前，我们几个人要先打开口径。", "corrected_sentence": "上台以前，我们几个人要先统一口径。", "error_description": "搭配错误。「口径」常与「统一」「对」搭配，说「统一口径」，不说「打开口径」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人各有一把口径，完全不同。", "corrected_sentence": "两个人各有一套口径，完全不同。", "error_description": "量词用错。口径是抽象的说法，应用〈套〉，不用〈把〉；〈把〉用于有柄的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
