INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97871, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个很响的声音。", "primary_collocate": null, "pronunciation": "pā", "ipa": "pʰa˥", "syllable_count": 1, "sentences": [{"text": "我听见一声很响的“啪”。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里传来一声“啪”，我吓了一跳。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那声“啪”是从厨房传来的。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一声“啪”真响，大家都看过来。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才那一声“啪”是什么？", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里突然有一声“啪”，我醒了。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书掉在地上，发出了一声大大的“啪”。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明学着“啪”的声音，大家都笑了。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只听到“啪”，没看到是什么。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那声“啪”过后，房间里很安静。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "啪啪", "label": "重叠"}], "register": "口语", "sense_fingerprint": "把“啪”当作一个声音本身来说，指一声很响的响动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97871, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啪", "is_correct": true, "explanation": "啪作名词指一个很响的声音，读 pā（第一声）。"}, {"text": "爬", "is_correct": false, "explanation": "pá（第二声）与 pā（第一声）声调不同，意思是攀爬。"}, {"text": "怕", "is_correct": false, "explanation": "pà（第四声）与 pā（第一声）声调不同，意思是害怕。"}, {"text": "发", "is_correct": false, "explanation": "f 与 p 声母不同，fā 意思是发出。"}, {"text": "妈", "is_correct": false, "explanation": "mā 与 pā 声母不同，意思是妈妈。"}], "explanations": {"啪": "啪作名词指一个很响的声音，读 pā（第一声）。", "爬": "pá（第二声）与 pā（第一声）声调不同，意思是攀爬。", "怕": "pà（第四声）与 pā（第一声）声调不同，意思是害怕。", "发": "f 与 p 声母不同，fā 意思是发出。", "妈": "mā 与 pā 声母不同，意思是妈妈。"}, "sentence_index": null, "correct_answer": "啪"}, "level_3": {"options": [{"text": "啪", "is_correct": true, "explanation": "“啪”作为一声很响的声音，可以放在“一声很响的”之后。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花”是植物，不会发出声音，与“一声很响的”不搭。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“一声很响的”后面不能接“树”，两者不能组合。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”是物品，不是可以听见的响声。"}], "explanations": {"啪": "“啪”作为一声很响的声音，可以放在“一声很响的”之后。", "花": "语义：“花”是植物，不会发出声音，与“一声很响的”不搭。", "树": "搭配：“一声很响的”后面不能接“树”，两者不能组合。", "书": "语义：“书”是物品，不是可以听见的响声。"}, "sentence_index": 0, "correct_answer": "啪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我闻到一股很香的“啪”。", "explanation": "这里应该用〈味道〉。“啪”是声音，只能听见，不能闻到。"}, {"text": "我看见一道很亮的“啪”，吓了一跳。", "explanation": "这里应该用〈闪电〉。“啪”指声音，不能用“看见”来描述有亮光的东西。"}, {"text": "那一声“啪”很好看，大家都看过来。", "explanation": "这里应该用〈烟花〉。烟花是可以看的东西，“啪”只是声音，不能说“好看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97871, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啪", "is_correct": true, "explanation": "啪作名词指一个很响的声音，读 pā（第一声）。"}, {"text": "咖", "is_correct": false, "explanation": "kā 与 pā 声母不同（k 与 p 发音部位不同），意思是咖（如咖啡）。"}, {"text": "她", "is_correct": false, "explanation": "tā 与 pā 声母不同，意思是她。"}, {"text": "巴", "is_correct": false, "explanation": "bā 与 pā 的送气与否不同（b 不送气），意思是巴（如巴士）。"}], "explanations": {"啪": "啪作名词指一个很响的声音，读 pā（第一声）。", "咖": "kā 与 pā 声母不同（k 与 p 发音部位不同），意思是咖（如咖啡）。", "她": "tā 与 pā 声母不同，意思是她。", "巴": "bā 与 pā 的送气与否不同（b 不送气），意思是巴（如巴士）。"}, "sentence_index": null, "correct_answer": "啪"}, "level_3": {"options": [{"text": "啪", "is_correct": true, "explanation": "“啪”作为一声大大的声音，可以放在“发出了一声大大的”之后。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“发出一声”后只能接声音，不能接“雨”。"}, {"text": "灯", "is_correct": false, "explanation": "语义：“灯”是照明的器具，不是声音。"}, {"text": "光", "is_correct": false, "explanation": "语义：“光”是光线，不是能听见的响声。"}], "explanations": {"啪": "“啪”作为一声大大的声音，可以放在“发出了一声大大的”之后。", "雨": "搭配：“发出一声”后只能接声音，不能接“雨”。", "灯": "语义：“灯”是照明的器具，不是声音。", "光": "语义：“光”是光线，不是能听见的响声。"}, "sentence_index": 6, "correct_answer": "啪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摸着那个“啪”，觉得很暖和。", "explanation": "这里应该用〈杯子〉。“啪”是声音，不能用手摸，只能说听见。"}, {"text": "他吃了那个“啪”，觉得很香。", "explanation": "这里应该用〈饼干〉。“啪”是声音，不能吃。"}, {"text": "我住在那个“啪”里。", "explanation": "这里应该用〈房间〉。“啪”是声音，不能当作居住的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刚才门外传来一个“啪”。", "corrected_sentence": "刚才门外传来一声“啪”。", "error_description": "量词错误：作为声音的名词“啪”应搭配量词“声”，说“一个啪”不地道，应改为“一声啪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "杯子掉在地上，发出了一声清脆地“啪”。", "corrected_sentence": "杯子掉在地上，发出了一声清脆的“啪”。", "error_description": "结构错误：“清脆”修饰名词“啪”时用“的”，不用“地”，应说“清脆的“啪””。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
