INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97872, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "拟声词，形容东西打在一起或开关发出的响声。", "primary_collocate": null, "pronunciation": "pā", "ipa": "pʰa˥", "syllable_count": 1, "sentences": [{"text": "门啪的一声关上了。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他啪地把书放在桌子上。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我按下开关，灯啪的一声亮了。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子高兴地啪地拍了一下手。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气了，啪地拍了一下桌子。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一颗雨点啪地打在窗户上。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书从架子上掉下来，啪的一声落在地上。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师啪地合上书，教室一下子安静了。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木柴在火里啪的一声裂开了。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他啪的一下关掉了电视。", "target_word": "啪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "啪啪", "label": "重叠"}], "register": "口语", "sense_fingerprint": "拟声词，表示东西碰撞、拍打或开关发出的清脆响声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97872, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啪", "is_correct": true, "explanation": "啪为拟声词，读 pā（第一声），形容清脆的撞击或开关声。"}, {"text": "爬", "is_correct": false, "explanation": "pá（第二声）与 pā（第一声）声调不同，意思是攀爬。"}, {"text": "怕", "is_correct": false, "explanation": "pà（第四声）与 pā（第一声）声调不同，意思是害怕。"}, {"text": "八", "is_correct": false, "explanation": "bā 与 pā 的声母送气与否不同（b 不送气），意思是数字八。"}, {"text": "他", "is_correct": false, "explanation": "tā 与 pā 声母不同，意思是他。"}, {"text": "妈", "is_correct": false, "explanation": "mā 与 pā 声母不同，意思是妈妈。"}], "explanations": {"啪": "啪为拟声词，读 pā（第一声），形容清脆的撞击或开关声。", "爬": "pá（第二声）与 pā（第一声）声调不同，意思是攀爬。", "怕": "pà（第四声）与 pā（第一声）声调不同，意思是害怕。", "八": "bā 与 pā 的声母送气与否不同（b 不送气），意思是数字八。", "他": "tā 与 pā 声母不同，意思是他。", "妈": "mā 与 pā 声母不同，意思是妈妈。"}, "sentence_index": null, "correct_answer": "啪"}, "level_3": {"options": [{"text": "啪", "is_correct": true, "explanation": "“啪”是拟声词，修饰“的一声”，描写门关上时清脆的响声。"}, {"text": "嗡", "is_correct": false, "explanation": "语义：“嗡”是持续的低鸣声，与门关上的清脆声不符。"}, {"text": "汪", "is_correct": false, "explanation": "语义：“汪”是狗叫声，与关门的声音不符。"}, {"text": "滴答", "is_correct": false, "explanation": "搭配：“滴答”多指钟表或水滴的声音，不用来形容门关上的声音。"}], "explanations": {"啪": "“啪”是拟声词，修饰“的一声”，描写门关上时清脆的响声。", "嗡": "语义：“嗡”是持续的低鸣声，与门关上的清脆声不符。", "汪": "语义：“汪”是狗叫声，与关门的声音不符。", "滴答": "搭配：“滴答”多指钟表或水滴的声音，不用来形容门关上的声音。"}, "sentence_index": 0, "correct_answer": "啪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他啪地笑了起来。", "explanation": "这里应该用〈哈哈〉。“啪”形容清脆的撞击或开关声，不能用来形容笑。"}, {"text": "他啪地走进了教室。", "explanation": "这里应该用〈轻轻〉。“啪”是清脆的撞击声，走路没有这种声音，不能用“啪地”描写。"}, {"text": "他很生气，啪地低下了头。", "explanation": "这里应该用〈默默〉。“啪”是有声响的拟声词，不能描写没有声音的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97872, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啪", "is_correct": true, "explanation": "啪为拟声词，读 pā（第一声），形容清脆的撞击或开关声。"}, {"text": "发", "is_correct": false, "explanation": "f 与 p 声母不同，fā 意思是发出。"}, {"text": "咖", "is_correct": false, "explanation": "kā 与 pā 声母不同（k 与 p 发音部位不同），意思是咖（如咖啡）。"}, {"text": "她", "is_correct": false, "explanation": "tā 与 pā 声母不同，意思是她。"}, {"text": "巴", "is_correct": false, "explanation": "bā 与 pā 的送气与否不同（b 不送气），意思是巴（如巴士）。"}], "explanations": {"啪": "啪为拟声词，读 pā（第一声），形容清脆的撞击或开关声。", "发": "f 与 p 声母不同，fā 意思是发出。", "咖": "kā 与 pā 声母不同（k 与 p 发音部位不同），意思是咖（如咖啡）。", "她": "tā 与 pā 声母不同，意思是她。", "巴": "bā 与 pā 的送气与否不同（b 不送气），意思是巴（如巴士）。"}, "sentence_index": null, "correct_answer": "啪"}, "level_3": {"options": [{"text": "啪", "is_correct": true, "explanation": "“啪”是拟声词，修饰“的一声”，描写书落地时清脆的响声。"}, {"text": "咕嘟", "is_correct": false, "explanation": "搭配：“咕嘟”指水或汤沸腾的声音，不用于书落地的声音。"}, {"text": "呼呼", "is_correct": false, "explanation": "语义：“呼呼”是风吹的声音，与书从架子上掉下来无关。"}, {"text": "叽叽", "is_correct": false, "explanation": "语义：“叽叽”是小鸟或虫子的叫声，与书落地不符。"}], "explanations": {"啪": "“啪”是拟声词，修饰“的一声”，描写书落地时清脆的响声。", "咕嘟": "搭配：“咕嘟”指水或汤沸腾的声音，不用于书落地的声音。", "呼呼": "语义：“呼呼”是风吹的声音，与书从架子上掉下来无关。", "叽叽": "语义：“叽叽”是小鸟或虫子的叫声，与书落地不符。"}, "sentence_index": 6, "correct_answer": "啪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心情啪地好了起来。", "explanation": "这里应该用〈突然〉。“啪”是拟声词，只能形容发出的声响，不能形容心情的变化。"}, {"text": "我们家的狗啪地叫了一声。", "explanation": "这里应该用〈汪汪〉。“啪”是清脆的撞击声，狗叫要用〈汪汪〉。"}, {"text": "夜里很安静，他啪地睡着了。", "explanation": "这里应该用〈很快〉。睡着是无声的过程，“啪”是拟声词，不能用来形容睡着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书地啪放在桌子上。", "corrected_sentence": "他把书啪地放在桌子上。", "error_description": "语序错误：状语后缀“地”要紧跟在“啪”后，说“啪地”，不能颠倒成“地啪”。应说“他把书啪地放在桌子上。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她啪地地把灯关了。", "corrected_sentence": "她啪地把灯关了。", "error_description": "重复标记：状语“啪地”的“地”只用一个，“地地”重复，应说“啪地把灯关了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
