INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "请来的、受大家欢迎的客人。", "primary_collocate": null, "pronunciation": "jiā bīn", "ipa": "tɕja˥ pin˥", "syllable_count": 2, "sentences": [{"text": "今天节目请来了一位嘉宾。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众热烈欢迎各位嘉宾。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位嘉宾唱歌唱得特别好听。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人向大家介绍了今晚的嘉宾。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嘉宾们坐在台上，笑着聊天。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台请了很多嘉宾来参加晚会。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位嘉宾讲了一个有意思的故事。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢这个节目的嘉宾。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节目里的嘉宾回答了观众的问题。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每期节目都有不同的嘉宾。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "嘉宾们", "label": "复数"}, {"form": "特邀嘉宾", "label": "复合"}], "register": "中性", "sense_fingerprint": "节目或活动中请来的受欢迎的客人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘉宾", "is_correct": true, "explanation": "嘉宾：节目请来的受欢迎的客人，与“节目请来了一位”相符。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”是家具，不能被节目“请来”，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，节目不会把它请来做嘉宾，句意不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不能被节目请来，量词“位”也只用于人。"}], "explanations": {"嘉宾": "嘉宾：节目请来的受欢迎的客人，与“节目请来了一位”相符。", "沙发": "语义：“沙发”是家具，不能被节目“请来”，句意不通。", "桌子": "语义：“桌子”是物品，节目不会把它请来做嘉宾，句意不通。", "月亮": "语义：“月亮”不能被节目请来，量词“位”也只用于人。"}, "sentence_index": 0, "correct_answer": "嘉宾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司有很多嘉宾，他们每天都来上班。", "explanation": "这里应该用〈员工〉。嘉宾指受邀的客人，不是公司的成员。"}, {"text": "这家健身房每天有很多嘉宾，他们都办了卡。", "explanation": "这里应该用〈会员〉。嘉宾指受邀的客人，办卡的人是会员。"}, {"text": "火车站每天有很多嘉宾，他们都在排队买票。", "explanation": "这里应该用〈旅客〉。嘉宾指受邀的客人，排队买票出行的是旅客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘉宾", "is_correct": true, "explanation": "嘉宾：受邀请的客人，与“讲了一个有意思的故事”相符。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像不能讲故事，与“讲了”的动作矛盾。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能讲故事，量词“位”也不用于物品。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不会讲有意思的故事，与句中的叙述不符。"}], "explanations": {"嘉宾": "嘉宾：受邀请的客人，与“讲了一个有意思的故事”相符。", "雕像": "语义：雕像不能讲故事，与“讲了”的动作矛盾。", "椅子": "语义：椅子不能讲故事，量词“位”也不用于物品。", "婴儿": "语义：婴儿还不会讲有意思的故事，与句中的叙述不符。"}, "sentence_index": 6, "correct_answer": "嘉宾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校有很多嘉宾，他们都是学生。", "explanation": "这里应该用〈在校生〉。嘉宾指受邀的客人，不是在校学习的人。"}, {"text": "那家商店每天都有很多嘉宾来买东西。", "explanation": "这里应该用〈顾客〉。嘉宾指受邀的客人，来买东西的是顾客。"}, {"text": "医院每天有很多嘉宾来看病。", "explanation": "这里应该用〈病人〉。嘉宾指受邀的客人，来医院看病的是病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天节目请来了两只嘉宾。", "corrected_sentence": "今天节目请来了两位嘉宾。", "error_description": "错误：“两只嘉宾”，量词“只”用于动物。正确：“两位嘉宾”，嘉宾是人，量词应用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位嘉宾们讲了一个很短的故事。", "corrected_sentence": "那位嘉宾讲了一个很短的故事。", "error_description": "错误：“那位嘉宾们”。“位”表示单数，与“们”表示的复数矛盾，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
