INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受邀请的尊贵客人。", "primary_collocate": null, "pronunciation": "jiā bīn", "ipa": "tɕja˥ pin˥", "syllable_count": 2, "sentences": [{"text": "婚礼上来了很多嘉宾。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请嘉宾坐在前面的位子上。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司邀请了几位嘉宾参加开幕式。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嘉宾到达以后，经理亲自去门口迎接。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是大会的嘉宾。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请各位嘉宾入座。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，我们送嘉宾上了车。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店为嘉宾准备了房间。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出席晚宴的嘉宾都穿着正式的衣服。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他作为嘉宾出席了学校的活动。", "target_word": "嘉宾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "嘉宾们", "label": "复数"}, {"form": "特邀嘉宾", "label": "复合"}], "register": "中性", "sense_fingerprint": "婚礼、会议等场合受邀的尊贵客人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘉宾", "is_correct": true, "explanation": "嘉宾：受邀的尊贵客人，与婚礼场合相符。"}, {"text": "囚犯", "is_correct": false, "explanation": "语义：囚犯不会被邀请到婚礼上，与句子的场合不符。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：婚礼上不会来很多老鼠，这种说法与场合相矛盾。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“来了很多”用于人，不能说“来了很多垃圾”。"}], "explanations": {"嘉宾": "嘉宾：受邀的尊贵客人，与婚礼场合相符。", "囚犯": "语义：囚犯不会被邀请到婚礼上，与句子的场合不符。", "老鼠": "语义：婚礼上不会来很多老鼠，这种说法与场合相矛盾。", "垃圾": "搭配：“来了很多”用于人，不能说“来了很多垃圾”。"}, "sentence_index": 0, "correct_answer": "嘉宾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景区门口挤满了排队买票的嘉宾。", "explanation": "这里应该用〈游客〉。嘉宾指受邀请的尊贵客人，排队买票进景区的是游客。"}, {"text": "我们请了一位嘉宾来收拾厨房。", "explanation": "这里应该用〈帮手〉。嘉宾是受邀的尊贵客人，不是被请来干活的人。"}, {"text": "下课铃响了，嘉宾们冲出教室。", "explanation": "这里应该用〈学生〉。嘉宾指受邀请的尊贵客人，下课冲出教室的是学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘉宾", "is_correct": true, "explanation": "嘉宾：受邀的尊贵客人，与“送……上了车”的语境相符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“送……上了车”的对象应是人或物件，“空气”不能被送上车。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光不能被人送上车，句意不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不能被送上车，句意完全不通。"}], "explanations": {"嘉宾": "嘉宾：受邀的尊贵客人，与“送……上了车”的语境相符。", "空气": "搭配：“送……上了车”的对象应是人或物件，“空气”不能被送上车。", "月光": "语义：月光不能被人送上车，句意不通。", "影子": "语义：影子不能被送上车，句意完全不通。"}, "sentence_index": 6, "correct_answer": "嘉宾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这次活动的嘉宾，负责安排一切。", "explanation": "这里应该用〈主人〉。嘉宾是受邀的客人，不负责安排活动。"}, {"text": "马路上，嘉宾们正在修路。", "explanation": "这里应该用〈工人〉。嘉宾指受邀请的尊贵客人，在马路上修路的是工人。"}, {"text": "路口的嘉宾正在指挥交通。", "explanation": "这里应该用〈警察〉。嘉宾指受邀请的尊贵客人，在路口指挥交通的是警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们请一只嘉宾坐在最前面的位子上。", "corrected_sentence": "我们请一位嘉宾坐在最前面的位子上。", "error_description": "错误：“一只嘉宾”，量词错误。“只”多用于动物，“嘉宾”指人，应用“位”，说“一位嘉宾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她作为嘉宾们出席了学校的晚会。", "corrected_sentence": "她作为嘉宾出席了学校的晚会。", "error_description": "错误：“嘉宾们”。“们”表示复数，与单数的“她”不合，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
