INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97881, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "等一会再见。", "primary_collocate": null, "pronunciation": "huí jiàn", "ipa": "xweɪ˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我去买点东西，咱们一会儿回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先忙，我们十分钟后回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先去银行，到时候在门口回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开完会我们在楼下回见吧。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先吃，我们晚点儿回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去接孩子，半小时以后回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午两点在图书馆回见，别忘了带书。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去洗个澡，一会儿回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先分头找，十分钟后在门口回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先去买票，咱们在电影院门口回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "约好过一会儿再见面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回见", "is_correct": true, "explanation": "回见：约定过一会儿再见面，与“一会儿”相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业要经过多年学业，不能在“一会儿”之内完成。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是重大人生事件，与“一会儿”的短时间安排不相符。"}, {"text": "离婚", "is_correct": false, "explanation": "语义：“离婚”不能约定在一会儿之后进行，句意不通。"}], "explanations": {"回见": "回见：约定过一会儿再见面，与“一会儿”相符。", "毕业": "语义：毕业要经过多年学业，不能在“一会儿”之内完成。", "结婚": "语义：结婚是重大人生事件，与“一会儿”的短时间安排不相符。", "离婚": "语义：“离婚”不能约定在一会儿之后进行，句意不通。"}, "sentence_index": 0, "correct_answer": "回见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毕业以后，我们要向母校回见。", "explanation": "这里应该用〈告别〉。回见约定不久后再见面，离开母校这种长久分别不能用。"}, {"text": "我们每年夏天都回见一次。", "explanation": "这里应该用〈见面〉。回见表示过一会儿再见面，不用于每年一次的定期见面。"}, {"text": "我们分开十年，在车站终于回见。", "explanation": "这里应该用〈重逢〉。回见是临别时的道别语，约定很快再见面，久别后的重逢不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回见", "is_correct": true, "explanation": "回见：约定下午两点之后再见面，与“下午两点”相符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休是人生阶段的变化，不能在下午两点的约定里发生。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：辞职是工作上的决定，不是能约在图书馆进行的事，句意不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”不是约在图书馆能发生的事，与“别忘了带书”的约定矛盾。"}], "explanations": {"回见": "回见：约定下午两点之后再见面，与“下午两点”相符。", "退休": "语义：退休是人生阶段的变化，不能在下午两点的约定里发生。", "辞职": "语义：辞职是工作上的决定，不是能约在图书馆进行的事，句意不通。", "出生": "语义：“出生”不是约在图书馆能发生的事，与“别忘了带书”的约定矛盾。"}, "sentence_index": 6, "correct_answer": "回见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们因为性格不合，决定回见。", "explanation": "这里应该用〈分手〉。回见约定不久后再见面，不用于关系的结束。"}, {"text": "他们约好二十年后在同一个地方回见。", "explanation": "这里应该用〈再见〉。回见约定的是过一会儿再见面，二十年后的见面不能用此词。"}, {"text": "我们回见了老同学，聊了一下午。", "explanation": "这里应该用〈见到〉。回见是不及物的约定用语，不能带宾语“老同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你先去忙，我们半个小时前回见。", "corrected_sentence": "你先去忙，我们半个小时后回见。", "error_description": "错误：“半个小时前回见”。回见约定的是过一会儿再见面，时间应在以后，应改为“半个小时后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去接孩子，咱们一会儿回见他。", "corrected_sentence": "我去接孩子，咱们一会儿回见。", "error_description": "错误：“回见他”。“回见”不带宾语，应去掉“他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
