INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97882, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "以后再见，用于道别。", "primary_collocate": null, "pronunciation": "huí jiàn", "ipa": "xweɪ˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我先走了，回见！", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不早了，大家回见！", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天还要上班，我回家了，回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天谢谢你，回见！", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的，那就这样，回见啊。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挥挥手说：“回见！”", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我得去上课了，回见！", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我们该回去了，回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着跟朋友说回见。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里他说了声“回见”就挂了。", "target_word": "回见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "分别时说的道别语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回见", "is_correct": true, "explanation": "回见：分别时用的道别语，与“我先走了”相符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”用于招呼或提醒，不是道别，说“我先走了，喂！”句意不通。"}, {"text": "哈哈", "is_correct": false, "explanation": "语义：“哈哈”表示笑声，与离开时的道别语气不符。"}, {"text": "哎呀", "is_correct": false, "explanation": "语义：“哎呀”表示惊讶或懊恼，与“我先走了”的道别场景不合。"}], "explanations": {"回见": "回见：分别时用的道别语，与“我先走了”相符。", "喂": "语义：“喂”用于招呼或提醒，不是道别，说“我先走了，喂！”句意不通。", "哈哈": "语义：“哈哈”表示笑声，与离开时的道别语气不符。", "哎呀": "语义：“哎呀”表示惊讶或懊恼，与“我先走了”的道别场景不合。"}, "sentence_index": 0, "correct_answer": "回见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "进门时，他先大声说：“回见！”", "explanation": "这里应该用〈问好〉。回见是道别语，进门时要先向大家问好，不能说回见。"}, {"text": "欢迎光临，回见！", "explanation": "这里应该用〈您好〉。回见是分别时的道别语，迎接客人进门时不能说。"}, {"text": "我们分别二十年后，终于在机场回见。", "explanation": "这里应该用〈相见〉。回见是临别时的道别语，久别重逢时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回见", "is_correct": true, "explanation": "回见：道别语，与“得去上课了”相符。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，与“得去上课了”的道别场景不合。"}, {"text": "呸", "is_correct": false, "explanation": "语义：“呸”表示唾弃，用在道别时语气完全不对。"}, {"text": "哦", "is_correct": false, "explanation": "语义：“哦”表示明白或应答，不用来道别，句意不通。"}], "explanations": {"回见": "回见：道别语，与“得去上课了”相符。", "哇": "语义：“哇”表示惊叹，与“得去上课了”的道别场景不合。", "呸": "语义：“呸”表示唾弃，用在道别时语气完全不对。", "哦": "语义：“哦”表示明白或应答，不用来道别，句意不通。"}, "sentence_index": 6, "correct_answer": "回见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "撞到人后，他急忙说：“回见！”", "explanation": "这里应该用〈对不起〉。回见是道别语，撞到人时要道歉，不能用来道别。"}, {"text": "他在路口拦住一位路人，急切地说：“回见！”", "explanation": "这里应该用〈请问〉。回见是道别语，向陌生人问路时应先说“请问”。"}, {"text": "考试开始了，老师说：“回见！”", "explanation": "这里应该用〈安静〉。回见是道别语，考试开始时老师要求的是安静，不能说回见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先去开会了，回见过！", "corrected_sentence": "我先去开会了，回见！", "error_description": "错误：“回见过”。“回见”是道别语，不能带体标“过”，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我得去洗衣服了，的回见！", "corrected_sentence": "我得去洗衣服了，回见！", "error_description": "错误：“回见”前多了结构助词“的”。“回见”是道别语，不能加“的”，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97883, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "站起来", "is_correct": true, "explanation": "正确：“站起来”与“坐下”相反，表示由坐变为站。"}, {"text": "走出去", "is_correct": false, "explanation": "与“坐下”没有反义关系，“走出去”是离开的动作。"}, {"text": "打开", "is_correct": false, "explanation": "与“坐下”没有反义关系，“打开”指使物体开启。"}, {"text": "说话", "is_correct": false, "explanation": "与“坐下”没有反义关系，“说话”是言语行为。"}], "correct_answer": "站起来", "explanations": {"站起来": "正确：“站起来”与“坐下”相反，表示由坐变为站。", "走出去": "与“坐下”没有反义关系，“走出去”是离开的动作。", "打开": "与“坐下”没有反义关系，“打开”指使物体开启。", "说话": "与“坐下”没有反义关系，“说话”是言语行为。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97883, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "站起来", "is_correct": true, "explanation": "正确：“站起来”与“坐下”相反，表示由坐变为站。"}, {"text": "进门", "is_correct": false, "explanation": "与“坐下”没有反义关系，“进门”指走进门里。"}, {"text": "关灯", "is_correct": false, "explanation": "与“坐下”没有反义关系，“关灯”指关闭电灯。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“坐下”没有反义关系，“吃饭”是进食的动作。"}], "correct_answer": "站起来", "explanations": {"站起来": "正确：“站起来”与“坐下”相反，表示由坐变为站。", "进门": "与“坐下”没有反义关系，“进门”指走进门里。", "关灯": "与“坐下”没有反义关系，“关灯”指关闭电灯。", "吃饭": "与“坐下”没有反义关系，“吃饭”是进食的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97883, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "屁股放在椅子上，不站着。", "primary_collocate": null, "pronunciation": "zuò xià", "ipa": "tsuɔ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "请坐下，我给你倒杯茶。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进教室，在第一排坐下了。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢在椅子上坐下。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都坐下，会议马上开始。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在我旁边坐下，笑着说话。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一进门就坐下吃饭。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你站了一天，快坐下休息吧。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们坐下。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在沙发上坐下，打开了电视。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚坐下，电话就响了。", "target_word": "坐下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐下了", "label": "体标"}, {"form": "坐下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "坐下：从站着变成坐在椅子上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97883, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坐下", "is_correct": true, "explanation": "正确答案。坐下 zuò xià，指由站着变成坐在椅子上。"}, {"text": "左下", "is_correct": false, "explanation": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边的下方。"}, {"text": "桌下", "is_correct": false, "explanation": "zhuō（第一声）与 zuò 声母不同（zh 与 z），意思是桌子的下面。"}, {"text": "坐向", "is_correct": false, "explanation": "xiàng 与 xià 韵母不同（ang 与 a），意思是房屋或座位的朝向。"}], "explanations": {"坐下": "正确答案。坐下 zuò xià，指由站着变成坐在椅子上。", "左下": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边的下方。", "桌下": "zhuō（第一声）与 zuò 声母不同（zh 与 z），意思是桌子的下面。", "坐向": "xiàng 与 xià 韵母不同（ang 与 a），意思是房屋或座位的朝向。"}, "sentence_index": null, "correct_answer": "坐下"}, "level_3": {"options": [{"text": "闭嘴", "is_correct": false, "explanation": "语域：“闭嘴”是命令式的粗率口气，与“请……”的礼貌语域冲突。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“出去”让对方离开，与“我给你倒杯茶”的待客语境矛盾。"}, {"text": "坐下", "is_correct": true, "explanation": "正确：“请坐下”是礼貌的待客说法，与后句“我给你倒杯茶”衔接自然。"}, {"text": "走开", "is_correct": false, "explanation": "语义：“走开”是让对方离去，与“我给你倒杯茶”的待客语境相反。"}], "explanations": {"闭嘴": "语域：“闭嘴”是命令式的粗率口气，与“请……”的礼貌语域冲突。", "出去": "语义：“出去”让对方离开，与“我给你倒杯茶”的待客语境矛盾。", "坐下": "正确：“请坐下”是礼貌的待客说法，与后句“我给你倒杯茶”衔接自然。", "走开": "语义：“走开”是让对方离去，与“我给你倒杯茶”的待客语境相反。"}, "sentence_index": 0, "correct_answer": "坐下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直坐下看书，不愿出门。", "explanation": "这里应该用〈坐着〉。“坐下”表示由站到坐的动作，有起点，不能与“一直”搭配表示持续；持续的姿势要说“坐着”。"}, {"text": "他在电脑前坐下了三个小时。", "explanation": "这里应该用〈坐着〉。“坐下”是由站到坐的瞬间动作，不能与“三个小时”这样的时段搭配；表示持续的坐姿要说“坐着”。"}, {"text": "他一听到名字，就坐下走向窗口。", "explanation": "这里应该用〈站起来〉。“坐下”与后面“走向窗口”的动作衔接不通，听到名字后应先站起来再走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跑步", "is_correct": false, "explanation": "语义：站了一天之后应该停下来休息，“快跑步休息”与语境相反。"}, {"text": "坐下", "is_correct": true, "explanation": "正确：“快坐下休息”符合站了一天后想休息的语境。"}, {"text": "大哭", "is_correct": false, "explanation": "语义：“大哭”与“休息”的语义冲突，“快大哭休息”说不通。"}, {"text": "吵架", "is_correct": false, "explanation": "搭配：“吵架”与“休息”不搭配，“快吵架休息吧”不成话。"}], "explanations": {"跑步": "语义：站了一天之后应该停下来休息，“快跑步休息”与语境相反。", "坐下": "正确：“快坐下休息”符合站了一天后想休息的语境。", "大哭": "语义：“大哭”与“休息”的语义冲突，“快大哭休息”说不通。", "吵架": "搭配：“吵架”与“休息”不搭配，“快吵架休息吧”不成话。"}, "sentence_index": 6, "correct_answer": "坐下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一直坐下弹钢琴，很少休息。", "explanation": "这里应该用〈坐着〉。“坐下”表示动作的起点，不能表示持续地弹琴；持续的姿势要说“坐着”。"}, {"text": "他在沙发上坐下了一下午，腿都麻了。", "explanation": "这里应该用〈坐着〉。“坐下”是瞬间完成的动作，不能与“一下午”这样的时段搭配；表示持续的坐姿要说“坐着”。"}, {"text": "他在佛像前坐下，磕了三个头。", "explanation": "这里应该用〈跪下〉。磕头要双膝跪地，“坐下”指臀部落在座位上，不能用来描述跪拜的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站了很久，最后在椅子上坐下着，等待叫号。", "corrected_sentence": "他站了很久，最后在椅子上坐下了，等待叫号。", "error_description": "体标错误：“坐下”表示动作已经完成，后面应接“了”，不能接“着”。应说“最后在椅子上坐下了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一进门就坐下着，喝了一杯水。", "corrected_sentence": "我一进门就坐下了，喝了一杯水。", "error_description": "体标错误：“坐下”表示动作完成，后面应接“了”，不能接“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
