INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97887, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "很多东西放在一起，成一大堆的数量。", "primary_collocate": null, "pronunciation": "duī", "ipa": "tweɪ˥", "syllable_count": 1, "sentences": [{"text": "地上有一堆衣服，像座小山。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一堆书，没人整理。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里有一堆沙子，孩子们在玩。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一堆石头，大小不一。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口放着一堆旧报纸。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一堆脏衣服放进洗衣机。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有一堆碗，还没洗。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在河边捡了一堆木头。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙角有一堆旧杂志，落满了灰。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把一堆玩具放回了箱子里。", "target_word": "堆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆", "label": "数量"}, {"form": "一大堆", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词：东西堆在一起成一堆的量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34d10ddf-7e02-4d9e-8c6e-6ed723a2eab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "堆", "is_correct": true, "explanation": "堆（duī，第一声）是本词，指很多东西聚在一起，与听到的读音一致。"}, {"text": "对", "is_correct": false, "explanation": "对（duì，第四声）与 duī（第一声）声调不同，意思是对错的对。"}, {"text": "推", "is_correct": false, "explanation": "推（tuī）与 duī 声母不同（t 与 d），意思是推动。"}, {"text": "队", "is_correct": false, "explanation": "队（duì，第四声）与 duī（第一声）声调不同，意思是队伍。"}], "explanations": {"堆": "堆（duī，第一声）是本词，指很多东西聚在一起，与听到的读音一致。", "对": "对（duì，第四声）与 duī（第一声）声调不同，意思是对错的对。", "推": "推（tuī）与 duī 声母不同（t 与 d），意思是推动。", "队": "队（duì，第四声）与 duī（第一声）声调不同，意思是队伍。"}, "sentence_index": null, "correct_answer": "堆"}, "level_3": {"options": [{"text": "堆", "is_correct": true, "explanation": "堆是量词，用于成堆的东西，与“衣服”搭配，填入后像座小山的描写也通顺。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对的东西，“一只衣服”搭配不当。"}, {"text": "颗", "is_correct": false, "explanation": "语义：“颗”用于小而圆的东西，衣服不属于此类。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，“一本衣服”不成立。"}], "explanations": {"堆": "堆是量词，用于成堆的东西，与“衣服”搭配，填入后像座小山的描写也通顺。", "只": "搭配：“只”用于动物或成对的东西，“一只衣服”搭配不当。", "颗": "语义：“颗”用于小而圆的东西，衣服不属于此类。", "本": "搭配：“本”用于书册，“一本衣服”不成立。"}, "sentence_index": 0, "correct_answer": "堆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上整整齐齐地放着一堆书。", "explanation": "这里应该用〈摞〉。〈堆〉指东西随意聚在一起，不整齐；整齐码放的书要用〈摞〉。"}, {"text": "村子前面流过一堆河。", "explanation": "量词用错。这里应该用〈条〉：河是长条形的，〈堆〉只用于聚在一起的东西。"}, {"text": "天边挂着一堆彩虹，很美。", "explanation": "这里应该用〈道〉：彩虹是单个景象，〈堆〉不用于彩虹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97887, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "堆", "is_correct": true, "explanation": "堆（duī，第一声）是本词，指很多东西聚在一起，与听到的读音一致。"}, {"text": "兑", "is_correct": false, "explanation": "兑（duì，第四声）与 duī（第一声）声调不同，意思是兑换。"}, {"text": "追", "is_correct": false, "explanation": "追（zhuī）与 duī 声母不同（zh 与 d），意思是追赶。"}, {"text": "蹲", "is_correct": false, "explanation": "蹲（dūn）与 duī 韵母不同（un 与 ui），意思是蹲下。"}], "explanations": {"堆": "堆（duī，第一声）是本词，指很多东西聚在一起，与听到的读音一致。", "兑": "兑（duì，第四声）与 duī（第一声）声调不同，意思是兑换。", "追": "追（zhuī）与 duī 声母不同（zh 与 d），意思是追赶。", "蹲": "蹲（dūn）与 duī 韵母不同（un 与 ui），意思是蹲下。"}, "sentence_index": null, "correct_answer": "堆"}, "level_3": {"options": [{"text": "堆", "is_correct": true, "explanation": "堆是量词，用于成堆的东西，与“碗”搭配，填入后“还没洗”的语境通顺。"}, {"text": "块", "is_correct": false, "explanation": "搭配：“块”用于成块的东西，“一块碗”搭配不当。"}, {"text": "株", "is_correct": false, "explanation": "搭配：“株”用于植物，“一株碗”不成立。"}, {"text": "面", "is_correct": false, "explanation": "语义：“面”用于平面或镜子等，碗不属于此类。"}], "explanations": {"堆": "堆是量词，用于成堆的东西，与“碗”搭配，填入后“还没洗”的语境通顺。", "块": "搭配：“块”用于成块的东西，“一块碗”搭配不当。", "株": "搭配：“株”用于植物，“一株碗”不成立。", "面": "语义：“面”用于平面或镜子等，碗不属于此类。"}, "sentence_index": 6, "correct_answer": "堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气喝了一堆水。", "explanation": "这里应该用〈杯〉。〈堆〉指成堆的实物，水不能堆成一堆，应说“一杯水”。"}, {"text": "窗外透进一堆光。", "explanation": "这里应该用〈束〉。〈堆〉指成堆的实物，光没有堆积的样子，应说“一束光”。"}, {"text": "他的脸上露出一堆笑容。", "explanation": "笑容不能堆成一堆，这里应说“满脸笑容”，不能用“一堆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCL