INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97888, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "堆", "is_correct": true, "explanation": "堆（duī，第一声）是本词，指成堆的东西或人，与听到的读音一致。"}, {"text": "兑", "is_correct": false, "explanation": "兑（duì，第四声）与 duī（第一声）声调不同，意思是兑换。"}, {"text": "追", "is_correct": false, "explanation": "追（zhuī）与 duī 声母不同（zh 与 d），意思是追赶。"}, {"text": "蹲", "is_correct": false, "explanation": "蹲（dūn）与 duī 韵母不同（un 与 ui），意思是蹲下。"}], "explanations": {"堆": "堆（duī，第一声）是本词，指成堆的东西或人，与听到的读音一致。", "兑": "兑（duì，第四声）与 duī（第一声）声调不同，意思是兑换。", "追": "追（zhuī）与 duī 声母不同（zh 与 d），意思是追赶。", "蹲": "蹲（dūn）与 duī 韵母不同（un 与 ui），意思是蹲下。"}, "sentence_index": null, "correct_answer": "堆"}, "level_3": {"options": [{"text": "堆", "is_correct": true, "explanation": "堆是量词，用于成堆的东西，与“吃的”搭配，填入后通顺。"}, {"text": "株", "is_correct": false, "explanation": "搭配：“株”用于植物，“一株吃的”不成立。"}, {"text": "颗", "is_correct": false, "explanation": "语义：“颗”用于小而圆的东西，“吃的”不属于此类。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、楼等大型物，“一座吃的”搭配不当。"}], "explanations": {"堆": "堆是量词，用于成堆的东西，与“吃的”搭配，填入后通顺。", "株": "搭配：“株”用于植物，“一株吃的”不成立。", "颗": "语义：“颗”用于小而圆的东西，“吃的”不属于此类。", "座": "搭配：“座”用于山、楼等大型物，“一座吃的”搭配不当。"}, "sentence_index": 6, "correct_answer": "堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗外挂着一堆彩虹，很美。", "explanation": "这里应该用〈道〉：彩虹是单个景象，〈堆〉不用于彩虹。"}, {"text": "天上挂着一堆月亮，很亮。", "explanation": "量词用错。这里应该用〈轮〉：月亮是单个天体，不能用〈堆〉计数。"}, {"text": "天上有一堆太阳，很热。", "explanation": "量词用错。太阳只有一个，应该用〈个〉，不能用〈堆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "广场上围着堆人，在看表演。", "corrected_sentence": "广场上围着一堆人，在看表演。", "error_description": "“堆”前缺少数词“一”，应说“一堆人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她带来了一个堆礼物，大家都很高兴。", "corrected_sentence": "她带来了一堆礼物，大家都很高兴。", "error_description": "错误形式：「一个堆礼物」；正确形式：「一堆礼物」。「堆」本身就是量词，数词后不能再加「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
