INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97893, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设立新的机构、部门、岗位或服务。", "primary_collocate": null, "pronunciation": "zēng shè", "ipa": "tsəŋ˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "公司为新项目增设了一个部门。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校增设了一个新的班级。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院夜里增设了一个急诊窗口。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在银行里增设了一个服务台。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院今年增设了汉语专业。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府增设了几个新岗位。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场在一楼增设了儿童区。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司增设了一个客服电话。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了方便大家，银行增设了自助机。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子增设了一个医疗站。", "target_word": "增设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增设了", "label": "完成体"}, {"form": "增设过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "新设机构岗位或服务来办事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34d10ddf-7e02-4d9e-8c6e-6ed723a2eab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增设", "is_correct": true, "explanation": "增设：增加设置，与「为新项目」新设一个部门的语境相符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：「翻译」是转换语言，不能用来设立部门，与句意不符。"}, {"text": "扫描", "is_correct": false, "explanation": "语义：「扫描」是用仪器读取信息，不能用来设立部门。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：「训练」的对象是人或动物，不说训练一个部门。"}], "explanations": {"增设": "增设：增加设置，与「为新项目」新设一个部门的语境相符。", "翻译": "语义：「翻译」是转换语言，不能用来设立部门，与句意不符。", "扫描": "语义：「扫描」是用仪器读取信息，不能用来设立部门。", "训练": "搭配：「训练」的对象是人或动物，不说训练一个部门。"}, "sentence_index": 0, "correct_answer": "增设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家银行的客户增设了三成。", "explanation": "这里应该用〈增加〉。增设指设置机构或设施，客户数量的增长要用增加。"}, {"text": "这项训练增设了学生的体质。", "explanation": "这里应该用〈增强〉。增设指设置机构或设施，体质的提升要用增强。"}, {"text": "他往汤里增设了盐。", "explanation": "这里应该用〈添加〉。增设指设置机构或设施，往食物里加入调料要用添加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增设", "is_correct": true, "explanation": "增设：增加设置，与「在一楼」新设儿童区的语境相符。"}, {"text": "回收", "is_correct": false, "explanation": "搭配：「回收」用于废品、物品，不能说回收一个区域。"}, {"text": "吸引", "is_correct": false, "explanation": "语义：「吸引」是引起注意，不能表示在商场设立儿童区。"}, {"text": "接待", "is_correct": false, "explanation": "搭配：「接待」的对象是人，不能说接待一个区域。"}], "explanations": {"增设": "增设：增加设置，与「在一楼」新设儿童区的语境相符。", "回收": "搭配：「回收」用于废品、物品，不能说回收一个区域。", "吸引": "语义：「吸引」是引起注意，不能表示在商场设立儿童区。", "接待": "搭配：「接待」的对象是人，不能说接待一个区域。"}, "sentence_index": 6, "correct_answer": "增设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子增设了医疗条件。", "explanation": "这里应该用〈改善〉。增设指设置机构或设施，条件的提升要用改善。"}, {"text": "这个村子增设了种植面积。", "explanation": "这里应该用〈扩大〉。增设指设置机构或设施，面积的扩展要用扩大。"}, {"text": "县里增设了村里的人口。", "explanation": "这里应该用〈增加〉。增设指设置机构或设施，人口的增长要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物业公司在小区里增设着一个健身区。", "corrected_sentence": "物业公司在小区里增设了一个健身区。", "error_description": "错误形式：「增设着」；正确形式：「增设了」。「增设」是一次完成的动作，表示完成要用「了」，「着」表示持续状态，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校前年增设了过一门创业课程。", "corrected_sentence": "这所学校前年增设过一门创业课程。", "error_description": "错误形式：「增设了过」；正确形式：「增设过」。「了」和「过」表示的体不能同时使用，表示经历只用「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
