INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增设", "is_correct": true, "explanation": "增设：增加设置，与「在门口」新增一个停车场的语境相符。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：「装饰」是美化，不是设置停车场，与句意不符。"}, {"text": "观看", "is_correct": false, "explanation": "语义：「观看」指看，不能表示在门口设置设施。"}, {"text": "聘请", "is_correct": false, "explanation": "搭配：「聘请」的对象是人员或专家，不说聘请一个停车场。"}], "explanations": {"增设": "增设：增加设置，与「在门口」新增一个停车场的语境相符。", "装饰": "语义：「装饰」是美化，不是设置停车场，与句意不符。", "观看": "语义：「观看」指看，不能表示在门口设置设施。", "聘请": "搭配：「聘请」的对象是人员或专家，不说聘请一个停车场。"}, "sentence_index": 0, "correct_answer": "增设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司今年的员工增设了三十人。", "explanation": "这里应该用〈增加〉。增设指设置机构或设施，人数的增长要用增加。"}, {"text": "他在菜里增设了一颗辣椒，结果太辣了。", "explanation": "这里应该用〈添加〉。增设指设置机构或设施，往菜里加入食材要用添加。"}, {"text": "这盆花为房间增设了生气。", "explanation": "这里应该用〈增添〉。增设指设置实体的机构或设施，抽象的生气要用增添。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增设", "is_correct": true, "explanation": "增设：增加设置，与「准备在公园里」新设厕所的语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」指观赏美好的事物，不能表示设置厕所。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：「游览」用于景点、名胜，不说游览厕所。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」用于展览、场所，不能说参观厕所这类设施。"}], "explanations": {"增设": "增设：增加设置，与「准备在公园里」新设厕所的语境相符。", "欣赏": "语义：「欣赏」指观赏美好的事物，不能表示设置厕所。", "游览": "搭配：「游览」用于景点、名胜，不说游览厕所。", "参观": "搭配：「参观」用于展览、场所，不能说参观厕所这类设施。"}, "sentence_index": 6, "correct_answer": "增设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂增设了生产规模。", "explanation": "这里应该用〈扩大〉。增设指设置新的机构或设施，规模的扩展要用扩大。"}, {"text": "公司增设了员工的工资。", "explanation": "这里应该用〈提高〉。增设指设置新的机构或设施，工资的上涨要用提高。"}, {"text": "这个作家增设了一本新书。", "explanation": "这里应该用〈出版〉。增设指设置机构或设施，出书要用出版。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学今年增设着两个新专业。", "corrected_sentence": "这所大学今年增设了两个新专业。", "error_description": "错误形式：「增设着」；正确形式：「增设了」。「增设」是一次完成的动作，表示完成要用「了」，「着」表示持续状态，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所医院去年在一楼增设了过一个中医门诊。", "corrected_sentence": "这所医院去年在一楼增设过一个中医门诊。", "error_description": "错误形式：「增设了过」；正确形式：「增设过」。「了」和「过」表示的体不能同时使用，表示经历只用「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
