INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97897, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让它更好、更强。", "primary_collocate": null, "pronunciation": "zēng jìn", "ipa": "tsəŋ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "多运动可以增进健康。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶能增进食欲。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天锻炼，想增进体质。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行能增进我们对世界的认识。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书可以增进知识。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次培训能增进员工的专业知识。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规律作息能增进员工的身体健康。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这个办法能增进孩子的食欲。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办运动会是为了增进学生的健康。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步增进了他的体力。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增进了", "label": "完成体"}, {"form": "增进过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "使健康、体质、食欲、知识等变得更好更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增进", "is_correct": true, "explanation": "句意是“多运动使健康变得更好”，只有“增进”符合。"}, {"text": "损害", "is_correct": false, "explanation": "语义：“多运动”与“损害健康”的作用相反，句意不通。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能说“增加健康”。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“多运动”与“破坏健康”相矛盾，句意不通。"}], "explanations": {"增进": "句意是“多运动使健康变得更好”，只有“增进”符合。", "损害": "语义：“多运动”与“损害健康”的作用相反，句意不通。", "增加": "搭配：“增加”说数量，不能说“增加健康”。", "破坏": "语义：“多运动”与“破坏健康”相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "增进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年公司的员工增进了一倍。", "explanation": "这里应该用〈增加〉。增进用于健康、知识、感情等抽象的好的方面，人数等数量要用增加。"}, {"text": "这家餐厅增进了营业面积。", "explanation": "这里应该用〈扩大〉。增进不用于面积等可以量化的范围，规模、面积要用扩大。"}, {"text": "今年农场的产量增进了一成。", "explanation": "这里应该用〈提高〉。产量是可以提高的指标，增进用于健康、知识等，不用于产量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增进", "is_correct": true, "explanation": "句意是“规律作息使员工的身体变得更健康”，只有“增进”符合。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少健康”与“规律作息”的作用相反，句意不通。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”测的是可量化的数值，不能接“健康”这类状态。"}, {"text": "削弱", "is_correct": false, "explanation": "语义：“削弱健康”与“规律作息”的作用相反，句意不通。"}], "explanations": {"增进": "句意是“规律作息使员工的身体变得更健康”，只有“增进”符合。", "减少": "语义：“减少健康”与“规律作息”的作用相反，句意不通。", "测量": "搭配：“测量”测的是可量化的数值，不能接“健康”这类状态。", "削弱": "语义：“削弱健康”与“规律作息”的作用相反，句意不通。"}, "sentence_index": 6, "correct_answer": "增进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他增进了脚步，想追上大家。", "explanation": "这里应该用〈加快〉。增进指使身心、知识等变得更好，不用于脚步的速度变化。"}, {"text": "妈妈为房间增进了一盏灯。", "explanation": "这里应该用〈增添〉。增进指使抽象的好的方面变好，不用于添加具体的物品。"}, {"text": "他认真规划，增进了很多时间。", "explanation": "这里应该用〈节省〉。增进不用于时间，节省时间要用节省。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次长途散步增进得我的健康。", "corrected_sentence": "这次长途散步增进了我的健康。", "error_description": "“了”误写为“得”。“增进”后应用完成体“了”表示已经产生的结果，“得”不能接在动词后直接带宾语，应说“增进了我的健康”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套训练增进了对他的体质。", "corrected_sentence": "这套训练增进了他的体质。", "error_description": "错误：多了介词「对」。「增进」是及物动词，直接带宾语，应说「增进了他的体质」，不能说「增进了对他的体质」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
