INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97898, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使增长；使更加深。", "primary_collocate": null, "pronunciation": "zēng jìn", "ipa": "tsəŋ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "一起旅行可以增进感情。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会是为了增进相互了解。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动增进了两国人民的友谊。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们常常聊天，想增进了解。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多沟通能增进夫妻之间的感情。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该增进对彼此的理解。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一顿晚饭增进了同事间的关系。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送了小礼物，增进了和邻居的感情。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交换学生可以增进两个学校的友谊。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想增进和孩子之间的感情。", "target_word": "增进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增进了", "label": "完成体"}, {"form": "增进过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "使感情、了解、友谊等关系更加深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增进", "is_correct": true, "explanation": "句意是“一起旅行使感情变得更深”，只有“增进”符合。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却感情”与“一起旅行”的作用相反，句意不通。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算感情”与句意无关，句意不通。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不能说“提高感情”。"}], "explanations": {"增进": "句意是“一起旅行使感情变得更深”，只有“增进”符合。", "冷却": "语义：“冷却感情”与“一起旅行”的作用相反，句意不通。", "计算": "语义：“计算感情”与句意无关，句意不通。", "提高": "搭配：“提高”用于水平、质量，不能说“提高感情”。"}, "sentence_index": 0, "correct_answer": "增进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动增进了参加的人数。", "explanation": "这里应该用〈增加〉。增进用于感情、了解等关系，人数等数量要用增加。"}, {"text": "两人的矛盾增进了。", "explanation": "这里应该用〈加剧〉。增进用于感情、了解等关系的增长加深，矛盾变得更尖锐要用加剧。"}, {"text": "妈妈为房间增进了一盏灯。", "explanation": "这里应该用〈增添〉。增进不用于添加具体的物品，只用于使抽象的好的方面变好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增进", "is_correct": true, "explanation": "句意是“一顿晚饭使同事关系变得更好”，只有“增进”符合。"}, {"text": "买卖", "is_correct": false, "explanation": "语义：“买卖关系”与“一顿晚饭”的语境不合，句意不通。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”不能接“关系”，“测量关系”不成立。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运关系”与句意无关，句意不通。"}], "explanations": {"增进": "句意是“一顿晚饭使同事关系变得更好”，只有“增进”符合。", "买卖": "语义：“买卖关系”与“一顿晚饭”的语境不合，句意不通。", "测量": "搭配：“测量”不能接“关系”，“测量关系”不成立。", "搬运": "语义：“搬运关系”与句意无关，句意不通。"}, "sentence_index": 6, "correct_answer": "增进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他增进了脚步，想赶上大家。", "explanation": "这里应该用〈加快〉。增进用于感情、了解等关系的增长加深，不用于脚步的速度变化。"}, {"text": "他认真规划，增进了很多时间。", "explanation": "这里应该用〈节约〉。增进是使感情、了解等增长加深，不用于时间；节约时间才是正确说法。"}, {"text": "他把行李增进了屋里。", "explanation": "这里应该用〈搬进〉。增进指使抽象的好的方面变好，不表示位置的移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上周的聚会增进着两家的感情。", "corrected_sentence": "上周的聚会增进了两家的感情。", "error_description": "体标错误。“上周的聚会”是已经完成的事，结果要用“增进了”，不能用表示持续的“增进着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次聚会增进了过我们的感情。", "corrected_sentence": "这次聚会增进了我们的感情。", "error_description": "体标错误。“了”和“过”不能叠用，说具体某次聚会的结果用“增进了”，不说“增进了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
