INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97899, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西的外面，从外面看到的样子。", "primary_collocate": null, "pronunciation": "wài biǎo", "ipa": "waɪ̯˥˩ pjɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个盒子的外表很漂亮。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子外表很旧，里面却很新。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果外表红红的，里面已经坏了。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑外表是银色的。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子外表有一层花纹。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车外表脏了，我想洗一洗。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的外表很普通，内容却很好。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外表很硬的水果，里面往往很甜。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包外表看起来像皮的，其实是布。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕外表很好看，吃起来一般。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体的外面和从外面看到的样子，与里面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b59156-5839-4aea-8d08-252264446946') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外表", "is_correct": true, "explanation": "外表：物体外面的样子，与“漂亮”搭配，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“漂亮”形容外观，不用于价格。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指轻重，与“漂亮”不搭。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“漂亮”不修饰味道，应说“好闻”或“香”。"}], "explanations": {"外表": "外表：物体外面的样子，与“漂亮”搭配，符合句意。", "价格": "搭配：“漂亮”形容外观，不用于价格。", "重量": "语义：“重量”指轻重，与“漂亮”不搭。", "味道": "搭配：“漂亮”不修饰味道，应说“好闻”或“香”。"}, "sentence_index": 0, "correct_answer": "外表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个盒子外表装满了书。", "explanation": "这里应该用〈里面〉。装满东西的是盒子里面，外表指物体外面的样子，不能说“外表装满了书”。"}, {"text": "这家店在顾客心中的外表一直很好。", "explanation": "这里应该用〈形象〉。顾客心中的印象说“形象”，“心中的外表”不通。"}, {"text": "这个西瓜的外表很甜。", "explanation": "这里应该用〈味道〉。甜是吃出来的味道，外表指从外面看到的样子，不能说外表很甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外表", "is_correct": true, "explanation": "外表：书的外面样子，与“普通”搭配，并与后句“内容却很好”形成对比。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：书没有“年龄”可以用“普通”来形容，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高度，不能说书的身高很普通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：书本身不发声，“这本书的声音很普通”说不通。"}], "explanations": {"外表": "外表：书的外面样子，与“普通”搭配，并与后句“内容却很好”形成对比。", "年龄": "语义：书没有“年龄”可以用“普通”来形容，句意不通。", "身高": "语义：“身高”指人的高度，不能说书的身高很普通。", "声音": "语义：书本身不发声，“这本书的声音很普通”说不通。"}, "sentence_index": 6, "correct_answer": "外表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的外表有十公斤。", "explanation": "这里应该用〈重量〉。能用“十公斤”计量的是箱子的重量，外表指外面的样子，不能说有多少公斤。"}, {"text": "这台电脑给我的外表很好。", "explanation": "这里应该用〈印象〉。“给我的外表”不通，外表是事物本身的样子，别人留下的印象才说“印象”。"}, {"text": "店员对顾客的外表很好。", "explanation": "这里应该用〈态度〉。外表不能用来说对人的好坏，对人友好要用“态度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个杯子有很漂亮外表。", "corrected_sentence": "那个杯子有很漂亮的外表。", "error_description": "修饰名词“外表”时，形容词后要加“的”，漏掉“的”不符合定中结构；应说“很漂亮的外表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个箱子地外表有很多划痕。", "corrected_sentence": "这个箱子的外表有很多划痕。", "error_description": "“箱子”与“外表”之间的定语要用“的”，不用“地”；“地”用于动词前作状语，这里应说“箱子的外表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97900, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内在", "is_correct": true, "explanation": "内在：指事物内部的性质，与“外表”相对，是反义关系。"}, {"text": "速度", "is_correct": false, "explanation": "速度：指快慢，与“外表”没有反义关系。"}, {"text": "声音", "is_correct": false, "explanation": "声音：指发出的声响，与“外表”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气：指气候状况，与“外表”没有反义关系。"}], "correct_answer": "内在", "explanations": {"内在": "内在：指事物内部的性质，与“外表”相对，是反义关系。", "速度": "速度：指快慢，与“外表”没有反义关系。", "声音": "声音：指发出的声响，与“外表”没有反义关系。", "天气": "天气：指气候状况，与“外表”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97900, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内心", "is_correct": true, "explanation": "内心：指心里的想法与性情，与“外表”相对，是反义关系。"}, {"text": "年龄", "is_correct": false, "explanation": "年龄：指人活了多少年，与“外表”没有反义关系。"}, {"text": "地址", "is_correct": false, "explanation": "地址：指所在的位置，与“外表”没有反义关系。"}, {"text": "价格", "is_correct": false, "explanation": "价格：指物品的金额，与“外表”没有反义关系。"}], "correct_answer": "内心", "explanations": {"内心": "内心：指心里的想法与性情，与“外表”相对，是反义关系。", "年龄": "年龄：指人活了多少年，与“外表”没有反义关系。", "地址": "地址：指所在的位置，与“外表”没有反义关系。", "价格": "价格：指物品的金额，与“外表”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外在的样子；表面。", "primary_collocate": null, "pronunciation": "wài biǎo", "ipa": "waɪ̯˥˩ pjɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "不要只看一个人的外表。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外表很冷，其实很热情。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的外表看起来很年轻。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外表漂亮不一定心也好。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢他，不是因为他的外表。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外表平静，心里却很紧张。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥外表严肃，说话却很有意思。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要相信他的外表。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩外表安静，其实很爱玩。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外表和性格不一样的人很多。", "target_word": "外表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或事物给人的外在印象，与内在相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b59156-5839-4aea-8d08-252264446946') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外表", "is_correct": true, "explanation": "外表：人的外在样子，与“看”搭配，符合句意。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“看”不接“歌声”，听歌声才说得通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要靠嗅觉或味觉感知，不能用“看”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不接“声音”，应说“听”。"}], "explanations": {"外表": "外表：人的外在样子，与“看”搭配，符合句意。", "歌声": "搭配：“看”不接“歌声”，听歌声才说得通。", "味道": "语义：味道要靠嗅觉或味觉感知，不能用“看”。", "声音": "搭配：“看”不接“声音”，应说“听”。"}, "sentence_index": 0, "correct_answer": "外表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在同学心中的外表一直很好。", "explanation": "这里应该用〈形象〉。别人心中的印象说“形象”，“心中的外表”不通；外表指人或物本身的外在样子。"}, {"text": "他对工作的外表很认真。", "explanation": "这里应该用〈态度〉。“认真”形容对事情的做法，外表说的是外在样子，对工作的认真要用“态度”。"}, {"text": "这碗汤的外表很咸。", "explanation": "这里应该用〈味道〉。咸是味觉，外表指物体外面的样子，不能说“外表很咸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外表", "is_correct": true, "explanation": "外表：人的外在样子，与“严肃”搭配，并与后句“说话却很有意思”形成对比。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是体形的数值，不能用“严肃”来形容。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“严肃”形容神情或态度，不能用来形容年龄。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“严肃”不修饰“颜色”，颜色只能说“鲜艳”“深浅”之类。"}], "explanations": {"外表": "外表：人的外在样子，与“严肃”搭配，并与后句“说话却很有意思”形成对比。", "身高": "体貌：身高是体形的数值，不能用“严肃”来形容。", "年龄": "语义：“严肃”形容神情或态度，不能用来形容年龄。", "颜色": "搭配：“严肃”不修饰“颜色”，颜色只能说“鲜艳”“深浅”之类。"}, "sentence_index": 6, "correct_answer": "外表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话的外表很温柔。", "explanation": "这里应该用〈语气〉。外表指人或物外在的样子，说话的方式和感觉要用“语气”。"}, {"text": "他给我的外表很好。", "explanation": "这里应该用〈印象〉。“给我的外表”不通，外表是事物本身的样子，别人留下的印象才说“印象”。"}, {"text": "他对我的外表很热情。", "explanation": "这里应该用〈态度〉。外表是外在样子，不能用来说对人的热情，对人的态度才用“态度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有很漂亮外表，但说话很粗鲁。", "corrected_sentence": "她有很漂亮的外表，但说话很粗鲁。", "error_description": "修饰名词“外表”时，形容词后要加“的”，漏掉“的”不通；应说“很漂亮的外表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地外表很冷，但心里很热情。", "corrected_sentence": "他的外表很冷，但心里很热情。", "error_description": "“外表”前的定语应用“的”，不用“地”；“地”用于动词前作状语，这里应说“他的外表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
