INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97903, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以做很多事。", "primary_collocate": null, "pronunciation": "duō mù dì", "ipa": "tuɔ˥ mu˥˩ ti˥˩", "syllable_count": 3, "sentences": [{"text": "这座多目的工程，既能发电，又能防洪。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè zuò duō mù dì gōng chéng, jì néng fā diàn, yòu néng fáng hóng.", "sentence_source": "generated"}, {"text": "这里是一座多目的平台，既能开会，也能展览。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè lǐ shì yí zuò duō mù dì píng tái, jì néng kāi huì, yě néng zhǎn lǎn.", "sentence_source": "generated"}, {"text": "这座多目的大坝既能挡水，又能通航。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè zuò duō mù dì dà bà, jì néng dǎng shuǐ, yòu néng tōng háng.", "sentence_source": "generated"}, {"text": "这块多目的用地既能停车，又能摆摊。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè kuài duō mù dì yòng dì, jì néng tíng chē, yòu néng bǎi tān.", "sentence_source": "generated"}, {"text": "这条多目的河道既能通航，又能灌溉。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè tiáo duō mù dì hé dào, jì néng tōng háng, yòu néng guàn gài.", "sentence_source": "generated"}, {"text": "这项多目的工程兼顾防洪和供水。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè xiàng duō mù dì gōng chéng, jiān gù fáng hóng hé gōng shuǐ.", "sentence_source": "generated"}, {"text": "这块土地的多目的利用可以节约资源。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè kuài tǔ dì de duō mù dì lì yòng kě yǐ jié yuē zī yuán.", "sentence_source": "generated"}, {"text": "这片多目的湿地既能蓄水，也能净化污水。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè piàn duō mù dì shī dì, jì néng xù shuǐ, yě néng jìng huà wū shuǐ.", "sentence_source": "generated"}, {"text": "这座多目的码头既能装货，也能停靠游船。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè zuò duō mù dì mǎ tou, jì néng zhuāng huò, yě néng tíng kào yóu chuán.", "sentence_source": "generated"}, {"text": "这套多目的软件能记账，也能管理库存。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè tào duō mù dì ruǎn jiàn, néng jì zhàng, yě néng guǎn lǐ kù cún.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一样东西或一个地方能做很多事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多目的", "is_correct": true, "explanation": "正确：“多目的”指有多种用途，与后半句“既能发电，又能防洪”相符。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种用途，与“既能发电，又能防洪”的多种用途矛盾。"}, {"text": "专职", "is_correct": false, "explanation": "搭配：“专职”修饰人员或工作岗位，不修饰“工程”。"}, {"text": "室内", "is_correct": false, "explanation": "语义：“室内”指房间内部，发电和防洪的水利工程不是室内工程，与句意矛盾。"}], "explanations": {"多目的": "正确：“多目的”指有多种用途，与后半句“既能发电，又能防洪”相符。", "单一": "语义：“单一”指只有一种用途，与“既能发电，又能防洪”的多种用途矛盾。", "专职": "搭配：“专职”修饰人员或工作岗位，不修饰“工程”。", "室内": "语义：“室内”指房间内部，发电和防洪的水利工程不是室内工程，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "多目的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手的嗓音多目的，大家都喜欢听。", "explanation": "这里应该用〈动听〉。“多目的”指事物有多种用途，不能形容嗓音，形容嗓音好听应说〈动听〉。"}, {"text": "这把多目的钥匙能打开所有的门。", "explanation": "这里应该用〈万能〉。“多目的”强调同一事物有多种用途，说一把钥匙能开所有门应用〈万能〉。"}, {"text": "他是一位多目的人。", "explanation": "这里应该用〈多才多艺〉。“多目的”指事物有多种用途，形容人有多方面才能应说〈多才多艺〉，不能用“多目的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多目的", "is_correct": true, "explanation": "正确：“多目的利用”指一块土地有多种用途，可以节约资源。"}, {"text": "闲置", "is_correct": false, "explanation": "语义：“闲置”指空着不用，与“利用”及“节约资源”的意思矛盾。"}, {"text": "单人", "is_correct": false, "explanation": "搭配：“单人”修饰人数或床位等，不修饰“利用”。"}, {"text": "荒芜", "is_correct": false, "explanation": "语义：“荒芜”指土地荒废，长满杂草，与“利用”矛盾。"}], "explanations": {"多目的": "正确：“多目的利用”指一块土地有多种用途，可以节约资源。", "闲置": "语义：“闲置”指空着不用，与“利用”及“节约资源”的意思矛盾。", "单人": "搭配：“单人”修饰人数或床位等，不修饰“利用”。", "荒芜": "语义：“荒芜”指土地荒废，长满杂草，与“利用”矛盾。"}, "sentence_index": 6, "correct_answer": "多目的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种多目的插头可以接在各种插座上。", "explanation": "这里应该用〈通用〉。“多目的”指一样东西有多种用途，插头只起接通电路的作用，适用范围广应说〈通用〉。"}, {"text": "我家的多目的猫很可爱。", "explanation": "这里应该用〈聪明〉。“多目的”指事物有多种用途，动物没有“用途”之说，形容猫机灵应说〈聪明〉，不能用“多目的”。"}, {"text": "这次的多目的比赛很精彩。", "explanation": "这里应该用〈多项目〉。“多目的”指事物有多种用途，比赛含多个项目应说〈多项目〉，不能用“多目的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个多目的的广场既能散步，也能演出。", "corrected_sentence": "这个多目的广场既能散步，也能演出。", "error_description": "“多目的”是区别词，作定语时直接修饰名词，如“多目的广场”，一般不加结构助词“的”。“多目的的广场”多了一个“的”，应改为“多目的广场”。（注意：“目的”中的“的”读 dì，不是助词。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套多目的软件能画图，也能多目的算账。", "corrected_sentence": "这套多目的软件能画图，也能算账。", "error_description": "“多目的”只能作定语修饰名词，不能直接放在动词前作状语。“也能多目的算账”中“多目的”位于动词“算账”前，应删去，改为“也能算账”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
