INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97904, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有多种用途或目的的。", "primary_collocate": null, "pronunciation": "duō mù dì", "ipa": "tuɔ˥ mu˥˩ ti˥˩", "syllable_count": 3, "sentences": [{"text": "这座水电站是多目的工程，既能发电，又能灌溉。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè zuò shuǐ diàn zhàn shì duō mù dì gōng chéng, jì néng fā diàn, yòu néng guàn gài.", "sentence_source": "generated"}, {"text": "这个多目的枢纽工程平时供水，汛期防洪。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè ge duō mù dì shū niǔ gōng chéng píng shí gōng shuǐ, xùn qī fáng hóng.", "sentence_source": "generated"}, {"text": "这套多目的系统可以监测水位，也可以发出警报。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè tào duō mù dì xì tǒng kě yǐ jiān cè shuǐ wèi, yě kě yǐ fā chū jǐng bào.", "sentence_source": "generated"}, {"text": "这项多目的规划兼顾了居住、交通和防灾。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè xiàng duō mù dì guī huà jiān gù le jū zhù, jiāo tōng hé fáng zāi.", "sentence_source": "generated"}, {"text": "多目的水库既能发电，又能防洪。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "duō mù dì shuǐ kù jì néng fā diàn, yòu néng fáng hóng.", "sentence_source": "generated"}, {"text": "这个多目的计划有三个目标。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè ge duō mù dì jì huà yǒu sān ge mù biāo.", "sentence_source": "generated"}, {"text": "多目的使用可以节约土地。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "duō mù dì shǐ yòng kě yǐ jié yuē tǔ dì.", "sentence_source": "generated"}, {"text": "政府正在建设一个多目的公园，里面有球场和花园。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhèng fǔ zhèng zài jiàn shè yí ge duō mù dì gōng yuán, lǐ miàn yǒu qiú chǎng hé huā yuán.", "sentence_source": "generated"}, {"text": "这块多目的场地，平时当停车场，周末当市场。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè kuài duō mù dì chǎng dì, píng shí dāng tíng chē chǎng, zhōu mò dāng shì chǎng.", "sentence_source": "generated"}, {"text": "这套多目的方案可以兼顾防洪、灌溉和发电。", "target_word": "多目的", "complexity_tier": "T3", "furigana": "zhè tào duō mù dì fāng àn kě yǐ jiān gù fáng hóng, guàn gài hé fā diàn.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "设计或建设时有多种用途和目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多目的", "is_correct": true, "explanation": "正确：“多目的”指有多种用途，与“既能发电，又能灌溉”相符。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种用途，与“既能发电，又能灌溉”矛盾。"}, {"text": "专职", "is_correct": false, "explanation": "搭配：“专职”修饰人员或职务，不修饰“工程”。"}, {"text": "室内", "is_correct": false, "explanation": "语义：“室内”指房屋内部，水电站不是室内工程，与句意矛盾。"}], "explanations": {"多目的": "正确：“多目的”指有多种用途，与“既能发电，又能灌溉”相符。", "单一": "语义：“单一”指只有一种用途，与“既能发电，又能灌溉”矛盾。", "专职": "搭配：“专职”修饰人员或职务，不修饰“工程”。", "室内": "语义：“室内”指房屋内部，水电站不是室内工程，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "多目的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气多目的，大家都有点怕他。", "explanation": "这里应该用〈暴躁〉。“多目的”指事物有多种用途，不能形容性情，形容脾气急躁应说〈暴躁〉。"}, {"text": "这把多目的钥匙能打开所有的门。", "explanation": "这里应该用〈万能〉。“多目的”强调同一事物有多种用途，说一把钥匙能开所有门应用〈万能〉。"}, {"text": "他是一位多目的老师。", "explanation": "这里应该用〈多才多艺〉。“多目的”指事物有多种用途，形容人有多方面才能应说〈多才多艺〉，不能用“多目的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多目的", "is_correct": true, "explanation": "正确：“多目的使用”指一块地有多种用途，可以节约土地。"}, {"text": "闲置", "is_correct": false, "explanation": "语义：“闲置”指空着不用，与“使用”矛盾。"}, {"text": "荒芜", "is_correct": false, "explanation": "语义：“荒芜”指土地荒废，与“使用”和“节约土地”的意思矛盾。"}, {"text": "方形", "is_correct": false, "explanation": "搭配：“方形”描述形状，不能修饰“使用”。"}], "explanations": {"多目的": "正确：“多目的使用”指一块地有多种用途，可以节约土地。", "闲置": "语义：“闲置”指空着不用，与“使用”矛盾。", "荒芜": "语义：“荒芜”指土地荒废，与“使用”和“节约土地”的意思矛盾。", "方形": "搭配：“方形”描述形状，不能修饰“使用”。"}, "sentence_index": 6, "correct_answer": "多目的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种多目的插座可以接各种插头。", "explanation": "这里应该用〈通用〉。“多目的”指一样东西有多种用途，插座只起接电的作用，适用范围广应说〈通用〉。"}, {"text": "我家的多目的猫很可爱。", "explanation": "这里应该用〈聪明〉。“多目的”指事物有多种用途，动物没有“用途”之说，形容猫机灵应说〈聪明〉，不能用“多目的”。"}, {"text": "这个多目的笑话很有趣。", "explanation": "这里应该用〈一语双关〉。“多目的”指事物有多种用途，笑话有多重含义应说〈一语双关〉，不能用“多目的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座多目的的公园既能散步，也能演出。", "corrected_sentence": "这座多目的公园既能散步，也能演出。", "error_description": "“多目的”是区别词，作定语时直接修饰名词，如“多目的公园”，一般不加结构助词“的”。“多目的的公园”多了一个“的”，应改为“多目的公园”。（注意：“目的”中的“的”读 dì，不是助词。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套多目的装置能测量、报警，也能多目的记录数据。", "corrected_sentence": "这套多目的装置能测量、报警，也能记录数据。", "error_description": "“多目的”只能作定语修饰名词，不能直接放在动词前作状语。“也能多目的记录数据”中“多目的”位于动词“记录”前，应删去，改为“也能记录数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97907, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "给", "is_correct": true, "explanation": "给：与“夺”的本义“用力拿走”相反，表示把东西交给别人，二者构成反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”表示用笔书写，与“夺”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”表示快速移动，与“夺”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”表示发出乐音，与“夺”没有反义关系。"}], "correct_answer": "给", "explanations": {"给": "给：与“夺”的本义“用力拿走”相反，表示把东西交给别人，二者构成反义关系。", "写": "“写”表示用笔书写，与“夺”没有反义关系。", "跑": "“跑”表示快速移动，与“夺”没有反义关系。", "唱": "“唱”表示发出乐音，与“夺”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
