INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97907, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力把别人手里的东西拿走。", "primary_collocate": null, "pronunciation": "duó", "ipa": "tuo˧˥", "syllable_count": 1, "sentences": [{"text": "他一把夺过我手里的书。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷夺走了她的包。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从弟弟手里夺走了玩具。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从我手里夺过手机就跑了。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人想从我手里夺走钱包。", "target_word": "夺", "complexity_tier": "T3", "furigana": "nà gè rén xiǎng cóng wǒ shǒu lǐ duó zǒu qián bāo", "sentence_source": "generated"}, {"text": "狗夺走了孩子手里的面包。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地夺过我的笔，扔在地上。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把我的球夺了过去。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩夺过糖，马上塞进嘴里。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察冲上去，夺下了他手里的刀。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夺了", "label": "完成体"}, {"form": "夺过", "label": "经历体"}, {"form": "抢夺", "label": "复合"}], "register": "中性", "sense_fingerprint": "用力从别人手中抢走东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34d10ddf-7e02-4d9e-8c6e-6ed723a2eab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97907, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺（duó，第二声）：用力从别人手里拿走东西，即本词。"}, {"text": "多", "is_correct": false, "explanation": "多（duō，第一声）与 duó（第二声）声调不同，意思是数量大。"}, {"text": "朵", "is_correct": false, "explanation": "朵（duǒ，第三声）与 duó 声调不同，是花朵的量词。"}, {"text": "躲", "is_correct": false, "explanation": "躲（duǒ，第三声）与 duó 声调不同，意思是躲避。"}, {"text": "驼", "is_correct": false, "explanation": "驼（tuó，第二声）与 duó 声母不同（t 与 d），意思是骆驼。"}], "explanations": {"夺": "夺（duó，第二声）：用力从别人手里拿走东西，即本词。", "多": "多（duō，第一声）与 duó（第二声）声调不同，意思是数量大。", "朵": "朵（duǒ，第三声）与 duó 声调不同，是花朵的量词。", "躲": "躲（duǒ，第三声）与 duó 声调不同，意思是躲避。", "驼": "驼（tuó，第二声）与 duó 声母不同（t 与 d），意思是骆驼。"}, "sentence_index": null, "correct_answer": "夺"}, "level_3": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺过：正确。用力拿走他人手中的书，与“一把”“我手里的书”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能接“书”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是液体，不能接“书”。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”是不及物动词，不能带“书”作宾语。"}], "explanations": {"夺": "夺过：正确。用力拿走他人手中的书，与“一把”“我手里的书”相符。", "吃": "搭配：“吃”的宾语是食物，不能接“书”。", "喝": "搭配：“喝”的宾语是液体，不能接“书”。", "坐": "配价：“坐”是不及物动词，不能带“书”作宾语。"}, "sentence_index": 0, "correct_answer": "夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在花园里夺了一朵玫瑰。", "explanation": "这里应该用〈摘〉。夺指用力从别人手里拿走东西；从植物上取下花朵要用摘。"}, {"text": "她在超市夺了一瓶牛奶，然后付了钱。", "explanation": "这里应该用〈买〉。夺指用力从别人手里拿走东西，在超市付钱买东西不用夺。"}, {"text": "他从自己手里夺过手机，急忙放进口袋。", "explanation": "这里应该用〈拿〉。夺指从别人手里强行拿走东西，从自己手里取回自己的东西要用拿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97907, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺（duó，第二声）：用力从别人手里拿走东西，即本词。"}, {"text": "多", "is_correct": false, "explanation": "多（duō，第一声）与 duó 声调不同，意思是数量大。"}, {"text": "躲", "is_correct": false, "explanation": "躲（duǒ，第三声）与 duó 声调不同，意思是躲避。"}, {"text": "剁", "is_correct": false, "explanation": "剁（duò，第四声）与 duó 声调不同，意思是切碎。"}, {"text": "舵", "is_correct": false, "explanation": "舵（duò，第四声）与 duó 声调不同，意思是船舵。"}], "explanations": {"夺": "夺（duó，第二声）：用力从别人手里拿走东西，即本词。", "多": "多（duō，第一声）与 duó 声调不同，意思是数量大。", "躲": "躲（duǒ，第三声）与 duó 声调不同，意思是躲避。", "剁": "剁（duò，第四声）与 duó 声调不同，意思是切碎。", "舵": "舵（duò，第四声）与 duó 声调不同，意思是船舵。"}, "sentence_index": null, "correct_answer": "夺"}, "level_3": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺过：正确。用力拿走他人手中的笔，与“生气地”“扔在地上”的语境相符。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“笔”作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“笔”作宾语。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”的宾语应是话语或道理，不能接“笔”。"}], "explanations": {"夺": "夺过：正确。用力拿走他人手中的笔，与“生气地”“扔在地上”的语境相符。", "笑": "配价：“笑”是不及物动词，不能带“笔”作宾语。", "睡": "配价：“睡”是不及物动词，不能带“笔”作宾语。", "讲": "搭配：“讲”的宾语应是话语或道理，不能接“笔”。"}, "sentence_index": 6, "correct_answer": "夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在草地上夺到了一颗四叶草。", "explanation": "这里应该用〈找〉。夺指从别人手里强行拿走东西，草地上找到的四叶草无人持有，不能用夺。"}, {"text": "我从桌子上夺过了书。", "explanation": "这里应该用〈拿〉。夺强调从别人手中用力拿走，从桌上取东西不用夺。"}, {"text": "我在路边夺到了一把伞。", "explanation": "这里应该用〈捡〉。夺指从别人手里强行拿走东西，路边无人持有的伞要用捡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
