INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97908, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "争取并得到冠军、奖牌、胜利等成果。", "primary_collocate": null, "pronunciation": "duó", "ipa": "tuo˧˥", "syllable_count": 1, "sentences": [{"text": "我们班在比赛中夺下了第一名。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在最后一圈夺走了冠军。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个球队都想夺金牌。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在游泳比赛中夺了三块金牌。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队终于把冠军夺了回来。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李每天练习，想夺下冠军。", "target_word": "夺", "complexity_tier": "T3", "furigana": "xiǎo lǐ měi tiān liàn xí xiǎng duó xià guàn jūn", "sentence_source": "generated"}, {"text": "中国队三次夺回了世界冠军。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的运动员夺了很多奖牌。", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想夺下失去的冠军头衔。", "target_word": "夺", "complexity_tier": "T3", "furigana": "tā xiǎng duó xià shī qù de guàn jūn tóu xián", "sentence_source": "generated"}, {"text": "谁能夺下这场比赛的胜利？", "target_word": "夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夺了", "label": "完成体"}, {"form": "夺过", "label": "经历体"}, {"form": "夺回", "label": "复合"}], "register": "中性", "sense_fingerprint": "争取得到冠军奖牌等成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34d10ddf-7e02-4d9e-8c6e-6ed723a2eab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺（duó，第二声）：争取得到，即本词。"}, {"text": "多", "is_correct": false, "explanation": "多（duō，第一声）与 duó 声调不同，意思是数量大。"}, {"text": "躲", "is_correct": false, "explanation": "躲（duǒ，第三声）与 duó 声调不同，意思是躲避。"}, {"text": "驼", "is_correct": false, "explanation": "驼（tuó，第二声）与 duó 声母不同（t 与 d），意思是骆驼。"}, {"text": "剁", "is_correct": false, "explanation": "剁（duò，第四声）与 duó 声调不同，意思是切碎。"}], "explanations": {"夺": "夺（duó，第二声）：争取得到，即本词。", "多": "多（duō，第一声）与 duó 声调不同，意思是数量大。", "躲": "躲（duǒ，第三声）与 duó 声调不同，意思是躲避。", "驼": "驼（tuó，第二声）与 duó 声母不同（t 与 d），意思是骆驼。", "剁": "剁（duò，第四声）与 duó 声调不同，意思是切碎。"}, "sentence_index": null, "correct_answer": "夺"}, "level_3": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺下：正确。在比赛中取得第一名，与“比赛中”“第一名”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能接“第一名”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“第一名”作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语“第一名”。"}], "explanations": {"夺": "夺下：正确。在比赛中取得第一名，与“比赛中”“第一名”相符。", "吃": "搭配：“吃”的宾语是食物，不能接“第一名”。", "唱": "搭配：“唱”不能带“第一名”作宾语。", "睡": "配价：“睡”是不及物动词，不能带宾语“第一名”。"}, "sentence_index": 0, "correct_answer": "夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈夺给我一本书。", "explanation": "这里应该用〈送〉。夺表示争取或强行拿走，不能表示赠予他人东西。"}, {"text": "他在图书馆夺了一本小说回家看。", "explanation": "这里应该用〈借〉。夺表示强行拿走或争取得到，借阅图书不用夺。"}, {"text": "她在厨房里夺了三个鸡蛋。", "explanation": "这里应该用〈拿〉。夺用于争取比赛胜利或奖项，厨房里拿取食材不能用夺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97908, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺（duó，第二声）：争取得到，即本词。"}, {"text": "多", "is_correct": false, "explanation": "多（duō，第一声）与 duó 声调不同，意思是数量大。"}, {"text": "剁", "is_correct": false, "explanation": "剁（duò，第四声）与 duó 声调不同，意思是切碎。"}, {"text": "朵", "is_correct": false, "explanation": "朵（duǒ，第三声）与 duó 声调不同，是花朵的量词。"}, {"text": "舵", "is_correct": false, "explanation": "舵（duò，第四声）与 duó 声调不同，意思是船舵。"}], "explanations": {"夺": "夺（duó，第二声）：争取得到，即本词。", "多": "多（duō，第一声）与 duó 声调不同，意思是数量大。", "剁": "剁（duò，第四声）与 duó 声调不同，意思是切碎。", "朵": "朵（duǒ，第三声）与 duó 声调不同，是花朵的量词。", "舵": "舵（duò，第四声）与 duó 声调不同，意思是船舵。"}, "sentence_index": null, "correct_answer": "夺"}, "level_3": {"options": [{"text": "夺", "is_correct": true, "explanation": "夺回：正确。夺回失去的冠军，与“三次”“回”相符。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语是商品，不能接“世界冠军”。"}, {"text": "飞", "is_correct": false, "explanation": "配价：“飞”是不及物动词，不能带“世界冠军”作宾语。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“世界冠军”作宾语。"}], "explanations": {"夺": "夺回：正确。夺回失去的冠军，与“三次”“回”相符。", "买": "搭配：“买”的宾语是商品，不能接“世界冠军”。", "飞": "配价：“飞”是不及物动词，不能带“世界冠军”作宾语。", "笑": "配价：“笑”是不及物动词，不能带“世界冠军”作宾语。"}, "sentence_index": 6, "correct_answer": "夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "主办方夺给他一枚奖牌。", "explanation": "这里应该用〈颁发〉。夺表示争取得到，不能表示授予、发放。"}, {"text": "我在快递站夺了一个包裹回家。", "explanation": "这里应该用〈取〉。夺表示强行拿走或争取得到，在快递站领取自己的包裹要用取。"}, {"text": "他在抽屉里夺到了一把钥匙。", "explanation": "这里应该用〈找〉。夺指从别人手里争取或抢走，在抽屉里找东西不用夺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支队伍在决赛中夺了得冠军。", "corrected_sentence": "这支队伍在决赛中夺得了冠军。", "error_description": "错误形式为“夺了得”，正确形式为“夺得了”：“了”应放在复合动词“夺得”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于在最后一分钟不夺得了金牌。", "corrected_sentence": "她终于在最后一分钟夺得了金牌。", "error_description": "多出了否定词“不”。“夺得了”表示已经实现，不能用“不”否定，应删去“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
