INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很大很大的力量。", "primary_collocate": null, "pronunciation": "wēi lì", "ipa": "weɪ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "台风的威力很大，很多树都倒了。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种炸弹的威力非常大。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海浪的威力很大，小船一下就翻了。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震的威力让整座桥都断了。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别小看火的威力，它能烧掉一座山。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚炮弹的威力有多大？", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水的威力很大，把路都冲坏了。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次看到雷电的威力，吓了一跳。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风的威力不大，小树还站得很稳。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新武器威力很大，大家都很怕。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "威力无穷", "label": "复合"}], "register": "中性", "sense_fingerprint": "自然现象或武器等具有的很大的破坏力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：台风不是商品，没有价格，“台风的价格很大”说不通。"}, {"text": "威力", "is_correct": true, "explanation": "正确：“台风的威力很大”指台风的破坏力，与“很多树都倒了”的结果相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：台风没有体温，“台风的体温很大”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说深浅，不说“很大”，“台风的颜色很大”搭配不当。"}], "explanations": {"价格": "语义：台风不是商品，没有价格，“台风的价格很大”说不通。", "威力": "正确：“台风的威力很大”指台风的破坏力，与“很多树都倒了”的结果相符。", "体温": "语义：台风没有体温，“台风的体温很大”说不通。", "颜色": "搭配：“颜色”说深浅，不说“很大”，“台风的颜色很大”搭配不当。"}, "sentence_index": 0, "correct_answer": "威力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天锻炼，身体的威力越来越强。", "explanation": "这里应该用〈力量〉。威力指自然现象或武器等的破坏力，人身体的力气要说力量。"}, {"text": "这个学生的威力很强，数学题做得又快又对。", "explanation": "这里应该用〈能力〉。威力是破坏性的力量，指人的本领要用能力。"}, {"text": "这台手机的威力很多，可以拍照、导航，还能看电影。", "explanation": "这里应该用〈功能〉。威力指破坏性的力量，手机能做的事要说功能，“威力很多”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：洪水不领工资，“洪水的工资很大”与句子无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：洪水没有年龄，“洪水的年龄很大”说不通。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“字数”说多少，不说“很大”，而且洪水没有字数。"}, {"text": "威力", "is_correct": true, "explanation": "正确：“洪水的威力很大，把路都冲坏了”符合句意，指洪水的破坏力。"}], "explanations": {"工资": "语义：洪水不领工资，“洪水的工资很大”与句子无关。", "年龄": "语义：洪水没有年龄，“洪水的年龄很大”说不通。", "字数": "搭配：“字数”说多少，不说“很大”，而且洪水没有字数。", "威力": "正确：“洪水的威力很大，把路都冲坏了”符合句意，指洪水的破坏力。"}, "sentence_index": 6, "correct_answer": "威力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个菜的威力很好，大家都爱吃。", "explanation": "这里应该用〈味道〉。威力指破坏性的力量，菜好不好吃要说味道。"}, {"text": "他在学校很有威力，学生都很尊敬他。", "explanation": "这里应该用〈威望〉。威力指破坏性的力量，指人在群体中的声望要说威望。"}, {"text": "这台新机器的威力很高，每小时能做两百件。", "explanation": "这里应该用〈效率〉。威力指破坏力，衡量机器做事快慢要说效率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗炸弹有一只很大的威力。", "corrected_sentence": "这颗炸弹有一种很大的威力。", "error_description": "量词错误：“威力”应该用量词“种”，不能用“只”。“只”多用于动物或器物等个体，“一种威力”才是正确说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场洪水的威力大很，把桥都冲断了。", "corrected_sentence": "这场洪水的威力很大，把桥都冲断了。", "error_description": "语序错误：程度副词“很”应放在形容词“大”前，说“很大”，不能说“大很”。“威力很大”才是正确说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
