INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "强大的力量；很大的作用。", "primary_collocate": null, "pronunciation": "wēi lì", "ipa": "weɪ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "广告的威力很大，大家都去买这个东西。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络的威力让世界变小了。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一句话，也有很大的威力。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要相信音乐的威力，它能让人高兴。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小公司第一次看到了电视广告的威力。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的威力很大，它能改变一个人。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂钱的威力，所以总是乱花。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让我们看到了科学的威力。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新药真的有威力，我吃了一天就好了。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的笑容也有威力，妈妈马上不生气了。", "target_word": "威力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "威力无穷", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物产生的很大的作用或影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：广告不是人，没有身高，“广告的身高很大”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：广告没有体重，“广告的体重很大”与句子无关。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”说重、淡，不说“很大”，“广告的口味很大”搭配不当。"}, {"text": "威力", "is_correct": true, "explanation": "正确：“广告的威力很大，大家都去买”指广告产生的影响，符合句意。"}], "explanations": {"身高": "语义：广告不是人，没有身高，“广告的身高很大”说不通。", "体重": "语义：广告没有体重，“广告的体重很大”与句子无关。", "口味": "搭配：“口味”说重、淡，不说“很大”，“广告的口味很大”搭配不当。", "威力": "正确：“广告的威力很大，大家都去买”指广告产生的影响，符合句意。"}, "sentence_index": 0, "correct_answer": "威力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的威力很强，三个月就学会了游泳。", "explanation": "这里应该用〈能力〉。威力指事物产生的作用，人的学习本领要说能力。"}, {"text": "这个城市的威力很干净，每年都有很多游客。", "explanation": "这里应该用〈环境〉。“威力”指作用或影响，说城市的卫生状况要用“环境”，“威力很干净”不这么用。"}, {"text": "这辆车的威力很快，半小时就到了。", "explanation": "这里应该用〈速度〉。威力指力量或作用，车跑得快慢要说速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：钱没有年龄，“不懂钱的年龄”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“钱”没有温度，“他不懂钱的温度”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“懂”和“乱花”搭配，句子说不通。"}, {"text": "威力", "is_correct": true, "explanation": "正确：“他不懂钱的威力，所以总是乱花”指钱的作用，符合句意。"}], "explanations": {"年龄": "语义：钱没有年龄，“不懂钱的年龄”说不通。", "温度": "语义：“钱”没有温度，“他不懂钱的温度”说不通。", "颜色": "搭配：“颜色”不能与“懂”和“乱花”搭配，句子说不通。", "威力": "正确：“他不懂钱的威力，所以总是乱花”指钱的作用，符合句意。"}, "sentence_index": 6, "correct_answer": "威力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的威力很漂亮，我很喜欢。", "explanation": "这里应该用〈样子〉。威力指作用或影响，衣服好不好看要说样子。"}, {"text": "这个孩子的威力很充沛，一天能跑三个小时。", "explanation": "这里应该用〈精力〉。威力指力量或作用，人的精神和体力要说精力，“威力很充沛”不这么用。"}, {"text": "这台机器的威力很贵，花了我三万块。", "explanation": "这里应该用〈价格〉。“威力”指作用，机器的价钱要说“价格”，“威力很贵”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种新药的威力大很，一天就好了。", "corrected_sentence": "这种新药的威力很大，一天就好了。", "error_description": "语序错误：程度副词“很”应放在形容词“大”之前，不能放在后面；应说“威力很大”，“威力大很”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的笑容有一只很大的威力，妈妈马上不生气了。", "corrected_sentence": "孩子的笑容有一种很大的威力，妈妈马上不生气了。", "error_description": "量词错误：“威力”应该用量词“种”，不能用“只”。“只”用于个体的动物或器物，“一种威力”才是正确说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
