INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新闻可以说出自己想法，不被人拦住。", "primary_collocate": null, "pronunciation": "méi tǐ zì yóu", "ipa": "meɪ˧˥ tʰi˨˩˦ tsɹ̩˥˩ joʊ˧˥", "syllable_count": 4, "sentences": [{"text": "在这个国家，媒体自由受到法律保护。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体自由让报纸敢说出自己的想法。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是媒体自由。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有媒体自由，记者不敢说真话。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇文章，谈媒体自由的重要性。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有媒体自由，电视台可以批评政府。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都希望有真正的媒体自由。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体自由对一个社会来说很重要。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者用报道告诉大家，媒体自由不能丢。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她研究过很多国家的媒体自由。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "媒體自由", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "新闻能说出自己的想法、没有人阻拦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97915, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "媒体自由", "is_correct": true, "explanation": "媒体自由：正确。“在这个国家……受到法律保护”与新闻可以自由表达想法的意思相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是具体家具，“桌子受到法律保护”与新闻自由表达想法的语境无关，句子不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是法律保护的对象，与新闻发表想法的语境无关。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”是生理活动，不能作为法律保护的对象，句子不通。"}], "explanations": {"媒体自由": "媒体自由：正确。“在这个国家……受到法律保护”与新闻可以自由表达想法的意思相符。", "桌子": "语义：“桌子”是具体家具，“桌子受到法律保护”与新闻自由表达想法的语境无关，句子不通。", "天空": "语义：“天空”不是法律保护的对象，与新闻发表想法的语境无关。", "呼吸": "语义：“呼吸”是生理活动，不能作为法律保护的对象，句子不通。"}, "sentence_index": 0, "correct_answer": "媒体自由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他休息了两周，终于恢复了媒体自由。", "explanation": "这里应该用〈体力〉。媒体自由指新闻机构的发表权利，不能指身体的力气。"}, {"text": "两人终于在菜市场买到了媒体自由。", "explanation": "这里应该用〈白菜〉。媒体自由是抽象的权利，不能像白菜一样在菜市场买到。"}, {"text": "他有很丰富的媒体自由。", "explanation": "这里应该用〈经验〉。媒体自由指新闻发表信息的权利，不能指个人的工作经验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97915, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "媒体自由", "is_correct": true, "explanation": "媒体自由：正确。“真正的媒体自由”指真实有效的新闻发表权利，与“大家都希望有”相符。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：“真正的”与“谎言”语义矛盾，大家不会希望有真正的谎言。"}, {"text": "假象", "is_correct": false, "explanation": "语义：“假象”指虚假的表面，与“真正的”矛盾。"}, {"text": "鬼话", "is_correct": false, "explanation": "语域：“鬼话”是口语中带贬义的词，与书面语“媒体自由”的语域不协调，语义也不符。"}], "explanations": {"媒体自由": "媒体自由：正确。“真正的媒体自由”指真实有效的新闻发表权利，与“大家都希望有”相符。", "谎言": "语义：“真正的”与“谎言”语义矛盾，大家不会希望有真正的谎言。", "假象": "语义：“假象”指虚假的表面，与“真正的”矛盾。", "鬼话": "语域：“鬼话”是口语中带贬义的词，与书面语“媒体自由”的语域不协调，语义也不符。"}, "sentence_index": 6, "correct_answer": "媒体自由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司持有很多报社的媒体自由。", "explanation": "这里应该用〈股份〉。媒体自由是发表信息的权利，不能被当作股份来持有。"}, {"text": "他的媒体自由很好，能看清远处。", "explanation": "这里应该用〈视力〉。媒体自由是发表信息的权利，不能指眼睛看得清远处。"}, {"text": "这幅画的媒体自由很鲜艳，颜色很亮。", "explanation": "这里应该用〈色彩〉。媒体自由指新闻机构发表信息的权利，不能用来形容画面的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的一个媒体自由得到了法律保护。", "corrected_sentence": "这个国家的媒体自由得到了法律保护。", "error_description": "错误：“媒体自由”是抽象的权利，不能用量词“个”计量，“一个”应去掉。正确说法是“这个国家的媒体自由得到了法律保护”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多记者都在争取一条媒体自由。", "corrected_sentence": "很多记者都在争取媒体自由。", "error_description": "量词错误：“条”用于长条形的东西或新闻、规定等，“媒体自由”是抽象权利，不能用“一条”计量，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
