INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新闻媒体可以自由发表信息而不受限制的权利。", "primary_collocate": null, "pronunciation": "méi tǐ zì yóu", "ipa": "meɪ˧˥ tʰi˨˩˦ tsɹ̩˥˩ joʊ˧˥", "syllable_count": 4, "sentences": [{"text": "法律保护媒体自由，报社可以说真话。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了媒体自由，记者才能自由发表报道。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的媒体自由很大，报纸敢批评政府。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为媒体自由是民主社会的重要权利。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有媒体自由，电视台不能随便报道政府的事。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上讨论了媒体自由的意义。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位记者一直为媒体自由努力工作。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体自由不等于可以乱说假话。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社失去了媒体自由，只能发表政府同意的消息。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人担心媒体自由会越来越少。", "target_word": "媒体自由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "媒體自由", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "新闻媒体依法自由发表信息、不受限制的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "媒体自由", "is_correct": true, "explanation": "媒体自由：正确。“法律保护媒体自由”与后句“报社可以说真话”相符。"}, {"text": "沉默权", "is_correct": false, "explanation": "语义：“沉默权”与“报社可以说真话”的意思相反，前后语义不连贯。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是具体用品，与“报社可以说真话”无关，“法律保护雨伞”不通。"}, {"text": "食品安全", "is_correct": false, "explanation": "语义：“食品安全”与后一分句“报社可以说真话”无关，句子语义不连贯。"}], "explanations": {"媒体自由": "媒体自由：正确。“法律保护媒体自由”与后句“报社可以说真话”相符。", "沉默权": "语义：“沉默权”与“报社可以说真话”的意思相反，前后语义不连贯。", "雨伞": "语义：“雨伞”是具体用品，与“报社可以说真话”无关，“法律保护雨伞”不通。", "食品安全": "语义：“食品安全”与后一分句“报社可以说真话”无关，句子语义不连贯。"}, "sentence_index": 0, "correct_answer": "媒体自由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠投资赚到了媒体自由。", "explanation": "这里应该用〈财务自由〉。媒体自由是发表信息的权利，不是金钱，不能靠投资“赚到”。"}, {"text": "超市终于进了一批媒体自由。", "explanation": "这里应该用〈货物〉。媒体自由是抽象的权利，不能像货物一样进货。"}, {"text": "下班后我终于有了媒体自由。", "explanation": "这里应该用〈空闲〉。媒体自由指新闻发表信息的权利，不能指个人的空闲时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "媒体自由", "is_correct": true, "explanation": "媒体自由：正确。记者为新闻发表的权利而工作，与“努力工作”的语境相符。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：记者的工作与“食谱”无关，句子语义不通。"}, {"text": "拼音", "is_correct": false, "explanation": "语义：“拼音”不是记者努力争取的目标，与语境不符。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“为……努力”后多接抽象目标，“拖鞋”是具体物品，不能这样搭配。"}], "explanations": {"媒体自由": "媒体自由：正确。记者为新闻发表的权利而工作，与“努力工作”的语境相符。", "食谱": "语义：记者的工作与“食谱”无关，句子语义不通。", "拼音": "语义：“拼音”不是记者努力争取的目标，与语境不符。", "拖鞋": "搭配：“为……努力”后多接抽象目标，“拖鞋”是具体物品，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "媒体自由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司拥有这家报社的媒体自由。", "explanation": "这里应该用〈所有权〉。媒体自由是发表信息的权利，不能被当作报社的所有权。"}, {"text": "他的媒体自由很丰富，已经积累了二十年。", "explanation": "这里应该用〈经验〉。媒体自由是发表信息的权利，不能像工作经验那样说“丰富”“积累”。"}, {"text": "他的媒体自由增加了三公斤。", "explanation": "这里应该用〈体重〉。媒体自由是抽象权利，不能用“增加了三公斤”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宪法保障了一个媒体自由。", "corrected_sentence": "宪法保障了媒体自由。", "error_description": "错误：在抽象名词“媒体自由”前加了量词“一个”。“媒体自由”指权利，不可数，不用“个”计量；正确说法是“宪法保障了媒体自由”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个年代，报社失去了一把媒体自由。", "corrected_sentence": "那个年代，报社失去了媒体自由。", "error_description": "量词错误：“把”多用于有柄的器具，“媒体自由”是抽象的权利，不能用“一把”计量，应去掉“一把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97919, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97919, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97919, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "差一点点才到那个数。", "primary_collocate": null, "pronunciation": "jiāng jìn", "ipa": "tɕjɑŋ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我等了将近两个小时。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班有将近三十个学生。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年将近五十岁了。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我家到学校，走路要将近一个小时。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在北京住了将近十年。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看了将近一个月。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开了将近三个小时才结束。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工资将近一万块。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里坐着将近四十个人。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了将近五公里。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在数量前，表示快要达到但还没到该数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b59156-5839-4aea-8d08-252264446946') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97919, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将近", "is_correct": true, "explanation": "将近：差一点才到这个数，与“两个小时”搭配，符合句意。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”描写突发的动作，不修饰时长“两个小时”。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“两个小时”的时长冲突。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”不修饰时长，与“等了两个小时”不搭。"}], "explanations": {"将近": "将近：差一点才到这个数，与“两个小时”搭配，符合句意。", "突然": "搭配：“突然”描写突发的动作，不修饰时长“两个小时”。", "立刻": "语义：“立刻”表示马上，与“两个小时”的时长冲突。", "忽然": "搭配：“忽然”不修饰时长，与“等了两个小时”不搭。"}, "sentence_index": 0, "correct_answer": "将近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我将近赶上了火车。", "explanation": "这里应该用〈差一点〉。将近是修饰数量或时间的副词，不能修饰“赶上火车”这类动作。"}, {"text": "他将近同意了。", "explanation": "这里应该用〈几乎〉。将近只修饰数量或时间，不修饰“同意”这类动作。"}, {"text": "我将近喜欢这个城市。", "explanation": "这里应该用〈很〉。将近修饰数量或时间，不修饰“喜欢”这类心理动词；表示程度要用“很”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将近", "is_correct": true, "explanation": "将近：差一点才到这个数，与“三个小时”搭配，符合句意。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻，与“三个小时”的时长不合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”后接动作进行，不接数量短语“三个小时”。"}, {"text": "早已", "is_correct": false, "explanation": "语义：“早已”指很久以前就完成，与“才结束”的语义冲突。"}], "explanations": {"将近": "将近：差一点才到这个数，与“三个小时”搭配，符合句意。", "马上": "语义：“马上”表示立刻，与“三个小时”的时长不合。", "正在": "搭配：“正在”后接动作进行，不接数量短语“三个小时”。", "早已": "语义：“早已”指很久以前就完成，与“才结束”的语义冲突。"}, "sentence_index": 6, "correct_answer": "将近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我将近跑完了全程。", "explanation": "这里应该用〈几乎〉。将近修饰数量或时间，不修饰“跑完全程”这类动作。"}, {"text": "我将近迷路了。", "explanation": "这里应该用〈险些〉。将近修饰数量或时间，不修饰“迷路”；表示差点发生可用“险些”或“差点”。"}, {"text": "我们将近到家了。", "explanation": "这里应该用〈快〉。将近修饰数量或时间，不修饰“到家”这类动作，表示快到用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他等了很将近三十分钟。", "corrected_sentence": "他等了将近三十分钟。", "error_description": "修饰错误：“很”是程度副词，不能修饰“将近”。“将近”本身表示差一点到某数，应说“等了将近三十分钟”，不能在前面加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们准备了将近了一个月。", "corrected_sentence": "他们准备了将近一个月。", "error_description": "体标错误：“了”应紧跟动词“准备”，不能插在“将近”和数量词之间，应说“准备了将近一个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
