INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接近。", "primary_collocate": null, "pronunciation": "jiāng jìn", "ipa": "tɕjɑŋ˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "春节将近，街上人很多。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年底将近，大家都很忙。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班时间将近，办公室里很安静。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试日期将近，他每天都复习。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚期将近，她开始准备礼物。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期将近，同学们都很高兴。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年关将近，工厂里更忙了。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业将近，大家拍了很多照片。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋将近，商店里卖很多月饼。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议时间将近，请大家坐好。", "target_word": "将近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用在时间或节日后作谓语，表示时间快要到了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b59156-5839-4aea-8d08-252264446946') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将近", "is_correct": true, "explanation": "将近：时间快要到了，与“春节”搭配，符合句意。"}, {"text": "出差", "is_correct": false, "explanation": "语义：春节不能“出差”，且与后句“街上人很多”的语境不合。"}, {"text": "上课", "is_correct": false, "explanation": "搭配：“春节”不接“上课”，句意不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是动作，不能用来指“春节”这个时间的到来。"}], "explanations": {"将近": "将近：时间快要到了，与“春节”搭配，符合句意。", "出差": "语义：春节不能“出差”，且与后句“街上人很多”的语境不合。", "上课": "搭配：“春节”不接“上课”，句意不通。", "迟到": "语义：“迟到”是动作，不能用来指“春节”这个时间的到来。"}, "sentence_index": 0, "correct_answer": "将近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们将近迟到了。", "explanation": "这里应该用〈差一点〉。将近在这里用在时间或节日后作谓语，表示时间快到，不能修饰“迟到”这类动作。"}, {"text": "这个孩子将近聪明。", "explanation": "这里应该用〈很〉。将近表示时间或节日快要到了，不能修饰“聪明”这样的形容词；表示程度要用“很”。"}, {"text": "他的病情将近好了。", "explanation": "这里应该用〈快〉。将近只用于时间或节日快要到，不用于病情这类状态；说病情快好了要用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将近", "is_correct": true, "explanation": "将近：时间快要到了，与“年关”搭配，并与后句“工厂里更忙了”呼应。"}, {"text": "放假", "is_correct": false, "explanation": "语义：放假意味着工作减少，与“工厂里更忙了”矛盾。"}, {"text": "停工", "is_correct": false, "explanation": "语义：停工则不会“更忙”，与句意相反。"}, {"text": "撒谎", "is_correct": false, "explanation": "搭配：“年关”不与“撒谎”搭配，句意不通。"}], "explanations": {"将近": "将近：时间快要到了，与“年关”搭配，并与后句“工厂里更忙了”呼应。", "放假": "语义：放假意味着工作减少，与“工厂里更忙了”矛盾。", "停工": "语义：停工则不会“更忙”，与句意相反。", "撒谎": "搭配：“年关”不与“撒谎”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "将近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我将近做完了作业。", "explanation": "这里应该用〈几乎〉。将近用于时间或节日快到，不修饰“做完作业”这类动作。"}, {"text": "我将近忘了带钥匙。", "explanation": "这里应该用〈险些〉。将近不能修饰“忘了”这类动作，差点发生要用“险些”。"}, {"text": "我将近吃完饭了。", "explanation": "这里应该用〈快〉。将近用在时间或节日后表示时间快到，不修饰“吃完饭”这类动作；表示动作快完成用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开学很将近了，我还没有准备好。", "corrected_sentence": "开学将近了，我还没有准备好。", "error_description": "“将近”前多加了程度副词“很”，应删去。“将近”表示时间快到，不能被“很”修饰，“很将近”不通，应说“开学将近了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交稿日期将近着，他有点着急。", "corrected_sentence": "交稿日期将近，他有点着急。", "error_description": "“将近”表示时间快到，不能带“着”，“将近着”不通，应说“将近”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18319b6a-0b41-40db-8dff-e76ba0a6f04d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
