INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97927, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97927, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "店里还没有卖掉，放在那里的东西。", "primary_collocate": null, "pronunciation": "kù cún", "ipa": "kʰu˥˩ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服是店里的库存，所以很便宜。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想把店里的库存快点卖掉。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天过去了，店里还有很多库存。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧手机是库存，现在打三折。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店在卖库存，每件只要十块钱。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋是去年的库存，没有人买。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店的库存太多，老板很着急。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的是库存，所以价钱很低。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些库存已经放了很久，都旧了。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天快到了，店里的冬衣库存要打折。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "库存量", "label": "复合"}], "register": "中性", "sense_fingerprint": "商店里没卖掉、还放着的商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体态，不能指衣服，“这件衣服是店里的身材”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：衣服没有体温，“衣服的体温”说不通。"}, {"text": "库存", "is_correct": true, "explanation": "正确：“这件衣服是店里的库存，所以很便宜”指店里没卖掉的商品，符合句意。"}, {"text": "学历", "is_correct": false, "explanation": "语义：衣服没有学历，“店里的学历”与句子无关。"}], "explanations": {"身材": "体貌：身材指人的体态，不能指衣服，“这件衣服是店里的身材”说不通。", "体温": "语义：衣服没有体温，“衣服的体温”说不通。", "库存": "正确：“这件衣服是店里的库存，所以很便宜”指店里没卖掉的商品，符合句意。", "学历": "语义：衣服没有学历，“店里的学历”与句子无关。"}, "sentence_index": 0, "correct_answer": "库存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的旧电脑是库存，我打算卖掉。", "explanation": "这里应该用〈旧货〉。库存指店里没卖掉的新商品，自己用过的东西要说旧货。"}, {"text": "这个月我的库存都用来交房租了。", "explanation": "这里应该用〈工资〉。库存是店里没卖掉的商品，用来交房租的钱要说工资。"}, {"text": "我的工资卡里有一笔库存，随时可以取。", "explanation": "这里应该用〈存款〉。库存是店里没卖掉的商品，银行里的钱要说存款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不说“太多”，“小店的价格太多”搭配不当。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：小店没有年龄，“小店的年龄太多”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：小店没有身高，“小店的身高太多”说不通。"}, {"text": "库存", "is_correct": true, "explanation": "正确：“小店的库存太多，老板很着急”指店里没卖掉的商品太多，符合句意。"}], "explanations": {"价格": "搭配：“价格”说高低，不说“太多”，“小店的价格太多”搭配不当。", "年龄": "语义：小店没有年龄，“小店的年龄太多”说不通。", "身高": "语义：小店没有身高，“小店的身高太多”说不通。", "库存": "正确：“小店的库存太多，老板很着急”指店里没卖掉的商品太多，符合句意。"}, "sentence_index": 6, "correct_answer": "库存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天快到了，店里把冬衣库存摆在门口给客人看，不卖。", "explanation": "这里应该用〈样品〉。库存是要卖掉的商品，只给客人看、不卖的叫样品。"}, {"text": "夏天快到了，老板去南方找新的冬衣库存，以后从那里进货。", "explanation": "这里应该用〈货源〉。进货的地方叫货源，库存是店里已有、还没卖掉的货。"}, {"text": "夏天快到了，店里的冬衣库存都是客人穿过的。", "explanation": "这里应该用〈旧货〉。库存是店里没卖掉的新商品，别人穿过的东西要说旧货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店里的这只库存很便宜。", "corrected_sentence": "店里的这批库存很便宜。", "error_description": "量词错误：“库存”应该用量词“批”，不能用“只”。“只”用于单个物品，库存按批计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店里还有很多没卖掉库存。", "corrected_sentence": "店里还有很多没卖掉的库存。", "error_description": "结构错误：“没卖掉”与“库存”之间漏了结构助词“的”。修饰名词时要说“没卖掉的库存”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
