INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97928, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "储存的货物。", "primary_collocate": null, "pronunciation": "kù cún", "ipa": "kʰu˥˩ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "仓库里的库存已经不多了。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的库存还够卖一个月。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的库存比上个月多。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在仓库里查库存。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的库存太多，东西卖不出去。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你去后面的仓库，把库存数一遍。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种米的库存只剩一百袋了。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新货到了，库存多了很多。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的库存都在城外的大仓库里。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，工厂要把库存都送出去。", "target_word": "库存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "库存量", "label": "复合"}], "register": "中性", "sense_fingerprint": "仓库里储存着的货物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：工资不放在仓库里，“仓库里的工资”说不通。"}, {"text": "库存", "is_correct": true, "explanation": "正确：“仓库里的库存已经不多了”指仓库里储存的货物，符合句意。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历不是货物，不能放在仓库里，句子不通。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”说重、淡，不说“不多了”，搭配不当。"}], "explanations": {"工资": "语义：工资不放在仓库里，“仓库里的工资”说不通。", "库存": "正确：“仓库里的库存已经不多了”指仓库里储存的货物，符合句意。", "学历": "语义：学历不是货物，不能放在仓库里，句子不通。", "口味": "搭配：“口味”说重、淡，不说“不多了”，搭配不当。"}, "sentence_index": 0, "correct_answer": "库存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在银行里有很多库存，随时都能取出来。", "explanation": "这里应该用〈存款〉。库存指储存的货物，银行里的钱要说存款。"}, {"text": "老板正在库存里睡觉。", "explanation": "这里应该用〈仓库〉。库存是储存的货物，人不能待在货物里睡觉，应说仓库。"}, {"text": "这家仓库的库存每天开车把货送到商店。", "explanation": "这里应该用〈工人〉。库存是储存的货物，会开车送货的是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：米没有年龄，“这种米的年龄”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不用“袋”计量，“只剩一百袋”搭配不当。"}, {"text": "字数", "is_correct": false, "explanation": "语义：米没有字数，“这种米的字数”说不通。"}, {"text": "库存", "is_correct": true, "explanation": "正确：“这种米的库存只剩一百袋了”指储存的米，用“袋”计量，符合句意。"}], "explanations": {"年龄": "语义：米没有年龄，“这种米的年龄”说不通。", "颜色": "搭配：“颜色”不用“袋”计量，“只剩一百袋”搭配不当。", "字数": "语义：米没有字数，“这种米的字数”说不通。", "库存": "正确：“这种米的库存只剩一百袋了”指储存的米，用“袋”计量，符合句意。"}, "sentence_index": 6, "correct_answer": "库存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过年前，工厂要把库存都存进银行。", "explanation": "这里应该用〈货款〉。库存是货物，不能存进银行，卖货收到的钱才叫货款。"}, {"text": "过年前，工厂要把库存都发给工人当工资。", "explanation": "这里应该用〈奖金〉。库存是储存的货物，发给工人的钱要说奖金或工资。"}, {"text": "过年前，工厂的库存很好，卖出了一万件。", "explanation": "这里应该用〈销量〉。卖出去的数量叫销量，库存是还没卖出去、储存着的货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只库存已经卖出去一半了。", "corrected_sentence": "这批库存已经卖出去一半了。", "error_description": "量词错误：“库存”应该用量词“批”，不能用“只”。“只”用于单个物品，库存是按批计量的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库里还有一批没运走库存。", "corrected_sentence": "仓库里还有一批没运走的库存。", "error_description": "结构错误：“没运走”与“库存”之间漏了结构助词“的”。修饰名词时要说“没运走的库存”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97935, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
