INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97935, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得了某种病。", "primary_collocate": null, "pronunciation": "huàn", "ipa": "xuan˥˩", "syllable_count": 1, "sentences": [{"text": "他去年患了重感冒，休息了一个星期。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，小明患了肠炎，要在家休息。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶患过一次肺炎，现在身体很好。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人患糖尿病已经十年了。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王患了胃病，不能吃太辣的菜。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟小时候患过水痘。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不幸患了癌症，家人都很难过。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他患了严重的眼病，看不清东西。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听说他患的是一种少见的病。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天很冷，不少孩子患了流感。", "target_word": "患", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "患了", "label": "完成体"}, {"form": "患过", "label": "经历体"}, {"form": "患着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "患：得了某种病，后面接病名，如患感冒、患肺炎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aa28573-c80f-4808-aa31-1a2121744695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97935, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "患", "is_correct": true, "explanation": "患 huàn（第四声）：得了某种病，即本句“患了重感冒”的“患”。"}, {"text": "欢", "is_correct": false, "explanation": "欢 huān 与 huàn 声调不同（第一声），意思是高兴。"}, {"text": "环", "is_correct": false, "explanation": "环 huán 与 huàn 声调不同（第二声），意思是环形。"}, {"text": "汗", "is_correct": false, "explanation": "汗 hàn 少了 u 介音，与 huàn 只差一个介音，意思是汗水。"}, {"text": "惯", "is_correct": false, "explanation": "惯 guàn 与 huàn 声母不同（g 与 h），意思是习惯。"}, {"text": "话", "is_correct": false, "explanation": "话 huà 少了鼻音韵尾 n，与 huàn 只差一个音，意思是说话。"}], "explanations": {"患": "患 huàn（第四声）：得了某种病，即本句“患了重感冒”的“患”。", "欢": "欢 huān 与 huàn 声调不同（第一声），意思是高兴。", "环": "环 huán 与 huàn 声调不同（第二声），意思是环形。", "汗": "汗 hàn 少了 u 介音，与 huàn 只差一个介音，意思是汗水。", "惯": "惯 guàn 与 huàn 声母不同（g 与 h），意思是习惯。", "话": "话 huà 少了鼻音韵尾 n，与 huàn 只差一个音，意思是说话。"}, "sentence_index": null, "correct_answer": "患"}, "level_3": {"options": [{"text": "患", "is_correct": true, "explanation": "患：得了某种病，与“重感冒”相符，句意完整。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是药或饭，不能说吃重感冒。"}, {"text": "戒", "is_correct": false, "explanation": "语义：“戒”是戒除之意，不表示得病，与句意不符。"}, {"text": "咳", "is_correct": false, "explanation": "配价：“咳”不能带病名作宾语，“咳了重感冒”不成立。"}], "explanations": {"患": "患：得了某种病，与“重感冒”相符，句意完整。", "吃": "搭配：“吃”的宾语是药或饭，不能说吃重感冒。", "戒": "语义：“戒”是戒除之意，不表示得病，与句意不符。", "咳": "配价：“咳”不能带病名作宾语，“咳了重感冒”不成立。"}, "sentence_index": 0, "correct_answer": "患"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上患了车祸，被送进了医院。", "explanation": "这里应该用〈遭遇〉。患只用于疾病，车祸等意外要说遭遇。"}, {"text": "他在比赛中患了第一名，大家都很惊讶。", "explanation": "这里应该用〈得〉。患只用于得病，获得名次要说得。"}, {"text": "他的伤口患了细菌，需要消毒。", "explanation": "这里应该用〈感染〉。患指人得病，伤口受细菌侵入要说感染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97935, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "患", "is_correct": true, "explanation": "患 huàn（第四声）：得了某种病，即本句“患了癌症”的“患”。"}, {"text": "缓", "is_correct": false, "explanation": "缓 huǎn 与 huàn 声调不同（第三声），意思是缓慢。"}, {"text": "还", "is_correct": false, "explanation": "还 huán 与 huàn 声调不同（第二声），意思是归还。"}, {"text": "灌", "is_correct": false, "explanation": "灌 guàn 与 huàn 声母不同（g 与 h），意思是灌注。"}, {"text": "画", "is_correct": false, "explanation": "画 huà 少了鼻音韵尾 n，与 huàn 只差一个音，意思是图画。"}], "explanations": {"患": "患 huàn（第四声）：得了某种病，即本句“患了癌症”的“患”。", "缓": "缓 huǎn 与 huàn 声调不同（第三声），意思是缓慢。", "还": "还 huán 与 huàn 声调不同（第二声），意思是归还。", "灌": "灌 guàn 与 huàn 声母不同（g 与 h），意思是灌注。", "画": "画 huà 少了鼻音韵尾 n，与 huàn 只差一个音，意思是图画。"}, "sentence_index": null, "correct_answer": "患"}, "level_3": {"options": [{"text": "患", "is_correct": true, "explanation": "患：得了癌症，与“不幸”和“家人都很难过”相符。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”是躲避之意，不表示得病，句中说不通。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，不能带病名作宾语，“躺了癌症”不成立。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃之意，不能与癌症搭配。"}], "explanations": {"患": "患：得了癌症，与“不幸”和“家人都很难过”相符。", "逃": "语义：“逃”是躲避之意，不表示得病，句中说不通。", "躺": "配价：“躺”是不及物动词，不能带病名作宾语，“躺了癌症”不成立。", "扔": "语义：“扔”是丢弃之意，不能与癌症搭配。"}, "sentence_index": 6, "correct_answer": "患"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在事故中患了伤，需要住院观察。", "explanation": "这里应该用〈受〉。患只用于疾病，受伤要说受。"}, {"text": "他在街上患了一位老朋友，两人聊了很久。", "explanation": "这里应该用〈遇见〉。患只指得病，偶然碰到人要说遇见。"}, {"text": "他这次患了一个大错误，大家都很生气。", "explanation": "这里应该用〈犯〉。患指得病，犯错误要说犯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他患起了肺炎，只好住院。", "corrected_sentence": "他患上了肺炎，只好住院。", "error_description": "“患起”错误，应为“患上”。“患上”表示染上某种病，“起”不能跟在“患”后作补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她三十岁就被患了糖尿病，现在要天天打针。", "corrected_sentence": "她三十岁就患了糖尿病，现在要天天打针。", "error_description": "“被患”错误，应为“患”。“患”是主动动词，不能加“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
