INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97939, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话里或事里有一点点别的意思。", "primary_collocate": null, "pronunciation": "yì wèi", "ipa": "i˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "他的话里带着一点讽刺的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话听起来有一点警告的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑了一下，笑里有些无奈的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话带有鼓励的意味，我听懂了。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼物有告别的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌有怀念过去的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有明说，但话里有拒绝的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说“随便你”，话里有生气的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈叹了口气，那口气里有担心的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那封信的最后一句有一点请求的意味。", "target_word": "意味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种意味", "label": "量词"}, {"form": "一丝意味", "label": "量词"}], "register": "书面语", "sense_fingerprint": "意味：话语或事情里含有的某种暗含的意思，如讽刺的意味、警告的意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aa28573-c80f-4808-aa31-1a2121744695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97939, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意味", "is_correct": true, "explanation": "意味 yì wèi：话里或事里暗含的意思，是本题正确答案。"}, {"text": "一味", "is_correct": false, "explanation": "yí（第二声，“一”在第四声前变调）与 yì（第四声）声调不同，“一味”意思是“只顾、一个劲儿”，与“话里暗含的意思”无关。"}, {"text": "意为", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，“意为”意思是“表示、意思是”。"}, {"text": "移位", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，“移位”意思是“位置改变”。"}, {"text": "意外", "is_correct": false, "explanation": "wài 与 wèi 韵母不同（ai 与 ei），“意外”意思是“没有预料到的事”。"}], "explanations": {"意味": "意味 yì wèi：话里或事里暗含的意思，是本题正确答案。", "一味": "yí（第二声，“一”在第四声前变调）与 yì（第四声）声调不同，“一味”意思是“只顾、一个劲儿”，与“话里暗含的意思”无关。", "意为": "wéi（第二声）与 wèi（第四声）声调不同，“意为”意思是“表示、意思是”。", "移位": "yí（第二声）与 yì（第四声）声调不同，“移位”意思是“位置改变”。", "意外": "wài 与 wèi 韵母不同（ai 与 ei），“意外”意思是“没有预料到的事”。"}, "sentence_index": null, "correct_answer": "意味"}, "level_3": {"options": [{"text": "意味", "is_correct": true, "explanation": "意味：话里暗含的意思。“带着一点讽刺的意味”指话中含有讽刺之意，符合语境。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，话里的讽刺不是物体，不能有形状。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或物的重量，不能与“讽刺”搭配。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体所占的空间，与话里的讽刺无关。"}], "explanations": {"意味": "意味：话里暗含的意思。“带着一点讽刺的意味”指话中含有讽刺之意，符合语境。", "形状": "语义：“形状”指物体的外形，话里的讽刺不是物体，不能有形状。", "体重": "搭配：“体重”指人或物的重量，不能与“讽刺”搭配。", "体积": "语义：“体积”指物体所占的空间，与话里的讽刺无关。"}, "sentence_index": 0, "correct_answer": "意味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“苹果”这个词的意味是一种水果。", "explanation": "这里应该用〈意思〉。意味指话里或事里暗含的意思，不用来解释词语本身的含义，“苹果”的含义应说“意思”。"}, {"text": "这瓶香水的意味很好闻。", "explanation": "这里应该用〈气味〉。意味指话或事里暗含的意思，不指气息，“很好闻”只能用于气味。"}, {"text": "这道菜的意味很鲜美。", "explanation": "这里应该用〈味道〉。意味不指食物的滋味，“很鲜美”描述的是味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97939, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意味", "is_correct": true, "explanation": "意味 yì wèi：话里或事里暗含的意思，是本题正确答案。"}, {"text": "以为", "is_correct": false, "explanation": "yǐ wéi 两个音节的声调都与 yì wèi 不同，“以为”意思是“认为”。"}, {"text": "一位", "is_correct": false, "explanation": "yí（第二声，“一”在第四声前变调）与 yì（第四声）声调不同，“一位”意思是“一个人”（用于尊称）。"}, {"text": "亦为", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，“亦为”意思是“也是”（书面语）。"}], "explanations": {"意味": "意味 yì wèi：话里或事里暗含的意思，是本题正确答案。", "以为": "yǐ wéi 两个音节的声调都与 yì wèi 不同，“以为”意思是“认为”。", "一位": "yí（第二声，“一”在第四声前变调）与 yì（第四声）声调不同，“一位”意思是“一个人”（用于尊称）。", "亦为": "wéi（第二声）与 wèi（第四声）声调不同，“亦为”意思是“也是”（书面语）。"}, "sentence_index": null, "correct_answer": "意味"}, "level_3": {"options": [{"text": "意味", "is_correct": true, "explanation": "意味：话里暗含的意思。“话里有拒绝的意味”指话中透露出拒绝之意，符合语境。"}, {"text": "香味", "is_correct": false, "explanation": "语义：“香味”指食物或花草的气味，话里不能有香味，与“拒绝”不合。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”指物体的大小，不能与“拒绝”搭配。"}, {"text": "样貌", "is_correct": false, "explanation": "语义：“样貌”指人或物的外表，话里不能有样貌，与“拒绝”不合。"}], "explanations": {"意味": "意味：话里暗含的意思。“话里有拒绝的意味”指话中透露出拒绝之意，符合语境。", "香味": "语义：“香味”指食物或花草的气味，话里不能有香味，与“拒绝”不合。", "尺寸": "搭配：“尺寸”指物体的大小，不能与“拒绝”搭配。", "样貌": "语义：“样貌”指人或物的外表，话里不能有样貌，与“拒绝”不合。"}, "sentence_index": 6, "correct_answer": "意味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的意味很沉。", "explanation": "这里应该用〈重量〉。意味指话或事里暗含的意思，不指物体的轻重，“很沉”描述的是重量。"}, {"text": "摸着布料，我觉得意味很粗糙。", "explanation": "这里应该用〈质地〉。意味不指物品表面的质感，“很粗糙”描述的是质地。"}, {"text": "这张桌子的意味很高。", "explanation": "这里应该用〈高度〉。意味不指物体的高低，“很高”描述的是高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的语气里带着一丝不满的意味着。", "corrected_sentence": "她的语气里带着一丝不满的意味。", "error_description": "错误：“意味”后面多加了“着”。“意味”作名词时后面不能加“着”，“意味着”是动词。正确形式为“不满的意味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最后一句话里藏着一颗威胁的意味。", "corrected_sentence": "他最后一句话里藏着一丝威胁的意味。", "error_description": "量词错误：“一颗威胁的意味”。“颗”多用于小而圆的实体，不搭配抽象的“意味”；可用“一丝”“一点”“一种”等。正确形式为“一丝威胁的意味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
