INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97943, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97943, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里很高兴，谢谢别人的帮助。", "primary_collocate": null, "pronunciation": "gǎn jī", "ipa": "kan˨˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "谢谢你帮我，我非常感激。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很感激老师给我的帮助。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感激地对邻居说了谢谢。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在我生病时照顾我，我一直很感激他。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都感激这位救了孩子的医生。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我感激过很多帮助我的人。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮了我大忙，我真不知道怎么感激他。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很感激邻居帮忙接孩子。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心里感激，所以请你吃饭。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到朋友送来的药，她感激极了。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感激了", "label": "体标（了）"}, {"form": "感激过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "别人帮了忙，心里高兴并表示感谢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "感激", "is_correct": true, "explanation": "感激（gǎn jī）：正确答案，心里高兴并感谢别人的帮助。"}, {"text": "赶集", "is_correct": false, "explanation": "赶集（gǎn jí）与感激（gǎn jī）第二音节声调不同（第二声与第一声），意思是到集市买卖东西。"}, {"text": "赶紧", "is_correct": false, "explanation": "赶紧（gǎn jǐn）与感激（gǎn jī）第二音节韵母不同（jǐn 与 jī），意思是抓紧时间。"}, {"text": "感知", "is_correct": false, "explanation": "感知（gǎn zhī）与感激（gǎn jī）第二音节声母不同（zh 与 j），意思是感觉到、察觉。"}], "explanations": {"感激": "感激（gǎn jī）：正确答案，心里高兴并感谢别人的帮助。", "赶集": "赶集（gǎn jí）与感激（gǎn jī）第二音节声调不同（第二声与第一声），意思是到集市买卖东西。", "赶紧": "赶紧（gǎn jǐn）与感激（gǎn jī）第二音节韵母不同（jǐn 与 jī），意思是抓紧时间。", "感知": "感知（gǎn zhī）与感激（gǎn jī）第二音节声母不同（zh 与 j），意思是感觉到、察觉。"}, "sentence_index": null, "correct_answer": "感激"}, "level_3": {"options": [{"text": "感激", "is_correct": true, "explanation": "正确：“感激”表示心里感谢别人的帮助，与“谢谢你帮我”相符。"}, {"text": "怨恨", "is_correct": false, "explanation": "语义：“怨恨”指不满并记恨，与“谢谢你帮我”的感谢相矛盾。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与句中的感谢相矛盾。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”需要带对象（原谅某人），“我非常原谅”后面缺少宾语，不成立。"}], "explanations": {"感激": "正确：“感激”表示心里感谢别人的帮助，与“谢谢你帮我”相符。", "怨恨": "语义：“怨恨”指不满并记恨，与“谢谢你帮我”的感谢相矛盾。", "讨厌": "语义：“讨厌”表示厌恶，与句中的感谢相矛盾。", "原谅": "配价：“原谅”需要带对象（原谅某人），“我非常原谅”后面缺少宾语，不成立。"}, "sentence_index": 0, "correct_answer": "感激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看到孩子进步，我很感激。", "explanation": "这里应该用〈感动〉。感激是对帮助过自己的人心存谢意，看到别人进步后的情绪应说〈感动〉。"}, {"text": "我感激这把椅子的高度。", "explanation": "这里应该用〈满意〉。感激针对给予自己帮助的人，对椅子高度觉得合适应说〈满意〉，不能用“感激”。"}, {"text": "我对这个结果很感激。", "explanation": "这里应该用〈满意〉。感激的对象是帮助过自己的人，对结果的满意应说〈满意〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感激", "is_correct": true, "explanation": "正确：“感激”指对帮助自己的人心存谢意，与“他帮了我大忙”相符。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负”指对不起别人的好意，与“他帮了我大忙”的情境矛盾。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”指怠慢、不理睬，与“他帮了我大忙”的情境矛盾。"}, {"text": "感慨", "is_correct": false, "explanation": "配价：“感慨”是不及物动词，后面不能直接带人作宾语。"}], "explanations": {"感激": "正确：“感激”指对帮助自己的人心存谢意，与“他帮了我大忙”相符。", "辜负": "语义：“辜负”指对不起别人的好意，与“他帮了我大忙”的情境矛盾。", "冷落": "语义：“冷落”指怠慢、不理睬，与“他帮了我大忙”的情境矛盾。", "感慨": "配价：“感慨”是不及物动词，后面不能直接带人作宾语。"}, "sentence_index": 6, "correct_answer": "感激"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很感激这张桌子的颜色。", "explanation": "这里应该用〈喜欢〉。感激针对帮助过自己的人，对桌子颜色的喜爱应说〈喜欢〉，不能用“感激”。"}, {"text": "老师很感激我的字迹。", "explanation": "这里应该用〈欣赏〉。感激针对帮助过自己的人，称赞字迹应说〈欣赏〉，不能用“感激”。"}, {"text": "我很感激这支笔的重量。", "explanation": "这里应该用〈满意〉。感激针对给予自己好处的人，对笔的重量表示满意应说〈满意〉，不能用“感激”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很多感激你的理解。", "corrected_sentence": "我非常感激你的理解。", "error_description": "“很多”是数量词组，不能作状语修饰动词“感激”，表示程度时应用“非常”。应把“很多”改为“非常”，即“我非常感激你的理解”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她感激的对护士说了谢谢。", "corrected_sentence": "她感激地对护士说了谢谢。", "error_description": "“感激”后面修饰动词“说”的状语要用“地”，写成“的”是错误的，应改为“感激地对护士说了谢谢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
