INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97944, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因受到好处而心存谢意。", "primary_collocate": null, "pronunciation": "gǎn jī", "ipa": "kan˨˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "他一直感激当年帮过他的人。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对您的好意十分感激。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家收到礼物，都很感激。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们感激老板在困难时借钱。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我永远感激父母的养育。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们感激这位送来粮食的老人。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得到奖学金后，她感激学校给她机会。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人感激主人热情的招待。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我感激你，因为你在我最难的时候没有离开。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里感激着那位好心的司机。", "target_word": "感激", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感激了", "label": "体标（了）"}, {"form": "感激过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "受到恩惠或好处后心里记着谢意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "感激", "is_correct": true, "explanation": "感激（gǎn jī）：正确答案，因受到好处而心存谢意。"}, {"text": "赶集", "is_correct": false, "explanation": "赶集（gǎn jí）与感激（gǎn jī）第二音节声调不同（第二声与第一声），意思是到集市买卖东西。"}, {"text": "赶紧", "is_correct": false, "explanation": "赶紧（gǎn jǐn）与感激（gǎn jī）第二音节韵母不同（jǐn 与 jī），意思是抓紧时间。"}, {"text": "感知", "is_correct": false, "explanation": "感知（gǎn zhī）与感激（gǎn jī）第二音节声母不同（zh 与 j），意思是感觉到、察觉。"}], "explanations": {"感激": "感激（gǎn jī）：正确答案，因受到好处而心存谢意。", "赶集": "赶集（gǎn jí）与感激（gǎn jī）第二音节声调不同（第二声与第一声），意思是到集市买卖东西。", "赶紧": "赶紧（gǎn jǐn）与感激（gǎn jī）第二音节韵母不同（jǐn 与 jī），意思是抓紧时间。", "感知": "感知（gǎn zhī）与感激（gǎn jī）第二音节声母不同（zh 与 j），意思是感觉到、察觉。"}, "sentence_index": null, "correct_answer": "感激"}, "level_3": {"options": [{"text": "感激", "is_correct": true, "explanation": "正确：“感激”指受到恩惠后心存谢意，与“帮过他的人”相符。"}, {"text": "怨恨", "is_correct": false, "explanation": "语义：“怨恨”指记恨，与“当年帮过他”的感激情境矛盾。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“帮过他”的情境矛盾。"}, {"text": "感慨", "is_correct": false, "explanation": "配价：“感慨”是不及物动词，后面不能直接带“帮过他的人”作宾语。"}], "explanations": {"感激": "正确：“感激”指受到恩惠后心存谢意，与“帮过他的人”相符。", "怨恨": "语义：“怨恨”指记恨，与“当年帮过他”的感激情境矛盾。", "讨厌": "语义：“讨厌”表示厌恶，与“帮过他”的情境矛盾。", "感慨": "配价：“感慨”是不及物动词，后面不能直接带“帮过他的人”作宾语。"}, "sentence_index": 0, "correct_answer": "感激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他感激老板借钱太少。", "explanation": "这里应该用〈埋怨〉。感激是心存谢意，对对方给的帮助不满应说〈埋怨〉。"}, {"text": "他感激这间屋子的寒冷。", "explanation": "这里应该用〈抱怨〉。感激针对给予自己好处的人，对屋子寒冷的不满应说〈抱怨〉，不能用“感激”。"}, {"text": "老师感激他的抄袭。", "explanation": "这里应该用〈批评〉。感激针对给予自己好处的人，对抄袭应说〈批评〉，不能用“感激”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感激", "is_correct": true, "explanation": "正确：“感激”指因受到好处而心存谢意，与“得到奖学金后”的情境相符。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌恶，与“得到奖学金”后的受惠情境矛盾。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”指怠慢，与“学校给她机会”的受惠情境矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”后面多接待遇、服务、生活等，“享受学校给她机会”搭配不当。"}], "explanations": {"感激": "正确：“感激”指因受到好处而心存谢意，与“得到奖学金后”的情境相符。", "嫌弃": "语义：“嫌弃”表示厌恶，与“得到奖学金”后的受惠情境矛盾。", "冷落": "语义：“冷落”指怠慢，与“学校给她机会”的受惠情境矛盾。", "享受": "搭配：“享受”后面多接待遇、服务、生活等，“享受学校给她机会”搭配不当。"}, "sentence_index": 6, "correct_answer": "感激"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很感激这块桌布的图案。", "explanation": "这里应该用〈喜欢〉。感激针对给予自己好处的人，对图案的喜爱应说〈喜欢〉，不能用“感激”。"}, {"text": "他感激那种粗鲁的做法。", "explanation": "这里应该用〈厌恶〉。感激针对给予自己好处的人，对粗鲁做法的反感应说〈厌恶〉，不能用“感激”。"}, {"text": "他感激这张床的软硬。", "explanation": "这里应该用〈满意〉。感激针对给予自己好处的人，对床的软硬表示满意应说〈满意〉，不能用“感激”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对老师的教导很多感激。", "corrected_sentence": "他对老师的教导十分感激。", "error_description": "“很多”是数量词组，不能作状语修饰动词“感激”，表示程度时应用“十分”。应把“很多”改为“十分”，即“他对老师的教导十分感激”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他感激的对司机说了谢谢。", "corrected_sentence": "他感激地对司机说了谢谢。", "error_description": "“感激”后面修饰动词“说”的状语要用“地”，写成“的”是错误的，应改为“感激地对司机说了谢谢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
