INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97947, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或团体里很重要的规矩书。", "primary_collocate": null, "pronunciation": "xiàn zhāng", "ipa": "ɕiɛn˥˩ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这个俱乐部有一部自己的宪章。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个成员都要遵守宪章。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国宪章是在1945年签的。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把宪章带到了会议上。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新会员要先读一读组织的宪章。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宪章里写着会员的权利。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织的宪章已经改了两次。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会的宪章规定了会员的义务。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会长给每个会员发了一份宪章。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按照宪章选出了新主席。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部宪章", "label": "量词"}, {"form": "一份宪章", "label": "量词"}, {"form": "憲章", "label": "繁体"}], "register": "书面", "sense_fingerprint": "团体或国家内部要求成员遵守的重要规章文本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宪章", "is_correct": true, "explanation": "宪章：国家或团体里很重要的规矩书。"}, {"text": "县长", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，县长指县的行政首长。"}, {"text": "现场", "is_correct": false, "explanation": "xiànchǎng 与 xiànzhāng 声母不同（ch 与 zh），声调也不同，现场指事情发生的地方。"}, {"text": "线装", "is_correct": false, "explanation": "线装：用线穿订的书籍装订方式；zhuāng 与 zhāng 只差一个介音 u。"}], "explanations": {"宪章": "宪章：国家或团体里很重要的规矩书。", "县长": "zhǎng（第三声）与 zhāng（第一声）声调不同，县长指县的行政首长。", "现场": "xiànchǎng 与 xiànzhāng 声母不同（ch 与 zh），声调也不同，现场指事情发生的地方。", "线装": "线装：用线穿订的书籍装订方式；zhuāng 与 zhāng 只差一个介音 u。"}, "sentence_index": null, "correct_answer": "宪章"}, "level_3": {"options": [{"text": "宪章", "is_correct": true, "explanation": "宪章：国家或团体里很重要的规矩书，此处指俱乐部自己的规章文件。"}, {"text": "电视剧", "is_correct": false, "explanation": "语义：俱乐部一般不会“有”一部自己的电视剧，句意不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，俱乐部不能“拥有”一部自己的太阳，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无形，不能用“部”计量，俱乐部也不能“拥有”一部空气。"}], "explanations": {"宪章": "宪章：国家或团体里很重要的规矩书，此处指俱乐部自己的规章文件。", "电视剧": "语义：俱乐部一般不会“有”一部自己的电视剧，句意不通。", "太阳": "语义：太阳是天体，俱乐部不能“拥有”一部自己的太阳，句意不通。", "空气": "语义：空气无形，不能用“部”计量，俱乐部也不能“拥有”一部空气。"}, "sentence_index": 0, "correct_answer": "宪章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校发了一份宪章，明天放假。", "explanation": "这里应该用〈通知〉。通知用于临时告知事项，宪章是国家或团体里的基本规矩书，不能用来宣布放假。"}, {"text": "他把宪章打碎了。", "explanation": "这里应该用〈撕〉或〈烧〉。打碎用于玻璃、瓷器这类易碎物，宪章是纸质文件，不能说打碎。"}, {"text": "妈妈正在厨房里炒宪章。", "explanation": "这里“炒”是烹饪的意思，与宪章作为纸质规矩书的意思不符，不能下锅做菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宪章", "is_correct": true, "explanation": "宪章：国家或团体里很重要的规矩书，此处指组织的规章文件，被修改过两次。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物存活的年数，组织的年龄不能被“改”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只指人或动物的高矮，不能用于组织。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物或气味，组织没有味道可以改，句意不通。"}], "explanations": {"宪章": "宪章：国家或团体里很重要的规矩书，此处指组织的规章文件，被修改过两次。", "年龄": "语义：“年龄”指人或生物存活的年数，组织的年龄不能被“改”。", "身高": "体貌：“身高”只指人或动物的高矮，不能用于组织。", "味道": "语义：“味道”指食物或气味，组织没有味道可以改，句意不通。"}, "sentence_index": 6, "correct_answer": "宪章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宪章选出了新主席。", "explanation": "这里应该用〈按照〉引出依据。宪章是规定准则的文件，不能作为施事去选人。"}, {"text": "明天会议的宪章是讨论预算。", "explanation": "这里应该用〈议程〉。议程是会议安排的事项，宪章是国家或团体的基本规矩书，不能用来指会议日程。"}, {"text": "宪章今天早上学会了游泳。", "explanation": "学会游泳只能用于有生命的人。宪章是规定基本准则的文件，不会学习游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们社团有一只宪章。", "corrected_sentence": "我们社团有一部宪章。", "error_description": "量词错误：“宪章”是书面文件，应说“一部宪章”或“一份宪章”，不能说“一只宪章”，“只”用于动物和成对物品中的单个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们修改得三次宪章。", "corrected_sentence": "他们修改过三次宪章。", "error_description": "“过”误写为“得”。表示经历要用“过”，应说“修改过三次宪章”，不能说“修改得三次宪章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
