INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重要的纲领性文件；规定基本准则的文件。", "primary_collocate": null, "pronunciation": "xiàn zhāng", "ipa": "ɕiɛn˥˩ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "联合国宪章规定各国应该和平相处。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份宪章是国际合作的基础。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧洲国家一起签了一份新宪章。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宪章中写明了基本的原则。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部宪章对世界很重要。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会通过了新的宪章。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宪章规定所有国家都是平等的。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书里读到了这部宪章的内容。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国代表在宪章上签了字。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份宪章影响了很多国家。", "target_word": "宪章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部宪章", "label": "量词"}, {"form": "一份宪章", "label": "量词"}, {"form": "憲章", "label": "繁体"}], "register": "书面", "sense_fingerprint": "规定基本原则和准则的纲领性文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宪章", "is_correct": true, "explanation": "宪章：规定基本准则的重要纲领性文件。"}, {"text": "县长", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，县长指县的行政首长。"}, {"text": "县中", "is_correct": false, "explanation": "zhōng 与 zhāng 韵母不同（ong 与 ang），县中指县里的中学。"}, {"text": "线装", "is_correct": false, "explanation": "线装：用线穿订的书籍装订方式；zhuāng 与 zhāng 只差一个介音 u。"}], "explanations": {"宪章": "宪章：规定基本准则的重要纲领性文件。", "县长": "zhǎng（第三声）与 zhāng（第一声）声调不同，县长指县的行政首长。", "县中": "zhōng 与 zhāng 韵母不同（ong 与 ang），县中指县里的中学。", "线装": "线装：用线穿订的书籍装订方式；zhuāng 与 zhāng 只差一个介音 u。"}, "sentence_index": null, "correct_answer": "宪章"}, "level_3": {"options": [{"text": "宪章", "is_correct": true, "explanation": "宪章：规定基本准则的重要纲领性文件，此处指联合国宪章。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不是规定国家关系的文件，句意不通。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：“口号”不能“规定”，“规定……”的搭配不成立。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱只记录做菜的步骤，与规定国家之间的关系无关。"}], "explanations": {"宪章": "宪章：规定基本准则的重要纲领性文件，此处指联合国宪章。", "足球": "语义：足球不是规定国家关系的文件，句意不通。", "口号": "搭配：“口号”不能“规定”，“规定……”的搭配不成立。", "菜谱": "语义：菜谱只记录做菜的步骤，与规定国家之间的关系无关。"}, "sentence_index": 0, "correct_answer": "宪章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买东西后要留一份宪章。", "explanation": "这里应该用〈发票〉。发票是购物凭证，宪章是规定基本准则的文件，不能当凭证。"}, {"text": "宪章举行了一场比赛。", "explanation": "这里不能让〈宪章〉作施事。宪章是规定原则的文件，不能举行比赛。"}, {"text": "妈妈用宪章给我做了一碗面。", "explanation": "这里不能把宪章当食材。宪章是纸质文件，不能用来做面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宪章", "is_correct": true, "explanation": "宪章：规定基本准则的重要纲领性文件，此处指规定国家平等的文件。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能规定国家的地位，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能“规定”，“规定……”的搭配不成立。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不能规定国家是否平等，句意不通。"}], "explanations": {"宪章": "宪章：规定基本准则的重要纲领性文件，此处指规定国家平等的文件。", "歌曲": "语义：歌曲不能规定国家的地位，句意不通。", "天气": "搭配：“天气”不能“规定”，“规定……”的搭配不成立。", "花朵": "语义：花朵不能规定国家是否平等，句意不通。"}, "sentence_index": 6, "correct_answer": "宪章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "餐厅的宪章很长。", "explanation": "这里应该用〈菜单〉。菜单是列出菜品的单子，宪章是规定基本准则的文件，不能用来指菜品。"}, {"text": "宪章在会议上发言了。", "explanation": "这里不能让〈宪章〉作施事。宪章是文件，不能发言。"}, {"text": "我们在宪章里踢足球。", "explanation": "这里不能把〈宪章〉当场地。宪章是纸质文件，不能作为运动的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各国代表签了一只宪章。", "corrected_sentence": "各国代表签了一份宪章。", "error_description": "量词错误：宪章用“份”计量，不能用“只”，应说“一份宪章”，不能说“一只宪章”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于把宪章写了完。", "corrected_sentence": "他们终于把宪章写完了。", "error_description": "结果补语位置错误：“完”紧跟动词，应说“写完了”，不能说“写了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97955, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
