INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97955, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "故意这样做，不是不小心。", "primary_collocate": null, "pronunciation": "chéng xīn", "ipa": "ʈʂʰɤŋ˧˥ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "他成心不接我的电话。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是成心让我迟到？", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她成心把门关得很响。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟成心藏起了我的手机。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不是我不小心，我就是成心的。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板成心不回答这个问题。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成心说错了地址，让大家白跑一趟。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子成心把杯子放在桌子边上。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我成心没告诉他这个消息。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌成心踩了我一脚。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词：故意做某事，不是无意或不小心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97955, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成心", "is_correct": true, "explanation": "成心（chéng xīn）：故意这样做，不是不小心。"}, {"text": "诚信", "is_correct": false, "explanation": "诚信（chéng xìn）的第二个音节与“心”（xīn）只差声调，意思是讲信用，不是故意。"}, {"text": "乘兴", "is_correct": false, "explanation": "乘兴（chéng xìng）的第二个音节 xìng 与“心” xīn 韵母和声调都不同，意思是趁着兴致。"}, {"text": "成型", "is_correct": false, "explanation": "成型（chéng xíng）的第二个音节 xíng 与“心” xīn 韵母和声调都不同，意思是定型、形成形状。"}, {"text": "成仙", "is_correct": false, "explanation": "成仙（chéng xiān）的第二个音节 xiān 比“心” xīn 多一个元音 a，意思是修成神仙。"}], "explanations": {"成心": "成心（chéng xīn）：故意这样做，不是不小心。", "诚信": "诚信（chéng xìn）的第二个音节与“心”（xīn）只差声调，意思是讲信用，不是故意。", "乘兴": "乘兴（chéng xìng）的第二个音节 xìng 与“心” xīn 韵母和声调都不同，意思是趁着兴致。", "成型": "成型（chéng xíng）的第二个音节 xíng 与“心” xīn 韵母和声调都不同，意思是定型、形成形状。", "成仙": "成仙（chéng xiān）的第二个音节 xiān 比“心” xīn 多一个元音 a，意思是修成神仙。"}, "sentence_index": null, "correct_answer": "成心"}, "level_3": {"options": [{"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急忙行动，与“不接我的电话”这种故意回避的行为相矛盾。"}, {"text": "成心", "is_correct": true, "explanation": "成心：故意，与“不接我的电话”的有意回避语境相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急着去做某事，与“不接”这一有意回避的行为相矛盾。"}, {"text": "顺便", "is_correct": false, "explanation": "搭配：“顺便”要附在另一件主要行为之后，不能单独修饰“不接我的电话”。"}], "explanations": {"连忙": "语义：“连忙”表示急忙行动，与“不接我的电话”这种故意回避的行为相矛盾。", "成心": "成心：故意，与“不接我的电话”的有意回避语境相符。", "赶紧": "语义：“赶紧”表示急着去做某事，与“不接”这一有意回避的行为相矛盾。", "顺便": "搭配：“顺便”要附在另一件主要行为之后，不能单独修饰“不接我的电话”。"}, "sentence_index": 0, "correct_answer": "成心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我成心把花瓶打碎了，这完全是意外。", "explanation": "这里的“成心”表示故意，与“完全是意外”矛盾；不是出于故意的事不能用“成心”。"}, {"text": "他成心脸红了，因为天气太热。", "explanation": "这里的“成心”只能修饰自己能控制的行为，不能修饰脸红这类不由自主的反应。"}, {"text": "我成心没带伞，结果被雨淋湿了，真是不小心。", "explanation": "这里的“成心”表示有意，与“真是不小心”矛盾；不小心造成的结果不能用“成心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97955, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成心", "is_correct": true, "explanation": "成心（chéng xīn）：故意这样做，不是不小心。"}, {"text": "成性", "is_correct": false, "explanation": "成性（chéng xìng）的第二个音节与“心” xīn 韵母和声调都不同，意思是养成习性。"}, {"text": "成行", "is_correct": false, "explanation": "成行（chéng xíng）的第二个音节与“心” xīn 韵母和声调都不同，意思是行程定下来、能够成行。"}, {"text": "成像", "is_correct": false, "explanation": "成像（chéng xiàng）的第二个音节与“心” xīn 韵母和声调都不同，意思是形成影像。"}, {"text": "争心", "is_correct": false, "explanation": "争心（zhēng xīn）的声母 zh 与 ch 不同，声调也不同，意思是好胜之心。"}], "explanations": {"成心": "成心（chéng xīn）：故意这样做，不是不小心。", "成性": "成性（chéng xìng）的第二个音节与“心” xīn 韵母和声调都不同，意思是养成习性。", "成行": "成行（chéng xíng）的第二个音节与“心” xīn 韵母和声调都不同，意思是行程定下来、能够成行。", "成像": "成像（chéng xiàng）的第二个音节与“心” xīn 韵母和声调都不同，意思是形成影像。", "争心": "争心（zhēng xīn）的声母 zh 与 ch 不同，声调也不同，意思是好胜之心。"}, "sentence_index": null, "correct_answer": "成心"}, "level_3": {"options": [{"text": "赶忙", "is_correct": false, "explanation": "语义：“赶忙”表示急忙去做，与“故意说错地址”的意图相矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“说错了”的完成态不能同时成立。"}, {"text": "成心", "is_correct": true, "explanation": "成心：故意，与“说错了地址，让大家白跑一趟”的有意捉弄相符。"}, {"text": "尽量", "is_correct": false, "explanation": "语义：“尽量”表示尽力做到某事，不表示故意说错；“尽量说错了地址”搭配不自然，与“故意”的意思不符。"}], "explanations": {"赶忙": "语义：“赶忙”表示急忙去做，与“故意说错地址”的意图相矛盾。", "正在": "体貌：“正在”表示动作进行中，与“说错了”的完成态不能同时成立。", "成心": "成心：故意，与“说错了地址，让大家白跑一趟”的有意捉弄相符。", "尽量": "语义：“尽量”表示尽力做到某事，不表示故意说错；“尽量说错了地址”搭配不自然，与“故意”的意思不符。"}, "sentence_index": 6, "correct_answer": "成心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈成心忘了锁门，这完全是不小心。", "explanation": "这里的“成心”表示有意，与“完全是不小心”矛盾；不小心的事不能用“成心”。"}, {"text": "我成心心跳加快，因为我一点都不紧张。", "explanation": "这里的“成心”只能修饰自己能控制的行为，不能修饰心跳加快这类不由自主的变化。"}, {"text": "我成心把伞忘在了车上，因为我根本不记得带过伞。", "explanation": "这里的“成心”表示有意，与“根本不记得带过伞”矛盾；不记得的事不能用“成心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹成心了把我的作业撕了。", "corrected_sentence": "妹妹成心把我的作业撕了。", "error_description": "错误：“成心”是副词，后面不能直接加“了”，“成心了把”不成立。正确：“妹妹成心把我的作业撕了”，“成心”直接放在“把”字句前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她成心了不回我的消息。", "corrected_sentence": "她成心不回我的消息。", "error_description": "错误：“成心”是副词，后面不能直接加“了”，“成心了不回”不成立。正确：“她成心不回我的消息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
