INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97956, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "有意；故意。", "primary_collocate": null, "pronunciation": "chéng xīn", "ipa": "ʈʂʰɤŋ˧˥ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "她成心躲着我，一整天没说话。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我不是成心的。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你成心找我麻烦，对不对？", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成心把声音放得很大。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居成心不开门。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个司机成心按喇叭吓我们。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥成心让妹妹多等一会儿。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她成心穿了和我一样的衣服。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成心忘了带书，想早点回家。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师觉得他是成心捣乱的。", "target_word": "成心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词：有意、故意地做，含有不满或捉弄的意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97956, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成心", "is_correct": true, "explanation": "成心（chéng xīn）：有意、故意，含有不满或捉弄的意味。"}, {"text": "诚信", "is_correct": false, "explanation": "诚信（chéng xìn）的第二个音节与“心” xīn 只差声调，意思是讲信用，不是故意。"}, {"text": "乘兴", "is_correct": false, "explanation": "乘兴（chéng xìng）的第二个音节 xìng 与“心” xīn 韵母和声调都不同，意思是趁着兴致。"}, {"text": "成型", "is_correct": false, "explanation": "成型（chéng xíng）的第二个音节 xíng 与“心” xīn 韵母和声调都不同，意思是定型、形成形状。"}, {"text": "成仙", "is_correct": false, "explanation": "成仙（chéng xiān）的第二个音节 xiān 比“心” xīn 多一个元音 a，意思是修成神仙。"}], "explanations": {"成心": "成心（chéng xīn）：有意、故意，含有不满或捉弄的意味。", "诚信": "诚信（chéng xìn）的第二个音节与“心” xīn 只差声调，意思是讲信用，不是故意。", "乘兴": "乘兴（chéng xìng）的第二个音节 xìng 与“心” xīn 韵母和声调都不同，意思是趁着兴致。", "成型": "成型（chéng xíng）的第二个音节 xíng 与“心” xīn 韵母和声调都不同，意思是定型、形成形状。", "成仙": "成仙（chéng xiān）的第二个音节 xiān 比“心” xīn 多一个元音 a，意思是修成神仙。"}, "sentence_index": null, "correct_answer": "成心"}, "level_3": {"options": [{"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急着行动，与“躲着我，一整天没说话”的持续回避不符。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求多个施事，“她一起躲着我”搭配不当。"}, {"text": "成心", "is_correct": true, "explanation": "成心：有意、故意，与“躲着我，一整天没说话”的有意疏远相符。"}, {"text": "务必", "is_correct": false, "explanation": "语域：“务必”是书面语，多用于嘱咐或要求，与口语叙述的事实不合。"}], "explanations": {"赶紧": "语义：“赶紧”表示急着行动，与“躲着我，一整天没说话”的持续回避不符。", "一起": "搭配：“一起”要求多个施事，“她一起躲着我”搭配不当。", "成心": "成心：有意、故意，与“躲着我，一整天没说话”的有意疏远相符。", "务必": "语域：“务必”是书面语，多用于嘱咐或要求，与口语叙述的事实不合。"}, "sentence_index": 0, "correct_answer": "成心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他成心把花瓶打碎了，这完全是个意外。", "explanation": "这里的“成心”表示故意，与“完全是个意外”矛盾；表示无意或不小心应说“无意”，不能用“成心”。"}, {"text": "我成心很难过，却一点也哭不出来。", "explanation": "这里的“成心”只能修饰自己能决定的行为，不能修饰“很难过”这类情绪；这种情绪不能当作故意去做的事。"}, {"text": "我成心不知道他的名字，因为我从来没见过他。", "explanation": "这里的“成心”表示故意装作不知，与“从来没见过他”的原因矛盾；确实不知情时不能用“成心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97956, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成心", "is_correct": true, "explanation": "成心（chéng xīn）：有意、故意，含有不满或捉弄的意味。"}, {"text": "成性", "is_correct": false, "explanation": "成性（chéng xìng）的第二个音节与“心” xīn 韵母和声调都不同，意思是养成习性。"}, {"text": "成行", "is_correct": false, "explanation": "成行（chéng xíng）的第二个音节与“心” xīn 韵母和声调都不同，意思是行程定下来、能够成行。"}, {"text": "成像", "is_correct": false, "explanation": "成像（chéng xiàng）的第二个音节与“心” xīn 韵母和声调都不同，意思是形成影像。"}, {"text": "争心", "is_correct": false, "explanation": "争心（zhēng xīn）的声母 zh 与 ch 不同，声调也不同，意思是好胜之心。"}], "explanations": {"成心": "成心（chéng xīn）：有意、故意，含有不满或捉弄的意味。", "成性": "成性（chéng xìng）的第二个音节与“心” xīn 韵母和声调都不同，意思是养成习性。", "成行": "成行（chéng xíng）的第二个音节与“心” xīn 韵母和声调都不同，意思是行程定下来、能够成行。", "成像": "成像（chéng xiàng）的第二个音节与“心” xīn 韵母和声调都不同，意思是形成影像。", "争心": "争心（zhēng xīn）的声母 zh 与 ch 不同，声调也不同，意思是好胜之心。"}, "sentence_index": null, "correct_answer": "成心"}, "level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“让妹妹多等一会儿”这样的使令行为。"}, {"text": "一齐", "is_correct": false, "explanation": "搭配：“一齐”要求多个施事或动作，“哥哥一齐让妹妹多等”搭配不当。"}, {"text": "千万", "is_correct": false, "explanation": "语法：“千万”用于叮嘱、劝告的祈使句（如“千万别…”），不能用于叙述已发生的事。"}, {"text": "成心", "is_correct": true, "explanation": "成心：有意、故意，表示哥哥有意让妹妹多等，与语境相符。"}], "explanations": {"非常": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“让妹妹多等一会儿”这样的使令行为。", "一齐": "搭配：“一齐”要求多个施事或动作，“哥哥一齐让妹妹多等”搭配不当。", "千万": "语法：“千万”用于叮嘱、劝告的祈使句（如“千万别…”），不能用于叙述已发生的事。", "成心": "成心：有意、故意，表示哥哥有意让妹妹多等，与语境相符。"}, "sentence_index": 6, "correct_answer": "成心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我成心不得不去参加那个会议。", "explanation": "这里的“成心”表示自主的故意，与“不得不”表示的被迫相矛盾，不能这样搭配。"}, {"text": "他成心在路上遇见了我，这完全是碰巧。", "explanation": "这里的“成心”表示故意，与“完全是碰巧”矛盾；偶然遇见不能用“成心”，应说“碰巧”。"}, {"text": "我成心脸红了，因为我一直都很冷静。", "explanation": "这里的“成心”只能用于自己能控制的行为，不能用于脸红这类不由自主的生理反应；这里应去掉“成心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他成心了把书藏起来了，不让我找到。", "corrected_sentence": "他成心把书藏起来了，不让我找到。", "error_description": "错误：“成心”是副词，后面不能直接加“了”，“成心了把”不成立。正确：“他成心把书藏起来了”，“成心”直接放在“把”字句前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她成心了不跟我说话。", "corrected_sentence": "她成心不跟我说话。", "error_description": "错误：“成心”是副词，后面不能直接加“了”，“成心了不跟”不成立。正确：“她成心不跟我说话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
