INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人的上肢，从肩膀到手腕。", "primary_collocate": null, "pronunciation": "shǒu bì", "ipa": "ʂoʊ˨˩ pi˥˩", "syllable_count": 2, "sentences": [{"text": "他的手臂上有一个小伤口。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手臂又细又长。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳的时候，手臂要用力。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起手臂，向我打招呼。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的右手臂有点疼。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷，她把手臂放进袖子里。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在我的手臂上打了一针。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的手臂上有一块红色的印子。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他张开手臂，抱住了我。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步的时候，手臂要前后摆动。", "target_word": "手臂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "双", "label": "量词"}], "register": "中性", "sense_fingerprint": "手臂：人身体的上肢部位，位置在肩膀和手腕之间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手势", "is_correct": false, "explanation": "sh 与 b 声母不同（shǒushì 与 shǒubì），手势指用手做出的动作，意思不同。"}, {"text": "手臂", "is_correct": true, "explanation": "正确：人从肩到手腕的上肢。"}, {"text": "手背", "is_correct": false, "explanation": "bèi 与 bì 韵母不同（ei 与 i），手背指手的背面，不是整条上肢。"}, {"text": "手笔", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，手笔指亲笔写的字迹或作品风格。"}, {"text": "手艺", "is_correct": false, "explanation": "yì 与 bì 只差声母（无声母与 b），手艺指手工技能。"}], "explanations": {"手势": "sh 与 b 声母不同（shǒushì 与 shǒubì），手势指用手做出的动作，意思不同。", "手臂": "正确：人从肩到手腕的上肢。", "手背": "bèi 与 bì 韵母不同（ei 与 i），手背指手的背面，不是整条上肢。", "手笔": "bǐ（第三声）与 bì（第四声）声调不同，手笔指亲笔写的字迹或作品风格。", "手艺": "yì 与 bì 只差声母（无声母与 b），手艺指手工技能。"}, "sentence_index": null, "correct_answer": "手臂"}, "level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：伤口指人或动物身体受的伤，窗户只会有裂缝，句子说不通。"}, {"text": "手臂", "is_correct": true, "explanation": "正确：“手臂”是身体部位，可以有小伤口，与“他的……上”搭配。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子破了说缺口，不说伤口，“伤口”只用于身体。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：伤口指人或动物身体受的伤，钢琴不会有伤口。"}], "explanations": {"窗户": "语义：伤口指人或动物身体受的伤，窗户只会有裂缝，句子说不通。", "手臂": "正确：“手臂”是身体部位，可以有小伤口，与“他的……上”搭配。", "盘子": "语义：盘子破了说缺口，不说伤口，“伤口”只用于身体。", "钢琴": "语义：伤口指人或动物身体受的伤，钢琴不会有伤口。"}, "sentence_index": 0, "correct_answer": "手臂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手臂把球踢进了球门。", "explanation": "这里应该用〈脚〉。踢球要用脚，手臂是人的上肢，不能用来踢。"}, {"text": "这把椅子的手臂很舒服，我常坐在上面看书。", "explanation": "这里应该用〈扶手〉。手臂指人的上肢，椅子两侧供人靠着的部件要说扶手。"}, {"text": "小鸟张开手臂，飞向了天空。", "explanation": "这里应该用〈翅膀〉。手臂是人的上肢，鸟类飞行要说翅膀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97960, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手气", "is_correct": false, "explanation": "q 与 b 声母不同（bì 与 qì），手气指赌博或抽奖时的运气。"}, {"text": "手臂", "is_correct": true, "explanation": "正确：人从肩到手腕的上肢。"}, {"text": "手记", "is_correct": false, "explanation": "j 与 b 声母不同（bì 与 jì），手记指个人记录的笔记。"}, {"text": "首部", "is_correct": false, "explanation": "韵母不同（bì 为 i，bù 为 u），首部指书或作品的第一部分。"}, {"text": "首饰", "is_correct": false, "explanation": "sh 与 b 声母不同（bì 与 shì），首饰指佩戴在身上的装饰品。"}], "explanations": {"手气": "q 与 b 声母不同（bì 与 qì），手气指赌博或抽奖时的运气。", "手臂": "正确：人从肩到手腕的上肢。", "手记": "j 与 b 声母不同（bì 与 jì），手记指个人记录的笔记。", "首部": "韵母不同（bì 为 i，bù 为 u），首部指书或作品的第一部分。", "首饰": "sh 与 b 声母不同（bì 与 shì），首饰指佩戴在身上的装饰品。"}, "sentence_index": null, "correct_answer": "手臂"}, "level_3": {"options": [{"text": "墙", "is_correct": false, "explanation": "语义：“打针”要扎在人体部位上，墙不能被注射。"}, {"text": "手臂", "is_correct": true, "explanation": "正确：手臂是人体部位，医生可以在上面打针。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不是人体，不能打针。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“打针”的对象是身体部位，“脚步”是动作，不能与之搭配。"}], "explanations": {"墙": "语义：“打针”要扎在人体部位上，墙不能被注射。", "手臂": "正确：手臂是人体部位，医生可以在上面打针。", "书包": "语义：书包是物品，不是人体，不能打针。", "脚步": "搭配：“打针”的对象是身体部位，“脚步”是动作，不能与之搭配。"}, "sentence_index": 6, "correct_answer": "手臂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑步的时候，用力蹬手臂。", "explanation": "这里应该用〈腿〉。蹬是用腿发力的动作，手臂不能用来蹬。"}, {"text": "他用手臂闻了闻花的香味。", "explanation": "这里应该用〈鼻子〉。闻气味要用鼻子，手臂不能用来闻。"}, {"text": "小狗用手臂扒着门，想出去。", "explanation": "这里应该用〈爪子〉。小狗扒门用爪子，手臂是人的上肢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一个手臂受伤了。", "corrected_sentence": "我的一条手臂受伤了。", "error_description": "量词错误：手臂作为肢体，量词应用“条”，不说“个”。错误形式为“一个手臂”，正确形式为“一条手臂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的两条的手臂都受伤了。", "corrected_sentence": "我的两条手臂都受伤了。", "error_description": "“的”多余：数量词“两条”直接修饰“手臂”，量词和名词之间不能加“的”。应说“两条手臂”，去掉第二个“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
