INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想办法，等一个可以做的时候。", "primary_collocate": null, "pronunciation": "zhǎo jī huì", "ipa": "ʈ͡ʂɑʊ̯˨˩ t͡ɕi˥ xu̯eɪ˥˩", "syllable_count": 3, "sentences": [{"text": "我想找机会跟老板谈谈。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在找机会告诉妈妈这件事。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李想找机会请大家吃饭。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我得找机会还他那本书。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她找机会把礼物送给了朋友。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你找机会跟他说一声吧。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在找机会向她道歉。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想找机会去看电影。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总找机会和老师说汉语。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打算找机会去看看爷爷。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找个机会", "label": "离合"}, {"form": "找找机会", "label": "重叠"}, {"form": "找機會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "找机会：想办法等到合适的时候去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6cfd6c5-0201-4335-98b8-7045c06a3902') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错过机会", "is_correct": false, "explanation": "语义：“错过”指失去已经到来的机会，与“想跟老板谈谈”的主动意愿矛盾。"}, {"text": "找机会", "is_correct": true, "explanation": "正确：“找机会”指想办法等合适的时候去做某事，与“想跟老板谈谈”相合。"}, {"text": "躲避机会", "is_correct": false, "explanation": "搭配：“躲避”多用于危险、责任，不与“机会”搭配。"}, {"text": "放弃机会", "is_correct": false, "explanation": "语义：“放弃”与“想……谈谈”的意愿相反。"}], "explanations": {"错过机会": "语义：“错过”指失去已经到来的机会，与“想跟老板谈谈”的主动意愿矛盾。", "找机会": "正确：“找机会”指想办法等合适的时候去做某事，与“想跟老板谈谈”相合。", "躲避机会": "搭配：“躲避”多用于危险、责任，不与“机会”搭配。", "放弃机会": "语义：“放弃”与“想……谈谈”的意愿相反。"}, "sentence_index": 0, "correct_answer": "找机会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心找机会把杯子打碎了。", "explanation": "“不小心”表示无意，“找机会”是有意寻找时机，二者矛盾。"}, {"text": "他偶然找机会，遇到了老同学。", "explanation": "这里应该用〈碰上〉。“偶然”指没有刻意去做，“找机会”是有意寻找，二者矛盾。"}, {"text": "他找机会打了个喷嚏。", "explanation": "“找机会”指有意寻找合适的时机去做事，“打喷嚏”是身体不由自己控制的反应，不能去找。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪费机会", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与“向她道歉”的主动意图不合。"}, {"text": "找机会", "is_correct": true, "explanation": "正确：“找机会”与“向她道歉”的主动意图相合。"}, {"text": "拒绝机会", "is_correct": false, "explanation": "语义：“拒绝”与“找机会向她道歉”的意图相反。"}, {"text": "回避机会", "is_correct": false, "explanation": "搭配：“回避”多与问题、责任搭配，不说“回避机会”。"}], "explanations": {"浪费机会": "语义：“浪费”指白白耗费，与“向她道歉”的主动意图不合。", "找机会": "正确：“找机会”与“向她道歉”的主动意图相合。", "拒绝机会": "语义：“拒绝”与“找机会向她道歉”的意图相反。", "回避机会": "搭配：“回避”多与问题、责任搭配，不说“回避机会”。"}, "sentence_index": 6, "correct_answer": "找机会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的找机会很精彩。", "explanation": "这里应该用〈内容〉。“找机会”是动词性短语，不能当名词用。"}, {"text": "我在包里找机会。", "explanation": "这里应该用〈找东西〉。“找机会”不能指寻找具体的物品。"}, {"text": "昨天晚上他找机会发烧了。", "explanation": "“发烧”不由人控制，不能有意“找机会”去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们想找机会了和他谈一谈。", "corrected_sentence": "我们想找机会和他谈一谈。", "error_description": "“了”不能加在“找机会”后表示意愿的句子里：“想”已表达意愿，“找机会”后不应加“了”，应说“我们想找机会和他谈一谈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于找机会，还清了欠款。", "corrected_sentence": "他终于找到机会，还清了欠款。", "error_description": "结果补语缺失：“终于”表示达成结果，应说“找到机会”，只说“找机会”表示还在寻找，不能说明已经达成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
