INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于产品或工作的技术规定。", "primary_collocate": null, "pronunciation": "jì shù biāo zhǔn", "ipa": "tɕi⁵¹ ʂu⁵¹ piɑʊ⁵⁵ ʈʂuən²¹⁴", "syllable_count": 4, "sentences": [{"text": "这款手机的电池要符合国家技术标准。", "target_word": "技术标准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批产品没有达到技术标准，不能出售。", "target_word": "技术标准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在检查零件是否符合技术标准。", "target_word": "技术标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的安全技术标准比以前更高了。", "target_word": "技术标准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂的新产品达到了技术标准。", "target_word": "技术标准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "设计新电梯时，必须先了解技术标准。", "target_word": "技术标准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理要求我们按技术标准完成每个零件。", "target_word": "技术标准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件里写着产品必须达到的技术标准。", "target_word": "技术标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买进口设备前，要先看它是否符合国家技术标准。", "target_word": "技术标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按照新的技术标准重新做了这批零件。", "target_word": "技术标准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "行业技术标准", "label": "复合"}], "register": "书面", "sense_fingerprint": "技术标准：对产品或工作的技术要求规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aa28573-c80f-4808-aa31-1a2121744695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术标准", "is_correct": true, "explanation": "技术标准：对产品或工作的技术要求规定。“电池要符合国家技术标准”符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，电池不能“符合国家颜色”，语义不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能与“符合国家”搭配，电池没有年龄。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，电池应符合的是技术要求，不是体重。"}], "explanations": {"技术标准": "技术标准：对产品或工作的技术要求规定。“电池要符合国家技术标准”符合语境。", "颜色": "语义：“颜色”指色彩，电池不能“符合国家颜色”，语义不通。", "年龄": "搭配：“年龄”不能与“符合国家”搭配，电池没有年龄。", "体重": "语义：“体重”指人或物的重量，电池应符合的是技术要求，不是体重。"}, "sentence_index": 0, "correct_answer": "技术标准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车的技术标准是红色的。", "explanation": "这里应该用〈颜色〉。技术标准指产品或工作的技术规定，不指外观，“红色的”描述的是颜色。"}, {"text": "这位老师的技术标准很和蔼。", "explanation": "这里应该用〈态度〉。技术标准指产品或工作的技术规定，不指人的性格，“很和蔼”描述的是人的态度。"}, {"text": "他的技术标准很强，能修好汽车。", "explanation": "这里应该用〈能力〉。技术标准指产品或工作的技术规定，不指人的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术标准", "is_correct": true, "explanation": "技术标准：对产品或工作的技术要求规定。“经理要求我们按技术标准完成每个零件”符合语境。"}, {"text": "籍贯", "is_correct": false, "explanation": "语义：“籍贯”指人的祖籍，与完成零件的依据无关。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“性别”不能作为完成零件的依据，二者搭配不当。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，属于体貌特征，不能用来作完成零件的依据。"}], "explanations": {"技术标准": "技术标准：对产品或工作的技术要求规定。“经理要求我们按技术标准完成每个零件”符合语境。", "籍贯": "语义：“籍贯”指人的祖籍，与完成零件的依据无关。", "性别": "搭配：“性别”不能作为完成零件的依据，二者搭配不当。", "身高": "体貌：“身高”指人的身体高矮，属于体貌特征，不能用来作完成零件的依据。"}, "sentence_index": 6, "correct_answer": "技术标准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批零件的技术标准很重。", "explanation": "这里应该用〈重量〉。技术标准指产品或工作的技术规定，不指物体的轻重，“很重”描述的是重量。"}, {"text": "这批零件的技术标准都下班了。", "explanation": "这里应该用〈工人〉。技术标准是规定，不能下班，“下班”的主语应是〈工人〉。"}, {"text": "我把技术标准放进锅里煮了。", "explanation": "这里应该用〈零件〉以外的实物，如〈面条〉。技术标准是规定，不是能煮的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂的产品都要符合新的技术标准们。", "corrected_sentence": "这家工厂的产品都要符合新的技术标准。", "error_description": "错误：“技术标准们”。“们”不能加在“技术标准”后，正确形式为“新的技术标准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司今年新定了一只技术标准。", "corrected_sentence": "公司今年新定了一项技术标准。", "error_description": "量词错误：“技术标准”是规定，量词应用“项”，不能用“只”。错误形式是“一只技术标准”，正确形式是“一项技术标准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
