INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用扫帚，把脏东西弄走。", "primary_collocate": null, "pronunciation": "sǎo", "ipa": "saʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我每天早上扫地。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用笤帚扫房间。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在院子里扫落叶。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把地上的纸扫干净。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正扫着门口的雪。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在教室里扫地。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，他扫了一上午的树叶。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌子下面的土扫出去了。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我和朋友一起扫楼梯。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老奶奶每天都扫街。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扫了", "label": "完成体"}, {"form": "扫过", "label": "经历体"}, {"form": "扫扫", "label": "重叠"}, {"form": "扫地", "label": "复合"}], "register": "口语", "sense_fingerprint": "用笤帚把地面、院子里的脏东西清走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚把脏东西弄走。"}, {"text": "早", "is_correct": false, "explanation": "z 与 s 声母不同（zǎo 与 sǎo），早指早晨或时间靠前。"}, {"text": "少", "is_correct": false, "explanation": "sh 与 s 声母不同（shǎo 与 sǎo），少指数量不多。"}, {"text": "草", "is_correct": false, "explanation": "c 与 s 声母不同（cǎo 与 sǎo），草指草地或草本植物。"}], "explanations": {"扫": "扫：用扫帚把脏东西弄走。", "早": "z 与 s 声母不同（zǎo 与 sǎo），早指早晨或时间靠前。", "少": "sh 与 s 声母不同（shǎo 与 sǎo），少指数量不多。", "草": "c 与 s 声母不同（cǎo 与 sǎo），草指草地或草本植物。"}, "sentence_index": null, "correct_answer": "扫"}, "level_3": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚把脏东西弄走，此处指清扫地面。"}, {"text": "占", "is_correct": false, "explanation": "语义：“占地”指占用土地面积，与每天早上清扫的动作不符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写地”不成词，“写”不能用于“地”，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃地”不成词，句意不通。"}], "explanations": {"扫": "扫：用扫帚把脏东西弄走，此处指清扫地面。", "占": "语义：“占地”指占用土地面积，与每天早上清扫的动作不符。", "写": "搭配：“写地”不成词，“写”不能用于“地”，句意不通。", "吃": "语义：“吃地”不成词，句意不通。"}, "sentence_index": 0, "correct_answer": "扫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你把窗户扫干净。", "explanation": "这里应该用〈擦〉。扫用于清除地面或院子里的碎屑，窗户要用抹布擦。"}, {"text": "请你把碗扫干净。", "explanation": "这里应该用〈洗〉。扫用于清除地面的脏东西，碗要用水洗。"}, {"text": "他用布扫了一下镜子。", "explanation": "这里应该用〈擦〉。扫用于清除地面或院子里的碎屑，擦镜子要用布擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97973, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚把脏东西弄走。"}, {"text": "嗓", "is_correct": false, "explanation": "ng 与 o 韵母不同（sǎng 与 sǎo），嗓指嗓子。"}, {"text": "找", "is_correct": false, "explanation": "zh 与 s 只差声母（zhǎo 与 sǎo），找指寻找。"}, {"text": "炒", "is_correct": false, "explanation": "ch 与 s 只差声母（chǎo 与 sǎo），炒指用油加热翻动食物。"}], "explanations": {"扫": "扫：用扫帚把脏东西弄走。", "嗓": "ng 与 o 韵母不同（sǎng 与 sǎo），嗓指嗓子。", "找": "zh 与 s 只差声母（zhǎo 与 sǎo），找指寻找。", "炒": "ch 与 s 只差声母（chǎo 与 sǎo），炒指用油加热翻动食物。"}, "sentence_index": null, "correct_answer": "扫"}, "level_3": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚把脏东西弄走，此处指清扫树叶。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指咽下，人不会吞了一上午的树叶，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”与树叶无关，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“树叶”搭配，唱树叶说不通。"}], "explanations": {"扫": "扫：用扫帚把脏东西弄走，此处指清扫树叶。", "吞": "语义：“吞”指咽下，人不会吞了一上午的树叶，句意不通。", "写": "语义：“写”与树叶无关，句意不通。", "唱": "搭配：“唱”不与“树叶”搭配，唱树叶说不通。"}, "sentence_index": 6, "correct_answer": "扫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "用水把车扫干净。", "explanation": "这里应该用〈冲〉。扫用扫帚清除干燥的脏东西，洗车要用水冲。"}, {"text": "他用香皂把手扫干净。", "explanation": "这里应该用〈洗〉。扫是用扫帚清除干燥的碎屑，手上的污垢要用水和香皂洗。"}, {"text": "我们一起扫院子里的草莓。", "explanation": "这里应该用〈摘〉。草莓要用手摘，扫只用于清除地面上的碎屑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你把屋里的灰尘扫了干净。", "corrected_sentence": "请你把屋里的灰尘扫干净。", "error_description": "“了”位置错误：了不能插在动词“扫”和结果补语“干净”之间，应说“扫干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我曾经扫了过这条街。", "corrected_sentence": "我曾经扫过这条街。", "error_description": "动态助词错误：表示经历的“过”应直接接在动词后，“扫了过”同时用了“了”和“过”，应说“扫过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
