INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用扫帚等除去灰尘垃圾。", "primary_collocate": null, "pronunciation": "sǎo", "ipa": "saʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "书架上有灰，你去扫一下。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把垃圾扫到一起。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把桌子上的灰尘扫掉。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王拿着笤帚扫灰。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有碎玻璃，要小心地扫。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先扫垃圾，再擦窗户。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把身上的土扫掉了。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快把床下的灰尘扫出来。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的面粉扫起来很麻烦。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起把院子里的垃圾扫走。", "target_word": "扫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扫了", "label": "完成体"}, {"form": "扫过", "label": "经历体"}, {"form": "扫扫", "label": "重叠"}, {"form": "扫地", "label": "复合"}], "register": "口语", "sense_fingerprint": "用笤帚等除去灰尘、垃圾、碎屑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc7e2ec-6067-45e3-9ff8-7b8a768ea992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚等除去灰尘、垃圾。"}, {"text": "早", "is_correct": false, "explanation": "z 与 s 声母不同（zǎo 与 sǎo），早指早晨或时间靠前。"}, {"text": "草", "is_correct": false, "explanation": "c 与 s 声母不同（cǎo 与 sǎo），草指草地或草本植物。"}, {"text": "少", "is_correct": false, "explanation": "sh 与 s 声母不同（shǎo 与 sǎo），少指数量不多。"}], "explanations": {"扫": "扫：用扫帚等除去灰尘、垃圾。", "早": "z 与 s 声母不同（zǎo 与 sǎo），早指早晨或时间靠前。", "草": "c 与 s 声母不同（cǎo 与 sǎo），草指草地或草本植物。", "少": "sh 与 s 声母不同（shǎo 与 sǎo），少指数量不多。"}, "sentence_index": null, "correct_answer": "扫"}, "level_3": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚等除去灰尘、垃圾，此处指清扫书架上的灰。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，书架上有灰不用修理，句中要的是清除灰尘。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与清除灰尘无关，句中是要人去清理。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”不能用于清除灰尘，搭配不成立。"}], "explanations": {"扫": "扫：用扫帚等除去灰尘、垃圾，此处指清扫书架上的灰。", "修": "语义：“修”指修理，书架上有灰不用修理，句中要的是清除灰尘。", "唱": "语义：“唱”与清除灰尘无关，句中是要人去清理。", "写": "搭配：“写”不能用于清除灰尘，搭配不成立。"}, "sentence_index": 0, "correct_answer": "扫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小王拿着抹布扫灰。", "explanation": "这里应该用〈擦〉。扫要用笤帚清除地面碎屑，抹布要擦灰尘。"}, {"text": "小王用笤帚扫牙齿。", "explanation": "这里应该用〈刷〉。扫是用笤帚除去灰尘垃圾，牙齿要用牙刷刷。"}, {"text": "小王用笤帚扫碗。", "explanation": "这里应该用〈洗〉。扫用笤帚清除碎屑，碗要用水洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97974, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚等除去灰尘、垃圾。"}, {"text": "嗓", "is_correct": false, "explanation": "ng 与 o 韵母不同（sǎng 与 sǎo），嗓指嗓子。"}, {"text": "找", "is_correct": false, "explanation": "zh 与 s 只差声母（zhǎo 与 sǎo），找指寻找。"}, {"text": "炒", "is_correct": false, "explanation": "ch 与 s 只差声母（chǎo 与 sǎo），炒指用油加热翻动食物。"}], "explanations": {"扫": "扫：用扫帚等除去灰尘、垃圾。", "嗓": "ng 与 o 韵母不同（sǎng 与 sǎo），嗓指嗓子。", "找": "zh 与 s 只差声母（zhǎo 与 sǎo），找指寻找。", "炒": "ch 与 s 只差声母（chǎo 与 sǎo），炒指用油加热翻动食物。"}, "sentence_index": null, "correct_answer": "扫"}, "level_3": {"options": [{"text": "扫", "is_correct": true, "explanation": "扫：用扫帚等除去灰尘、垃圾，此处指扫掉身上的土。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”是饮用，不能用于清除身上的土，句意不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是用水加热烹饪，不能用于清除身上的土，句意不通。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”是栽种植物，不能用于清除身上的土，句意不通。"}], "explanations": {"扫": "扫：用扫帚等除去灰尘、垃圾，此处指扫掉身上的土。", "喝": "语义：“喝”是饮用，不能用于清除身上的土，句意不通。", "煮": "语义：“煮”是用水加热烹饪，不能用于清除身上的土，句意不通。", "种": "语义：“种”是栽种植物，不能用于清除身上的土，句意不通。"}, "sentence_index": 6, "correct_answer": "扫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把垃圾扫在土里。", "explanation": "这里应该用〈埋〉。扫是清除地面上的东西，不能表示把垃圾埋进土里。"}, {"text": "我们一起扫树上的苹果。", "explanation": "这里应该用〈摘〉。苹果要用手摘，扫只用于清除地面上的碎屑。"}, {"text": "我们用毛巾扫了一下脸上的汗。", "explanation": "这里应该用〈抹〉。扫是用扫帚清除碎屑，擦汗要用毛巾抹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e354b37a-21c8-4695-a5c2-d3c4e6a153c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
