INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97987, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有责任是说这件事该由你来管，出了错你要负责。", "primary_collocate": null, "pronunciation": "yǒu zé rèn", "ipa": "joʊ˨˩˦ tsɤ˧˥ ɻən˥˩", "syllable_count": 3, "sentences": [{"text": "你是组长，对这件事有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为爸爸，他对家人有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间归你管，你有责任打扫。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是班长，你有责任叫大家准时来。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对每个学生都有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁借的书，谁有责任还。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对病人有责任，要认真看病。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理有责任把工作分给大家。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都有责任保护这个公园。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是这里的管理员，该做的事你有责任做好。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某件事该由你来管、要负责", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有责任", "is_correct": true, "explanation": "“有责任”表示这件事该由你来管、要负责，与“你是组长，对这件事……”相合。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”说事情好玩，与组长对这件事的职责无关。"}, {"text": "有钱", "is_correct": false, "explanation": "搭配：“有钱”说财力，不能与“对这件事”搭配。"}, {"text": "有病", "is_correct": false, "explanation": "语义：“有病”说身体不适，与组长负责这件事的意思无关。"}], "explanations": {"有责任": "“有责任”表示这件事该由你来管、要负责，与“你是组长，对这件事……”相合。", "有趣": "语义：“有趣”说事情好玩，与组长对这件事的职责无关。", "有钱": "搭配：“有钱”说财力，不能与“对这件事”搭配。", "有病": "语义：“有病”说身体不适，与组长负责这件事的意思无关。"}, "sentence_index": 0, "correct_answer": "有责任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间是我的，我有责任住进去。", "explanation": "这里应该用〈有权〉。“有责任”指该承担的后果，住进自己的房间是权利，不是责任，应说〈有权〉。"}, {"text": "今天天气很好，我有责任出去玩。", "explanation": "这里应该用〈想〉。出去玩是个人愿望，不是该负责的事，应说〈想〉。"}, {"text": "这个蛋糕很甜，我有责任喜欢它。", "explanation": "这里应该用〈喜欢〉。“有责任”说的是该承担的义务，对蛋糕的喜爱是个人喜好，应说〈喜欢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有责任", "is_correct": true, "explanation": "“有责任”表示医生对病人负有应尽的职责，与“要认真看病”相合。"}, {"text": "有名", "is_correct": false, "explanation": "语义：“有名”说人或事物出名，与“要认真看病”所说的职责无关。"}, {"text": "有成就", "is_correct": false, "explanation": "语义：“有成就”说取得的成绩，句中没有这样的语境，也不表示对病人的义务。"}, {"text": "有效", "is_correct": false, "explanation": "搭配：“有效”修饰药物或方法，不说“医生对病人有效”来指医生的职责。"}], "explanations": {"有责任": "“有责任”表示医生对病人负有应尽的职责，与“要认真看病”相合。", "有名": "语义：“有名”说人或事物出名，与“要认真看病”所说的职责无关。", "有成就": "语义：“有成就”说取得的成绩，句中没有这样的语境，也不表示对病人的义务。", "有效": "搭配：“有效”修饰药物或方法，不说“医生对病人有效”来指医生的职责。"}, "sentence_index": 6, "correct_answer": "有责任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书很有责任，我看了三遍。", "explanation": "这里应该用〈有意思〉。“有责任”的主语应是能负责的人，评价书好看要说〈有意思〉。"}, {"text": "他长得很有责任。", "explanation": "这里应该用〈高〉。“有责任”描述的是承担后果，不能用来形容外貌，身高要说〈高〉。"}, {"text": "我很有责任去旅行。", "explanation": "这里应该用〈想〉。去旅行是个人意愿，不是应承担的责任，“有责任”不能表示想做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作为队长，她对这次比赛不有责任。", "corrected_sentence": "作为队长，她对这次比赛有责任。", "error_description": "否定错误：“有责任”前不能加“不”，否定“有”要用“没有”。这句是肯定句，应去掉“不”，说“有责任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是这个部门的领导，对安全被有责任。", "corrected_sentence": "他是这个部门的领导，对安全有责任。", "error_description": "结构错误：“被”字句需要动作性动词，“有责任”表示状态，不能用于被动结构。这里应去掉“被”，说“对安全有责任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97988, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97988, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97988, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对某事负有应尽的义务，出了问题须承担后果。", "primary_collocate": null, "pronunciation": "yǒu zé rèn", "ipa": "joʊ˨˩˦ tsɤ˧˥ ɻən˥˩", "syllable_count": 3, "sentences": [{"text": "这件事出了问题，我也有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机喝了酒，他对这次事故有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有检查，所以公司有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在学校受了伤，学校有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁对这个错误有责任，一定要说清楚。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是老板，但对这次的损失也有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有坑，修路的公司有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人都有错，所以两个人都有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这次考试不好，我们都有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西丢了，保管的人有责任。", "target_word": "有责任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对出了问题的事应承担后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有责任", "is_correct": true, "explanation": "“有责任”表示对出了问题的事应承担后果，与“这件事出了问题，我也……”相合。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”说事情好玩，与“出了问题”的语境矛盾。"}, {"text": "有名", "is_correct": false, "explanation": "搭配：“有名”说人或作品出名，不能用来指“我”对这件事应承担的后果。"}, {"text": "有成就", "is_correct": false, "explanation": "语义：“有成就”指取得了成绩，与“出了问题”的语境正好相反。"}], "explanations": {"有责任": "“有责任”表示对出了问题的事应承担后果，与“这件事出了问题，我也……”相合。", "有趣": "语义：“有趣”说事情好玩，与“出了问题”的语境矛盾。", "有名": "搭配：“有名”说人或作品出名，不能用来指“我”对这件事应承担的后果。", "有成就": "语义：“有成就”指取得了成绩，与“出了问题”的语境正好相反。"}, "sentence_index": 0, "correct_answer": "有责任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份文件有责任，我们需要重新检查。", "explanation": "这里应该用〈有问题〉。“有责任”的主语应是能承担后果的人，说文件或材料出了毛病要用〈有问题〉。"}, {"text": "他说的话很有责任，大家都愿意听。", "explanation": "这里应该用〈有道理〉。“有责任”说的是对后果的承担，不能用来评价话的内容，说话有道理要用〈有道理〉。"}, {"text": "我有责任见到了那位大明星。", "explanation": "这里应该用〈有幸〉。“有责任”表示该承担的后果，能见到名人是运气，应说〈有幸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有责任", "is_correct": true, "explanation": "“有责任”表示修路公司应对路上的坑承担后果，与句意相合。"}, {"text": "有利", "is_correct": false, "explanation": "语义：“有利”说对某方有好处，与“路上有坑”的危害相反。"}, {"text": "有效", "is_correct": false, "explanation": "搭配：“有效”修饰方法、措施，不说“修路的公司有效”。"}, {"text": "有成绩", "is_correct": false, "explanation": "语义：“有成绩”说业绩好，与“路上有坑”的过失相矛盾。"}], "explanations": {"有责任": "“有责任”表示修路公司应对路上的坑承担后果，与句意相合。", "有利": "语义：“有利”说对某方有好处，与“路上有坑”的危害相反。", "有效": "搭配：“有效”修饰方法、措施，不说“修路的公司有效”。", "有成绩": "语义：“有成绩”说业绩好，与“路上有坑”的过失相矛盾。"}, "sentence_index": 6, "correct_answer": "有责任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头很有责任，一直不动。", "explanation": "这里应该用〈重〉。“有责任”的主语必须是能承担后果的人，石头不能承担责任，描述重量要说〈重〉。"}, {"text": "他得了第一名，很有责任。", "explanation": "这里应该用〈高兴〉。“有责任”表示应承担的后果，得了第一名后的心情要说〈高兴〉。"}, {"text": "这个三岁的孩子对糖很有责任。", "explanation": "这里应该用〈喜欢〉。糖不是责任的对象，孩子对糖的喜好要说〈喜欢〉，“有责任”只用于能承担后果的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出了这样的事，我也不有责任。", "corrected_sentence": "出了这样的事，我也有责任。", "error_description": "否定错误：“有责任”的否定要用“没有责任”，不能在“有责任”前加“不”说成“不有责任”。这里是肯定句，应说“我也有责任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次事故，他也向此有责任。", "corrected_sentence": "这次事故，他也对此有责任。", "error_description": "介词错误：“有责任”引出的对象要用介词“对”，说“对此有责任”；“向”表示动作的方向，不能与“有责任”搭配，应改为“对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
