INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97989, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "槽是一个长长的、中间凹下去的东西，可以用来装水或装吃的。", "primary_collocate": null, "pronunciation": "cáo", "ipa": "tsʰɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "牛低着头在槽里吃草。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把水倒进槽里，让羊喝水。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "槽里的饲料没有了。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猪都围着槽抢吃的。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在院子里放了一个长槽给鸡喝水。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个槽很长，十头羊可以一起吃。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把剩饭倒进槽里喂狗。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "槽里有水，小鸟飞来喝了几口。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马吃完了槽里的草。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，他都先给牛的槽里加草。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个槽", "label": "量词"}, {"form": "食槽", "label": "复合"}, {"form": "马槽", "label": "复合"}], "register": "中性", "sense_fingerprint": "给牲畜装水或饲料的长条容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97989, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：正确答案，指盛放牲畜饲料或饮水的长条容器，读 cáo（第二声）。"}, {"text": "草", "is_correct": false, "explanation": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。"}, {"text": "吵", "is_correct": false, "explanation": "chǎo 与 cáo 声母不同（ch 与 c），声调也不同，意思是吵闹。"}, {"text": "早", "is_correct": false, "explanation": "zǎo 与 cáo 声母不同（z 与 c），声调也不同，意思是早上。"}, {"text": "藏", "is_correct": false, "explanation": "cáng 与 cáo 韵母不同（ang 与 ao），意思是隐藏。"}], "explanations": {"槽": "槽：正确答案，指盛放牲畜饲料或饮水的长条容器，读 cáo（第二声）。", "草": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。", "吵": "chǎo 与 cáo 声母不同（ch 与 c），声调也不同，意思是吵闹。", "早": "zǎo 与 cáo 声母不同（z 与 c），声调也不同，意思是早上。", "藏": "cáng 与 cáo 韵母不同（ang 与 ao），意思是隐藏。"}, "sentence_index": null, "correct_answer": "槽"}, "level_3": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：牛吃草的地方是盛草的长条容器，只有它合适。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是人用来盛饭的器具，牛不会低头在碗里吃草，句意不合。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子装东西的空间太小，牛不能在盒子里吃草。"}, {"text": "篮子", "is_correct": false, "explanation": "语义：篮子是用来提着装东西的，牛不能低头在篮子里吃草，句意不通。"}], "explanations": {"槽": "槽：牛吃草的地方是盛草的长条容器，只有它合适。", "碗": "语义：碗是人用来盛饭的器具，牛不会低头在碗里吃草，句意不合。", "盒子": "语义：盒子装东西的空间太小，牛不能在盒子里吃草。", "篮子": "语义：篮子是用来提着装东西的，牛不能低头在篮子里吃草，句意不通。"}, "sentence_index": 0, "correct_answer": "槽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用槽把水烧开了，然后泡了茶。", "explanation": "用法不当。槽是盛放饲料或饮水的容器，不能当锅用来烧水泡茶。"}, {"text": "他提着一个槽，去井边打水。", "explanation": "这里应该用〈水桶〉。水桶可以提着走，槽是固定放在地上盛放饲料或饮水的长条容器，不能提着去打水。"}, {"text": "他心里有一道槽，装满了悲伤。", "explanation": "这里应该用〈伤痕〉。伤痕可以比喻心里的创伤，槽指具体的长条容器，不能用来比喻人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97989, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：正确答案，指盛放牲畜饲料或饮水的长条容器，读 cáo（第二声）。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 cáo（第二声）声调不同，意思是操作、体操。"}, {"text": "潮", "is_correct": false, "explanation": "cháo 与 cáo 声母不同（ch 与 c），意思是潮水。"}, {"text": "草", "is_correct": false, "explanation": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 cáo 韵母不同（ai 与 ao），意思是才能、刚刚。"}], "explanations": {"槽": "槽：正确答案，指盛放牲畜饲料或饮水的长条容器，读 cáo（第二声）。", "操": "cāo（第一声）与 cáo（第二声）声调不同，意思是操作、体操。", "潮": "cháo 与 cáo 声母不同（ch 与 c），意思是潮水。", "草": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。", "才": "cái 与 cáo 韵母不同（ai 与 ao），意思是才能、刚刚。"}, "sentence_index": null, "correct_answer": "槽"}, "level_3": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：「倒进……里喂狗」的器具是盛食物的长条容器，只有它合适。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶用来插花，不用来盛剩饭喂狗，句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的，把剩饭倒进书包喂狗不合常理。"}, {"text": "抽屉", "is_correct": false, "explanation": "搭配：「倒进……里喂狗」一般不接抽屉，抽屉不用来盛食物喂狗。"}], "explanations": {"槽": "槽：「倒进……里喂狗」的器具是盛食物的长条容器，只有它合适。", "花瓶": "语义：花瓶用来插花，不用来盛剩饭喂狗，句意不通。", "书包": "语义：书包是装书的，把剩饭倒进书包喂狗不合常理。", "抽屉": "搭配：「倒进……里喂狗」一般不接抽屉，抽屉不用来盛食物喂狗。"}, "sentence_index": 6, "correct_answer": "槽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躺在槽上睡着了。", "explanation": "这里应该用〈床〉。床是供人躺卧的家具，食槽是盛放饲料或饮水的容器，不能拿来躺。"}, {"text": "他打开槽，让风吹进来。", "explanation": "这里应该用〈窗户〉。窗户可以打开通风，槽是盛放饲料或饮水的长条容器，没有开合的功能。"}, {"text": "天很冷，他把槽戴在头上出门了。", "explanation": "这里应该用〈帽子〉。帽子是戴在头上保暖的，槽是盛放饲料或饮水的长条容器，不能戴在头上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "牛在一朵槽里吃草，很安静。", "corrected_sentence": "牛在一个槽里吃草，很安静。", "error_description": "错误在量词「朵」。「朵」用于花，盛草料的食槽应用「个」（一个槽）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民把饲料倒进一本槽里。", "corrected_sentence": "农民把饲料倒进一个槽里。", "error_description": "错误在量词「本」。「本」用于书本，盛饲料的槽应用「个」（一个槽）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
