INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体上长条形、中间凹下去的部分，可以放东西或让别的东西沿着它滑动。", "primary_collocate": null, "pronunciation": "cáo", "ipa": "tsʰɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "桌子下面有两条槽，抽屉沿着槽滑动。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗框上的槽里全是灰。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在铁板上刻了一道槽。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "螺丝头上有一道槽，螺丝刀要对准它。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门底下有一条槽，门可以左右推开。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条槽太浅，放不住玻璃。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刀在木头上挖了一个长长的槽。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小车沿着槽慢慢往前滑。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把电线放在墙上的槽里。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头上的槽里，积了很多雨水。", "target_word": "槽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道槽", "label": "量词"}, {"form": "一条槽", "label": "量词"}, {"form": "凹槽", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体上用来放东西或让别的东西滑动的长条凹处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：正确答案，指长条形的凹槽，读 cáo（第二声）。"}, {"text": "草", "is_correct": false, "explanation": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 cáo（第二声）声调不同，意思是操作、体操。"}, {"text": "潮", "is_correct": false, "explanation": "cháo 与 cáo 声母不同（ch 与 c），意思是潮水。"}, {"text": "藏", "is_correct": false, "explanation": "cáng 与 cáo 韵母不同（ang 与 ao），意思是隐藏。"}], "explanations": {"槽": "槽：正确答案，指长条形的凹槽，读 cáo（第二声）。", "草": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。", "操": "cāo（第一声）与 cáo（第二声）声调不同，意思是操作、体操。", "潮": "cháo 与 cáo 声母不同（ch 与 c），意思是潮水。", "藏": "cáng 与 cáo 韵母不同（ang 与 ao），意思是隐藏。"}, "sentence_index": null, "correct_answer": "槽"}, "level_3": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：空格处指抽屉滑动所沿的导向凹槽，只有它合适。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能作为抽屉滑动的导向，「沿着树滑动」句意不通。"}, {"text": "河", "is_correct": false, "explanation": "搭配：「沿着……滑动」一般不接河流，抽屉不会沿河滑行。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可供抽屉滑动的凹槽，句意不通。"}], "explanations": {"槽": "槽：空格处指抽屉滑动所沿的导向凹槽，只有它合适。", "树": "语义：树不能作为抽屉滑动的导向，「沿着树滑动」句意不通。", "河": "搭配：「沿着……滑动」一般不接河流，抽屉不会沿河滑行。", "石头": "语义：石头不是可供抽屉滑动的凹槽，句意不通。"}, "sentence_index": 0, "correct_answer": "槽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把一个槽放进锅里煮汤。", "explanation": "这里应该用〈藕〉。藕是可以下锅煮的食材，槽是长条形的凹陷，不能放进锅里煮。"}, {"text": "他拿起一个槽，梳了梳头。", "explanation": "这里应该用〈梳子〉。梳子是用来梳头的工具，槽是长条形的凹陷或器具，不能拿来梳头。"}, {"text": "他额头上有一道槽，看起来很累。", "explanation": "这里应该用〈皱纹〉。皱纹是皮肤上的细纹，人脸上的纹路不叫槽，槽指长条形的凹陷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：正确答案，指长条形的凹槽，读 cáo（第二声）。"}, {"text": "草", "is_correct": false, "explanation": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 cáo（第二声）声调不同，意思是操作、体操。"}, {"text": "劳", "is_correct": false, "explanation": "láo 与 cáo 声母不同（l 与 c），意思是劳动。"}, {"text": "逃", "is_correct": false, "explanation": "táo 与 cáo 声母不同（t 与 c），意思是逃跑。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 cáo 韵母不同（ai 与 ao），意思是才能、刚刚。"}], "explanations": {"槽": "槽：正确答案，指长条形的凹槽，读 cáo（第二声）。", "草": "cǎo（第三声）与 cáo（第二声）声调不同，意思是草。", "操": "cāo（第一声）与 cáo（第二声）声调不同，意思是操作、体操。", "劳": "láo 与 cáo 声母不同（l 与 c），意思是劳动。", "逃": "táo 与 cáo 声母不同（t 与 c），意思是逃跑。", "才": "cái 与 cáo 韵母不同（ai 与 ao），意思是才能、刚刚。"}, "sentence_index": null, "correct_answer": "槽"}, "level_3": {"options": [{"text": "槽", "is_correct": true, "explanation": "槽：「挖了一个长长的」之后应是凹槽，只有它合适。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌不能被挖，「挖一个长长的歌」句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是成品家具，不能用刀挖成「长长的」东西，句意不通。"}, {"text": "信", "is_correct": false, "explanation": "搭配：「挖」一般不与「信」搭配，信不能挖出长条形状。"}], "explanations": {"槽": "槽：「挖了一个长长的」之后应是凹槽，只有它合适。", "歌": "语义：歌不能被挖，「挖一个长长的歌」句意不通。", "桌子": "语义：桌子是成品家具，不能用刀挖成「长长的」东西，句意不通。", "信": "搭配：「挖」一般不与「信」搭配，信不能挖出长条形状。"}, "sentence_index": 6, "correct_answer": "槽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把槽拉开，取出了一把钥匙。", "explanation": "这里应该用〈抽屉〉。抽屉是可以拉开取物的盒子，槽是抽屉滑动时沿着的长条形凹陷，不能拉开。"}, {"text": "他在槽上铺好纸，开始写字。", "explanation": "这里应该用〈桌子〉。桌子是平整的台面，可以铺纸写字，槽是长条形的凹陷，不能当作台面使用。"}, {"text": "他把槽穿在脚上，出门跑步了。", "explanation": "这里应该用〈鞋〉。鞋是穿在脚上的，槽是物体上长条形的凹陷，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗框上有一只槽，雨水可以顺着它流走。", "corrected_sentence": "窗框上有一条槽，雨水可以顺着它流走。", "error_description": "错误在量词「只」。「只」用于动物或成对的东西，槽应用「条」（一条槽）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只槽里卡了一粒沙子。", "corrected_sentence": "这道槽里卡了一粒沙子。", "error_description": "错误在量词「只」。「只」用于动物或成对的东西，槽应用「道」或「条」（这道槽）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
