INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97991, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "标准像是一张人的正面照片，拍得整整齐齐，用来让人认出他是谁。", "primary_collocate": null, "pronunciation": "biāo zhǔn xiàng", "ipa": "pjɑʊ˥ ʈʂʊn˨˩ ɕjɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "标准像让人一眼认出你是谁。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张标准像拍得很整齐。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准像里，他看着前面，没有笑。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我手机里没有标准像，只有生活照。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈要一张我的标准像。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察看着标准像，认出了他。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准像不能侧着脸拍。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把标准像放在信封里。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相馆的人帮我拍了标准像。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张不是标准像，你在笑，头也歪着。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "標準像", "label": "繁体"}], "register": "中性", "sense_fingerprint": "拍得端正、用来认人的正面照片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标准像", "is_correct": true, "explanation": "标准像拍得端正、背景单一，所以能让人一眼认出你是谁。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气描述的是气候，与人的照片无关，无法让人认出你是谁。"}, {"text": "公式", "is_correct": false, "explanation": "语义：公式是数学或化学的表达式，跟认人没有关系。"}, {"text": "脾气", "is_correct": false, "explanation": "体貌：脾气是性格，不是外貌，不能“一眼”认出一个人。"}], "explanations": {"标准像": "标准像拍得端正、背景单一，所以能让人一眼认出你是谁。", "天气": "语义：天气描述的是气候，与人的照片无关，无法让人认出你是谁。", "公式": "语义：公式是数学或化学的表达式，跟认人没有关系。", "脾气": "体貌：脾气是性格，不是外貌，不能“一眼”认出一个人。"}, "sentence_index": 0, "correct_answer": "标准像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅水彩画是名家画的标准像。", "explanation": "这里应该用〈肖像〉。标准像指拍得端正、用来认人的正面照片，不能指画家画的人像。"}, {"text": "我们一家人在春节拍了一张标准像。", "explanation": "这里应该用〈全家福〉。标准像只拍一个人，要求端正、背景单一，不指一家人的合影。"}, {"text": "这张标准像是她在海边摆着姿势拍的。", "explanation": "这里应该用〈艺术照〉。标准像要求正面端正、用来认人，不是在海边摆姿势拍的照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准像", "is_correct": true, "explanation": "标准像要求正面端正，所以不能侧着脸拍。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景没有脸，句中的“侧着脸拍”只能针对人像，风景说不通。"}, {"text": "收据", "is_correct": false, "explanation": "语义：收据是消费凭证，不是人像，不能侧着脸拍。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体尺寸，不是可以拍摄的画面，“侧着脸拍”无法用于身高。"}], "explanations": {"标准像": "标准像要求正面端正，所以不能侧着脸拍。", "风景": "语义：风景没有脸，句中的“侧着脸拍”只能针对人像，风景说不通。", "收据": "语义：收据是消费凭证，不是人像，不能侧着脸拍。", "身高": "体貌：身高是身体尺寸，不是可以拍摄的画面，“侧着脸拍”无法用于身高。"}, "sentence_index": 6, "correct_answer": "标准像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把一只标准像夹进了书里。", "explanation": "这里应该用〈张〉。“只”多用于动物或成对的器物，标准像是平面照片，不能用“只”计量。"}, {"text": "老师让我们拿一把标准像去交。", "explanation": "这里应该用〈张〉。“把”用于有柄的器具，标准像不能用“把”计量。"}, {"text": "他在墙上挂了一根标准像。", "explanation": "这里应该用〈张〉。“根”用于细长条状的东西，标准像是平面照片，应用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "照相馆的人帮我拍了一个标准像，我把它寄给了老师。", "corrected_sentence": "照相馆的人帮我拍了一张标准像，我把它寄给了老师。", "error_description": "量词错误：“一个标准像”应为“一张标准像”。标准像是平面照片，计量用“张”，用“个”属于量词搭配错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一条标准像放在了信封里。", "corrected_sentence": "他把一张标准像放在了信封里。", "error_description": "量词错误：“一条标准像”应为“一张标准像”。“条”用于细长的东西，标准像是平面照片，要用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
