INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按规定拍摄的人物正面半身照，用于证件、档案等。", "primary_collocate": null, "pronunciation": "biāo zhǔn xiàng", "ipa": "pjɑʊ˥ ʈʂʊn˨˩ ɕjɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "办护照要交一张标准像。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "档案里要贴一张标准像。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张标准像是正面半身照。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请证件时，标准像不能戴帽子。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去照相馆拍了标准像。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作证上的标准像要用白色背景。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把标准像贴在表格右上角。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准像要拍到肩膀以上。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要我们交两张标准像。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的标准像照得很清楚。", "target_word": "标准像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "標準像", "label": "繁体"}], "register": "中性", "sense_fingerprint": "证件、档案用的按规定拍的正面半身照", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标准像", "is_correct": true, "explanation": "标准像指按规定拍摄的证件用正面半身照，办护照时要交的正是这种照片。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图与护照申请无关，办理时不需要交地图。"}, {"text": "风景画", "is_correct": false, "explanation": "语义：风景画是艺术作品，护照申请不需要交画。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“一张脸”把外貌当成可交的材料，与证件申请的要求不合。"}], "explanations": {"标准像": "标准像指按规定拍摄的证件用正面半身照，办护照时要交的正是这种照片。", "地图": "语义：地图与护照申请无关，办理时不需要交地图。", "风景画": "语义：风景画是艺术作品，护照申请不需要交画。", "脸": "体貌：“一张脸”把外貌当成可交的材料，与证件申请的要求不合。"}, "sentence_index": 0, "correct_answer": "标准像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅油画是名家画的标准像。", "explanation": "这里应该用〈肖像〉。标准像专指按规定拍摄、用于证件和档案的正面半身照，不能指画家画的人像。"}, {"text": "周末我和朋友去公园，拍了很多标准像。", "explanation": "这里应该用〈生活照〉。标准像要求正面、端正，用于证件和档案，不用于郊游时随手拍的照片。"}, {"text": "毕业那天，我们在校门口拍了一张标准像。", "explanation": "这里应该用〈合影〉。标准像只拍一个人的正面半身，不能指多人合拍的照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准像", "is_correct": true, "explanation": "标准像是按规定拍摄的证件照，贴在表格上正是它的用途。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是容器，不是能贴在表格上的平面材料。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“贴”不能和“蛋糕”搭配，蛋糕没法贴在表格上。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能贴在表格上。"}], "explanations": {"标准像": "标准像是按规定拍摄的证件照，贴在表格上正是它的用途。", "花瓶": "语义：花瓶是容器，不是能贴在表格上的平面材料。", "蛋糕": "搭配：“贴”不能和“蛋糕”搭配，蛋糕没法贴在表格上。", "咖啡": "语义：咖啡是饮品，不能贴在表格上。"}, "sentence_index": 6, "correct_answer": "标准像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿着一根标准像走进了教室。", "explanation": "这里应该用〈张〉。标准像是平面照片，“根”用于细长条状的东西，不能用来计量标准像。"}, {"text": "妈妈把一支标准像放进了相框。", "explanation": "这里应该用〈张〉。“支”多用于笔、枪等有杆的东西，标准像应用“张”计量。"}, {"text": "他在桌上摆了一只标准像。", "explanation": "这里应该用〈张〉。“只”多用于动物或成对的器物，不能用来计量标准像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去照相馆拍了一个标准像，用来办护照。", "corrected_sentence": "他去照相馆拍了一张标准像，用来办护照。", "error_description": "量词错误：“一个标准像”应为“一张标准像”。标准像是平面的照片，计量要用“张”，用“个”是常见的量词搭配错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "报名时要交三条标准像。", "corrected_sentence": "报名时要交三张标准像。", "error_description": "量词错误：“三条标准像”应为“三张标准像”。“条”用于细长的东西，标准像是平面照片，要用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
