INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "权利要求是写在纸上的话，说清楚这个新发明哪些地方是你的，别人不能用。", "primary_collocate": null, "pronunciation": "quán lì yāo qiú", "ipa": "tɕʰɥɛn˧˥ li˥˩ jɑʊ˥ tɕʰjoʊ˧˥", "syllable_count": 4, "sentences": [{"text": "权利要求说明哪些地方是你的。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份权利要求写得很清楚。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "权利要求里要写清新发明的特点。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人不能用权利要求里写的东西。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先写权利要求，再写说明书。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再看一遍这项权利要求。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "权利要求写得不清楚，别人会用你的发明。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么写权利要求。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "权利要求要写进专利申请里。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新发明的权利要求有五项。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "權利要求", "label": "繁体"}], "register": "书面", "sense_fingerprint": "写明新发明哪些部分归你、别人不能用的文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97993, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权利要求", "is_correct": true, "explanation": "权利要求是专利申请中划定保护范围的条款，能说明哪些地方归申请人。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单列出菜品，说不出专利中哪些地方归你。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报说的是天气，与专利保护范围无关。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：发型只说明头发的样式，不能用来界定发明的保护范围。"}], "explanations": {"权利要求": "权利要求是专利申请中划定保护范围的条款，能说明哪些地方归申请人。", "菜单": "语义：菜单列出菜品，说不出专利中哪些地方归你。", "天气预报": "语义：天气预报说的是天气，与专利保护范围无关。", "发型": "体貌：发型只说明头发的样式，不能用来界定发明的保护范围。"}, "sentence_index": 0, "correct_answer": "权利要求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份权利要求详细介绍了产品的使用方法。", "explanation": "这里应该用〈说明书〉。权利要求只写保护范围的条款，不介绍产品的使用方法。"}, {"text": "他拥有这项发明的权利要求。", "explanation": "这里应该用〈专利权〉。专利权是法律赋予的权利，可以拥有；权利要求是文件里的条款，不能拥有。"}, {"text": "这份权利要求画出了机器的结构图。", "explanation": "这里应该用〈附图〉。权利要求是文字条款，结构图画在附图里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权利要求", "is_correct": true, "explanation": "权利要求划定发明归你的范围，写得不清楚，别人就可能用你的发明。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写饼干”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，与文件内容的长短无关。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能被“写”，句中的“写”指撰写文件。"}], "explanations": {"权利要求": "权利要求划定发明归你的范围，写得不清楚，别人就可能用你的发明。", "饼干": "搭配：“写”的对象是文字，不能说“写饼干”。", "雨伞": "语义：雨伞是日用品，与文件内容的长短无关。", "钥匙": "语义：钥匙不能被“写”，句中的“写”指撰写文件。"}, "sentence_index": 6, "correct_answer": "权利要求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这份申请里写了两只权利要求。", "explanation": "这里应该用〈项〉。“只”用于动物或成对的器物，权利要求要用“项”计量。"}, {"text": "这份申请有五把权利要求。", "explanation": "这里应该用〈项〉。“把”用于有柄的器具，权利要求不能用“把”计量。"}, {"text": "发明人写了一盏权利要求。", "explanation": "这里应该用〈项〉。“盏”用于灯具，与权利要求不搭，应用“项”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份申请的权利要求有五块，写得很清楚。", "corrected_sentence": "这份申请的权利要求有五项，写得很清楚。", "error_description": "量词错误：“五块权利要求”应为“五项权利要求”。“块”用于块状物，权利要求用“项”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "申请人修改了这个新发明的权利要求，共有五幅。", "corrected_sentence": "申请人修改了这个新发明的权利要求，共有五项。", "error_description": "量词错误：“共有五幅权利要求”应为“共有五项权利要求”。“幅”用于字画、布匹等平面物件，与权利要求不搭，应用“项”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
