INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专利申请文件中，申请人请求法律保护的技术范围的条款。", "primary_collocate": null, "pronunciation": "quán lì yāo qiú", "ipa": "tɕʰɥɛn˧˥ li˥˩ jɑʊ˥ tɕʰjoʊ˧˥", "syllable_count": 4, "sentences": [{"text": "专利申请文件必须有权利要求。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "权利要求决定专利保护的范围。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "审查员认真看了第一项权利要求。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份专利的权利要求共有八项。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师建议修改权利要求。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "权利要求写得太宽，专利局不同意。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请人在权利要求里写明技术方案。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院根据权利要求判断是否侵权。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把权利要求放在申请文件后面。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "权利要求是专利申请的核心部分。", "target_word": "权利要求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "權利要求", "label": "繁体"}], "register": "书面", "sense_fingerprint": "专利申请文件里请求法律保护技术范围的条款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd789ac9d-1688-42a0-822d-40f37c2036dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权利要求", "is_correct": true, "explanation": "权利要求是专利申请文件中请求法律保护的技术范围条款，申请文件必须有。"}, {"text": "香味", "is_correct": false, "explanation": "语义：申请文件不会有香味，句中说的是必备的文件内容。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“有”的宾语须是文件的组成部分，“体温”不能算文件的内容。"}, {"text": "恐龙", "is_correct": false, "explanation": "语义：申请文件里不会有恐龙，与专利申请的要求无关。"}], "explanations": {"权利要求": "权利要求是专利申请文件中请求法律保护的技术范围条款，申请文件必须有。", "香味": "语义：申请文件不会有香味，句中说的是必备的文件内容。", "体温": "搭配：“有”的宾语须是文件的组成部分，“体温”不能算文件的内容。", "恐龙": "语义：申请文件里不会有恐龙，与专利申请的要求无关。"}, "sentence_index": 0, "correct_answer": "权利要求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份权利要求记录了实验的失败过程。", "explanation": "这里应该用〈说明书〉。权利要求只写保护范围的条款，不记录实验过程，实验过程写在说明书里。"}, {"text": "这份文件的权利要求画得很清楚。", "explanation": "这里应该用〈附图〉。权利要求是文字条款，不能“画得很清楚”，画的是附图。"}, {"text": "他享有这项专利的权利要求。", "explanation": "这里应该用〈权利〉。“享有”的对象是权利，权利要求是专利文件中的条款，不能享有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权利要求", "is_correct": true, "explanation": "权利要求是专利申请中划定保护范围的条款，申请人会在里面写明技术方案。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是书写的载体，无法在其中写明技术方案。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜是家具，不能用来书写技术内容。"}, {"text": "咖啡杯", "is_correct": false, "explanation": "搭配：“写明”需要文本载体，咖啡杯不能和“写明”搭配。"}], "explanations": {"权利要求": "权利要求是专利申请中划定保护范围的条款，申请人会在里面写明技术方案。", "花园": "语义：花园不是书写的载体，无法在其中写明技术方案。", "衣柜": "语义：衣柜是家具，不能用来书写技术内容。", "咖啡杯": "搭配：“写明”需要文本载体，咖啡杯不能和“写明”搭配。"}, "sentence_index": 6, "correct_answer": "权利要求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "申请人提交了两首权利要求。", "explanation": "这里应该用〈项〉。“首”多用于诗歌、歌曲，权利要求要用“项”计量。"}, {"text": "这份专利有八朵权利要求。", "explanation": "这里应该用〈项〉。“朵”用于花等物，权利要求不能用“朵”计量。"}, {"text": "审查员读完了三座权利要求。", "explanation": "这里应该用〈项〉。“座”用于建筑、山等大型物体，权利要求应用“项”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份申请的权利要求共有十根。", "corrected_sentence": "这份申请的权利要求共有十项。", "error_description": "量词错误：“十根权利要求”应为“十项权利要求”。“根”用于细长的东西，权利要求用“项”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "申请人修改了三块权利要求。", "corrected_sentence": "申请人修改了三项权利要求。", "error_description": "量词错误：“三块权利要求”应为“三项权利要求”。“块”用于块状物，权利要求用“项”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9130f839-c85d-42fa-a0b7-3e92b0b67dd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
