INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97997, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "次女是家里的二女儿。", "primary_collocate": null, "pronunciation": "cì nǚ", "ipa": "tsʰɨ˥˩ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "她是家里的次女，上面有一个姐姐。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的次女今年十岁了。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有两个女儿，次女在北京工作。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次女喜欢画画，长女喜欢唱歌。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生的次女下个月结婚。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为次女，她从小就跟姐姐一起长大。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是次女，我还有一个妹妹。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的次女很聪明，学习很好。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次女出生的时候，大女儿已经三岁了。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，次女的成绩比长女还好。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "家里的二女儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97997, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独女", "is_correct": false, "explanation": "语义：「独女」是家里唯一的女儿，没有兄弟姐妹，与「上面有一个姐姐」矛盾。"}, {"text": "长女", "is_correct": false, "explanation": "语义：「长女」是家里排行第一的女儿，上面不会有姐姐，与后半句矛盾。"}, {"text": "次女", "is_correct": true, "explanation": "正确：「次女」指家中排行第二的女儿，与「上面有一个姐姐」相符。"}, {"text": "次序", "is_correct": false, "explanation": "搭配：「次序」指先后顺序，不指人，不能说「家里的次序」。"}], "explanations": {"独女": "语义：「独女」是家里唯一的女儿，没有兄弟姐妹，与「上面有一个姐姐」矛盾。", "长女": "语义：「长女」是家里排行第一的女儿，上面不会有姐姐，与后半句矛盾。", "次女": "正确：「次女」指家中排行第二的女儿，与「上面有一个姐姐」相符。", "次序": "搭配：「次序」指先后顺序，不指人，不能说「家里的次序」。"}, "sentence_index": 0, "correct_answer": "次女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是家里的次女，喜欢踢足球。", "explanation": "这里应该用〈次子〉。「次女」指女儿，只用于女性；说男孩要用「次子」。"}, {"text": "她是公司的次女，负责财务。", "explanation": "这里误用了〈次女〉。「次女」只指家中排行第二的女儿，不能表示公司里的职位。"}, {"text": "我们班的次女考了第一名。", "explanation": "这里应该用〈同学〉。「次女」只用于家庭中的女儿排行，班级里的人没有这种称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独生子", "is_correct": false, "explanation": "语义：「独生子」没有兄弟姐妹，与「我还有一个妹妹」矛盾。"}, {"text": "次位", "is_correct": false, "explanation": "搭配：「次位」指名次或位置，不指人，不能用来说自己是家里的某个人。"}, {"text": "次女", "is_correct": true, "explanation": "正确：「次女」指排行第二，与「我还有一个妹妹」相符。"}, {"text": "独生女", "is_correct": false, "explanation": "语义：「独生女」没有兄弟姐妹，与「我还有一个妹妹」矛盾。"}], "explanations": {"独生子": "语义：「独生子」没有兄弟姐妹，与「我还有一个妹妹」矛盾。", "次位": "搭配：「次位」指名次或位置，不指人，不能用来说自己是家里的某个人。", "次女": "正确：「次女」指排行第二，与「我还有一个妹妹」相符。", "独生女": "语义：「独生女」没有兄弟姐妹，与「我还有一个妹妹」矛盾。"}, "sentence_index": 6, "correct_answer": "次女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是独生的次女，从小没有兄弟姐妹。", "explanation": "这里应该用〈独生女〉。「次女」表示排行第二，要有姐姐或哥哥才成立；独生子女没有排行，不能说次女。"}, {"text": "我们家有两个次女，大家都很喜欢她们。", "explanation": "这里应该用〈两个女儿〉。「次女」在一个家庭里只有一个，不能用「两个」来数。"}, {"text": "我家的小狗是次女，每天陪我散步。", "explanation": "这里误用了〈次女〉。「次女」指家中排行第二的女儿，只用于人，不能用来指狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是我们家的一只次女，喜欢读书。", "corrected_sentence": "她是我们家的次女，喜欢读书。", "error_description": "错误在于「一只次女」：「只」用于动物或小东西，「次女」指人，不能加量词「只」。去掉「一只」即为正确形式「她是我们家的次女」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她们家的次女们很聪明。", "corrected_sentence": "她们家的次女很聪明。", "error_description": "错误在于「次女们」：一个家庭只有一位次女，「她们家的」指一家，这一家不可能有复数的次女。去掉「们」即为正确形式「她们家的次女很聪明」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
