INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家中排行第二的女儿。", "primary_collocate": null, "pronunciation": "cì nǚ", "ipa": "tsʰɨ˥˩ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "在我们家，我排行第二，是次女。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员是家里的次女，从小爱唱歌。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的次女已经上大学了。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶最疼爱的是次女。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王家的次女生日在春天。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家的次女很懂事，常常帮妈妈做饭。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张太太有三个孩子，次女最爱笑。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给家里的次女买一件新衣服。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是父母的次女，姐姐比她大两岁。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天李家的次女给我打了电话。", "target_word": "次女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "家中排行第二的女儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长女", "is_correct": false, "explanation": "语义：「长女」是排行第一，与「我排行第二」矛盾。"}, {"text": "次女", "is_correct": true, "explanation": "正确：「次女」指家中排行第二的女儿，与「我排行第二」相符。"}, {"text": "次序", "is_correct": false, "explanation": "搭配：「次序」指先后顺序，不指人，不能说「是次序」。"}, {"text": "独生女", "is_correct": false, "explanation": "语义：「独生女」没有排行，与「我排行第二」矛盾。"}], "explanations": {"长女": "语义：「长女」是排行第一，与「我排行第二」矛盾。", "次女": "正确：「次女」指家中排行第二的女儿，与「我排行第二」相符。", "次序": "搭配：「次序」指先后顺序，不指人，不能说「是次序」。", "独生女": "语义：「独生女」没有排行，与「我排行第二」矛盾。"}, "sentence_index": 0, "correct_answer": "次女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位男孩是我家的次女，很爱运动。", "explanation": "这里应该用〈次子〉。「次女」指女孩，男孩要用「次子」。"}, {"text": "她是市政府的次女，负责财政。", "explanation": "这里误用了〈次女〉。「次女」只指家中排行第二的女儿，不能表示政府里的职位。"}, {"text": "这位老师是我们学校的次女，教我们数学。", "explanation": "这里误用了〈次女〉。「次女」只指家里排行第二的女儿，不能用来称呼学校里的老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独生子", "is_correct": false, "explanation": "语义：「独生子」没有兄弟姐妹，与「有三个孩子」矛盾。"}, {"text": "次位", "is_correct": false, "explanation": "搭配：「次位」不指人，不能作「最爱笑」的主语。"}, {"text": "次女", "is_correct": true, "explanation": "正确：「次女」指排行第二的女儿，与「张太太有三个孩子」相符。"}, {"text": "独生女", "is_correct": false, "explanation": "语义：「独生女」没有兄弟姐妹，与「有三个孩子」矛盾。"}], "explanations": {"独生子": "语义：「独生子」没有兄弟姐妹，与「有三个孩子」矛盾。", "次位": "搭配：「次位」不指人，不能作「最爱笑」的主语。", "次女": "正确：「次女」指排行第二的女儿，与「张太太有三个孩子」相符。", "独生女": "语义：「独生女」没有兄弟姐妹，与「有三个孩子」矛盾。"}, "sentence_index": 6, "correct_answer": "次女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是家里的老大，也是独生的次女。", "explanation": "这里应该用〈独生女〉。「次女」表示排行第二，独生子女没有排行，不能同时说老大和次女。"}, {"text": "我们家的次女有两个，都很聪明。", "explanation": "这里应该用〈两个女儿〉。「次女」在一个家庭里只有一个，不能用「两个」来数。"}, {"text": "我家的猫咪是次女，每天睡在床上。", "explanation": "这里误用了〈次女〉。「次女」指家中排行第二的女儿，只用于人，不能用来指猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹是家里的一条次女，她比我小一岁。", "corrected_sentence": "我妹妹是家里的次女，她比我小一岁。", "error_description": "错误在于「一条次女」：「条」用于长条形的东西，「次女」指人，不能加量词「条」。去掉「一条」即为正确形式「我妹妹是家里的次女」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "张家的次女们今年考上了大学。", "corrected_sentence": "张家的次女今年考上了大学。", "error_description": "错误在于「张家的次女们」：一个家庭只有一位次女，「张家的」指一家，这一家不可能有复数的次女。去掉「们」即为正确形式「张家的次女今年考上了大学」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
