INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "死别是有人死了，再也见不到他了。", "primary_collocate": null, "pronunciation": "sǐ bié", "ipa": "sɿ˨˩ pie˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶去世后，我第一次明白什么是死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和爷爷经历了死别，他哭了很久。", "target_word": "死别", "complexity_tier": "T3", "furigana": "xiǎo míng hé yé ye jīng lì le sǐ bié, tā kū le hěn jiǔ", "sentence_source": "generated"}, {"text": "这部电影讲的是一对夫妻的死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死别让她十分难过，几天没吃饭。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十岁那年经历了与爸爸的死别。", "target_word": "死别", "complexity_tier": "T3", "furigana": "tā shí suì nà nián jīng lì le yǔ bà ba de sǐ bié", "sentence_source": "generated"}, {"text": "我们都怕死别，因为再也见不到那个人了。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老人来说，朋友一个个离开，就是一次次死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少说起和妻子的死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆走了，孩子第一次遇到死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死别以后，她常常梦见母亲。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "生离死别", "label": "复合"}], "register": "书面语", "sense_fingerprint": "死别：有人去世，再也见不到这个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aa28573-c80f-4808-aa31-1a2121744695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "死别", "is_correct": true, "explanation": "死别：有人去世，再也见不到这个人，与句意相符。"}, {"text": "重逢", "is_correct": false, "explanation": "语义：“重逢”是再次相见，与“奶奶去世后”的语境相反。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是庆祝出生的日子，与“奶奶去世后”的语境不符。"}, {"text": "相遇", "is_correct": false, "explanation": "语义：“相遇”是偶然碰见，与“去世后”的语境不符。"}], "explanations": {"死别": "死别：有人去世，再也见不到这个人，与句意相符。", "重逢": "语义：“重逢”是再次相见，与“奶奶去世后”的语境相反。", "生日": "语义：“生日”是庆祝出生的日子，与“奶奶去世后”的语境不符。", "相遇": "语义：“相遇”是偶然碰见，与“去世后”的语境不符。"}, "sentence_index": 0, "correct_answer": "死别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在机场迎来一次死别，激动地拥抱在一起。", "explanation": "这里应该用〈重逢〉。死别是永久分离，久别重逢的场面要说重逢。"}, {"text": "全家在春节有了一次死别，笑声不断。", "explanation": "这里应该用〈欢聚〉。死别是永别，不能用于短暂的快乐聚会。"}, {"text": "他们每天都有一次死别，非常开心。", "explanation": "这里应该用〈相处〉。死别是永别，日常和睦相处要说相处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死别", "is_correct": true, "explanation": "死别：因死亡而永远分离，与“朋友一个个离开”的语境相符。"}, {"text": "相会", "is_correct": false, "explanation": "语义：“相会”是见面，与“朋友一个个离开”的语境相反。"}, {"text": "相识", "is_correct": false, "explanation": "语义：“相识”是认识，与“离开”的语境相反，句意不通。"}, {"text": "团圆", "is_correct": false, "explanation": "语义：“团圆”指一家人欢聚在一起，与“朋友一个个离开”的语境相反。"}], "explanations": {"死别": "死别：因死亡而永远分离，与“朋友一个个离开”的语境相符。", "相会": "语义：“相会”是见面，与“朋友一个个离开”的语境相反。", "相识": "语义：“相识”是认识，与“离开”的语境相反，句意不通。", "团圆": "语义：“团圆”指一家人欢聚在一起，与“朋友一个个离开”的语境相反。"}, "sentence_index": 6, "correct_answer": "死别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天死别后，我们各自回家。", "explanation": "这里应该用〈分别〉。死别是因死亡而永别，普通告别后各自回家要说分别。"}, {"text": "我们每个周末都有一次死别，一起吃饭。", "explanation": "这里应该用〈相聚〉。死别只表示永别，不能用于周末聚餐。"}, {"text": "节日里，全家人有了一次死别，大家都聚在一起吃饭。", "explanation": "这里应该用〈团圆〉。死别是永别，节日里全家聚在一起要说团圆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明经历过一座死别。", "corrected_sentence": "小明经历过一次死别。", "error_description": "量词错误：“死别”是事件，应用“次”；“座”多用于山、桥、房屋等大型固定物，不能用于此类事件。正确形式为“一次死别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一生中会经历几个死别。", "corrected_sentence": "我们一生中会经历几次死别。", "error_description": "“几个死别”错误，应为“几次死别”。“死别”是事件，量词用“次”，“个”不能用于此类事件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
