INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98002, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "因一方死亡而永远分离。", "primary_collocate": null, "pronunciation": "sǐ bié", "ipa": "sɿ˨˩ pie˥˩", "syllable_count": 2, "sentences": [{"text": "他年轻时经历过一次死别，很多年都走不出来。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与亲人的死别，是人生中最痛苦的事。", "target_word": "死别", "complexity_tier": "T3", "furigana": "yǔ qīn rén de sǐ bié, shì rén shēng zhōng zuì tòng kǔ de shì", "sentence_source": "generated"}, {"text": "战争让许多家庭经历了死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她经历了与丈夫的死别以后，一个人把孩子养大。", "target_word": "死别", "complexity_tier": "T3", "furigana": "tā jīng lì le yǔ zhàng fu de sǐ bié yǐ hòu, yí gè rén bǎ hái zi yǎng dà", "sentence_source": "generated"}, {"text": "死别的痛苦，时间也很难带走。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对死别，小女孩哭得说不出话来。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，生病不可怕，最怕的是死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一次死别，他一直记在心里。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗写的是朋友之间的死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿意回忆那次死别。", "target_word": "死别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "生离死别", "label": "复合"}], "register": "书面语", "sense_fingerprint": "死别：亲人或朋友死亡，从此永远分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aa28573-c80f-4808-aa31-1a2121744695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "死别", "is_correct": true, "explanation": "死别：因一方死亡而永远分离，与“走不出来”的悲痛相符。"}, {"text": "重逢", "is_correct": false, "explanation": "语义：“重逢”是再次相见，与“走不出来”的悲痛语境相反。"}, {"text": "团聚", "is_correct": false, "explanation": "语义：“团聚”是欢聚，与“很多年都走不出来”的语境不符。"}, {"text": "结缘", "is_correct": false, "explanation": "搭配：“结缘”指建立缘分，不能与“经历过一次”搭配。"}], "explanations": {"死别": "死别：因一方死亡而永远分离，与“走不出来”的悲痛相符。", "重逢": "语义：“重逢”是再次相见，与“走不出来”的悲痛语境相反。", "团聚": "语义：“团聚”是欢聚，与“很多年都走不出来”的语境不符。", "结缘": "搭配：“结缘”指建立缘分，不能与“经历过一次”搭配。"}, "sentence_index": 0, "correct_answer": "死别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在车站有一次死别，朋友要去外地工作。", "explanation": "这里应该用〈离别〉。死别专指一方死亡而永远分离，朋友远行要说离别。"}, {"text": "他们之间曾有过一次死别，二十年后才再相见。", "explanation": "这里应该用〈分离〉。死别专指一方死亡，两人都活着分开要说分离。"}, {"text": "他这次经历了一次死别，去了北京工作。", "explanation": "这里应该用〈离开〉。死别只用于一方死亡而永别，人离开家乡不能说死别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死别", "is_correct": true, "explanation": "死别：因死亡而永别，与“最怕的是”的语境相符。"}, {"text": "喜事", "is_correct": false, "explanation": "语义：“喜事”是高兴的事，与“最怕”的语境相反。"}, {"text": "相识", "is_correct": false, "explanation": "配价：“相识”是双方彼此认识，不能作“最怕的是”的对象。"}, {"text": "欢聚", "is_correct": false, "explanation": "语义：“欢聚”是快乐的相聚，与“最怕”的语境相反。"}], "explanations": {"死别": "死别：因死亡而永别，与“最怕的是”的语境相符。", "喜事": "语义：“喜事”是高兴的事，与“最怕”的语境相反。", "相识": "配价：“相识”是双方彼此认识，不能作“最怕的是”的对象。", "欢聚": "语义：“欢聚”是快乐的相聚，与“最怕”的语境相反。"}, "sentence_index": 6, "correct_answer": "死别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次一家人终于有了死别，大家都很高兴。", "explanation": "这里应该用〈团聚〉。死别是永远分离，团聚是相聚，两者意思相反。"}, {"text": "她对童年的往事有了一次死别。", "explanation": "这里应该用〈遗忘〉。死别指因死亡而永别，忘记往事要说遗忘。"}, {"text": "他们去年有过一次死别，后来才正式举办婚礼。", "explanation": "这里应该用〈结婚〉。死别指永久分离，两人结为夫妻要说结婚，不能说死别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲去世那天，我经历了一只死别。", "corrected_sentence": "父亲去世那天，我经历了一次死别。", "error_description": "“一只死别”错误，应为“一次死别”。“死别”是事件，量词用“次”，“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她不得不接受这次被死别。", "corrected_sentence": "她不得不接受这次死别。", "error_description": "“被死别”错误，应为“死别”。“死别”不能加“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
