INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "殿是很大很高的房子，里面常常住着国王或者放着神像。", "primary_collocate": null, "pronunciation": "diàn", "ipa": "tjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这座殿又高又大。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殿里放着一尊很大的神像。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走进殿里，里面很安静。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殿前有两棵老树。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王住在那座殿里。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殿外站着很多人，都在等国王。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座殿有一千多年了。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩看着殿里的神像，不敢说话。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游带我们去看山上的那座殿。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殿的屋顶是金色的，很漂亮。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词：高大的房子，住着国王或放着神像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98005, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "殿", "is_correct": true, "explanation": "殿（diàn）：很大很高的房子，里面常住国王或放神像。"}, {"text": "点", "is_correct": false, "explanation": "点（diǎn，第三声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是点子、点缀。"}, {"text": "颠", "is_correct": false, "explanation": "颠（diān，第一声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是上下震动。"}, {"text": "现", "is_correct": false, "explanation": "现（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是现在、显现。"}, {"text": "线", "is_correct": false, "explanation": "线（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是细长的东西。"}], "explanations": {"殿": "殿（diàn）：很大很高的房子，里面常住国王或放神像。", "点": "点（diǎn，第三声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是点子、点缀。", "颠": "颠（diān，第一声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是上下震动。", "现": "现（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是现在、显现。", "线": "线（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是细长的东西。"}, "sentence_index": null, "correct_answer": "殿"}, "level_3": {"options": [{"text": "小庙", "is_correct": false, "explanation": "语义：“小”与“又高又大”的外形描述相矛盾，不能说小庙又高又大。"}, {"text": "矮楼", "is_correct": false, "explanation": "语义：“矮”与“高”相反，“矮楼又高又大”自相矛盾。"}, {"text": "地窖", "is_correct": false, "explanation": "语义：地窖深在地下，与“又高”的外形描述相矛盾。"}, {"text": "殿", "is_correct": true, "explanation": "殿：高大的房屋，与“又高又大”相符。"}], "explanations": {"小庙": "语义：“小”与“又高又大”的外形描述相矛盾，不能说小庙又高又大。", "矮楼": "语义：“矮”与“高”相反，“矮楼又高又大”自相矛盾。", "地窖": "语义：地窖深在地下，与“又高”的外形描述相矛盾。", "殿": "殿：高大的房屋，与“又高又大”相符。"}, "sentence_index": 0, "correct_answer": "殿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们住在一座小殿里，屋子不大但很暖和。", "explanation": "这里应该用〈小楼〉。殿指很大很高、住国王或放神像的建筑，不用来形容小巧的住处。"}, {"text": "我们走进那座殿，里面全是卖衣服的柜台。", "explanation": "这里应该用〈商场〉。殿是高大的宫殿或神殿，不用于卖东西的场所。"}, {"text": "我们看到一只殿，又高又大。", "explanation": "这里应该用〈座〉。殿是建筑，量词应用“座”，不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98005, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "殿", "is_correct": true, "explanation": "殿（diàn）：很大很高的房子，里面常住国王或放神像。"}, {"text": "见", "is_correct": false, "explanation": "见（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是看见。"}, {"text": "建", "is_correct": false, "explanation": "建（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是建造。"}, {"text": "件", "is_correct": false, "explanation": "件（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，是衣物、事情的量词。"}], "explanations": {"殿": "殿（diàn）：很大很高的房子，里面常住国王或放神像。", "见": "见（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是看见。", "建": "建（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是建造。", "件": "件（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，是衣物、事情的量词。"}, "sentence_index": null, "correct_answer": "殿"}, "level_3": {"options": [{"text": "新楼", "is_correct": false, "explanation": "语义：“新”指外观崭新，与“有一千多年了”的古老形象不符。"}, {"text": "新桥", "is_correct": false, "explanation": "语义：“新”表示刚建成，与“一千多年了”的年代相矛盾。"}, {"text": "新塔", "is_correct": false, "explanation": "语义：新塔刚建成，年代与“有一千多年了”明显矛盾。"}, {"text": "殿", "is_correct": true, "explanation": "殿：古老的高大建筑，与“有一千多年了”相符。"}], "explanations": {"新楼": "语义：“新”指外观崭新，与“有一千多年了”的古老形象不符。", "新桥": "语义：“新”表示刚建成，与“一千多年了”的年代相矛盾。", "新塔": "语义：新塔刚建成，年代与“有一千多年了”明显矛盾。", "殿": "殿：古老的高大建筑，与“有一千多年了”相符。"}, "sentence_index": 6, "correct_answer": "殿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座殿的菜很好吃，价格也便宜。", "explanation": "这里应该用〈饭馆〉。殿指高大的宫殿或神殿，不用于形容菜的味道和价格。"}, {"text": "这座殿很矮，我一伸手就能摸到屋顶。", "explanation": "这里应该用〈小屋〉。殿指很大很高、住国王或放神像的建筑，不能说很矮、伸手就能摸到屋顶。"}, {"text": "这座殿是村里的小卖部，专门卖零食。", "explanation": "这里应该用〈小卖部〉。殿指很大很高、住国王或放神像的建筑，不用于售卖零食的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只殿的墙是红色的。", "corrected_sentence": "这座殿的墙是红色的。", "error_description": "“殿”是建筑，量词应用“座”，不能用“只”。应为“这座殿的墙是红色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国王在一块殿里接见了大臣。", "corrected_sentence": "国王在一座殿里接见了大臣。", "error_description": "错误：“殿”是建筑，量词应用“座”，不能用“块”。应为“在一座殿里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
