INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高大宏伟的房屋，多指帝王处理政事的场所或供奉神佛的建筑。", "primary_collocate": null, "pronunciation": "diàn", "ipa": "tjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "皇帝每天早上都到殿里处理国事。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们站在殿前等着皇上。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和尚在殿里给佛像烧香。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座殿是古代皇帝开会的地方。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客不能随便进殿拍照。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殿里供着一尊很旧的佛像。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝坐在殿上，听大臣说话。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每个月都来这座殿拜佛。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座殿是用红色的木头盖成的。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员们走进殿，对皇帝行礼。", "target_word": "殿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词：帝王处理政事的场所，或供奉神佛的建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "殿", "is_correct": true, "explanation": "殿（diàn）：高大宏伟的房屋，多指帝王处理政事的场所或供奉神佛的建筑。"}, {"text": "点", "is_correct": false, "explanation": "点（diǎn，第三声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是点子、点缀。"}, {"text": "颠", "is_correct": false, "explanation": "颠（diān，第一声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是上下震动。"}, {"text": "现", "is_correct": false, "explanation": "现（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是现在、显现。"}, {"text": "线", "is_correct": false, "explanation": "线（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是细长的东西。"}], "explanations": {"殿": "殿（diàn）：高大宏伟的房屋，多指帝王处理政事的场所或供奉神佛的建筑。", "点": "点（diǎn，第三声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是点子、点缀。", "颠": "颠（diān，第一声）与殿（diàn，第四声）声母韵母相同，只有声调不同，意思是上下震动。", "现": "现（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是现在、显现。", "线": "线（xiàn）的声母 x 与殿的 d 不同，韵母和声调相同，意思是细长的东西。"}, "sentence_index": null, "correct_answer": "殿"}, "level_3": {"options": [{"text": "寺", "is_correct": false, "explanation": "语义：寺院供奉佛教，不是处理国事的场所，与“处理国事”不符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“处理国事”需要政事场所，厨房与之搭配不当。"}, {"text": "殿", "is_correct": true, "explanation": "殿：帝王处理政事的场所，与“处理国事”相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是教学场所，与“处理国事”的政务场景不符。"}], "explanations": {"寺": "语义：寺院供奉佛教，不是处理国事的场所，与“处理国事”不符。", "厨房": "搭配：“处理国事”需要政事场所，厨房与之搭配不当。", "殿": "殿：帝王处理政事的场所，与“处理国事”相符。", "教室": "语义：教室是教学场所，与“处理国事”的政务场景不符。"}, "sentence_index": 0, "correct_answer": "殿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座殿是公司开会的地方。", "explanation": "这里应该用〈会议室〉。殿多指帝王处理政事或供奉神佛的建筑，公司会议场所不用殿。"}, {"text": "这座殿关着很多犯人。", "explanation": "这里应该用〈监狱〉。殿是帝王处理政事或供奉神佛的建筑，不用于关押犯人。"}, {"text": "大臣们走进一只殿，向皇帝行礼。", "explanation": "这里应该用〈座〉。殿是建筑，量词应用“座”，不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98006, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "殿", "is_correct": true, "explanation": "殿（diàn）：高大宏伟的房屋，多指帝王处理政事的场所或供奉神佛的建筑。"}, {"text": "见", "is_correct": false, "explanation": "见（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是看见。"}, {"text": "建", "is_correct": false, "explanation": "建（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是建造。"}, {"text": "件", "is_correct": false, "explanation": "件（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，是衣物、事情的量词。"}], "explanations": {"殿": "殿（diàn）：高大宏伟的房屋，多指帝王处理政事的场所或供奉神佛的建筑。", "见": "见（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是看见。", "建": "建（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，意思是建造。", "件": "件（jiàn）的声母 j 与殿的 d 不同，韵母和声调相同，是衣物、事情的量词。"}, "sentence_index": null, "correct_answer": "殿"}, "level_3": {"options": [{"text": "马桶", "is_correct": false, "explanation": "语义：“马桶”是卫生间的用具，皇帝坐在上面听大臣说话，与语境完全不符。"}, {"text": "灶台", "is_correct": false, "explanation": "搭配：“坐在灶台上”搭配不当，灶台是用来做饭的，不能用来坐。"}, {"text": "殿", "is_correct": true, "explanation": "殿：帝王听政的大殿，与“坐在殿上，听大臣说话”相符。"}, {"text": "垃圾堆", "is_correct": false, "explanation": "语义：垃圾堆与皇帝听大臣议事的场景相矛盾。"}], "explanations": {"马桶": "语义：“马桶”是卫生间的用具，皇帝坐在上面听大臣说话，与语境完全不符。", "灶台": "搭配：“坐在灶台上”搭配不当，灶台是用来做饭的，不能用来坐。", "殿": "殿：帝王听政的大殿，与“坐在殿上，听大臣说话”相符。", "垃圾堆": "语义：垃圾堆与皇帝听大臣议事的场景相矛盾。"}, "sentence_index": 6, "correct_answer": "殿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座殿是大家买菜的市场，每天都很热闹。", "explanation": "这里应该用〈市场〉。殿指帝王处理政事或供奉神佛的建筑，不用于买菜的场所。"}, {"text": "这座殿里住满了病人。", "explanation": "这里应该用〈医院〉。殿不用于收治病人，也不是住院的场所。"}, {"text": "这座殿是我家的小厨房，每天都在这里做饭。", "explanation": "这里应该用〈厨房〉。殿指高大宏伟、帝王或神佛所在的建筑，不是家里做饭的小厨房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只殿是皇帝处理国事的地方。", "corrected_sentence": "这座殿是皇帝处理国事的地方。", "error_description": "“殿”是建筑，量词应用“座”，不能用“只”。应为“这座殿是皇帝处理国事的地方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "皇帝在一块殿里批阅奏章。", "corrected_sentence": "皇帝在一座殿里批阅奏章。", "error_description": "错误：“殿”是建筑，量词应用“座”，不能用“块”。应为“在一座殿里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98009, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98009, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98009, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "气质是一个人从里到外让人感觉到的样子，比如安静或者很有礼貌。", "primary_collocate": null, "pronunciation": "qì zhì", "ipa": "tɕʰi˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "她很安静，有一种特别的气质。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个女孩说话很有礼貌，气质很好。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次见他，就觉得他气质不一般。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的气质让大家都很喜欢她。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿着白衣服，看起来很有气质。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的气质和她很不一样，她比较安静。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太爱说话，但是气质很温柔。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位先生很有礼貌，气质也很好。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢那个安静又有气质的女老师。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一走进来，大家就注意到了他的气质。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "艺术气质", "label": "复合"}, {"form": "氣質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人对一个人的整体印象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98009, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气质", "is_correct": true, "explanation": "气质：本题正确答案，指人的整体风格，与「很安静」相符。"}, {"text": "旗帜", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是旗帜。"}, {"text": "气势", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是气势。"}, {"text": "起止", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）、zhǐ（第三声）与 zhì（第四声）声调不同，意思是起止。"}], "explanations": {"气质": "气质：本题正确答案，指人的整体风格，与「很安静」相符。", "旗帜": "qí（第二声）与 qì（第四声）声调不同，意思是旗帜。", "气势": "shì 与 zhì 声母不同（sh 与 zh），意思是气势。", "起止": "qǐ（第三声）与 qì（第四声）、zhǐ（第三声）与 zhì（第四声）声调不同，意思是起止。"}, "sentence_index": null, "correct_answer": "气质"}, "level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "搭配：「体重」是数量，不能说「有一种特别的体重」。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：「噪音」与「她很安静」矛盾。"}, {"text": "气质", "is_correct": true, "explanation": "正确：「气质」指人的整体风格，与「很安静」「特别的」相符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」是数字，不能说「有一种特别的年龄」。"}], "explanations": {"体重": "搭配：「体重」是数量，不能说「有一种特别的体重」。", "噪音": "语义：「噪音」与「她很安静」矛盾。", "气质": "正确：「气质」指人的整体风格，与「很安静」「特别的」相符。", "年龄": "搭配：「年龄」是数字，不能说「有一种特别的年龄」。"}, "sentence_index": 0, "correct_answer": "气质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的气质有八十公斤，比他弟弟还重。", "explanation": "这里应该用〈体重〉。「气质」指人的性格、修养和仪态，不能用来称重。"}, {"text": "他对工作的气质很认真，总是按时完成任务。", "explanation": "这里应该用〈态度〉。「认真」形容对工作的态度，不能用「气质」。"}, {"text": "她的气质很好听，大家都喜欢。", "explanation": "这里应该用〈声音〉。「气质」指人从里到外让人感觉到的样子，不能用来说声音好不好听；说声音好听应用〈声音〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口才", "is_correct": false, "explanation": "语义：「口才」指善于说话，与「她不太爱说话」矛盾。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：「嗓门」指声音大小，不能说「很温柔」。"}, {"text": "气质", "is_correct": true, "explanation": "正确：「气质」指人的整体风格，与「但是……很温柔」相符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「身高」是数字，不能用「很温柔」来形容。"}], "explanations": {"口才": "语义：「口才」指善于说话，与「她不太爱说话」矛盾。", "嗓门": "搭配：「嗓门」指声音大小，不能说「很温柔」。", "气质": "正确：「气质」指人的整体风格，与「但是……很温柔」相符。", "身高": "搭配：「身高」是数字，不能用「很温柔」来形容。"}, "sentence_index": 6, "correct_answer": "气质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的气质很快，开起来很稳。", "explanation": "这里应该用〈速度〉。「气质」指人的性格、修养和仪态，不能用来形容车跑得快慢；说车速应用〈速度〉。"}, {"text": "这种物质加热后会产生很多气质。", "explanation": "这里应该用〈气体〉。「气质」指人的风格，不指加热后产生的物质。"}, {"text": "这根绳子的气质有十米长。", "explanation": "这里应该用〈长度〉。「气质」指人的性格、修养和仪态，不能用来说物体的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她身上有一条特别的气质，很让人喜欢。", "corrected_sentence": "她身上有一种特别的气质，很让人喜欢。", "error_description": "错误在于量词「一条」：「条」用于细长的东西，「气质」是抽象的，不能用「条」。正确形式为「一种特别的气质」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位先生有很气质，大家都很尊敬他。", "corrected_sentence": "那位先生很有气质，大家都很尊敬他。", "error_description": "错误在于副词位置：「很有气质」是固定说法，「很」应放在「有」前面，「有很气质」不能说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
