INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人在性格、修养和仪态上表现出来的稳定特点。", "primary_collocate": null, "pronunciation": "qì zhì", "ipa": "tɕʰi˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "一个人的气质和他的修养有关系。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小学音乐，气质很文雅。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多读书可以改变一个人的气质。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有军人的气质，站得很直。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺术家的气质和别人不太一样。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她性格开朗，气质也很活泼。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老教授的气质很温和，学生都喜欢他。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的气质不是一天就能养成的。", "target_word": "气质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的气质像个读书人，说话慢慢的。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的气质，不用学别人。", "target_word": "气质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "艺术气质", "label": "复合"}, {"form": "氣質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "性格修养仪态的稳定特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气质", "is_correct": true, "explanation": "气质：本题正确答案，指人在性格、修养和仪态上的稳定特点。"}, {"text": "旗帜", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是旗帜。"}, {"text": "气势", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是气势。"}, {"text": "起止", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）、zhǐ（第三声）与 zhì（第四声）声调不同，意思是起止。"}], "explanations": {"气质": "气质：本题正确答案，指人在性格、修养和仪态上的稳定特点。", "旗帜": "qí（第二声）与 qì（第四声）声调不同，意思是旗帜。", "气势": "shì 与 zhì 声母不同（sh 与 zh），意思是气势。", "起止": "qǐ（第三声）与 qì（第四声）、zhǐ（第三声）与 zhì（第四声）声调不同，意思是起止。"}, "sentence_index": null, "correct_answer": "气质"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高与修养无关，这样说不成立。"}, {"text": "气质", "is_correct": true, "explanation": "正确：「气质」与修养、仪态相关，与「和他的修养有关系」相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与修养无关，这样说不成立。"}, {"text": "气氛", "is_correct": false, "explanation": "搭配：「气氛」指场合或环境，不说「一个人的气氛」。"}], "explanations": {"身高": "语义：身高与修养无关，这样说不成立。", "气质": "正确：「气质」与修养、仪态相关，与「和他的修养有关系」相符。", "体重": "语义：体重与修养无关，这样说不成立。", "气氛": "搭配：「气氛」指场合或环境，不说「一个人的气氛」。"}, "sentence_index": 0, "correct_answer": "气质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的气质很大了，走路很慢。", "explanation": "这里应该用〈年纪〉。「气质」指人的性格、修养和仪态，不能用来说年纪大小；说年纪大应用〈年纪〉。"}, {"text": "他对学习的气质很认真，总是按时完成作业。", "explanation": "这里应该用〈态度〉。「认真」形容对学习的态度，不能用「气质」。"}, {"text": "他的气质有一米九，比班里其他人都高。", "explanation": "这里应该用〈身高〉。「气质」指人的性格、修养和仪态，不能用来量身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怒气", "is_correct": false, "explanation": "语义：「怒气」与「很温和」矛盾。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：「体力」指力量，不能用「很温和」来形容。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：「嗓门」指声音大小，不能说「很温和」。"}, {"text": "气质", "is_correct": true, "explanation": "正确：「气质」指人的整体风格，与「很温和，学生都喜欢他」相符。"}], "explanations": {"怒气": "语义：「怒气」与「很温和」矛盾。", "体力": "搭配：「体力」指力量，不能用「很温和」来形容。", "嗓门": "搭配：「嗓门」指声音大小，不能说「很温和」。", "气质": "正确：「气质」指人的整体风格，与「很温和，学生都喜欢他」相符。"}, "sentence_index": 6, "correct_answer": "气质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的气质很烫，别急着喝。", "explanation": "这里应该用〈温度〉。「气质」指人的性格、修养和仪态，不能用来形容饮料的冷热；说咖啡烫应描述〈温度〉。"}, {"text": "这种液体遇热后会产生大量气质。", "explanation": "这里应该用〈气体〉。「气质」指人的风格，不指液体加热后产生的东西。"}, {"text": "这本书的气质有五百页。", "explanation": "这里应该用〈页数〉。「气质」指人的性格、修养和仪态，不能用来说书有多少页。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一条让人安心的气质。", "corrected_sentence": "他有一种让人安心的气质。", "error_description": "错误在于量词「一条」：「条」用于细长的东西，「气质」是抽象的，不能用「条」。正确形式为「一种让人安心的气质」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有很气质，说话也很有礼貌。", "corrected_sentence": "他很有气质，说话也很有礼貌。", "error_description": "错误在于副词位置：「很有气质」是固定说法，「很」应放在「有」前面，「有很气质」不能说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98013, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": true, "explanation": "正确：“沉重”指分量大，“轻”指分量小，二者是反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“沉重”的分量义无反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与“沉重”的分量或心情义无反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥形容水分少，与“沉重”没有反义关系。"}], "correct_answer": "轻", "explanations": {"轻": "正确：“沉重”指分量大，“轻”指分量小，二者是反义关系。", "明亮": "明亮形容光线或颜色，与“沉重”的分量义无反义关系。", "柔软": "柔软形容质地，与“沉重”的分量或心情义无反义关系。", "干燥": "干燥形容水分少，与“沉重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98013, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻快", "is_correct": true, "explanation": "正确：形容脚步时，“沉重”与“轻快”相对，指脚步轻松利落。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容明白或清晰，与“沉重”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情形容态度，与“沉重”的分量或心情义无反义关系。"}, {"text": "友好", "is_correct": false, "explanation": "友好形容关系，与“沉重”没有反义关系。"}], "correct_answer": "轻快", "explanations": {"轻快": "正确：形容脚步时，“沉重”与“轻快”相对，指脚步轻松利落。", "清楚": "清楚形容明白或清晰，与“沉重”没有反义关系。", "热情": "热情形容态度，与“沉重”的分量或心情义无反义关系。", "友好": "友好形容关系，与“沉重”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98013, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "沉重是东西分量很大，拿起来很费力。", "primary_collocate": null, "pronunciation": "chén zhòng", "ipa": "ʈʂʰən˧˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个箱子太沉重，我拿不动。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背着沉重的书包走路。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沉重的行李让她走得很慢。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着沉重的桶，一步一步上楼。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋米很沉重，我一个人搬不动。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提着沉重的袋子，走得很累。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头很沉重，两个人才搬得动。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们抬着沉重的木头往前走。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把沉重的箱子放在了地上。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚步很沉重，好像很累。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "沉重：物体分量大，拿、背、搬起来费力（箱子、行李、石头、脚步）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻", "is_correct": false, "explanation": "语义：“轻”与“沉重”相反，箱子太轻就不会拿不动，句子矛盾。"}, {"text": "沉重", "is_correct": true, "explanation": "正确：形容箱子分量大，与“拿不动”的原因一致。"}, {"text": "干净", "is_correct": false, "explanation": "语义：干净说的是清洁程度，与“拿不动”的原因无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：漂亮形容外观好看，不能说明箱子为什么拿不动。"}], "explanations": {"轻": "语义：“轻”与“沉重”相反，箱子太轻就不会拿不动，句子矛盾。", "沉重": "正确：形容箱子分量大，与“拿不动”的原因一致。", "干净": "语义：干净说的是清洁程度，与“拿不动”的原因无关。", "漂亮": "语义：漂亮形容外观好看，不能说明箱子为什么拿不动。"}, "sentence_index": 0, "correct_answer": "沉重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小猫很沉重，一下子就跳上了桌子。", "explanation": "这里应该用〈轻盈〉。跳上桌子要说轻盈，沉重表示分量大或心情压抑，与跳跃的动作矛盾。"}, {"text": "这次考完试，我的心情很沉重，一路蹦蹦跳跳地回了家。", "explanation": "这里应该用〈轻松〉。考完试一路蹦跳应说轻松，沉重表示心里压抑、负担大，与蹦蹦跳跳矛盾。"}, {"text": "他做事很沉重，从不慌张。", "explanation": "这里应该用〈沉稳〉。沉稳形容做事稳重有把握，沉重不能用来形容做事的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "软", "is_correct": false, "explanation": "语义：软说的是质地，不能说明为什么要两个人才搬得动。"}, {"text": "沉重", "is_correct": true, "explanation": "正确：形容石头分量大，与“两个人才搬得动”一致。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆形容声音，不能用来形容石头。"}, {"text": "细小", "is_correct": false, "explanation": "语义：细小表示体积小，与“两个人才搬得动”矛盾。"}], "explanations": {"软": "语义：软说的是质地，不能说明为什么要两个人才搬得动。", "沉重": "正确：形容石头分量大，与“两个人才搬得动”一致。", "清脆": "搭配：清脆形容声音，不能用来形容石头。", "细小": "语义：细小表示体积小，与“两个人才搬得动”矛盾。"}, "sentence_index": 6, "correct_answer": "沉重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收到录取通知，他的脚步很沉重，几乎要跳起来了。", "explanation": "这里应该用〈轻快〉。高兴得几乎要跳起来，脚步应说轻快，沉重形容分量大或心情压抑，与跳起来矛盾。"}, {"text": "这只气球很沉重，飘上了天空。", "explanation": "这里应该用〈轻〉。气球要能飘上天空，应说很轻，沉重表示分量大，与飘起来的事实相反。"}, {"text": "孩子们在操场上跑来跑去，显得很沉重。", "explanation": "这里应该用〈活泼〉。孩子跑跳玩耍要说活泼，沉重不能形容这种状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他沉重的叹了一口气。", "corrected_sentence": "他沉重地叹了一口气。", "error_description": "“的”与“地”混用：修饰动词“叹”要用“地”，“沉重的叹”不对，应为“沉重地叹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个箱子地沉重，我搬不动。", "corrected_sentence": "这个箱子很沉重，我搬不动。", "error_description": "程度词用错：形容词谓语前应用程度副词“很”，不用结构助词“地”，应说“很沉重”，不能说“地沉重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98014, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻松", "is_correct": true, "explanation": "正确：形容负担或责任时，“沉重”与“轻松”是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容明白或清晰，与“沉重”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情形容态度，与“沉重”的责任义无反义关系。"}, {"text": "友好", "is_correct": false, "explanation": "友好形容关系，与“沉重”没有反义关系。"}], "correct_answer": "轻松", "explanations": {"轻松": "正确：形容负担或责任时，“沉重”与“轻松”是反义关系。", "清楚": "清楚形容明白或清晰，与“沉重”没有反义关系。", "热情": "热情形容态度，与“沉重”的责任义无反义关系。", "友好": "友好形容关系，与“沉重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98014, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻松", "is_correct": true, "explanation": "正确：形容语气或心情时，“沉重”与“轻松”是反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“沉重”的语气义无反义关系。"}, {"text": "灿烂", "is_correct": false, "explanation": "灿烂形容光彩或笑容，与“沉重”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度，与“沉重”的语气义无反义关系。"}], "correct_answer": "轻松", "explanations": {"轻松": "正确：形容语气或心情时，“沉重”与“轻松”是反义关系。", "明亮": "明亮形容光线或颜色，与“沉重”的语气义无反义关系。", "灿烂": "灿烂形容光彩或笑容，与“沉重”没有反义关系。", "迅速": "迅速形容速度，与“沉重”的语气义无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98014, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "压力、负担、责任等很大；心情压抑，让人难受。", "primary_collocate": null, "pronunciation": "chén zhòng", "ipa": "ʈʂʰən˧˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他每天都承受着沉重的压力。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的负担很沉重。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷走后，妈妈的心情一直很沉重。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他肩上的责任很沉重。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个话题太沉重，我们换一个吧。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说话时，语气很沉重。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人付出了沉重的代价。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是沉重的历史。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争给这个国家带来了沉重的灾难。", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低着头，沉重地说：“对不起。”", "target_word": "沉重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "沉重：分量大；压力、责任、心情、代价等让人感到压抑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明亮", "is_correct": false, "explanation": "语义：明亮形容光线或颜色，不能用来修饰压力。"}, {"text": "沉重", "is_correct": true, "explanation": "正确：压力大、让人压抑，与“承受着”搭配。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆形容声音，不能用来修饰压力。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“压力”不能用干燥形容，“干燥的压力”搭配不当。"}], "explanations": {"明亮": "语义：明亮形容光线或颜色，不能用来修饰压力。", "沉重": "正确：压力大、让人压抑，与“承受着”搭配。", "清脆": "搭配：清脆形容声音，不能用来修饰压力。", "干燥": "搭配：“压力”不能用干燥形容，“干燥的压力”搭配不当。"}, "sentence_index": 0, "correct_answer": "沉重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很沉重，总是一蹦一跳的。", "explanation": "这里应该用〈活泼〉。一蹦一跳的孩子要说活泼，沉重表示心情压抑、负担大，与一蹦一跳不符。"}, {"text": "收到好消息，她心里很沉重，笑个不停。", "explanation": "这里应该用〈高兴〉。收到好消息应说高兴，沉重表示心里压抑、负担大，与笑个不停矛盾。"}, {"text": "班里的同学都很沉重，爱说爱笑。", "explanation": "这里应该用〈活泼〉。形容同学爱说爱笑要用活泼，沉重不能形容人的活跃状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻盈", "is_correct": false, "explanation": "搭配：轻盈形容动作或体态，不能用来形容代价。"}, {"text": "沉重", "is_correct": true, "explanation": "正确：代价很大，与“付出了”搭配。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：干净形容清洁，不能用来形容代价。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：嘹亮形容声音，不能用来形容代价。"}], "explanations": {"轻盈": "搭配：轻盈形容动作或体态，不能用来形容代价。", "沉重": "正确：代价很大，与“付出了”搭配。", "干净": "搭配：干净形容清洁，不能用来形容代价。", "嘹亮": "搭配：嘹亮形容声音，不能用来形容代价。"}, "sentence_index": 6, "correct_answer": "沉重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只风筝很沉重，飞得又高又远。", "explanation": "这里应该用〈轻〉。风筝要飞得高远，应说很轻，沉重表示分量大，与飞得高远矛盾。"}, {"text": "他一路哼着歌，脚步很沉重。", "explanation": "这里应该用〈轻快〉。哼着歌走路的脚步要说轻快，沉重不能形容这种状态。"}, {"text": "他的笑声很沉重，逗得大家哈哈大笑。", "explanation": "这里应该用〈爽朗〉。形容笑声要说爽朗，沉重表示分量大或心情压抑，与哈哈大笑不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他沉重的摇了摇头，什么也没说。", "corrected_sentence": "他沉重地摇了摇头，什么也没说。", "error_description": "“的”与“地”混用：修饰动词“摇”要用“地”，“沉重的摇”不对，应为“沉重地摇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事让他的心情变得很沉重着。", "corrected_sentence": "这件事让他的心情变得很沉重。", "error_description": "体标记错误：“变得很沉重”表示变化的结果，后面不能加持续体“着”，应去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
