INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98015, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "泄露是把不能说的事情告诉了别人。", "primary_collocate": null, "pronunciation": "xiè lòu", "ipa": "ɕjɛ˥˩ lou˥˩", "syllable_count": 2, "sentences": [{"text": "请不要把我们的计划泄露出去。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人泄露了公司的秘密。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他泄露了考试的题目。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事别泄露给记者。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王泄露了我的新地址。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，谁也不能泄露客户的信息。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心泄露了朋友的生日惊喜。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从没泄露过这个秘密。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结果提前泄露了。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想知道谁泄露了消息。", "target_word": "泄露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "泄露了", "label": "体标"}, {"form": "泄露过", "label": "体标"}], "register": "中性", "sense_fingerprint": "泄露：把不能说的事告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”是藏起来不让人知道，与“出去”所指的传到外面相反，句子不通。"}, {"text": "泄露", "is_correct": true, "explanation": "“泄露”指把不该说的计划传到外面，符合“请不要……出去”的语境。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或计划本身，不能带“出去”作补语，“讨论出去”不成立。"}, {"text": "保守", "is_correct": false, "explanation": "配价：“保守”要求“秘密”之类的宾语，不能用在“把……出去”这一结构里。"}], "explanations": {"隐藏": "语义：“隐藏”是藏起来不让人知道，与“出去”所指的传到外面相反，句子不通。", "泄露": "“泄露”指把不该说的计划传到外面，符合“请不要……出去”的语境。", "讨论": "搭配：“讨论”的对象是问题或计划本身，不能带“出去”作补语，“讨论出去”不成立。", "保守": "配价：“保守”要求“秘密”之类的宾语，不能用在“把……出去”这一结构里。"}, "sentence_index": 0, "correct_answer": "泄露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把那本书泄露给了朋友。", "explanation": "这里应该用〈赠送〉。泄露只用于不该让人知道的秘密、消息，书是实物，不能“泄露”。"}, {"text": "她向老师泄露了自己的感谢。", "explanation": "这里应该用〈表达〉。泄露指不该让人知道的消息被传出去，感谢应当直接“表达”出来。"}, {"text": "他在饭店里泄露了一顿晚饭。", "explanation": "这里应该用〈吃〉。泄露针对秘密或消息，饭菜要说“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保留", "is_correct": false, "explanation": "语义：“保留”要求有意为之，与“不小心”相矛盾，句子不通。"}, {"text": "泄露", "is_correct": true, "explanation": "“泄露”指说出本应保密的惊喜，符合“不小心”的语境。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”是愉快地得到，与“不小心”的无意相矛盾，句子不通。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”多指保存实物或纪念品，不能说“收藏惊喜”。"}], "explanations": {"保留": "语义：“保留”要求有意为之，与“不小心”相矛盾，句子不通。", "泄露": "“泄露”指说出本应保密的惊喜，符合“不小心”的语境。", "享受": "语义：“享受”是愉快地得到，与“不小心”的无意相矛盾，句子不通。", "收藏": "搭配：“收藏”多指保存实物或纪念品，不能说“收藏惊喜”。"}, "sentence_index": 6, "correct_answer": "泄露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司正式泄露了新产品的价格。", "explanation": "这里应该用〈公布〉。泄露指不该让人知道的消息被传出去，经正式程序对外发布的内容要说“公布”。"}, {"text": "她在舞台上泄露了一支舞，观众都很惊讶。", "explanation": "这里应该用〈表演〉。泄露只用于秘密、消息，舞蹈是公开的节目，要说“表演”。"}, {"text": "他每天在公园里泄露一个小时的锻炼。", "explanation": "这里应该用〈进行〉。泄露指秘密被传出去，锻炼是日常活动，要说“进行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把考试题目泄露了出了去。", "corrected_sentence": "他把考试题目泄露了出去。", "error_description": "趋向补语“出去”是一个整体，“了”不能插在“出”和“去”之间，应说“泄露了出去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从没泄露了我们的密码。", "corrected_sentence": "他从没泄露过我们的密码。", "error_description": "“从没”与“了”不能共现，表示未曾有过的经历要用“过”：应说“从没泄露过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
