INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98019, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "派对是很多人聚在一起玩、吃东西、唱歌的快乐聚会。", "primary_collocate": null, "pronunciation": "pài duì", "ipa": "pʰai˥˩ twei˥˩", "syllable_count": 2, "sentences": [{"text": "周末我们在家开了一个派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "派对上大家唱歌，也吃了很多东西。", "target_word": "派对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了二十个朋友来参加派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场派对真热闹，我玩得很开心。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "派对从晚上七点开始。", "target_word": "派对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友们在派对上吃蛋糕。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今天晚上去不去派对？", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次参加这么大的派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈为我准备了生日派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "派对结束后，我们一起打扫房间。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "生日派对", "label": "复合"}, {"form": "派對", "label": "繁体"}], "register": "口语", "sense_fingerprint": "很多人一起玩、吃、唱歌的快乐聚会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "派对", "is_correct": true, "explanation": "派对：很多人聚在一起玩、吃东西、唱歌的快乐聚会，即本词的意思。"}, {"text": "排队", "is_correct": false, "explanation": "pái（第二声）与 pài（第四声）声调不同，意思是排成一列等候。"}, {"text": "带队", "is_correct": false, "explanation": "dài（第四声）与 pài 声母不同（d 与 p），意思是率领一支队伍。"}, {"text": "配对", "is_correct": false, "explanation": "pèi（第四声）与 pài（第四声）韵母不同（ei 与 ai），意思是两两配成一对。"}], "explanations": {"派对": "派对：很多人聚在一起玩、吃东西、唱歌的快乐聚会，即本词的意思。", "排队": "pái（第二声）与 pài（第四声）声调不同，意思是排成一列等候。", "带队": "dài（第四声）与 pài 声母不同（d 与 p），意思是率领一支队伍。", "配对": "pèi（第四声）与 pài（第四声）韵母不同（ei 与 ai），意思是两两配成一对。"}, "sentence_index": null, "correct_answer": "派对"}, "level_3": {"options": [{"text": "派对", "is_correct": true, "explanation": "派对：多人聚在一起玩乐的聚会，可以在家里举办，与“周末在家开了一个”搭配自然。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆是公共场所，不能在家里开。"}, {"text": "火车站", "is_correct": false, "explanation": "语义：火车站是公共交通场所，不能在家里开，句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“开”不搭配“作业”，应说“做作业”。"}], "explanations": {"派对": "派对：多人聚在一起玩乐的聚会，可以在家里举办，与“周末在家开了一个”搭配自然。", "体育馆": "语义：体育馆是公共场所，不能在家里开。", "火车站": "语义：火车站是公共交通场所，不能在家里开，句意不通。", "作业": "搭配：“开”不搭配“作业”，应说“做作业”。"}, "sentence_index": 0, "correct_answer": "派对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只派对真热闹，我玩得很开心。", "explanation": "这里应该用〈场〉。派对的量词是“场”，“只”用于动物或成对的东西，不能用于派对。"}, {"text": "这首派对真热闹，我玩得很开心。", "explanation": "这里应该用〈场〉。“首”用于歌曲、诗词，派对不能用“首”来数。"}, {"text": "这本派对真热闹，我玩得很开心。", "explanation": "这里应该用〈场〉。“本”用于书籍、簿册，派对不能用“本”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "派对", "is_correct": true, "explanation": "派对：去参加的聚会，与“去不去”搭配正确。"}, {"text": "饼干", "is_correct": false, "explanation": "配价：“去”后要接地点或活动，饼干不能作“去”的宾语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是地点或活动，不能去。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“去”一般不接“作业”，应说“做作业”。"}], "explanations": {"派对": "派对：去参加的聚会，与“去不去”搭配正确。", "饼干": "配价：“去”后要接地点或活动，饼干不能作“去”的宾语。", "天气": "语义：天气不是地点或活动，不能去。", "作业": "搭配：“去”一般不接“作业”，应说“做作业”。"}, "sentence_index": 6, "correct_answer": "派对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们为去世的老人举办了派对，亲友都来送行。", "explanation": "这里应该用〈葬礼〉。派对是轻松快乐的聚会，不能用于悼念去世的人，那种场合要说“葬礼”。"}, {"text": "我们今天去听派对。", "explanation": "这里应该用〈讲座〉。“听”的对象是讲座、音乐等，派对是聚会，不能说“听派对”。"}, {"text": "医生为病人进行了一场很成功的派对。", "explanation": "这里应该用〈治疗〉。派对是娱乐聚会，不能用于医疗场合，应说“进行了一场很成功的治疗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每个周末都在家开一只派对。", "corrected_sentence": "我们每个周末都在家开一场派对。", "error_description": "量词错误：派对应用“场”，不能用“只”（“只”用于动物或成对的东西）。正确说“开一场派对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天帮我办了一只生日派对。", "corrected_sentence": "妈妈昨天帮我办了一场生日派对。", "error_description": "量词错误：派对应用“场”，不能用“只”（“只”用于动物或成对的东西）。正确说“一场生日派对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
