INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为庆祝或娱乐而举行的聚会。", "primary_collocate": null, "pronunciation": "pài duì", "ipa": "pʰai˥˩ twei˥˩", "syllable_count": 2, "sentences": [{"text": "公司为新年举行了一场派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了庆祝毕业，同学们办了派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在海边举办了一场派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个派对是为欢迎新同事开的。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "派对上有音乐，也有舞蹈。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们邀请了老师参加毕业派对。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圣诞节的派对要穿红衣服。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在派对上认识了很多新朋友。", "target_word": "派对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场派对办得很成功。", "target_word": "派对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把家里布置好，准备开派对。", "target_word": "派对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "生日派对", "label": "复合"}, {"form": "派對", "label": "繁体"}], "register": "口语", "sense_fingerprint": "为庆祝或娱乐而举行的聚会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "派对", "is_correct": true, "explanation": "派对：为庆祝或娱乐而举行的聚会，即本词的意思。"}, {"text": "排队", "is_correct": false, "explanation": "pái（第二声）与 pài（第四声）声调不同，意思是排成一列等候。"}, {"text": "带队", "is_correct": false, "explanation": "dài（第四声）与 pài 声母不同（d 与 p），意思是率领一支队伍。"}, {"text": "配对", "is_correct": false, "explanation": "pèi（第四声）与 pài（第四声）韵母不同（ei 与 ai），意思是两两配成一对。"}], "explanations": {"派对": "派对：为庆祝或娱乐而举行的聚会，即本词的意思。", "排队": "pái（第二声）与 pài（第四声）声调不同，意思是排成一列等候。", "带队": "dài（第四声）与 pài 声母不同（d 与 p），意思是率领一支队伍。", "配对": "pèi（第四声）与 pài（第四声）韵母不同（ei 与 ai），意思是两两配成一对。"}, "sentence_index": null, "correct_answer": "派对"}, "level_3": {"options": [{"text": "派对", "is_correct": true, "explanation": "派对：为庆祝或娱乐而举行的聚会，可以说“举行”，与句意搭配正确。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是可以举行的活动。"}, {"text": "事故", "is_correct": false, "explanation": "搭配：“举行”不搭配“事故”，事故是发生的。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不是活动，不能举行。"}], "explanations": {"派对": "派对：为庆祝或娱乐而举行的聚会，可以说“举行”，与句意搭配正确。", "感冒": "语义：感冒是疾病，不是可以举行的活动。", "事故": "搭配：“举行”不搭配“事故”，事故是发生的。", "眼镜": "语义：眼镜是物品，不是活动，不能举行。"}, "sentence_index": 0, "correct_answer": "派对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只派对是为欢迎新同事开的。", "explanation": "这里应该用〈个〉或〈场〉。“只”用于动物或成对的东西，派对不能用“只”来数。"}, {"text": "这张派对是为欢迎新同事开的。", "explanation": "这里应该用〈个〉或〈场〉。“张”用于桌子、纸张等平面物，派对不能用“张”来数。"}, {"text": "这把派对是为欢迎新同事开的。", "explanation": "这里应该用〈个〉或〈场〉。“把”用于有柄的物品（如椅子、刀），派对不能用“把”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDE