INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "派对", "is_correct": true, "explanation": "派对：圣诞节的聚会，参加者常穿红衣服，与句意相合。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤不能穿衣服，与“要穿红衣服”矛盾。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是考核，不是需要穿红衣服的场合。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“穿”不搭配“歌”，歌曲不穿衣服。"}], "explanations": {"派对": "派对：圣诞节的聚会，参加者常穿红衣服，与句意相合。", "汤": "语义：汤不能穿衣服，与“要穿红衣服”矛盾。", "考试": "语义：考试是考核，不是需要穿红衣服的场合。", "歌": "搭配：“穿”不搭配“歌”，歌曲不穿衣服。"}, "sentence_index": 6, "correct_answer": "派对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校为去世的老师举行了派对，同事们都来送别。", "explanation": "这里应该用〈追悼会〉。派对是快乐的聚会，不能用于悼念去世的人，那种场合要说“追悼会”。"}, {"text": "大家安静地听派对。", "explanation": "这里应该用〈演讲〉。“听”的对象是演讲、音乐等，派对是聚会，不能被“听”。"}, {"text": "这场派对讲得很精彩，大家都很满意。", "explanation": "这里应该用〈讲座〉。派对是聚会，不能被“讲”，讲得精彩的应是讲座。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在酒店办了一座派对，邀请了很多朋友。", "corrected_sentence": "我们在酒店办了一场派对，邀请了很多朋友。", "error_description": "量词错误：派对应用“场”或“个”，不能用“座”（“座”用于山、房屋等大型固定物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天参加了两派对。", "corrected_sentence": "我昨天参加了两场派对。", "error_description": "量词错误：数词“两”后面数派对要加量词，应说“两场派对”或“两个派对”，不能直接说“两派对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
