INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98023, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海边是大海旁边的地方，那里有沙子和浪花。", "primary_collocate": null, "pronunciation": "hǎi biān", "ipa": "xaɪ̯˨˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "周末我们全家去海边玩。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的沙子很软，孩子们喜欢在那儿玩。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在海边，每天都能听到海浪的声音。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的海边有很多游客。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边走了很久，一起看日落。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的风很大，你要多穿一件衣服。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在海边捡了很多漂亮的贝壳。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有一家小饭店，海鲜非常新鲜。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在海边堆了一座沙子城堡。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "傍晚的海边很安静，只有浪花的声音。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海邊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大海旁边有沙滩和浪花的地方，常用来玩耍、散步、看风景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98023, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：正确答案，指靠近大海的地方，读 hǎi biān。"}, {"text": "海鲜", "is_correct": false, "explanation": "xiān 与 biān 声母不同（x 与 b），意思是海鲜食物。"}, {"text": "海绵", "is_correct": false, "explanation": "mián 与 biān 声母不同（m 与 b），声调也不同，意思是海绵。"}, {"text": "海天", "is_correct": false, "explanation": "tiān 与 biān 声母不同（t 与 b），意思是海和天。"}, {"text": "外边", "is_correct": false, "explanation": "wài 与 hǎi 声母不同（w 与 h），声调也不同，意思是外面。"}], "explanations": {"海边": "海边：正确答案，指靠近大海的地方，读 hǎi biān。", "海鲜": "xiān 与 biān 声母不同（x 与 b），意思是海鲜食物。", "海绵": "mián 与 biān 声母不同（m 与 b），声调也不同，意思是海绵。", "海天": "tiān 与 biān 声母不同（t 与 b），意思是海和天。", "外边": "wài 与 hǎi 声母不同（w 与 h），声调也不同，意思是外面。"}, "sentence_index": null, "correct_answer": "海边"}, "level_3": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：指可以去游玩的海岸地带，只有它合适。"}, {"text": "海鲜", "is_correct": false, "explanation": "语义：海鲜是食物，不是可以去玩的地方，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是放食物的电器，全家人不能「去冰箱玩」，句意不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，「去厨房玩」不合常理。"}], "explanations": {"海边": "海边：指可以去游玩的海岸地带，只有它合适。", "海鲜": "语义：海鲜是食物，不是可以去玩的地方，句意不通。", "冰箱": "语义：冰箱是放食物的电器，全家人不能「去冰箱玩」，句意不通。", "厨房": "语义：厨房是做饭的地方，「去厨房玩」不合常理。"}, "sentence_index": 0, "correct_answer": "海边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片海边很深，大船可以直接开进去。", "explanation": "这里应指〈海〉。海边指靠海的陆地地带，不是海水本身，不能说它深、可以开船进去。"}, {"text": "孩子们喝了一杯海边，觉得很甜。", "explanation": "用法错误。海边是地点，不是饮品，不能用「杯」来数，也不能被喝。"}, {"text": "孩子们用海边堆了一座城堡。", "explanation": "用法错误。海边是地点，不能当作堆城堡的材料，应说「在海边堆」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98023, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：正确答案，指靠近大海的地方，读 hǎi biān。"}, {"text": "海冰", "is_correct": false, "explanation": "bīng 与 biān 韵母不同（ing 与 ian），意思是海上的冰。"}, {"text": "海天", "is_correct": false, "explanation": "tiān 与 biān 声母不同（t 与 b），意思是海和天。"}, {"text": "白边", "is_correct": false, "explanation": "bái 与 hǎi 声母不同（b 与 h），声调也不同，意思是白色的边。"}, {"text": "海面", "is_correct": false, "explanation": "miàn 与 biān 声母不同（m 与 b），声调也不同，意思是海的表面。"}], "explanations": {"海边": "海边：正确答案，指靠近大海的地方，读 hǎi biān。", "海冰": "bīng 与 biān 韵母不同（ing 与 ian），意思是海上的冰。", "海天": "tiān 与 biān 声母不同（t 与 b），意思是海和天。", "白边": "bái 与 hǎi 声母不同（b 与 h），声调也不同，意思是白色的边。", "海面": "miàn 与 biān 声母不同（m 与 b），声调也不同，意思是海的表面。"}, "sentence_index": null, "correct_answer": "海边"}, "level_3": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：指可以捡贝壳的海滩地带，只有它合适。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行里没有贝壳，「在银行捡贝壳」句意不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不产贝壳，句意不通。"}, {"text": "药店", "is_correct": false, "explanation": "搭配：「捡……贝壳」的地点应是海滩或河边，药店不搭配。"}], "explanations": {"海边": "海边：指可以捡贝壳的海滩地带，只有它合适。", "银行": "语义：银行里没有贝壳，「在银行捡贝壳」句意不通。", "医院": "语义：医院不产贝壳，句意不通。", "药店": "搭配：「捡……贝壳」的地点应是海滩或河边，药店不搭配。"}, "sentence_index": 6, "correct_answer": "海边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的海边很干净。", "explanation": "用法错误。海边指靠海的陆地地带，这里却把它当作屋里的一个角落来用，与词义矛盾。"}, {"text": "妈妈把海边炒进了菜里。", "explanation": "这里应该用〈海鲜〉。海边是地点，不能当作食材炒进菜里。"}, {"text": "他把海边装进箱子里，带回了家。", "explanation": "用法错误。海边是一片地带，无法装进箱子，应说〈沙子〉这类具体东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去海边的散步吧。", "corrected_sentence": "我们明天去海边散步吧。", "error_description": "错误在「海边」与动词之间多出了「的」。「去海边」后直接接动词「散步」，不应在地点与动词间加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们沿着一个海边慢慢散步。", "corrected_sentence": "我们沿着海边慢慢散步。", "error_description": "错误在「一个」修饰「海边」。海边作路线的地点时不加数量词，应直接说「沿着海边」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
