INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠近海的地方。", "primary_collocate": null, "pronunciation": "hǎi biān", "ipa": "xaɪ̯˨˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "他从小在海边长大，会游泳。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的天气比城市凉快。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算在海边租一间房子。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市就在海边，坐车十分钟就到。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的渔民每天很早出海。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢海边的生活，所以搬到了青岛。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的空气又湿又咸。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着海边慢慢走了一个小时。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有一排高高的椰子树。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家酒店建在海边，窗外就是大海。", "target_word": "海边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海邊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠近海的区域，指居住、建造或生活的地理位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：正确答案，指靠近海的地方，读 hǎi biān。"}, {"text": "海鲜", "is_correct": false, "explanation": "xiān 与 biān 声母不同（x 与 b），意思是海鲜食物。"}, {"text": "海绵", "is_correct": false, "explanation": "mián 与 biān 声母不同（m 与 b），声调也不同，意思是海绵。"}, {"text": "海冰", "is_correct": false, "explanation": "bīng 与 biān 韵母不同（ing 与 ian），意思是海上的冰。"}, {"text": "外边", "is_correct": false, "explanation": "wài 与 hǎi 声母不同（w 与 h），声调也不同，意思是外面。"}], "explanations": {"海边": "海边：正确答案，指靠近海的地方，读 hǎi biān。", "海鲜": "xiān 与 biān 声母不同（x 与 b），意思是海鲜食物。", "海绵": "mián 与 biān 声母不同（m 与 b），声调也不同，意思是海绵。", "海冰": "bīng 与 biān 韵母不同（ing 与 ian），意思是海上的冰。", "外边": "wài 与 hǎi 声母不同（w 与 h），声调也不同，意思是外面。"}, "sentence_index": null, "correct_answer": "海边"}, "level_3": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：指靠近海的地方，「从小在……长大」只有它合适。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是看书的地方，「从小在图书馆长大，会游泳」句意不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，人不会在厨房里长大，句意不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，「从小在教室长大」句意不通。"}], "explanations": {"海边": "海边：指靠近海的地方，「从小在……长大」只有它合适。", "图书馆": "语义：图书馆是看书的地方，「从小在图书馆长大，会游泳」句意不通。", "厨房": "语义：厨房是做饭的地方，人不会在厨房里长大，句意不通。", "教室": "语义：教室是上课的地方，「从小在教室长大」句意不通。"}, "sentence_index": 0, "correct_answer": "海边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的海边在山顶，我们骑车就能到。", "explanation": "用法错误。海边指靠近海的地方，这里说它在山顶，等于把它当成了远离海的高地，与词义矛盾。"}, {"text": "我们喝了一杯海边，觉得很咸。", "explanation": "用法错误。海边是地点，不是饮品，不能被喝，也不能用「杯」来数。"}, {"text": "她用海边做了一把椅子。", "explanation": "用法错误。海边是地点，不是材料，不能用来制作椅子，应说〈木头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：正确答案，指靠近海的地方，读 hǎi biān。"}, {"text": "海天", "is_correct": false, "explanation": "tiān 与 biān 声母不同（t 与 b），意思是海和天。"}, {"text": "白边", "is_correct": false, "explanation": "bái 与 hǎi 声母不同（b 与 h），声调也不同，意思是白色的边。"}, {"text": "海面", "is_correct": false, "explanation": "miàn 与 biān 声母不同（m 与 b），声调也不同，意思是海的表面。"}], "explanations": {"海边": "海边：正确答案，指靠近海的地方，读 hǎi biān。", "海天": "tiān 与 biān 声母不同（t 与 b），意思是海和天。", "白边": "bái 与 hǎi 声母不同（b 与 h），声调也不同，意思是白色的边。", "海面": "miàn 与 biān 声母不同（m 与 b），声调也不同，意思是海的表面。"}, "sentence_index": null, "correct_answer": "海边"}, "level_3": {"options": [{"text": "海边", "is_correct": true, "explanation": "海边：指靠近海的地方，「海边的空气」只有它合适。"}, {"text": "高原", "is_correct": false, "explanation": "语义：高原离海远，空气干燥，不会又湿又咸。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干燥，空气不会又湿又咸。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：「又湿又咸」描写的是海风或海雾，草原一般不与「咸」搭配。"}], "explanations": {"海边": "海边：指靠近海的地方，「海边的空气」只有它合适。", "高原": "语义：高原离海远，空气干燥，不会又湿又咸。", "沙漠": "语义：沙漠干燥，空气不会又湿又咸。", "草原": "搭配：「又湿又咸」描写的是海风或海雾，草原一般不与「咸」搭配。"}, "sentence_index": 6, "correct_answer": "海边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海边一阵阵拍打着礁石，声音很响。", "explanation": "这里应该用〈海浪〉。海浪会拍打礁石，海边是靠近海的地方，本身不会运动，不能拍打礁石。"}, {"text": "妈妈把海边切成小块，放进锅里煮。", "explanation": "用法错误。海边是地点，不是食材，不能切块煮，应说〈海鲜〉。"}, {"text": "这条船把海边装进货舱，运到了远方。", "explanation": "用法错误。海边指靠近海的一片地带，不能当作具体货物装进容器，应说〈货物〉这类具体东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想从海边开一家小餐厅。", "corrected_sentence": "他们想在海边开一家小餐厅。", "error_description": "错误：「在海边」的「在」被换成了「从」。正确：「他们想在海边开一家小餐厅。」「从」表示起点，「在」才表示动作发生的地点，「想在海边开」不能说成「想从海边开」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他海边的小屋里住了三年。", "corrected_sentence": "他在海边的小屋里住了三年。", "error_description": "错误在漏掉了「在」。表示居住的地点要说「在海边的小屋里住」，不能省略「在」直接说「海边的小屋里住了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
