INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "演说是站在很多人面前，大声讲出自己想说的话。", "primary_collocate": null, "pronunciation": "yǎn shuō", "ipa": "jɛn˨˩˦ ʂwɔ˥˥", "syllable_count": 2, "sentences": [{"text": "校长站在台上对同学们演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大声地演说了十分钟。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明天要在全班同学面前演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一演说，大家都安静下来。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人正在广场上演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在台上演说，声音很大。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太会演说，一说话就紧张。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明第一次在很多人面前演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围着他，听他演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在会上演说了很久。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演说了", "label": "完成体"}, {"form": "演说过", "label": "经历体"}, {"form": "演说着", "label": "持续体"}, {"form": "演说家", "label": "复合词"}], "register": "书面", "sense_fingerprint": "动词：站在众人面前大声讲话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：游泳要在水中进行，与“站在台上”的场景不符。"}, {"text": "演说", "is_correct": true, "explanation": "正确：演说指站在众人面前大声讲话，与“站在台上对同学们”的场景相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能对着同学们进行，与“站在台上”讲话的情境矛盾。"}, {"text": "唠嗑", "is_correct": false, "explanation": "语域：唠嗑是口语、方言色彩很浓的说法，与“校长站在台上”的正式场合不合。"}], "explanations": {"游泳": "语义：游泳要在水中进行，与“站在台上”的场景不符。", "演说": "正确：演说指站在众人面前大声讲话，与“站在台上对同学们”的场景相符。", "睡觉": "语义：睡觉不能对着同学们进行，与“站在台上”讲话的情境矛盾。", "唠嗑": "语域：唠嗑是口语、方言色彩很浓的说法，与“校长站在台上”的正式场合不合。"}, "sentence_index": 0, "correct_answer": "演说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和朋友演说了一下午。", "explanation": "这里应该用〈聊天〉。演说是站在众人面前讲话，两人闲谈要用聊天。"}, {"text": "他在课堂上演说课文。", "explanation": "这里应该用〈朗读〉。演说是讲出自己想说的话，读已写好的课文要用朗读。"}, {"text": "她在台上演说了一首新歌。", "explanation": "这里应该用〈唱歌〉。演说是讲话，唱歌不能用演说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉默", "is_correct": false, "explanation": "语义：沉默就是不说话，与“一说话就紧张”的情况正相反。"}, {"text": "演说", "is_correct": true, "explanation": "正确：演说是站在人前讲话，与“一说话就紧张”的情境相符。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“发呆”不是可以说“不太会”的技能，与后半句说话的语境也对不上。"}, {"text": "闭嘴", "is_correct": false, "explanation": "语义：闭嘴与“一说话”的情形正相反。"}], "explanations": {"沉默": "语义：沉默就是不说话，与“一说话就紧张”的情况正相反。", "演说": "正确：演说是站在人前讲话，与“一说话就紧张”的情境相符。", "发呆": "搭配：“发呆”不是可以说“不太会”的技能，与后半句说话的语境也对不上。", "闭嘴": "语义：闭嘴与“一说话”的情形正相反。"}, "sentence_index": 6, "correct_answer": "演说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "睡觉前，我在床上小声地跟妹妹演说。", "explanation": "这里应该用〈聊天〉。演说是站在众人面前大声讲话，两个人小声说话要用聊天。"}, {"text": "他在电话里对朋友演说了很久。", "explanation": "这里应该用〈打电话〉。演说是面向众人讲自己的主张，跟朋友在电话里说话要用打电话。"}, {"text": "他在书桌前演说了一下午的作文。", "explanation": "这里应该用〈写〉。演说是当众讲出自己的想法，写作文要用写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长在礼堂里全校同学演说。", "corrected_sentence": "校长在礼堂里向全校同学演说。", "error_description": "错误：听众“全校同学”前缺少介词“向”，不能直接放在“演说”前。正确：“向全校同学演说”，用“向”引出听众。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年在全市会上演说过过一次。", "corrected_sentence": "他去年在全市会上演说过一次。", "error_description": "错误：“过”重复出现，“演说过过”不成立。正确：“演说过一次”，经历体的“过”只用一次，紧跟动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
