INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在公众面前就某个问题发表自己的看法和主张。", "primary_collocate": null, "pronunciation": "yǎn shuō", "ipa": "jɛn˨˩˦ ʂwɔ˥˥", "syllable_count": 2, "sentences": [{"text": "市长就环境问题向市民演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大会上就教育问题演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统明天将向全国人民演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她就工作中的问题向同事们演说，讲了自己的看法。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家在会上演说，讲了他的主张。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想就这件事向大家演说一次。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师常在公开场合就读书问题演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在大会上演说，介绍了公司的计划。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她演说的时候，讲得很有道理。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请了一位作家来学校演说。", "target_word": "演说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演说了", "label": "完成体"}, {"form": "演说过", "label": "经历体"}, {"form": "演说着", "label": "持续体"}, {"form": "演说家", "label": "复合词"}], "register": "书面", "sense_fingerprint": "动词：在公开场合就某问题发表看法和主张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是身体动作，与“就环境问题发表看法”的内容无关。"}, {"text": "演说", "is_correct": true, "explanation": "正确：演说指在公开场合就某问题发表看法和主张，与句中语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳要在水中进行，与“就环境问题向市民”的讲话情境不符。"}, {"text": "讲笑话", "is_correct": false, "explanation": "语域：讲笑话偏轻松随意，与就环境问题发表主张的正式场合不合。"}], "explanations": {"跳舞": "语义：跳舞是身体动作，与“就环境问题发表看法”的内容无关。", "演说": "正确：演说指在公开场合就某问题发表看法和主张，与句中语境相符。", "游泳": "语义：游泳要在水中进行，与“就环境问题向市民”的讲话情境不符。", "讲笑话": "语域：讲笑话偏轻松随意，与就环境问题发表主张的正式场合不合。"}, "sentence_index": 0, "correct_answer": "演说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和妈妈演说了周末的计划。", "explanation": "这里应该用〈商量〉。演说是对众人发表主张，和家人商量计划要用商量。"}, {"text": "她向老师演说数学题，老师一一讲解。", "explanation": "这里应该用〈请教〉。演说是面向众人发表看法，向老师问问题要用请教。"}, {"text": "他和朋友为一件小事演说了很久。", "explanation": "这里应该用〈争论〉。演说是一人向众人讲，双方来回争执要用争论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "搭配：“就……问题”后接的应是发表看法，“睡觉”无法与之搭配。"}, {"text": "演说", "is_correct": true, "explanation": "正确：演说指在公开场合就某问题发表看法，与句中“公开场合”和“读书问题”相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与“就读书问题”发表看法的内容毫不相关。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆是不做事的状态，与公开场合发表看法的行为矛盾。"}], "explanations": {"睡觉": "搭配：“就……问题”后接的应是发表看法，“睡觉”无法与之搭配。", "演说": "正确：演说指在公开场合就某问题发表看法，与句中“公开场合”和“读书问题”相符。", "唱歌": "语义：唱歌与“就读书问题”发表看法的内容毫不相关。", "发呆": "语义：发呆是不做事的状态，与公开场合发表看法的行为矛盾。"}, "sentence_index": 6, "correct_answer": "演说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在厨房里演说了一顿晚饭。", "explanation": "这里应该用〈做〉。演说是就问题发表看法，做晚饭要用做。"}, {"text": "他在书店里演说了一下午的书架。", "explanation": "这里应该用〈整理〉。演说是发表看法和主张，整理书架要用整理。"}, {"text": "她在河边演说了一件湿衣服。", "explanation": "这里应该用〈洗〉。演说是就问题发表看法，洗衣服要用洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市长在广场上就物价问题演说的很精彩。", "corrected_sentence": "市长在广场上就物价问题演说得很精彩。", "error_description": "错误：补语前用了“的”。正确：“演说得很精彩”，表示程度的补语要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长明天要在大会上演说过。", "corrected_sentence": "校长明天要在大会上演说。", "error_description": "错误：表示将来的句子里，“演说”后不能加“过”。正确：去掉“过”，说“明天要在大会上演说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
