INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98031, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在乎", "is_correct": true, "explanation": "正确：“在乎”指放在心上，与“无所谓”的不在乎意思相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”表示休息，与“无所谓”既非近义也非反义。"}, {"text": "拒绝", "is_correct": false, "explanation": "“拒绝”表示不接受，与“无所谓”既非近义也非反义。"}, {"text": "离开", "is_correct": false, "explanation": "“离开”表示走开，与“无所谓”既非近义也非反义。"}], "correct_answer": "在乎", "explanations": {"在乎": "正确：“在乎”指放在心上，与“无所谓”的不在乎意思相反。", "睡觉": "“睡觉”表示休息，与“无所谓”既非近义也非反义。", "拒绝": "“拒绝”表示不接受，与“无所谓”既非近义也非反义。", "离开": "“离开”表示走开，与“无所谓”既非近义也非反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98031, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "无所谓是怎么样都可以，我不在乎。", "primary_collocate": null, "pronunciation": "wú suǒ wèi", "ipa": "u˧˥ swɔ˨˩ weɪ˥˩", "syllable_count": 3, "sentences": [{"text": "喝茶还是喝咖啡，对我都无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红的蓝的我都无所谓，你喜欢就买。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说下雨也无所谓，照样去跑步。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事问我几点开会，我说无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住大房子小房子，他都无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考得好不好，她好像无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她满不在乎地说：“无所谓，随便吧。”", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天吃面条还是米饭，我无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子说穿旧鞋无所谓，只要舒服。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得坐哪里都无所谓，别麻烦了。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無所謂", "label": "繁体"}], "register": "口语", "sense_fingerprint": "怎么样都可以，表示自己不在乎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无所谓", "is_correct": true, "explanation": "正确：“无所谓”表示怎样都可以，与“都无所谓”一致。"}, {"text": "在意", "is_correct": false, "explanation": "语义：“在意”表示放在心上，与“都无所谓”的态度相反。"}, {"text": "讲究", "is_correct": false, "explanation": "语义：“讲究”表示有要求、挑选，与“都无所谓”的态度相反。"}, {"text": "计较", "is_correct": false, "explanation": "搭配：“计较”多用于“跟……计较”，此处缺少对象，不自然。"}], "explanations": {"无所谓": "正确：“无所谓”表示怎样都可以，与“都无所谓”一致。", "在意": "语义：“在意”表示放在心上，与“都无所谓”的态度相反。", "讲究": "语义：“讲究”表示有要求、挑选，与“都无所谓”的态度相反。", "计较": "搭配：“计较”多用于“跟……计较”，此处缺少对象，不自然。"}, "sentence_index": 0, "correct_answer": "无所谓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子无所谓，什么问题都知道答案。", "explanation": "这里应该用〈无所不知〉。“无所谓”表示不在乎，不表示什么都知道。"}, {"text": "这个神仙无所谓，到处都能找到他。", "explanation": "这里应该用〈无所不在〉。“无所谓”表示不在乎，不表示到处都有。"}, {"text": "这个村子无所谓，一个人也没有。", "explanation": "这里应该用〈空无一人〉。“无所谓”表示不在乎，不表示没有人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无所谓", "is_correct": true, "explanation": "正确：“无所谓”表示不在乎，与“满不在乎地说”的语气一致。"}, {"text": "在乎", "is_correct": false, "explanation": "语义：“在乎”表示放在心上，与“满不在乎”的语气相反。"}, {"text": "介意", "is_correct": false, "explanation": "语义：“介意”表示心里在意，与“满不在乎”的语气相反。"}, {"text": "计较", "is_correct": false, "explanation": "搭配：“计较”不能单独用来回答“随便吧”，搭配上不自然。"}], "explanations": {"无所谓": "正确：“无所谓”表示不在乎，与“满不在乎地说”的语气一致。", "在乎": "语义：“在乎”表示放在心上，与“满不在乎”的语气相反。", "介意": "语义：“介意”表示心里在意，与“满不在乎”的语气相反。", "计较": "搭配：“计较”不能单独用来回答“随便吧”，搭配上不自然。"}, "sentence_index": 6, "correct_answer": "无所谓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他退休后天天无所谓，只在家里看电视。", "explanation": "这里应该用〈无所事事〉。“无所谓”表示不在乎，不表示没有事情做。"}, {"text": "你会修电脑吗？——无所谓。", "explanation": "这里应该用〈修得好〉或〈修不了〉来回答。“无所谓”只表示态度，不能回答会不会做到的问题。"}, {"text": "这位医生无所谓，什么病都能治。", "explanation": "这里应该用〈无所不能〉。“无所谓”表示不在乎，不能用来说本领很强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
