INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98032, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "不在乎；认为怎样都行，没有关系。", "primary_collocate": null, "pronunciation": "wú suǒ wèi", "ipa": "u˧˥ swɔ˨˩ weɪ˥˩", "syllable_count": 3, "sentences": [{"text": "你想吃什么都行，我无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去哪儿玩儿我无所谓，你决定吧。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对输赢好像无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人怎么说，我无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说穿什么衣服无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一点儿也无所谓，笑着走了。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐火车还是坐飞机，对我来说无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到大家的话，他装作无所谓的样子。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早一点儿晚一点儿都无所谓。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对钱无所谓，只想做喜欢的事。", "target_word": "无所谓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無所謂", "label": "繁体"}], "register": "口语", "sense_fingerprint": "对某事不在乎，怎样都行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无所谓", "is_correct": true, "explanation": "正确：“无所谓”表示不在乎，与“什么都行”的态度一致。"}, {"text": "在乎", "is_correct": false, "explanation": "语义：“在乎”表示放在心上，与“什么都行”的态度相反。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示不满，与前半句的随和态度矛盾。"}, {"text": "计较", "is_correct": false, "explanation": "搭配：“计较”多用于“跟……计较”或“计较得失”，“我计较”缺少对象，不自然。"}], "explanations": {"无所谓": "正确：“无所谓”表示不在乎，与“什么都行”的态度一致。", "在乎": "语义：“在乎”表示放在心上，与“什么都行”的态度相反。", "生气": "语义：“生气”表示不满，与前半句的随和态度矛盾。", "计较": "搭配：“计较”多用于“跟……计较”或“计较得失”，“我计较”缺少对象，不自然。"}, "sentence_index": 0, "correct_answer": "无所谓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他退休后每天无所谓，在家看电视。", "explanation": "这里应该用〈无所事事〉。“无所谓”表示不在乎，说的是态度，不表示没有事情做。"}, {"text": "你会说英语吗？——无所谓。", "explanation": "这里应该用〈学过〉或〈没学过〉来回答。“无所谓”只表示态度，不能回答会不会做到的问题。"}, {"text": "这座仓库无所谓，里面什么都没有。", "explanation": "这里应该用〈空空如也〉。“无所谓”表示不在乎，不表示没有东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
